window.SITE_COURSES=window.SITE_COURSES||{};SITE_COURSES["wahi"]={"lessons":[{"id":"wahi-intro","title":"مقدمة المنظومة: قصة «وحي المنام»","summary":"كيف بدأ المؤلف منظومته، ولماذا سماها «وحي المنام»، وما الأرجوزة.","verse":{"number":1,"section":"المقدمة","text":"قَالَ سُلَيْمَانُ هُوَ الْعُيُونِي: سُبْحَانَ رَبِّي الْوَاحِدِ الْمُعِينِ\nمُصَلِّيًا مُسَلِّمًا -يَا مُبْتَدِي- عَلَى الرَّسُولِ الْمُصْطَفَى مُحَمَّدِ\nوَهَذِهِ أَرْجُوزَةٌ خَفِيفَةْ فِي نَحْوِنَا مُفِيدَةٌ لَطِيفَةْ"},"segments":[{"body":["نبدأ دورتنا بأول أبيات المنظومة، وهي ثلاثة: «قَالَ سُلَيْمَانُ هُوَ الْعُيُونِي: سُبْحَانَ رَبِّي الْوَاحِدِ الْمُعِينِ * مُصَلِّيًا مُسَلِّمًا -يَا مُبْتَدِي- عَلَى الرَّسُولِ الْمُصْطَفَى مُحَمَّدِ * وَهَذِهِ أَرْجُوزَةٌ خَفِيفَةْ فِي نَحْوِنَا مُفِيدَةٌ لَطِيفَةْ». ونفهمها كلمة كلمة.","البيت الأول لفظًا لفظًا: «قَالَ»: فعل ماضٍ معناه تكلم. «سُلَيْمَانُ»: اسم علم لشخص المؤلف. «هُوَ الْعُيُونِي»: أي الذي ينتسب إلى العيون، وهي بلدته، فأخبرنا عن نفسه باسمه ونسبته. «سُبْحَانَ رَبِّي»: كلمة نقولها لتنزيه الله عن كل نقص، أي: أُنزِّه ربي. «الْوَاحِدِ»: الذي لا شريك له ولا ثاني معه. «الْمُعِينِ»: الذي يعين عباده ويوفقهم لكل خير.","فالمؤلف بدأ كتابه باسمه، ثم بتسبيح ربه، اقتداءً بأهل العلم الذين يبدؤون كتبهم بذكر الله؛ فالبركة تكون بذكر الله أولًا.","البيت الثاني لفظًا لفظًا: «مُصَلِّيًا»: أي داعيًا بالصلاة على النبي، وهي الدعاء له بالرحمة والرفعة. «مُسَلِّمًا»: أي داعيًا له بالسلامة من كل آفة. «-يَا مُبْتَدِي-»: كلام معترض بين الشطرين، معناه: يا أيها المبتدئ في تعلم هذا العلم، وهو نداء من المؤلف للطالب نفسه. «عَلَى الرَّسُولِ»: النبي المرسل من الله. «الْمُصْطَفَى»: المختار المنتقى من بين الخلق. «مُحَمَّدِ»: اسمه صلى الله عليه وسلم.","فالمعنى: أنا أصلي وأسلم على الرسول المختار محمد صلى الله عليه وسلم. وبدأ بالصلاة عليه بعد ذكر الله؛ لأنه صلى الله عليه وسلم سيد ولد آدم وصاحب هذه الشريعة.","البيت الثالث لفظًا لفظًا: «وَهَذِهِ»: اسم إشارة للمفرد المؤنث القريب، أي: هذا الكتاب الذي بين يديك. «أَرْجُوزَةٌ»: قصيدة نظمت على بحر الرجز، وهو وزن من أوزان الشعر سهل خفيف. «خَفِيفَةْ»: سهلة على اللسان لا يثقل حفظها. «فِي نَحْوِنَا»: أي في علم النحو الذي نتعلمه. «مُفِيدَةٌ»: تنفعك بعلمها. «لَطِيفَةْ»: حسنة رقيقة في ألفاظها ومعانيها."],"examples":["قال سليمان: علم الفاعل، والعيوني: نسبة","سبحان ربي: تنزيه الله عن النقص","الواحد: لا شريك له","مصليًا مسلمًا: الصلاة والسلام على النبي","يا مبتدي: نداء معترض للطالب المبتدئ","أرجوزة: قصيدة على بحر الرجز"],"questions":[{"question":"من مؤلف المنظومة وكيف عرف بنفسه؟","options":["سليمان العيوني؛ ذكر اسمه ونسبته إلى العيون","ابن مالك","العيوني دون اسم","سليمان الأعمش"],"answer":0,"explanation":"قال سليمان هو العيوني: ذكر اسمه (سليمان) ونسبته (العيوني: منسوب إلى العيون)."},{"question":"ما معنى «سبحان ربي الواحد المعين»؟","options":["أنزه ربي الذي لا شريك له وهو الذي يعين عباده","أحمد الله كثيرًا","أستغفر الله","الله أكبر"],"answer":0,"explanation":"سبحان: تنزيه؛ الواحد: لا ثاني له؛ المعين: الموفق لعباده لكل خير."},{"question":"بم بدأ المؤلف منظومته ولماذا؟","options":["بذكر الله ثم الصلاة على النبي طلبًا للبركة واقتداءً بأهل العلم","بذكر الشيوخ","بذكر نفسه فقط","بالحكايات"],"answer":0,"explanation":"عادة أهل العلم البدء بذكر الله ثم الصلاة على رسوله؛ ففعل المؤلف ذلك في أول بيتين."},{"question":"ما معنى «يا مبتدي» في البيت الثاني؟","options":["كلام معترض: نداء للطالب المبتدئ ملاطفةً له وشدًّا لانتباهه","نداء للمؤلف","اسم للكتاب","بيت منقطع"],"answer":0,"explanation":"«يا مبتدي» جملة اعتراضية بين الشطرين: نداء من المؤلف للطالب المبتدئ في طلب العلم."},{"question":"ما الأرجوزة؟","options":["قصيدة على بحر الرجز","كتاب نثري","خطبة","رسالة"],"answer":0,"explanation":"الأرجوزة قصيدة نظمت على بحر الرجز، وهو وزن خفيف يسهل حفظه؛ ولهذا اختاره المؤلف."}]},{"body":["لماذا سماها «وحي المنام»؟ أخبر المؤلف في ديباجة كتابه أن هذه المنظومة أُلهمت له في نومه؛ فكان إذا استيقظ من نومه أثبت ما أُلهمَه من الأبيات، وأضاف إليها في أربعة أيام حتى تمت مائة بيت.","فهي ليست وحيًا كوحي الأنبياء؛ بل إلهامًا رآه المؤلف في منامه، وسمّاها بذلك شكرًا لله على هذه النعمة؛ ثم سأل الله أن يجعل فيها البركة والنفع.","ترتيب المنظومة: مائة بيت كاملة. تبدأ بالمقدمة (الأبيات الثلاثة الأولى)، ثم موضوع النحو وترتيبه، ثم أحكام الكلمة: أنواعها، والنكرة والمعرفة، والمعرب والمبني، وعلامات الإعراب، ثم أحكام الكلام بأقسامه الأربعة: الجملة الفعلية، والجملة الاسمية، والمكملات، وإعراب المضارع، ثم خاتمة.","كيف ندرس كل بيت؟ نقرأ البيت بالتشكيل الكامل، ثم نفهم كل كلمة فيه، ثم نشرح الحكم النحوي الذي جاء به، ثم نتدرب بالأمثلة والأسئلة، حتى إذا ختمت المنظومة كنت قد تعلمت كل كلمة فيها.","فائدة النظم: حفظ العلم في أبيات شعر يجعله ثابتًا في الذهن؛ فالنظم يجمع القاعدة في كلمات معدودة تسهل مراجعتها، ولهذا نظم العلماء كثيرًا من العلوم: كألفية ابن مالك في النحو أيضًا.","نصيحة المؤلف الضمنية في مقدمته: هو يسمي نفسه ويسبح ربه ويصلي على نبيه قبل أن يعلمك؛ فتعلم منه الأدب مع العلم: التواضع، والبدء بذكر الله، والدعاء لطالب العلم."],"examples":["ألهمت له في المنام فأثبتها عند اليقظة","تمت في أربعة أيام مائة بيت","ترتيبها: مقدمة فأحكام الكلمة فأحكام الكلام","نقرأ البيت ثم نفهم كلماته ثم نتدرب","النظم يثبت العلم ويسهل حفظه","ألفية ابن مالك: أرجوزة نحوية مشهورة"],"questions":[{"question":"لم سميت المنظومة «وحي المنام»؟","options":["لأنها ألهمت للمؤلف في نومه فأثبتها عند استيقاظه","لأنها وحي منزل","لأنها نسخت من كتاب","اسم بلدته"],"answer":0,"explanation":"أخبر المؤلف أنها ألهمت له في المنام فكان يثبت ما ألهمه، وأتمها في أربعة أيام مائة بيت."},{"question":"كم عدد أبيات المنظومة وكيف ترتيبها العام؟","options":["مائة بيت: مقدمة ثم أحكام الكلمة ثم أحكام الكلام بأقسامه الأربعة ثم خاتمة","خمسون بيتًا","ألف بيت","بلا ترتيب"],"answer":0,"explanation":"المنظومة مائة بيت: تبدأ بالمقدمة فموضوع النحو فأحكام الكلمة فأحكام الكلام الأربعة ثم الخاتمة."},{"question":"ما فائدة نظم العلم في أبيات شعر؟","options":["يجمع القاعدة في كلمات معدودة تثبت في الذهن ويسهل حفظها ومراجعتها","للزينة فقط","للتطويل","لا فائدة"],"answer":0,"explanation":"النظم يحفظ العلم من الضياع؛ فالأبيات الموزونة تعلق بالذهن؛ ولهذا نظم العلماء كثيرًا من المتون."},{"question":"ماذا نفعل مع كل بيت في هذه الدورة؟","options":["نقرؤه مشكولًا ونفهم كل كلمة فيه ثم نشرح حكمه ونتدرب","نحفظه بلا فهم","نترجمه","نحذفه"],"answer":0,"explanation":"طريقتنا: قراءة البيت بتشكيله، وفهمه لفظًا لفظًا، ثم شرح القاعدة، ثم التدريب بالأمثلة والأسئلة."},{"question":"ما صفتان وصف بهما المؤلف أرجوزته؟","options":["خفيفة على اللسان ومفيدة لطيفة","طويلة وصعبة","قديمة ومهملة","قصيرة فارغة"],"answer":0,"explanation":"قال: خفيفة (سهلة الحفظ) ومفيدة لطيفة (نافعة حسنة الألفاظ)؛ وهذا ما تطلبه في متن محفوظ."}]}]},{"id":"wahi-verse-002","title":"الصلاة والسلام على الرسول المصطفى","summary":"صلاة المؤلف وتسليمه على رسول الله صلى الله عليه وسلم، ونداؤه للطالب المبتدئ.","verse":{"number":2,"section":"المقدمة","text":"مُصَلِّيًا مُسَلِّمًا -يَا مُبْتَدِي- عَلَى الرَّسُولِ الْمُصْطَفَى مُحَمَّدِ"},"segments":[{"body":["البيت الثاني: «مُصَلِّيًا مُسَلِّمًا -يَا مُبْتَدِي- عَلَى الرَّسُولِ الْمُصْطَفَى مُحَمَّدِ». هذا البيت كله صلاة وسلام على النبي صلى الله عليه وسلم، ونفهمه كلمة كلمة.","«مُصَلِّيًا»: اسم منصوب على الحال، قائله يصف نفسه: أقول هذا الكلام وأنا مصلٍّ على النبي. والصلاة على النبي معناها: الدعاء له بأن يرحمه الله ويرفع درجته. «مُسَلِّمًا»: مثلها: أسلم عليه، أي: أدعو له بالسلامة وأسلم عليه تحية.","«-يَا مُبْتَدِي-»: بين الشرطتين كلام معترض، أي مقطوع عما قبله وعما بعده في المعنى الظاهر؛ وحروف النداء «يا» مع «مبتدي»: يا من ابتدأ في طلب العلم. والمؤلف يناديك أنت يا طالب العلم بهذا النداء اللطيف في أثناء كلامه.","«عَلَى الرَّسُولِ»: الرسول هو المبعوث من الله بالرسالة. «الْمُصْطَفَى»: صفة للرسول معناها: المختار؛ اصطفاه الله أي اختاره واجتباه من بين الناس كلهم. «مُحَمَّدِ»: اسمه الشريف صلى الله عليه وسلم، وهو اسم مضاف إليه مع «المصطفى»... بل «محمد» بدل أو بيان لاسمه.","فالمعنى الكامل: أقول هذه الأبيات حالي كوني مصليًا مسلمًا على الرسول الذي اختاره الله، محمد صلى الله عليه وسلم.","فائدة أدبية: المؤلف يعلمك أن العلم يبدأ بالأدب: ذكر الله أولًا (البيت الأول)، ثم الصلاة على رسوله (البيت الثاني)، ثم الكلام عن الكتاب (البيت الثالث). فهذا ترتيب أهل العلم في مؤلفاتهم قديمًا وحديثًا."],"examples":["مصليًا مسلمًا: حالان منصوبان","الصلاة على النبي: دعاء له بالرحمة والرفعة","يا مبتدي: جملة اعتراضية","المصطفى: المختار من الخلق","الرسول: المبعوث بالرسالة","ترتيب: ذكر الله ثم نبيه ثم الكتاب"],"questions":[{"question":"ما إعراب «مصليًا مسلمًا»؟","options":["حالان منصوبان بالفتحة","مفعول به","نعتان","مبتدآن"],"answer":0,"explanation":"مصليًا مسلمًا: وصفان نكرتان بينا حال القائل وقت الكلام: حالان منصوبان بالفتحة."},{"question":"ما معنى الصلاة والسلام على النبي؟","options":["الصلاة: الدعاء له بالرحمة والرفعة؛ والسلام: الدعاء بالسلامة والتحية","الركوع والسجود","الصيام","الذكر فقط"],"answer":0,"explanation":"صلى الله عليه: رحمه ورفعه؛ وسلم عليه: سلمه من كل آفة وحياه."},{"question":"ما «يا مبتدي» في البيت؟","options":["جملة اعتراضية: نداء للطالب المبتدئ","فاعل البيت","خبر مبتدأ","نعت للرسول"],"answer":0,"explanation":"وقعت بين الشرطتين معترضة: المؤلف ينادي الطالب المبتدئ «يا من ابتدأ في طلب العلم» في أثناء صلاته على النبي."},{"question":"ما معنى «المصطفى»؟","options":["المختار المجتبى من بين الخلق","المرسل فقط","العابد","الغائب"],"answer":0,"explanation":"المصطفى من الاصطفاء: الاختيار؛ اختاره الله للرسالة من بين الناس: وصف للرسول محمد صلى الله عليه وسلم."},{"question":"ما ترتيب الأبيات الثلاثة الأولى في المعنى؟","options":["ذكر الله وتسبيحه ثم الصلاة على الرسول ثم تعريف الكتاب","تعريف الكتاب أولًا","الصلاة أولًا","بلا ترتيب"],"answer":0,"explanation":"البيت الأول تسبيح الرب الواحد المعين؛ والثاني صلاة وسلام على الرسول؛ والثالث تعريف بالأرجوزة."}]},{"body":["تدريب إعرابي على البيت: «مصليًا»: حال منصوب بالفتحة، وصاحب الحال ضمير مستتر يعود على القائل (سليمان). «مسلمًا»: حال ثانية منصوبة معطوفة على الأولى... أو حال معطوفة: فالتعدد جائز للحال كما تقدم.","«يا»: حرف نداء مبني على السكون لا محل له من الإعراب. «مبتدي»: منادى مبني على الضمة المقدرة منع من ظهورها الياء، في محل نصب؛ لأنه نكرة مقصودة: يقصد الطالب المبتدئ أمامه.","«على»: حرف جر. «الرسول»: اسم مجرور بعلى وعلامة جره الكسرة. «المصطفى»: نعت للرسول مجرور بالكسرة المقدرة على الألف (لأنه مقصور). «محمد»: بدل من الرسول أو عطف بيان مجرور بالكسرة المقدرة للتعذر (علم ممنوع من الصرف: للعلمية والتعديل).","لماذا قدم المؤلف الصلاة على النبي في أول كتابه؟ لأن الصلاة على النبي سبب للبركة في العمل؛ قال تعالى: «إن الله وملائكته يصلون على النبي يا أيها الذين آمنوا صلوا عليه وسلموا تسليمًا». فافتتاح الكتب بها سنة العلماء.","لاحظ الجرس: مصليًا... مسلمًا: كلمتان من جنس واحد على وزن واحد (مُفَعِّلًا)، وهذا من المحسنات التي تجعل البيت خفيفًا محبوبًا للسان؛ وهو قصد المؤلف في قوله «خفيفة».","تدريب: غيّر الحال إلى جملة: «وأنا أصلي وأسلم على الرسول». وغيّر النداء: «يا طالبَ الهدى» (منادى منصوب مضاف). فالتدريب على صور البيت يثبت معناه."],"examples":["مبتدي: منادى نكرة مقصودة مبني في محل نصب","الرسول: مجرور بعلى","المصطفى: نعت مجرور","محمد: بدل مجرور مقدرة الكسرة","الصلاة على النبي في افتتاح الكتب سنة العلماء","مصليًا ومسلمًا على وزن واحد: محسن بديعي"],"questions":[{"question":"أعرب «مبتدي» في «يا مبتدي»:","options":["منادى مبني على الضمة المقدرة في محل نصب نكرة مقصودة","منصوب بالفتحة","نعت مجرور","فاعل"],"answer":0,"explanation":"مبتدي نكرة يقصد بها الطالب المبتدئ: نكرة مقصودة: منادى مبني على الضمة المقدرة منع من ظهورها الياء في محل نصب."},{"question":"أعرب «الرسول» و«المصطفى» و«محمد»:","options":["الرسول مجرور بعلى والمصطفى نعت مجرور ومحمد بدل مجرور","كلها مرفوعة","كلها منصوبة","فاعل ونعت"],"answer":0,"explanation":"على الرسول: جار ومجرور؛ والمصطفى نعت تبع له؛ ومحمد بدل من الرسول مجرور بالكسرة المقدرة."},{"question":"لم افتتح العلماء كتبهم بالصلاة على النبي؟","options":["طلبًا للبركة وامتثالًا لأمر الله: «صلوا عليه وسلموا تسليمًا»","للزخرفة","للتطويل","عادة بلا سبب"],"answer":0,"explanation":"أمر الله المؤمنين بالصلاة على نبيه؛ فصار افتتاح الكتب بها بعد ذكر الله سنة جارية عند العلماء."},{"question":"ما المحسن اللفظي بين «مصليًا مسلمًا»؟","options":["اتحادهما في الوزن والجنس (مفعِّلًا) مما يخفف اللفظ","الطباق","السجع المتنافر","لا شيء"],"answer":0,"explanation":"الكلمتان على وزن واحد ومعنى متقارب؛ فهذا التناسب من أسباب خفة الأرجوزة على اللسان."},{"question":"حوّل «مصليًا» إلى جملة حالية:","options":["وأنا أصلي على الرسول","لأني صليت","مصلٍّ كان","يا مصلي"],"answer":0,"explanation":"الحال المفردة تتحول إلى جملة حالية: مصليًا = وأنا أصلي؛ والمعنى محفوظ مع واو الحال."}]}]},{"id":"wahi-verse-003","title":"تعريف المنظومة: أرجوزة خفيفة لطيفة","summary":"ما الأرجوزة، ولماذا وصف المؤلف نظمه بأنه خفيف مفيد لطيف.","verse":{"number":3,"section":"المقدمة","text":"وَهَذِهِ أَرْجُوزَةٌ خَفِيفَةْ فِي نَحْوِنَا مُفِيدَةٌ لَطِيفَةْ"},"segments":[{"body":["البيت الثالث: «وَهَذِهِ أَرْجُوزَةٌ خَفِيفَةْ فِي نَحْوِنَا مُفِيدَةٌ لَطِيفَةْ». فيه يعرف المؤلف بكتابه، ونفهمه كلمة كلمة.","«وَهَذِهِ»: الواو حرف عطف أو استئناف؛ و«هذه» اسم إشارة للمفردة القريبة: يشير المؤلف إلى منظومته التي بين أيدينا. «أَرْجُوزَةٌ»: خبر هذه: قصيدة على بحر الرجز. فالجملة اسمية: مبتدأ (هذه) وخبر (أرجوزة).","«خَفِيفَةْ»: نعت لأرجوزة: خفيفة على اللسان سهلة الحفظ؛ فبحر الرجز من أخف بحور الشعر وأقربها إلى الكلام العادي. «فِي نَحْوِنَا»: في علم النحو الخاص بنا نحن النحويين وطلابه؛ وقوله «نحونا» فيه لطف: جعل النحو علمًا مشتركًا بينه وبينك.","«مُفِيدَةٌ لَطِيفَةْ»: نعتان آخران: مفيدة: تجلب لك الفائدة العلمية؛ لطيفة: رقيقة حسنة في نظمها ومعانيها لا غلظة فيها. فوصف كتابه بأربع صفات: خفيفة ومفيدة ولطيفة... والرابعة كونه أرجوزة أصلًا.","بحر الرجز: وزن شعري قالبُه «مستفعلن مستفعلن مستفعلن»، وفي مجزوئه (وهو بحر هذه المنظومة): «مستفعلن مستفعلن». وخفته جعلت العلماء ينظمون فيه المتون التعليمية كثيرًا.","لماذا يعرّف المؤلف بكتابه في المقدمة؟ ليعرف القارئ ماذا بين يديه: جنس الكتاب (أرجوزة)، ومادته (النحو)، وصفته (خفيفة مفيدة لطيفة)؛ فهذه الديباجة الصادقة تفتح شهية الطالب."],"examples":["هذه: اسم إشارة مبتدأ","أرجوزة: خبر مرفوع","خفيفة ومفيدة ولطيفة: نعوت","بحر الرجز: مستفعلن مستفعلن","مجزوء الرجز بحر المنظومة","نحونا: إضافة النحو إلى ضميرنا"],"questions":[{"question":"ما إعراب «هذه» و«أرجوزة»؟","options":["هذه مبتدأ مبني في محل رفع وأرجوزة خبر مرفوع","كلاهما مبتدأ","نعت وموصوف","حال وصاحبها"],"answer":0,"explanation":"هذه اسم إشارة مبني على الكسر في محل رفع مبتدأ؛ وأرجوزة خبره مرفوع بالضمة: جملة اسمية."},{"question":"ما بحر المنظومة؟","options":["مجزوء الرجز","الطويل","البسيط","الكامل"],"answer":0,"explanation":"المنظومة على مجزوء الرجز: مستفعلن مستفعلن؛ وهو من أخف البحور ولذلك كثرت فيه المتون التعليمية."},{"question":"بم وصف المؤلف أرجوزته؟","options":["خفيفة ومفيدة ولطيفة","صعبة مملة","طويلة غامضة","قديمة مكررة"],"answer":0,"explanation":"ثلاث صفات نعوت لأرجوزة: خفيفة (سهلة الحفظ) ومفيدة (نافعة العلم) ولطيفة (حسنة النظم)."},{"question":"ما معنى «في نحونا»؟","options":["في علم النحو الخاص بنا؛ وفي الإضافة لطف ومشاركة للقارئ","في لغتنا العامية","في ديوانه","في كتابه الآخر"],"answer":0,"explanation":"أضاف النحو إلى ضمير المتكلمين (نا): نحونا: علمنا المشترك؛ وفيها تلطف بالطالب وإشراك له."},{"question":"لم يعرف المؤلف بكتابه في المقدمة؟","options":["ليعرف القارئ جنس الكتاب ومادته وصفته فتنفتح شهيته","ليطيل الكتاب","ليمدح نفسه","بلا سبب"],"answer":0,"explanation":"الديباجة الصادقة تبين للطالب ما بين يديه: أرجوزة في النحو خفيفة مفيدة لطيفة؛ فهذا باب المقدمات."}]},{"body":["تدريب إعرابي: «وهذه أرجوزة خفيفة»: الواو استئنافية؛ هذه: اسم إشارة مبني على الكسر في محل رفع مبتدأ؛ أرجوزة: خبر مرفوع بالضمة؛ خفيفة: نعت مرفوع بالضمة.","«في نحونا»: في: حرف جر؛ نحو: اسم مجرور بفي وهو مضاف؛ ونا: ضمير متصل مبني على السكون في محل جر مضاف إليه. «مفيدة لطيفة»: نعتان لأرجوزة مرفوعان بالضمة.","من بلاغة البيت: السجع: خفيفة... لطيفة، وقبلهما مفيدة: فالكلمات الثلاث تنتهي بصوت واحد؛ وهذا السجع من أسباب سهولة الحفظ، وهو مقصود في الأراجيز التعليمية.","قارن: لو قال «هذا نظم» لكان أثقل؛ لكن «أرجوزة خفيفة» كلمة دقيقة: الأرجوزة جنس، وخفيفة صفة تميزها من غيرها من الأراجيز الثقيلة.","تدريب على القياس: صف كتابك أنت: «هذه رسالة نفيسة في عقيدتنا جامعة وافية». فالتركيب: مبتدأ إشارة + خبر + نعوت، هو باب الديباجات.","خلاصة الأبيات الثلاثة: عرف المؤلف بنفسه وسبح ربه (١)، وصلى على نبيه ودعا لقارئه (٢)، وعرف بكتابه وجنسه وصفاته (٣). وهذه سُنّة المقدمات: الاسم والحمد والصلاة ثم الغرض."],"examples":["هذه مبتدأ وأرجوزة خبر وخفيفة نعت","نحو مضاف ونا مضاف إليه","السجع: خفيفة مفيدة لطيفة","المبتدأ إشارة + خبر + نعوت: قالب الديباجة","سنة المقدمات: اسم وحمد وصلاة ثم غرض","مفيدة لطيفة: نعتان مرفوعان"],"questions":[{"question":"أعرب «نا» في «نحونا»:","options":["ضمير متصل مبني في محل جر مضاف إليه","فاعل","نعت","حال"],"answer":0,"explanation":"نحو اسم مجرور بفي مضاف؛ ونا ضمير المتكلمين مضاف إليه في محل جر."},{"question":"ما السجع في البيت وأثره؟","options":["اتفاق فواصل الكلمات (خفيفة مفيدة لطيفة) ويسهل الحفظ","تشابه الأوزان فقط","الجناس","لا شيء"],"answer":0,"explanation":"السجع اتفاق آخر الكلمات في الحرف والحركة؛ وهو في الأراجيز محبوب لأنه يثبت النظم في الذهن."},{"question":"أعرب «لطيفة»:","options":["نعت لأرجوزة مرفوع بالضمة","خبر ثانٍ","حال","مفعول به"],"answer":0,"explanation":"لطيفة صفة ثالثة لأرجوزة: نعت مرفوع بالضمة تبع لموصوفه في الرفع."},{"question":"ما قالب جملة «هذه أرجوزة خفيفة»؟","options":["مبتدأ (اسم إشارة) + خبر + نعت","فعل وفاعل","حرف جر واسم","شرط وجواب"],"answer":0,"explanation":"جملة اسمية: هذه (مبتدأ) أرجوزة (خبر) خفيفة (نعت)؛ وهو قالب جمل التعريف في الديباجات."},{"question":"ما خلاصة وظائف الأبيات الثلاثة؟","options":["تعريف بالمؤلف وتسبيح، ثم صلاة على النبي ودعاء للقارئ، ثم تعريف بالكتاب","ثلاثة أحكام نحوية","قصة كاملة","خاتمة"],"answer":0,"explanation":"البيت الأول اسم وتسبيح؛ والثاني صلاة وسلام ودعاء؛ والثالث تعريف بالأرجوزة وصفاتها."}]}]},{"id":"wahi-verse-004","title":"النحو جزآن: أحكام الكلمة وأحكام الكلام","summary":"موضوع علم النحو وتقسيمه إلى جزأين كبيرين.","verse":{"number":4,"section":"موضوع النحو وترتيبه","text":"اَلنَّحْوُ -يَا وَفَّقَكَ اللهُ- عَلَى جُزْأَيْنِ، فَافْهَمِ الْكَلِمَ أَوَّلَا"},"segments":[{"body":["البيت الرابع: «اَلنَّحْوُ -يَا وَفَّقَكَ اللهُ- عَلَى جُزْأَيْنِ، فَافْهَمِ الْكَلِمَ أَوَّلَا». أول بيت في صلب العلم، ونفهمه كلمة كلمة.","«اَلنَّحْوُ»: مبتدأ، وهو علم القواعد التي نعرف بها أحوال أواخر الكلم: إعرابها وبناءها. «-يَا وَفَّقَكَ اللهُ-»: جملة اعتراضية: يا من وفقك الله، أي: يا من أعانك الله على الفهم؛ دعاء للطالب في أثناء الكلام. «عَلَى جُزْأَيْنِ»: خبر المبتدأ: النحو مبني على جزأين اثنين. «فَافْهَمِ»: الفاء تفريع، وافهم: فعل أمر. «الْكَلِمَ»: مفعول به منصوب: الكلمات. «أَوَّلَا»: ظرف: في البداية.","فالمعنى: علم النحو -يا من وفقك الله- ينقسم إلى جزأين كبيرين، فافهم -أيها الطالب- أحكام الكلمات أولًا قبل الجمل.","ما الجزآن؟ الأول: أحكام الكلمة الواحدة: نوعها (اسم أم فعل أم حرف) وأقسامها وإعرابها وبناؤها وعلاماتها. والثاني: أحكام الكلام: الجمل وأركانها وما يكملها.","لماذا قدم الكلمات؟ لأن الجملة مبنية من كلمات؛ فمن لم يعرف الكلمة ونوعها لم يفهم الجملة؛ فترتيب الدراسة من الأصغر إلى الأكبر: حرف، فكلمة، فجملة.","وموضوع علم النحو عند العلماء: الكلمة والكلام من حيث الإعراب والبناء؛ فكل مباحث الكتاب ترجع إلى هذين: حكم يخص الكلمة وحدها، أو حكم يخص تركيبها في الكلام."],"examples":["النحو: مبتدأ وعلى جزأين: خبر","يا وفقك الله: جملة اعتراضية دعائية","فافهم الكلم أولًا: فعل أمر ومفعول وظرف","الجزء الأول: أحكام الكلمة","الجزء الثاني: أحكام الكلام","الترتيب: من الكلمة إلى الجملة"],"questions":[{"question":"إلى كم جزء قسم المؤلف النحو؟","options":["جزأين: أحكام الكلمة وأحكام الكلام","ثلاثة","أربعة","جزء واحد"],"answer":0,"explanation":"النحو على جزأين: ما يخص الكلمة الواحدة، وما يخص تركيبها في الكلام."},{"question":"ما معنى «يا وفقك الله»؟","options":["جملة اعتراضية فيها دعاء للطالب بالتوفيق","فاعل الجملة","نعت للنحو","بيت مستقل"],"answer":0,"explanation":"كلام معترض بين الشطرين: يا من وفقه الله للفهم؛ دعاء من المؤلف للطالب، كما ناداه بـ«يا مبتدي» سابقًا."},{"question":"لم قدم المؤلف فهم الكلم على الكلام؟","options":["لأن الجمل مبنية من الكلمات فمن فهم الكلمة سهل عليه فهم الجملة","لأنها أطول","بلا سبب","لأن الجمل سهلة"],"answer":0,"explanation":"الترتيب التعليمي من الأصغر إلى الأكبر: الكلمة لبنة الكلام؛ فافهم الكلم أولًا."},{"question":"ما إعراب «الكلم» في «فافهم الكلم أولًا»؟","options":["مفعول به منصوب بالفتحة","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"افهم: فعل أمر مبني على حذف حرف العلة والفاعل مستتر تقديره أنت؛ والكلم مفعول به منصوب."},{"question":"ما موضوع علم النحو؟","options":["الكلمة والكلام من حيث الإعراب والبناء","القراءة","البلاغة","الفقه"],"answer":0,"explanation":"موضوع النحو: الكلمة والكلام من جهة إعرابها وبنائها؛ وعليه بني تقسيم الكتاب كله."}]},{"body":["تدريب إعرابي: «النحو على جزأين»: النحو: مبتدأ مرفوع بالضمة؛ على: حرف جر؛ جزأين: اسم مجرور بعلى وعلامة جره الياء لأنه مثنى (جزآن: جزء + ياء ونون المثنى)؛ والجار والمجرور خبر المبتدأ.","«فافهم الكلم أولًا»: الفاء: حرف تفريع (تربط الأمر بما قبله: إذا عرفت أنه جزآن فافهم...)؛ افهم: فعل أمر مبني على حذف حرف العلة (أصله افهمُ) والفاعل مستتر تقديره أنت؛ الكلم: مفعول به منصوب؛ أولًا: ظرف زمان منصوب... أو نعت لمصدر محذوف.","جملة الدعاء «وفقك الله»: وفق: فعل ماضٍ، والكاف: مفعول به، واسم الله: فاعل مؤخر؛ والجملة في محل نصب نعتًا لضمير المخاطب في «يا»... والأظهر: جملة اعتراضية دعائية لا محل لها.","قاعدة الاعتراض: الجملة الاعتراضية تكون بين قوسين أو شرطتين، وتخرج عن سياق الكلام لدعاء أو تنبيه أو تعليل، ثم يعود الكلام إلى سياقه؛ مثل: «النحو -يا وفقك الله- على جزأين».","تطبيق: قسّم ما تعلمته سابقًا: معرفتك أن «زيد» اسم: من أحكام الكلمة؛ ومعرفتك أن «قام زيد» جملة فعلية: من أحكام الكلام. فكل قاعدة آتية ضعها في جزئها.","خلاصة: البيت الرابع باب الكتاب: قسم النحو إلى أحكام كلمة وأحكام كلام، وأمرك أن تبدأ بالكلمات؛ فالدروس القادمة تتبع هذا الترتيب: أنواع الكلمة، فأقسامها، ثم أحكام الكلام الأربعة."],"examples":["جزأين: مجرور بعلى بالياء لأنه مثنى","افهم: أمر مبني على حذف حرف العلة","الفاء في فافهم: تفريع","الاعتراضية تخرج عن السياق لدعاء أو تنبيه","وفقك الله: فعل ومفعول وفاعل","ضع كل قاعدة في جزئها"],"questions":[{"question":"أعرب «جزأين»:","options":["اسم مجرور بعلى وعلامة جره الياء لأنه مثنى","مرفوع بالألف","منصوب بالفتحة","مبتدأ"],"answer":0,"explanation":"جزآن مثنى جزء: المثنى يجر بالياء: على جزأين؛ والجار والمجرور خبر المبتدأ (النحو)."},{"question":"أعرب «افهم»:","options":["فعل أمر مبني على حذف حرف العلة والفاعل مستتر تقديره أنت","ماضٍ","مضارع مرفوع","اسم"],"answer":0,"explanation":"افهم أصله افهمُ: فعل أمر من فهم يفهم؛ بني على حذف الواو (حرف العلة)؛ والفاعل ضمير مستتر: أنت."},{"question":"ما الفاء في «فافهم»؟","options":["فاء التفريع: تفرع الأمر عما قبله","فاء الفاء","حرف عطف","فاء السببية فقط"],"answer":0,"explanation":"لما بيّن أن النحو جزآن فرّع عليه الأمر بفهم الكلم أولًا: فهي فاء تفريع وتعليل."},{"question":"ما الجملة الاعتراضية وما وظيفتها؟","options":["جملة تتخلل الكلام بين شرطتين لدعاء أو تنبيه ثم يعود السياق","جملة فعلية عادية","جواب شرط","نعت"],"answer":0,"explanation":"مثل «يا وفقك الله» و«يا مبتدي»: تقطع السياق لغرض بلاغي (دعاء أو نداء) ولا تغير إعراب ما حولها."},{"question":"أعرب «الله» في «وفقك الله»:","options":["فاعل مرفوع مؤخر","مفعول به","مبتدأ","مضاف إليه"],"answer":0,"explanation":"وفق: فعل ماضٍ؛ الكاف مفعول به مقدم؛ واسم الله فاعل مرفوع مؤخر: وفقك الله = الله وفقك."}]}]},{"id":"wahi-verse-005","title":"الجزء الأول: أحكام الكلمة وأقسامها","summary":"مباحث أحكام الكلمة الثلاثة: أنواع الكلمة، النكرة والمعرفة، المعرب والمبني.","verse":{"number":5,"section":"موضوع النحو وترتيبه","text":"فَالْأَوَّلُ الْكَلِمَةُ فِي أَحْكَامِهَا: أَنْوَاعُهَا فِي النَّحْوِ، وَأَقْسَامُهَا"},"segments":[{"body":["البيت الخامس: «فَالْأَوَّلُ الْكَلِمَةُ فِي أَحْكَامِهَا: أَنْوَاعُهَا فِي النَّحْوِ، وَأَقْسَامُهَا». يفصل الجزء الأول من جزأي النحو، ونفهمه كلمة كلمة.","«فَالْأَوَّلُ»: الفاء تفصيل لما أجمل قبله (جزأين)؛ والأول: مبتدأ: الجزء الأول. «الْكَلِمَةُ»: خبره... أي: الجزء الأول هو (باب) الكلمة. «فِي أَحْكَامِهَا»: أي: الأول مختص بأحكام الكلمة؛ والهاء تعود على الكلمة.","«أَنْوَاعُهَا فِي النَّحْوِ»: بدل أو بيان: ما هذه الأحكام؟ أولها أنواع الكلمة في علم النحو: اسم وفعل وحرف. «وَأَقْسَامُهَا»: معطوف: وأقسامها أيضًا، أي تقسيمات الكلمة الأخرى.","فالمعنى: الجزء الأول من النحو هو النظر في أحكام الكلمة الواحدة؛ وأحكامها ثلاثة مباحث: أنواعها (اسم وفعل وحرف)، وأقسامها الأخرى (نكرة ومعرفة، معرب ومبني)، وما يتبع ذلك من العلامات.","ترتيب المباحث الثلاثة في الدروس القادمة: أولًا: أنواع الكلمة الثلاثة وضوابطها (الأبيات 8-11). ثانيًا: انقسام الاسم إلى نكرة ومعرفة وأنواع المعرفة الستة والضمائر (الأبيات 12-17). ثالثًا: المعرب والمبني والأحكام الأربعة وعلامات الإعراب (الأبيات 18-45).","فائدة التقسيم: العلم إذا قسم صغُرت أجزاؤه في الذهن فسهل إحاطتك به؛ فبدل أن تقول: أريد تعلم النحو كله دفعة واحدة، تعلمه بابًا بابًا؛ وهذا منهج العلماء في تصانيفهم كلها."],"examples":["الفاء للتفصيل بعد الإجمال","الأول مبتدأ والكلمة خبره","أنواعها: اسم وفعل وحرف","أقسامها: نكرة ومعرفة، معرب ومبني","الترتيب: أنواع فمعرفة ونكرة فمعرب ومبني","التقسيم يسهل الإحاطة بالعلم"],"questions":[{"question":"ما الجزء الأول من النحو وما مباحثه؟","options":["أحكام الكلمة: أنواعها وأقسامها","الجمل الفعلية","الإعراب التطبيقي","البلاغة"],"answer":0,"explanation":"الأول الكلمة في أحكامها: أنواعها في النحو (اسم وفعل وحرف) وأقسامها (نكرة ومعرفة ومعرب ومبني)."},{"question":"ما الفاء في «فالأول»؟","options":["فاء تفصيل لما أجمل من قوله جزأين","عطف","سببية","استئناف"],"answer":0,"explanation":"لما أجمل قوله «على جزأين» فصلهما: فالأول... والآخر...: فهي فاء التفصيل."},{"question":"ما ترتيب مباحث أحكام الكلمة في المنظومة؟","options":["أنواع الكلمة ثم النكرة والمعرفة ثم المعرب والمبني وعلامات الإعراب","المعرب أولًا","الجمل أولًا","عشوائي"],"answer":0,"explanation":"يبدأ بأنواع الكلمة الثلاثة، ثم انقسام الاسم نكرة ومعرفة، ثم المعرب والمبني والأحكام وعلامات الإعراب."},{"question":"ما فائدة تقسيم العلم إلى أجزاء؟","options":["يصغُر كل جزء في الذهن فيسهل إتقانه بابًا بابًا","للتطويل","لا فائدة","للحفظ فقط دون فهم"],"answer":0,"explanation":"التقسيم منهج العلماء: يحول العلم الكبير إلى أبواب صغيرة محكمة الترتيب فيتقنها الطالب واحدًا واحدًا."},{"question":"أعرب «أحكامها»:","options":["أحكام مجرور بفي مضاف والهاء مضاف إليه","مبتدأ","نعت للكلمة","مفعول به"],"answer":0,"explanation":"في أحكامها: أحكام اسم مجرور بفي مضاف؛ والهاء ضمير مضاف إليه يعود على الكلمة."}]},{"body":["تدريب: لو سئلت: ما نوع كلمة «كتب»؟ فأجبت: فعل ماضٍ؛ فأنت تتكلم في أحكام الكلمة. ولو قلت: «كتب الطالب الدرس» جملة فعلية ركنها الفعل والفاعل؛ فأنت في أحكام الكلام.","الضابط العملي: انظر وحدة الكلام: كلمة مفردة؟ فالحكم من الجزء الأول. جملة أو تركيب؟ فالحكم من الجزء الثاني. مثال: «الكتابُ»: أحكامه (اسم، معرفة، معرب، مرفوع) كلها من الجزء الأول.","الكلمة الواحدة قد تجمع أحكامًا كثيرة من الجزء الأول: «المسلمونَ»: اسم، معرفة بأل، معرب، جمع مذكر سالم، يرفع بالواو. كل باب منها سيأتي له درس.","تنبيه: «أنواعها في النحو»: قيدها بـ«في النحو» لأن للكلمة أنواعًا في علوم أخرى: ففي الصرف: مجرد ومزيد؛ وفي البلاغة: حقيقة ومجاز؛ لكن أنواعها في النحو ثلاثة فقط: اسم وفعل وحرف.","تدريب تصنيفي: ضع كل كلمة في نوعها: محمد (اسم)، كتب (فعل)، على (حرف)، يذهب (فعل)، القلم (اسم)، هل (حرف). هذا أول تمرين في أحكام الكلمة.","خلاصة: الجزء الأول يدرس الكلمة: نوعها وأقسامها وإعرابها وعلاماتها؛ وهو القاعدة التي يبنى عليها الجزء الثاني كله؛ فأتقنه يَسُرْ عليك ما بعده."],"examples":["كتب: فعل؛ حكم من الجزء الأول","كتب الطالب الدرس: جملة؛ حكم من الجزء الثاني","المسلمون: اسم معرفة معرب جمع سالم","أنواع الكلمة في النحو ثلاثة فقط","في الصرف: مجرد ومزيد؛ في البلاغة: حقيقة ومجاز","محمد اسم، على حرف، يذهب فعل"],"questions":[{"question":"«كتب» إلى أي جزء ينتمي الحكم عليها بأنها فعل؟","options":["أحكام الكلمة (الجزء الأول)","أحكام الكلام","لا ينتمي","الجزء الثالث"],"answer":0,"explanation":"الحكم على الكلمة المفردة بنوعها من أحكام الكلمة؛ أما تركيبها في جملة فمن أحكام الكلام."},{"question":"لم قيد المؤلف الأنواع بقوله «في النحو»؟","options":["لأن للكلمة أنواعًا أخرى في علوم غير النحو","للزينة","للقافية فقط","احتراز من الجمل"],"answer":0,"explanation":"في الصرف تقسم مجردًا ومزيدًا، وفي البلاغة حقيقة ومجازًا؛ أما في النحو فثلاثة: اسم وفعل وحرف."},{"question":"صنف: «يذهب» و«القلم» و«على»:","options":["فعل مضارع واسم معرفة وحرف جر","كلها أسماء","كلها أفعال","كلها حروف"],"answer":0,"explanation":"يذهب: فعل مضارع لقبوله لم؛ والقلم: اسم لقبوله أل؛ وعلى: حرف جر لا يقبل شيئًا من ذلك."},{"question":"كم نوعًا للكلمة في النحو؟","options":["ثلاثة: اسم وفعل وحرف","اثنان","أربعة","خمسة"],"answer":0,"explanation":"سيأتي في البيت الثامن: كل الكلام لو نظرت معناه اسم وفعل ثم حرف معنى."},{"question":"ما العلاقة بين الجزء الأول والثاني؟","options":["الأول قاعدة يبنى عليها الثاني","مستقلان تمامًا","الثاني أول","لا علاقة"],"answer":0,"explanation":"من لم يعرف الكلمة ونوعها لم يفهم الجملة؛ فأحكام الكلام مبنية على أحكام الكلمة."}]}]},{"id":"wahi-verse-006","title":"الجزء الثاني: أحكام الكلام","summary":"المباحث الأربعة في أحكام الكلام: الجملة الفعلية، الجملة الاسمية، المكملات، وإعراب المضارع.","verse":{"number":6,"section":"موضوع النحو وترتيبه","text":"وَالْآخَرُ قَدْ جَاءَ لِلْكَلَامِ فِي أَرْبَعِ مُنْتَظِمِ الْأَقْسَامِ"},"segments":[{"body":["البيت السادس: «وَالْآخَرُ قَدْ جَاءَ لِلْكَلَامِ فِي أَرْبَعِ مُنْتَظِمِ الْأَقْسَامِ». يفصل الجزء الثاني من جزأي النحو، ونفهمه كلمة كلمة.","«وَالْآخَرُ»: معطوف على «الأول» في البيت السابق: الجزء الآخر من جزأي النحو. «قَدْ جَاءَ»: قد حرف تحقيق، وجاء فعل ماضٍ؛ أي: هذا الجزء قد جاء مصنفًا في هذا الكتاب.","«لِلْكَلَامِ»: اللام للاختصاص: جاء مختصًا بأحكام الكلام، أي الجمل. «فِي أَرْبَعِ»: أي في أربعة أقسام؛ والألف والتاء محذوفة تخفيفًا للوزن (أربع: أصلها أربعة، حذفت الهاء للضرورة الشعرية).","«مُنْتَظِمِ الْأَقْسَامِ»: منتظم: نعت منصوب بالفتحة: أقسام مرتبة منضبطة بعضها في إثر بعض؛ والأقسام: مضاف إليه مجرور.","فالمعنى: والجزء الآخر -وهو أحكام الكلام- قد جاء في هذا الكتاب في أربعة أقسام منتظمة مرتبة.","ما الكلام؟ عند النحويين: اللفظ المركب المفيد بالوضع: أن تقول كلمتين أو أكثر بينهما إسناد يفيد السامع: «قام زيد»، «العلم نور». فالكلام هو الجملة المفيدة، وهو موضوع الجزء الثاني."],"examples":["الآخر معطوف على الأول","قد: حرف تحقيق","للكلام: مختص بأحكام الجمل","أربع: حذفت التاء للوزن","منتظم الأقسام: مرتبة منضبطة","الكلام: اللفظ المركب المفيد بالوضع"],"questions":[{"question":"ما الجزء الآخر من النحو وفي كم قسم جاء؟","options":["أحكام الكلام في أربعة أقسام منتظمة","أحكام الكلمة في ثلاثة","الصرف","قسم واحد"],"answer":0,"explanation":"والآخر قد جاء للكلام في أربع منتظم الأقسام: أحكام الكلام في أربعة أقسام مرتبة."},{"question":"ما معنى «قد جاء»؟","options":["قد للتحقيق مع الماضي: جاء تحققًا ووقع","قد للتقليل","استقبال","نهي"],"answer":0,"explanation":"قد مع الفعل الماضي للتحقيق: هذا الجزء قد جاء فعلًا في هذا التصنيف."},{"question":"ما تعريف الكلام عند النحويين؟","options":["اللفظ المركب المفيد بالوضع","كل كلمة","الصوت","الحرف"],"answer":0,"explanation":"قام زيد: لفظ مركب من كلمتين بينهما إسناد أفاد السامع؛ فهو كلام؛ وهو موضوع أحكام الكلام."},{"question":"لم حذفت تاء «أربع»؟","options":["للضرورة الشعرية: ضبط الوزن","خطأ مطبعي","للإبهام","قاعدة إلزامية"],"answer":0,"explanation":"أصلها أربعة؛ حذفت الهاء تخفيفًا ليلائم الوزن؛ والضرورة جائزة في الشعر دون النثر."},{"question":"أعرب «منتظم»:","options":["نعت منصوب بالفتحة لـ«أربع» المحذوفة التاء... أو حال","مرفوع","مجرور","مبتدأ"],"answer":0,"explanation":"منتظم وصف للأقسام الأربع بأنها مرتبة: نعت منصوب بالفتحة؛ والأقسام مضاف إليه مجرور."}]},{"body":["ما الأقسام الأربعة؟ يبينها البيت التالي: الجملة الفعلية، والجملة الاسمية، والمكملات، وإعراب الفعل المضارع مفصلًا. فثلاثة منها أبواب جمل، والرابع باب إعرابي جامع.","لماذا سميت مكملات؟ لأنها تتمم الجملتين الفعلية والاسمية بعد اكتمال أركانهما: كالمفاعيل والحال والتمييز والمستثنى والمنادى والمجرورات والتوابع.","ولم أفرد المضارع؟ لأن إعرابه (رفعًا ونصبًا وجزمًا) يحتاج ضبط أدواته: نواصبه وجوازمه؛ فجعله المؤلف قسمًا مستقلًا تتجمع فيه الأدوات كلها.","تدريب على الكلام: أي مما يلي كلام؟ «العلمُ نافعٌ»: كلام (جملة اسمية مفيدة). «إنْ»: ليس كلامًا (لفظ غير مفيد وحده). «ذهبَ المعلمُ»: كلام (جملة فعلية). «من فوق»: شبه جملة لا تفيد وحدها... فليست كلامًا تامًّا.","فائدة: قوله «منتظم الأقسام» إشارة إلى منهج الكتاب: كل باب يبنى على الذي قبله؛ فالفعلية قبل الاسمية لأن الفعل أظهر، والمكملات بعدهما لأنها تابعة لهما، والمضارع آخرًا لأنه جامع.","خلاصة البيتين الخامس والسادس: الجزء الأول أحكام الكلمة بمباحثها، والجزء الآخر أحكام الكلام في أربعة أقسام منتظمة؛ وهذا فهرس الكتاب كله في بيتين."],"examples":["الأقسام الأربعة: فعلية واسمية ومكملات ومضارع","المكملات تتمم الجملتين بعد أركانهما","المضارع قسم مستقل لضبط أدواته","العلم نافع: كلام مفيد","من فوق: شبه جملة ليست كلامًا","فهرس الكتاب في بيتين"],"questions":[{"question":"ما الأقسام الأربعة لأحكام الكلام؟","options":["الفعلية والاسمية والمكملات وإعراب المضارع","النكرة والمعرفة","الرفع والنصب","الماضي والأمر"],"answer":0,"explanation":"فعلية وأسمية ومكمله وأربع المضارع المفصله: كما يبين البيت السابع تفصيلًا."},{"question":"لم سمي القسم الثالث مكملات؟","options":["لأنها تتمم الجملتين الفعلية والاسمية بعد اكتمال أركانهما","لأنها أفعال","لأنها حروف","لأنها أركان"],"answer":0,"explanation":"المفاعيل والحال والتمييز والمستثنى والمنادى والمجرورات والتوابع: كلها زيادات تكمل الجمل."},{"question":"لم أفرد المؤلف إعراب المضارع قسمًا رابعًا؟","options":["ليجمع فيه نواصب المضارع وجوازمه ومرفوعاته ضبطًا","لأنه مبني","لأنه ليس فعلًا","للقافية"],"answer":0,"explanation":"المضارع يدخله الرفع والنصب والجزم بأدوات كثيرة؛ فجعل له قسمًا مستقلًا تتجمع فيه أدواته."},{"question":"أيها كلام مفيد؟","options":["ذهب المعلم","إن","من فوق","يا"],"answer":0,"explanation":"ذهب المعلم: جملة فعلية أفادت السامع؛ أما الحرف وشبه الجملة وحدهما فلا يستقلان بالفائدة."},{"question":"ما وجه ترتيب الأقسام الأربعة؟","options":["الفعلية أظهر فقدمت، والمكملات تبع للجملتين، والمضارع جامع فأخر","عشوائي","أبجدي","بالطول"],"answer":0,"explanation":"قوله «منتظم الأقسام»: رتبها ترتيبًا تعليميًّا: جملة فعلية فاسمية فما يكملهما فإعراب المضارع الجامع."}]}]},{"id":"wahi-verse-007","title":"تفصيل الأقسام الأربعة لأحكام الكلام","summary":"فعلية وأسمية ومكملات، وأحكام المضارع المفصلة رفعًا ونصبًا وجزمًا.","verse":{"number":7,"section":"موضوع النحو وترتيبه","text":"فِعْلِيَّةٍ وَأَسْمِيَّةٍ وَمُكْمِلَهْ وَأَرْبُعِ الْمُضَارِعِ الْمُفَصَّلَهْ"},"segments":[{"body":["البيت السابع: «فِعْلِيَّةٍ وَأَسْمِيَّةٍ وَمُكْمِلَهْ وَأَرْبُعِ الْمُضَارِعِ الْمُفَصَّلَهْ». يعدد الأقسام الأربعة لأحكام الكلام، ونفهمه كلمة كلمة.","«فِعْلِيَّةٍ»: أي: القسم الأول: أحكام الجملة الفعلية، وهي الجملة التي تبدأ بفعل: «قام زيد»، «يكتب الطالب». «وَأَسْمِيَّةٍ»: والقسم الثاني: أحكام الجملة الاسمية، وهي التي تبدأ باسم: «العلم نور»، «المسلم صادق».","«وَمُكْمِلَهْ»: والقسم الثالث: أحكام المكملات، وهي ما يكمل الجملتين بعد أركانهما؛ حذفت التاء (مكملة) للوزن كما حذفت في «أربع».","«وَأَرْبُعِ»: والقسم الرابع... حذفت أيضًا هاء التأنيث (أربعة) للوزن؛ والمعنى: والقسم الرابع. «الْمُضَارِعِ»: مضاف إليه: قسم الفعل المضارع. «الْمُفَصَّلَهْ»: نعت: المضارع المفصَّل، أي الذي فصلت أحكامه وأدواته؛ وحذفت التاء للوزن أيضًا.","فالمعنى: أقسام أحكام الكلام أربعة: أحكام الجملة الفعلية، وأحكام الجملة الاسمية، وأحكام المكملات، والقسم الرابع: إعراب الفعل المضارع مفصلًا.","لاحظ بلاغة النظم: حذف التاء في ثلاث كلمات (مكمله، أربع، المفصله) ليستقيم الوزن، والمعنى باق واضح؛ وهذا من خفة الرجز: يحتمل الحذف اليسير دون اختلال الفهم."],"examples":["فعلية: تبدأ بفعل: قام زيد","اسمية: تبدأ باسم: العلم نور","مكمله: المكملات؛ حذفت التاء للوزن","أربع: القسم الرابع","المضارع المفصل: باب نواصبه وجوازمه","حذف التاء ثلاثًا لضبط الوزن"],"questions":[{"question":"عدد الأقسام الأربعة كما في البيت:","options":["الجملة الفعلية والجملة الاسمية والمكملات وإعراب المضارع المفصل","الماضي والمضارع والأمر","النكرة والمعرفة","الرفع والنصب والجر"],"answer":0,"explanation":"فعلية وأسمية ومكمله وأربع المضارع المفصله: أربعة أقسام لأحكام الكلام."},{"question":"ما الجملة الفعلية وما الجملة الاسمية؟","options":["الفعلية تبدأ بفعل والاسمية تبدأ باسم","بالعكس","كلتاهما تبدأ بفعل","لا فرق"],"answer":0,"explanation":"قام زيد: فعلية؛ العلم نور: اسمية؛ والتمييز بأول الجملة."},{"question":"لم حذفت التاء من «مكمله وأربع والمفصله»؟","options":["للضرورة الشعرية: ضبط وزن الرجز","خطأ","اختصار معنى","قاعدة نحوية واجبة"],"answer":0,"explanation":"التاء المحذوفة تاء التأنيث؛ حذفها ضرورة للوزن والمعنى باق؛ وهذا مألوف في الأراجيز."},{"question":"ما معنى «المضارع المفصل»؟","options":["الفعل المضارع الذي فصلت أدوات إعرابه نواصب وجوازم","المضارع المبني","الماضي","الأمر"],"answer":0,"explanation":"القسم الرابع يفصل إعراب المضارع: نواصبه العشرة وجوازمه الخمسة ومواضع رفعه."},{"question":"أعرب «فعلية» في البيت:","options":["خبر مبتدأ محذوف تقديره الأقسام فعلية... مرفوع","مفعول به","حال","مجرور"],"answer":0,"explanation":"التقدير: الأقسام فعلية وأسمية...: فعلية خبر مبتدأ محذوف مرفوع بالضمة؛ والمعطوفات عليه مرفوعة."}]},{"body":["تدريب التصنيف: صنف الجمل: «يكرم المؤمن والديه»: فعلية (بدأت بفعل مضارع). «الصدق منجاة»: اسمية. «جاء الطلاب إلا كسلان»: فعلية معها مكمل (استثناء). «لن يهمل المجتهد»: مضارع منصوب بلن: من باب المضارع.","كل قسم من الأربعة له دروسه القادمة: الفعلية: الفعل وأنواعه والفاعل ونائب الفاعل؛ والاسمية: المبتدأ والخبر ونواسخها؛ والمكملات: المفاعيل الخمسة والحال والتمييز والاستثناء والنداء والمجرورات والتوابع؛ والمضارع: نواصبه وجوازمه ومرفوعاته.","فائدة العد بالأسماء لا بالأرقام: قال «فعلية وأسمية» ولم يقل الأول والثاني؛ لأن التسمية أوقع في الذهن وأبعد عن اللبس؛ فاحفظ الأقسام بأسمائها.","تنبيه: «المكملات» تشمل منصوبات ومجرورات وتوابع؛ فلا تظننها المفاعيل فقط؛ بل كل ما زاد على ركني الجملتين.","أمثلة محفوظة للأقسام: الفعلية: «ينزل القرآن من الله». الاسمية: «القرآن نور». المكملات: «أكرم والديك إحسانًا». المضارع: «المسلم لن يعبد إلا الله».","خلاصة فهرس الكتاب: أحكام الكلمة (أنواع، نكرة ومعرفة، معرب ومبني، علامات) ثم أحكام الكلام الأربعة؛ فهذا البيت مع السابقين خريطة الدورة كلها: احفظها تهدك الطريق."],"examples":["يكرم المؤمن والديه: فعلية","الصدق منجاة: اسمية","المكملات: منصوبات ومجرورات وتوابع","لن يهمل: من باب المضارع","التسمية أوقع من الترقيم","خريطة الدورة في ثلاثة أبيات"],"questions":[{"question":"صنف: «الصدق منجاة»:","options":["جملة اسمية","فعلية","مكملة","مضارع"],"answer":0,"explanation":"بدأت باسم (الصدق) فهي اسمية: مبتدأ وخبر؛ وهي من القسم الثاني."},{"question":"ماذا تشتمل أبواب المكملات؟","options":["المفاعيل الخمسة والحال والتمييز والاستثناء والنداء والمجرورات والتوابع","المبتدأ فقط","الفعل وفاعله","الحروف"],"answer":0,"explanation":"المكملات كل ما زاد على ركني الجملتين: منصوبات ومجرورات وتوابع؛ وليست المفاعيل وحدها."},{"question":"لم عدّ المؤلف الأقسام بأسمائها لا بأرقامها؟","options":["لأن التسمية أثبت في الذهن وأبعد عن اللبس","للقافية فقط","لا سبب","لأن الأرقام حرام"],"answer":0,"explanation":"قوله فعلية وأسمية ومكمله: سمى كل قسم باسمه؛ فالاسم يدل على مضمون القسم مباشرة."},{"question":"«ينزل القرآن من الله» من أي قسم؟","options":["الجملة الفعلية","الاسمية","المكملات","المضارع المفصل"],"answer":0,"explanation":"بدأت بفعل مضارع (ينزل) وفاعله (القرآن): جملة فعلية؛ والجار والمجرور متعلق بالفعل."},{"question":"ما موضع «المسلم لن يعبد إلا الله» من الأقسام؟","options":["إعراب المضارع: يعبد منصوب بلن","الاسمية","المكملات","المعرب والمبني"],"answer":0,"explanation":"المضارع بعد لن منصوب؛ وهذا من القسم الرابع: إعراب المضارع المفصل."}]}]},{"id":"wahi-verse-008","title":"أنواع الكلمة ثلاثة: اسم وفعل وحرف","summary":"كل كلام العرب لا يخرج عن اسم أو فعل أو حرف معنى.","verse":{"number":8,"section":"أنواع الكلمة","text":"كُلُّ الْكَلَامِ لَوْ نَظَرْتَ مَعْنَاهْ اِسْمٌ وَفِعْلٌ ثُمَّ حَرْفُ مَعْنَى"},"segments":[{"body":["البيت الثامن: «كُلُّ الْكَلَامِ لَوْ نَظَرْتَ مَعْنَاهْ اِسْمٌ وَفِعْلٌ ثُمَّ حَرْفُ مَعْنَى». به يبدأ أول مباحث أحكام الكلمة: أنواعها، ونفهمه كلمة كلمة.","«كُلُّ»: مبتدأ مضاف. «الْكَلَامِ»: مضاف إليه مجرور: أي جميع الكلام الذي نتكلم به. «لَوْ نَظَرْتَ مَعْنَاهْ»: لو حرف شرط: لو تأملت وتدبرت معناه؛ والهاء تعود على الكلام.","«اِسْمٌ وَفِعْلٌ»: جواب الشرط محذوف تقديره: لوجدته اسمًا وفعلًا... أي: الكلام كله ينقسم إلى اسم وفعل. «ثُمَّ»: حرف عطف للترتيب مع مهلة... وهنا للترتيب الرتبي: النوع الثالث أخف وأدنى. «حَرْفُ مَعْنَى»: النوع الثالث: الحرف الدال على معنى.","فالمعنى: جميع كلام العرب -لو تأملته- لا يخرج عن ثلاثة أنواع: اسم، وفعل، وحرف دال على معنى.","لم سمي «حرف معنى»؟ لأن الحرف لا يدل على معنى في نفسه (كالاسم: قلم، والفعل: كتب)؛ بل يدل على معنى في غيره: «في» تدل على الظرفية، «من» على الابتداء؛ فمعناه يظهر فيما يتصل به.","هذه القسمة قسمة حصر: لا تجد كلمة رابعة في كلام العرب؛ جرب: محمد (اسم)، كتب (فعل)، على (حرف)، هل (حرف)، يقرأ (فعل)، القلم (اسم)... فالأنواع ثلاثة لا رابع لها."],"examples":["كل الكلام: مبتدأ مضاف ومضاف إليه","لو نظرت معناه: شرطية: لو تأملته","اسم وفعل ثم حرف معنى","الحرف يدل على معنى في غيره","قسمة حصر: لا رابع لها","محمد اسم، كتب فعل، على حرف"],"questions":[{"question":"على كم نوع ينقسم كلام العرب؟","options":["ثلاثة: اسم وفعل وحرف معنى","نوعان","أربعة","خمسة"],"answer":0,"explanation":"كل الكلام لو نظرت معناه اسم وفعل ثم حرف معنى: قسمة حصرية لا رابع لها."},{"question":"لم سمي الحرف «حرف معنى»؟","options":["لأنه يدل على معنى في غيره لا في نفسه","لأنه بلا معنى","لأنه اسم","لأنه فعل"],"answer":0,"explanation":"في ومن وعلى: معانيها (ظرفية وابتداء واستعلاء) لا تظهر إلا مع ما يتصل بها من الأسماء والأفعال."},{"question":"ما معنى «لو نظرت معناه»؟","options":["لو تأملت وتدبرت معنى الكلام","لو رأيته بعينك","لو سمعته فقط","لو نسيته"],"answer":0,"explanation":"لو حرف شرط بمعنى التعليق: لو تأملت الكلام لوجدته منقسمًا إلى الأنواع الثلاثة."},{"question":"ما وجه «ثم» في البيت؟","options":["للترتيب الرتبي: الحرف أدنى الأنواع مرتبة","للعطف المحض","للاستئناف","للتفصيل"],"answer":0,"explanation":"ثم للترتيب مع مهلة؛ واستعملت هنا لأن الحرف أخف الأنواع وأتبعها خدمة للاسم والفعل."},{"question":"صنف: «هل» و«يقرأ» و«القلم»:","options":["حرف وفعل مضارع واسم معرفة","كلها أسماء","كلها حروف","فعل وحرف واسم معكوسة"],"answer":0,"explanation":"هل: حرف استفهام؛ يقرأ: فعل مضارع؛ القلم: اسم معرف بأل؛ فكل كلمة تدخل في واحد من الثلاثة."}]},{"body":["تدريب الحصر: خذ آية أو بيتًا وصنف كلماته: «بسم الله الرحمن الرحيم»: بسم: اسم (همزته قطع مضمومة)... الله: اسم؛ الرحمن: اسم نعت؛ الرحيم: اسم نعت. فالآية كلها أسماء.","«قل هو الله أحد»: قل: فعل أمر؛ هو: اسم (ضمير)؛ الله: اسم؛ أحد: اسم. فاجتمع فيها فعل وأسماء ولا حرف فيها.","«إنا أعطيناك الكوثر»: إن: حرف؛ نا: اسم (ضمير)؛ أعطينا: فعل مع ضمير؛ كاف: اسم (ضمير)؛ الكوثر: اسم. فاجتمعت الأنواع الثلاثة في آية واحدة.","الحروف أقسام كثيرة ستمر بك: جر، وعطف، ونصب، وجزم، واستفهام، ونفي، وشرط... وكلها حروف معنى: تخدم الأسماء والأفعال وتربطها.","تنبيه: بعض الكلمات تحتار فيها أول الأمر: «أمس»: اسم (ظرف زمان) لا حرف؛ «غدًا»: اسم؛ «الآن»: اسم. والضمائر كلها أسماء. وأسماء الإشارة والموصولات أسماء. فلا كل مبني حرف.","خلاصة: الكلام كله اسم أو فعل أو حرف معنى؛ والبيت فاتحة باب أنواع الكلمة؛ والأبيات الثلاثة القادمة تضبط كل نوع بعلاماته: الاسم (٩)، والفعل (١٠)، والحرف (١١)."],"examples":["بسم الله الرحمن: كلها أسماء","قل هو الله أحد: فعل وأسماء","إنا أعطيناك الكوثر: الأنواع الثلاثة","الحروف أقسام: جر وعطف ونصب وجزم","أمس وغد: أسماء لا حروف","الضمائر كلها أسماء"],"questions":[{"question":"صنف كلمات «بسم الله الرحمن»:","options":["كلها أسماء","فعل واسم وحرف","حروف فقط","فعلان"],"answer":0,"explanation":"بسم: اسم مجرور بالباء المقدرة... بسم: اسم؛ والله اسم؛ والرحمن نعت: فالتركيب كله أسماء."},{"question":"في «إنا أعطيناك الكوثر» اذكر الأنواع الثلاثة:","options":["إن حرف ونا اسم وأعطينا فعل والكوثر اسم","كلها أسماء","كلها أفعال","حرفان فقط"],"answer":0,"explanation":"إن: حرف ناسخ؛ نا: ضمير (اسم)؛ أعطينا: فعل ماضٍ مع نا؛ الكاف ضمير (اسم)؛ الكوثر اسم."},{"question":"«أمس» و«غدًا» ما نوعهما؟","options":["اسمان (ظرفا زمان) وليسا حرفين","حرفان","فعلان","أحدهما حرف"],"answer":0,"explanation":"ليس كل مبني حرفًا: أمس وغد واليوم والآن أسماء مبنية تدل على أزمنة؛ وتجرى مجرى الظروف."},{"question":"ما الضمائر نوعًا؟","options":["أسماء كلها","حروف","أفعال","بعضها حروف"],"answer":0,"explanation":"أنا وأنت وهو والتاء والكاف والهاء: كلها أسماء؛ لأنها تدل على معانٍ في نفسها: متكلم ومخاطب وغائب."},{"question":"ما فائدة ضبط الأنواع الثلاثة بعلامات؟","options":["لتميز كل كلمة عند ورودها فتحكم عليها حكمًا صحيحًا","للزينة","لا فائدة","للحفظ فقط"],"answer":0,"explanation":"الإعراب مبني على معرفة النوع: فالاسم يرفع وينصب ويجر، والفعل له أحكامه، والحرف لا إعراب له."}]}]},{"id":"wahi-verse-009","title":"ضابط الاسم: التنوين وأل والنداء وحرف الجر","summary":"أربع علامات لفظية تعرف بها الاسم من غيره.","verse":{"number":9,"section":"أنواع الكلمة","text":"فَالِاسْمُ مَعْرُوفٌ عَلَى التَّعْيِينْ بِـ(أَلْ) وَحَرْفِ الْجَرِّ وَالتَّنْوِينِ"},"segments":[{"body":["البيت التاسع: «فَالِاسْمُ مَعْرُوفٌ عَلَى التَّعْيِينْ بِـ(أَلْ) وَحَرْفِ الْجَرِّ وَالتَّنْوِينِ». يضبط الاسم بعلامات تعرفه بها على التعيين، ونفهمه كلمة كلمة.","«فَالِاسْمُ»: الفاء تفصيل للأنواع الثلاثة المتقدمة؛ والاسم: مبتدأ: الكلمة الدالة على معنى في نفسها غير مقترن بزمان: رجل، شجرة، علم، صدق. «مَعْرُوفٌ»: خبر: يعرف ويميز. «عَلَى التَّعْيِينْ»: أي: معرفة محققة لا تقبل الشك؛ والنون محذوفة للوزن (التعيينِ).","«بِـ(أَلْ)»: الباء حرف جر للتعدية: يعرف الاسم بأل التعريف: الرجل، الكتاب؛ فكل كلمة قبلت أل فهي اسم. «وَحَرْفِ الْجَرِّ»: ويعرف بدخول حرف الجر عليه: في البيت، من المدرسة؛ فكل كلمة صح جرها فهي اسم.","«وَالتَّنْوِينِ»: ويعرف بقبول التنوين: وهو نون ساكنة زائدة في آخر الاسم تلفظ ولا تكتب: رجلٌ، كتابٌ، عالمٍ؛ فكل كلمة قبلت التنوين فهي اسم.","فالمعنى: الاسم يعرف معرفة محققة بعلامات: قبوله أل، ودخول حرف الجر عليه، وقبوله التنوين؛ وفي شرح المؤلف ضابط رابع: النداء: يا رجلُ.","جمع المؤلف هذه الضوابط في بيت من نظمه: «الضابطُ: تنوينُه ونداهْ ۞ وحرفُ جرٍّ و(أل) يا راجيَ تُقَهْ»؛ فالضوابط أربعة: التنوين، والنداء، وحرف الجر، وأل؛ ما قبل واحدًا منها فهو اسم."],"examples":["الاسم: يدل على معنى في نفسه بلا زمان","أل: الرجل والكتاب","حرف الجر: في البيت","التنوين: رجلٌ وكتابٌ","النداء: يا رجل","الضوابط أربعة جامعة"],"questions":[{"question":"بم يعرف الاسم على التعيين؟","options":["بأل وحرف الجر والتنوين والنداء","بلم","بتاء التأنيث","بياء المخاطبة"],"answer":0,"explanation":"الضابط: تنوينه ونداه وحرف جر وأل؛ فما قبل واحدًا من الأربعة فهو اسم."},{"question":"ما التنوين؟","options":["نون ساكنة زائدة في آخر الاسم تلفظ ولا تكتب","حرف جر","علامة جزم","ضمة مضاعفة للفعل"],"answer":0,"explanation":"رجلٌ: النون الساكنة الزائدة في الآخر هي التنوين؛ وهي خاصة بالاسم لا تدخل على فعل ولا حرف."},{"question":"كيف تعرف أن «الكتاب» اسم؟","options":["لقبوله أل التعريف","لقبوله لم","لقبوله قد","لقبوله ياء المخاطبة"],"answer":0,"explanation":"الكتاب: دخلت عليه أل التعريف؛ فهو اسم؛ إذ أل لا تدخل إلا على الأسماء."},{"question":"«يا عالمُ» ما وجه الدلالة على أن عالم اسم؟","options":["قبوله النداء","قبوله لم","قبوله سين","لا دليل"],"answer":0,"explanation":"النداء من ضوابط الاسم: يا رجل يا عالم؛ فالمنادى اسم قطعًا."},{"question":"جرب الضوابط على «علمٌ»:","options":["يقبل التنوين وأل وجرًا ونداء: فهو اسم","لا يقبل شيئًا","يقبل لم","فعل ماضٍ"],"answer":0,"explanation":"علمٌ: نوّنّاه، والعلمُ: أدخلنا أل، وبالعلم: جررناه، ويا عالمَ: ناديناه: فهو اسم بأربعة أدلة."}]},{"body":["تدريب تطبيقي على كلمات متشابهة: «صوم»: نقول صومٌ والصوم وبالصوم ويا صائم... فهو اسم (مصدر). «صام»: لا تقبل أل ولا تنوينًا: فهي فعل.","«عدل»: قد تكون اسمًا (العدل: ضد الظلم) وفعلًا (عدل زيد: أقام الحق). الميزان الضوابط: العدلُ وعدلٌ: اسم؛ وعدلْ بلا تنوين مع زمن ماضٍ: فعل.","الضمائر أسماء: أنا وأنت وهو؛ والدليل: تقبل حرف الجر: بي وبك وبه؛ وتجرى مجرى المعارف. وأسماء الإشارة أسماء: بهذا وبذلك. والموصولات أسماء: بالذي وبالتي.","تنبيه: قبول أل على التعيين: بعض الأسماء لا تقبلها لمانع: كالضمائر وأسماء الإشارة؛ فإذا لم تقبل الكلمة أل فجرب بقية الضوابط: التنوين أو الجر أو النداء.","من أمثلة الكتاب على الضوابط: «زيدٌ»: بالتنوين؛ «الرحمن»: بأل؛ «يا هذا»: بالنداء؛ «مررت به»: بحرف الجر. فالضابط الواحد يكفي للحكم.","خلاصة: الاسم أول الأنواع الثلاثة؛ يعرف بأل والتنوين والنداء وحرف الجر؛ وكل كلمة قبلت واحدًا منها فهي اسم ولو لم تقبل الباقي؛ وهذا البيت مفتاح تمييز الأسماء كلها في الدروس الآتية."],"examples":["صوم: اسم؛ صام: فعل","عدل: اسم وفعل بالسياق","بي وبك وبه: الضمائر تجر","بهذا وبالذي: الإشارة والموصول أسماء","مانع واحد لا يسقط بقية الضوابط","زيدٌ والرحمن ويا هذا ومررت به"],"questions":[{"question":"«صام» لم ليست اسمًا؟","options":["لأنها لا تقبل أل ولا تنوينًا ولا جرًّا بل تدل على حدث في زمان مضى","لأنها مبنية","لأنها قصيرة","هي اسم"],"answer":0,"explanation":"صام: حدث (الصيام وقوعًا) مقترن بالزمن الماضي: فعل؛ ولا تقول الصام ولا صامٌ."},{"question":"كيف تفرق بين «عدل» الاسم والفعل؟","options":["بالضوابط: العدل وعدلٌ اسم، وعدلَ (حدث ماضٍ) فعل","لا فرق","بالطول","بالكتابة"],"answer":0,"explanation":"جرب أل والتنوين: قبلتهما فاسم؛ وجرب الزمن: دلت على حدث ماضٍ ففعل."},{"question":"ما دليل أن الضمائر أسماء؟","options":["تقبل حرف الجر: بي وبك وبه","تقبل لم","تقبل النونين","لا دليل"],"answer":0,"explanation":"الضمائر تجر بحروف الجر: لي وعنك ومنه؛ فهي أسماء؛ وكذلك أسماء الإشارة والموصولات: بهذا وبالذي."},{"question":"كلمة لم تقبل أل فهل تخرج عن كونها اسمًا؟","options":["لا؛ تختبر ببقية الضوابط كالضمائر وأسماء الإشارة","نعم حتمًا","تصير فعلًا","تصير حرفًا"],"answer":0,"explanation":"هذا وأنا: لا تقبلان أل لكنها تجر: بهذا وبي؛ فالضابط الواحد كافٍ في الحكم بالاسمية."},{"question":"ما الضوابط الأربعة للاسم مرتبة كبيت الضابط؟","options":["التنوين ثم النداء ثم حرف الجر ثم أل","أل فقط","التنوين فقط","لم وقد"],"answer":0,"explanation":"الضابط: تنوينه ونداه وحرف جر وأل يا راجي تقه: أربعة ضوابط جامعة للاسم."}]}]},{"id":"wahi-verse-010","title":"ضوابط الفعل: الماضي والمضارع والأمر","summary":"الماضي بتا التأنيث، والمضارع بـ(لم)، والأمر بياء المخاطبة.","verse":{"number":10,"section":"أنواع الكلمة","text":"وَمَيِّزِ الْمَاضِي بِالتَّا، وَبِـ(لَمْ) مُضَارِعًا؛ وَالْأَمْرَ بِالْيَاءِ، كَـ(نَمْ)"},"segments":[{"body":["البيت العاشر: «وَمَيِّزِ الْمَاضِي بِالتَّا، وَبِـ(لَمْ) مُضَارِعًا؛ وَالْأَمْرَ بِالْيَاءِ، كَـ(نَمْ)». يضبط أقسام الفعل الثلاثة، ونفهمه كلمة كلمة.","«وَمَيِّزِ»: فعل أمر: ميّز وافرق. «الْمَاضِي»: الفعل الدال على حدث وقع في زمان مضى وانقضى: كتب، ذهب، استغفر. «بِالتَّا»: الضابط: تاء التأنيث الساكنة: كل كلمة قبلتها فهي فعل ماضٍ: سجدَ وسجدتْ، ذهبَ وذهبتْ.","«وَبِـ(لَمْ) مُضَارِعًا»: والفعل المضارع -وهو الدال على حدث يقع الآن أو في المستقبل- يعرف بقبوله لم: لم يكتبْ، لم يذهبوا. وشرطه: أن يبدأ بحرف من أحرف المضارعة الأربعة المجموعة في (أنيت): الهمزة والنون والياء والتاء: أدرس، ندرس، يدرس، تدرس.","«وَالْأَمْرَ»: الفعل الدال على طلب الحدث: اكتب، اجتهد، استغفر. «بِالْيَاءِ»: يعرف بقبوله ياء المخاطبة: اكتبْ واكتبي، اجتهدْ واجتهدي.","«كَـ(نَمْ)»: الكاف للتشبيه: مثل كلمة «نمْ» من نام ينام: تقول للمفرد: نمْ، وللمخاطبة: نمي (بالياء)؛ فدلت الياء على أنه فعل أمر.","فالمعنى: ميّز الفعل الماضي بقبوله تاء التأنيث الساكنة، والمضارع بقبوله لم، والأمر بقبوله ياء المخاطبة، مثل: نمْ ونمي."],"examples":["الماضي: حدث في زمن مضى","ضابطه: تاء التأنيث: سجد وسجدت","المضارع: يقبل لم ويبدأ بأنيت","الأمر: طلب الحدث","ضابطه: ياء المخاطبة: اكتبي","نم ونمي: من نام ينام"],"questions":[{"question":"ما ضابط الفعل الماضي؟","options":["قبوله تاء التأنيث الساكنة","قبوله لم","قبوله أل","قبوله التنوين"],"answer":0,"explanation":"سجد وسجدت: تاء التأنيث الساكنة لا تتصل إلا بالماضي؛ فما قبلها فهو فعل ماضٍ."},{"question":"ما ضابط الفعل المضارع؟","options":["قبوله لم مع ابتدائه بحرف من أنيت","قبوله أل","التنوين","النداء"],"answer":0,"explanation":"لم يكتب: المضارع يقبل لم الجازمة؛ وحروف المضارعة أربعة: الهمزة والنون والياء والتاء (أنيت)."},{"question":"ما ضابط فعل الأمر؟","options":["قبوله ياء المخاطبة","تاء التأنيث","لم","أل"],"answer":0,"explanation":"اكتب واكتبي: ياء المخاطبة تتصل بالأمر؛ فما قبلها فهو أمر طلب."},{"question":"ما معنى «كـ(نم)»؟","options":["مثل كلمة نم: تقول للمخاطبة نمي فدلت الياء على الأمر","اسم رجل","حرف جر","نعت"],"answer":0,"explanation":"نم: فعل أمر من نام ينام؛ وياء المخاطبة (نمي) ضابطه؛ فمثّل المؤلف بها لقصرها ووضوحها."},{"question":"جمع أحرف المضارعة في كلمة:","options":["أنيت: الهمزة والنون والياء والتاء","أنمي","كتب","على"],"answer":0,"explanation":"أدرس وندرس ويدرس وتدرس: أربعة أحرف لا يبدأ المضارع إلا بأحدها؛ جمعت في كلمة (أنيت)."}]},{"body":["تدريب تطبيقي: «استغفر»: قبلت التاء (استغفرتْ): فعل ماضٍ. «يستغفر»: قبل لم (لم يستغفرْ): مضارع. «استغفرْ» للمفرد و«استغفري» للمخاطبة: أمر.","كلمات أصلها أسماء تشبه الأفعال: «عسى» و«كان» و«ليس»: قبلت التاء: عسَت وكانت وليست: فهي أفعال ماضية وإن خالفت قياس التصريف التام.","ومن الأمر: «هاتِ» و«تعالَ»: تقول للمخاطبة: يا هند هاتي مثالًا، وتعالي: فقبلتا ياء المخاطبة: فهما فعلا أمر.","الفرق بين تاء التأنيث وتاء الفاعل: سجدتْ: التاء ساكنة لا يقوم غيرها مقامها: تاء تأنيث. سجدتُ وسجدتَ: التاء ضمير فاعل (تاء المتكلم والمخاطب): فهي هنا تاء فاعل مبنية؛ وكلاهما يدل على الماضي.","تدريب التمييز الثلاثي: ميّز: «كتب» (ماضٍ بالتا: كتبت)؛ «يكتب» (مضارع بلم: لم يكتب)؛ «اكتب» (أمر بالياء: اكتبي). وكرر مع: درس، حفظ، قرأ، فهم.","خلاصة: الفعل ثلاثة أقسام بثلاثة ضوابط: الماضي بالتا، والمضارع بلم مع أنيت، والأمر بالياء؛ وما لم يقبل شيئًا من هذا ولا ضوابط الاسم فهو حرف كما يأتي في البيت الحادي عشر."],"examples":["استغفر واستغفرت: ماضٍ","عسى وكان وليست تقبل التاء: أفعال","هاتي وتعالي: أمر بالياء","سجدتْ تأنيث وسجدتُ فاعل","كتب ويكتب واكتب: ثلاثة بثلاثة ضوابط","الباقي حرف"],"questions":[{"question":"«عسى» و«كان» و«ليس» ما نوعها وما دليلها؟","options":["أفعال ماضية لقبولها تاء التأنيث: عست وكانت وليست","أسماء","حروف","أفعال أمر"],"answer":0,"explanation":"قبلت تاء التأنيث الساكنة: عست أن تقوم وكانت وليست: فهي أفعال ماضية ناسخة."},{"question":"ما الفرق بين تاء التأنيث وتاء الفاعل؟","options":["تاء التأنيث ساكنة لا ضمير، وتاء الفاعل ضمير متكلم أو مخاطب","لا فرق","الفاعل للمؤنث","التأنيث للمذكر"],"answer":0,"explanation":"سجدتْ (هي): تاء تأنيث ساكنة؛ سجدتُ (أنا) وسجدتَ (أنت): التاء ضمير فاعل مبني في محل رفع."},{"question":"«هاتي» ما دليل أنها فعل أمر؟","options":["قبولها ياء المخاطبة","قبولها أل","التنوين","لم"],"answer":0,"explanation":"هاتِ وتعالَ: تقبلان ياء المخاطبة: هاتي وتعالي؛ فهما فعلا أمر بضابط البيت."},{"question":"ميّز أقسام: «قرأ» و«يقرأ» و«اقرأ»:","options":["ماضٍ بالتا ومضارع بلم وأمر بالياء","كلها ماضية","كلها أسماء","كلها حروف"],"answer":0,"explanation":"قرأ: قرأت؛ يقرأ: لم يقرأ؛ اقرأ: اقرئي؛ فلكل قسم ضابطه اللفظي."},{"question":"لم لا يكون «على» فعلًا؟","options":["لأنه لا يقبل تاء التأنيث ولا لم ولا ياء المخاطبة","لأنه قصير","لأنه طويل","هو فعل"],"answer":0,"explanation":"على: لا تقول علىت ولا لم على ولا عليي... بمعنى الأمر؛ فهو حرف جر كما يأتي في البيت التالي."}]}]},{"id":"wahi-verse-011","title":"الحرف: ما سوى الاسم والفعل","summary":"ضابط الحرف، وأنواع الحروف، وبيان أن هذه المعرفة ضرورة مهمة.","verse":{"number":11,"section":"أنواع الكلمة","text":"سِوَاهُمَا الْحَرْفُ، كَـ(فِي)، وَثُمَّهْ وَهَذِهِ ضَرُورَةٌ مُهِمَّهْ"},"segments":[{"body":["البيت الحادي عشر: «سِوَاهُمَا الْحَرْفُ، كَـ(فِي)، وَثُمَّهْ وَهَذِهِ ضَرُورَةٌ مُهِمَّهْ». يضبط النوع الثالث من الكلمة: الحرف، ونفهمه كلمة كلمة.","«سِوَاهُمَا»: أي: ما سوى الاسم والفعل، غيرهما؛ والهاء والميم تعود على النوعين المتقدمين. «الْحَرْفُ»: خبر: هو الحرف؛ فالحرف ما بقي بعد الاسم والفعل.","«كَـ(فِي)»: الكاف للتشبيه: مثل «في» حرف الجر الدال على الظرفية. «وَثُمَّهْ»: ومثل «ثم» حرف العطف للترتيب مع مهلة؛ وحذفت التاء للوزن كعادة البيت.","«وَهَذِهِ ضَرُورَةٌ»: الإشارة إلى معرفة الأنواع الثلاثة وضوابطها: وهذا العلم ضرورة: لا بد منه. «مُهِمَّهْ»: نعت ثانٍ: مهمة عظيمة القدر؛ وحذفت التاء للوزن.","فالمعنى: ما سوى الاسم والفعل من الكلمات فهو الحرف، مثل: في وثم؛ وهذه المعرفة -معرفة الأنواع الثلاثة وضوابطها- ضرورة مهمة لطالب النحو.","الحرف: كلمة تدل على معنى في غيرها: فـ«في» لا تدل على شيء قائم بنفسه؛ لكن «في البيت» أفادت أن البيت ظرف للشيء؛ و«ثم» أفادت الترتيب بين كلامين؛ فمعنى الحرف فيما يتصل به."],"examples":["سواهما: غير الاسم والفعل","الحرف: يدل على معنى في غيره","في: للظرفية؛ ثم: للترتيب مع مهلة","كاف التشبيه للتمثيل","معرفة الأنواع ضرورة مهمة","حذف التاء للوزن: ثمه ومهمه"],"questions":[{"question":"ما الحرف وما ضابطه؟","options":["ما سوى الاسم والفعل؛ لا يقبل ضوابطهما ويدل على معنى في غيره","يدل على زمان","يقبل التنوين","يقبل أل"],"answer":0,"explanation":"سواهما الحرف: ما لم يقبل علامات الاسم ولا علامات الفعل فهو حرف؛ كفي وثم."},{"question":"لم قال «كفي وثم»؟","options":["تمثيلًا للحرف بأشهر أفراده: حرف جر وحرف عطف","للمدح","للنداء","بلا سبب"],"answer":0,"explanation":"في حرف جر وثم حرف عطف؛ مثل بهما المؤلف لأنهما من أكثر الحروف دورانًا في الكلام."},{"question":"ما معنى «وهذه ضرورة مهمه»؟","options":["معرفة الأنواع الثلاثة بضوابطها علم لا بد منه لطالب النحو","أمر كمالي","زائدة لفظية","شعر محض"],"answer":0,"explanation":"الإشارة إلى ضبط الاسم والفعل والحرف: من لم يميزها لم يعرب؛ فهي ضرورة أولية مهمة."},{"question":"«في» ما معناها ولم هي حرف؟","options":["تدل على الظرفية في غيرها ولا تدل على معنى في نفسها","تدل على زمان","اسم مكان","فعل أمر"],"answer":0,"explanation":"في البيت: أفادت البيت ظرفًا للمستقر؛ وحدها لا تفيد شيئًا قائمًا بنفسه: فهي حرف معنى."},{"question":"لم حذفت التاء في «ثمه» و«مهمه»؟","options":["للضرورة الشعرية: ضبط الوزن","خطأ","للإبهام","وجوب نحوي"],"answer":0,"explanation":"كما حذفت في أربع ومكمله والمفصله: تخفيف للوزن والمعنى محفوظ."}]},{"body":["تدريب حصر الأنواع: صنف: «عن» (حرف جر)؛ «كتب» (فعل ماضٍ)؛ «مدرسة» (اسم)؛ «هل» (حرف استفهام)؛ «يجتهد» (فعل مضارع)؛ «أم» (حرف عطف)؛ «العلم» (اسم).","الحروف أبواب ستأتي: حروف الجر (من وإلى وعن وعلى وفي...)، حروف العطف (الواو والفاء وثم وأو...)، حروف النصب (أن ولن وكي...)، حروف الجزم (لم ولما ولا الناهية...)، حروف الاستفهام (هل وهمزة)، حروف النفي (ما ولا ولم...)، حروف الشرط (إن ولو...).","كلمة «ثم» في البيت نفسه مثال: فهي حرف عطف يفيد الترتيب مع المهلة: جاء الولد ثم أبوه: أي جاء الأب بعد الولد بزمن. قارن بالفاء: جاء الولد فأبوه: بلا مهلة.","لم الحرف مبني دائمًا؟ لأنه لا يقبل العلامات؛ والإعراب تغير لمعنى يقبله الاسم والفعل؛ والحرف خادم معنوي فبقي على صورة واحدة: في دائمًا، وثم دائمًا.","فائدة الترتيب: قدم المؤلف الاسم ثم الفعل ثم الحرف؛ لأن الاسم أدل على المعنى بنفسه، ثم الفعل يقترن بزمان، ثم الحرف تابع لهما؛ فالترتيب من الأقوى دلالة إلى الأضعف.","خلاصة مبحث الأنواع: كل الكلام اسم (يعرف بأل والتنوين والنداء والجر) أو فعل (يعرف بالتا ولم والياء) أو حرف (ما سواهما)؛ وهذه الضرورة المهمة أساس كل ما يأتي."],"examples":["عن وهل وأم: حروف","أبواب الحروف: جر وعطف ونصب وجزم واستفهام ونفي وشرط","ثم: ترتيب مع مهلة","الحرف مبني دائمًا","الترتيب: الأقوى دلالة أولًا","الضرورة المهمة أساس الإعراب"],"questions":[{"question":"صنف: «هل» و«أم» و«عن»:","options":["حروف: استفهام وعطف وجر","أسماء","أفعال","ضمائر"],"answer":0,"explanation":"لا تقبل علامة اسم ولا فعل: هل للاستفهام وأم للعطف والتعيين وعن للجر: كلها حروف معنى."},{"question":"اذكر أبوابًا من الحروف:","options":["جر وعطف ونصب وجزم واستفهام ونفي وشرط","باب واحد","فعلية واسمية","مبتدأ وخبر"],"answer":0,"explanation":"الحروف أجناس: من وإلى (جر)، الواو والفاء (عطف)، أن ولن (نصب)، لم (جزم)، هل (استفهام)، ما ولا (نفي)، إن (شرط)."},{"question":"لم الحروف كلها مبنية؟","options":["لأنها لا تقبل علامات الإعراب ومعناها ثابت في غيرها","لأنها أفعال","لأنها معربة","بلا سبب"],"answer":0,"explanation":"الإعراب تغير آخر الكلمة لعامل؛ والحرف لا يقبل العوامل ولا العلامات: في وثم على صورة واحدة دائمًا."},{"question":"ما وجه تقديم الاسم ثم الفعل ثم الحرف؟","options":["من الأقوى دلالة إلى الأضعف: الاسم يدل بنفسه والفعل يقترن بزمان والحرف تابع","عشوائي","أبجدي","بالطول"],"answer":0,"explanation":"الاسم أدل على معناه استقلالًا؛ ثم الفعل يحتاج زمانًا؛ ثم الحرف لا يفيد إلا معهما: فهذا ترتيب رتب المعاني."},{"question":"لخص ضوابط الأنواع الثلاثة:","options":["الاسم بأل والتنوين والنداء والجر؛ والفعل بالتا ولم والياء؛ والحرف ما سواهما","الكل بالتنوين","الكل بلم","لا ضابط"],"answer":0,"explanation":"ثلاثة أبيات ضبطت الثلاثة: فالاسم معروف (٩)، وميز الماضي بالتا (١٠)، وسواهما الحرف (١١)."}]}]},{"id":"wahi-verse-012","title":"النكرة والمعرفة","summary":"الاسم لا يخرج عن معرفة أو نكرة، وضابط كل منهما.","verse":{"number":12,"section":"النكرة والمعرفة","text":"أَسْمَاؤُنَا مَعْرِفَةٌ أَوْ نَكِرَهْ وَالثَّانِ مَا يَقْبَلُ (أَلْ) مُؤَثِّرَهْ"},"segments":[{"body":["البيت الثاني عشر: «أَسْمَاؤُنَا مَعْرِفَةٌ أَوْ نَكِرَهْ وَالثَّانِ مَا يَقْبَلُ (أَلْ) مُؤَثِّرَهْ». به يبدأ المبحث الثاني من أحكام الكلمة: أقسام الاسم، ونفهمه كلمة كلمة.","«أَسْمَاؤُنَا»: مبتدأ مضاف: الأسماء التي نتكلم بها نحن؛ ونا: ضمير المتكلمين مضاف إليه. «مَعْرِفَةٌ أَوْ نَكِرَهْ»: خبره: الأسماء كلها على قسمين: معرفة أو نكرة؛ وحذفت التاء للوزن.","«وَالثَّانِ»: القسم الثاني منهما: النكرة. «مَا يَقْبَلُ (أَلْ) مُؤَثِّرَهْ»: ما: نافية؛ يقبل: مضارع؛ أل: مفعول به؛ مؤثره: نعت لأل منصوب: أل مؤثرة، أي: عاملة تغير المعنى وتفيد التعريف.","فالمعنى: أسماؤنا قسمان: معرفة ونكرة؛ والثاني -وهو النكرة- ما لا يقبل أل المؤثرة في معناه.","المعرفة: اسم يدل على معين بعينه: زيد، مكة، أنا، هذا، الكتاب؛ فإذا سمعته عرف السامع من أو ما أريد به. والنكرة: اسم يدل على غير معين: رجل، كتاب، عالم: أي رجل وأي كتاب.","ضابط النكرة هنا: أنها لا تقبل أل المؤثرة التي تفيد تعريفها؛ فلو أدخلت أل على «رجل» صارت «الرجل» معرفة بتعريف آخر؛ فالنكرة الأصلية تمتنع من أل المغيرة لمعناها... والأدق كما في شرح المؤلف: النكرة ما دل على غير معين، وقبول أل ينقلها إلى المعرفة."],"examples":["أسماؤنا: معرفة أو نكرة","المعرفة: تدل على معين","النكرة: تدل على غير معين","الثاني: النكرة لا تقبل أل مؤثرة","زيد ومكة وأنا وهذا: معارف","رجل وكتاب وعالم: نكرات"],"questions":[{"question":"على كم قسم تنقسم الأسماء في هذا البيت؟","options":["قسمين: معرفة ونكرة","ثلاثة","أربعة","خمسة"],"answer":0,"explanation":"أسماؤنا معرفة أو نكره: قسمة ثنائية جامعة: كل اسم إما دال على معين أو على غير معين."},{"question":"ما المعرفة؟","options":["اسم يدل على معين بعينه","اسم عام","فعل ماضٍ","حرف"],"answer":0,"explanation":"زيد ومكة وأنا وهذا والكتاب: إذا سمعتها عرفت المعني بها: فهي معارف."},{"question":"ما النكرة وما ضابطها في البيت؟","options":["اسم يدل على غير معين ولا يقبل أل المؤثرة","يدل على معين","يقبل أل","فعل"],"answer":0,"explanation":"رجل وكتاب: أي واحد من جنسه؛ ولا يقبل أل المغيرة لمعناه؛ فإن قبلها صار معرفة."},{"question":"ما معنى «أل مؤثره»؟","options":["أل عاملة تغير المعنى وتفيد التعريف","أل زائدة بلا أثر","حرف جر","نون"],"answer":0,"explanation":"مؤثره: نعت منصوب لأل: أل التي تؤثر في الكلمة فتنقلها من نكرة إلى معرفة: رجل → الرجل."},{"question":"أعرب «أسماؤنا»:","options":["مبتدأ مرفوع بالضمة مضاف ونا مضاف إليه","فاعل","مفعول به","خبر"],"answer":0,"explanation":"أسماء: مبتدأ مرفوع بالضمة مضاف؛ ونا ضمير متصل مبني في محل جر مضاف إليه؛ والخبر: معرفة أو نكرة."}]},{"body":["تدريب التمييز: صنف: «بغداد» (معرفة: علم مدينة معينة)؛ «مدينة» (نكرة: أي مدينة)؛ «هو» (معرفة: ضمير معين)؛ «عالم» (نكرة)؛ «القلم» (معرفة بأل)؛ «قلمٌ» (نكرة منونة).","لاحظ التنوين: التنوين من علامات التنكير: رجلٌ بالتنوين أظهر في النكرة منه بغيره؛ فالمنون في كلام العرب نكرة في الغالب... إلا أعلام منونة كـ«محمدٌ»: فهي معرفة بالعلمية والتنوين فيها لغرض آخر.","المعرفة والنكرة يتبادلان بالسياق: «اشتريت كتابًا»: نكرة؛ «الكتابُ الذي اشتريته نفيس»: صار معرفة بأل والإضافة إلى الموصول... والكتاب المعهود بين المتكلمين معرفة.","فائدة القسمة: النكرة والمعرفة أصل لأحكام كثيرة آتية: فالحال نكرة وصاحبها معرفة؛ والنعت يتبع موصوفه تعريفًا وتنكيرًا؛ والمبتدأ معرفة في الأصل؛ فمن أتقن هذا الباب سهلت عليه أبواب كثيرة.","تدريب التحويل: حول النكرة معرفة بأل: رجل → الرجل؛ وبإضافتها إلى معرفة: كتاب → كتاب الطالب؛ وبالنداء المقصود: يا رجلُ (نكرة مقصودة في حكم المعرفة).","خلاصة: الأسماء معرفة (تدل على معين) أو نكرة (تدل على غير معين ولا تقبل أل المؤثرة)؛ والبيتان القادمان يعددان المعارف الستة ثم يفصلان أولها: الضمير."],"examples":["بغداد معرفة ومدينة نكرة","التنوين من علامات التنكير","محمدٌ: علم منون معرفة","الكتاب الذي اشتريته: معرفة بالسياق","الحال نكرة وصاحبه معرفة","كتاب الطالب: نكرة صارت معرفة بالإضافة"],"questions":[{"question":"صنف: «هو» و«القلم» و«عالم» و«بغداد»:","options":["معرفة ومعرفة ونكرة ومعرفة","كلها نكرات","كلها معارف","نكرة ومعرفة ومعرفة ونكرة"],"answer":0,"explanation":"هو ضمير معين؛ والقلم معرف بأل؛ وعالم نكرة: أي عالم؛ وبغداد علم مدينة: معرفة."},{"question":"ما علاقة التنوين بالتنكير؟","options":["التنوين علامة تنكير في الغالب","علامة تعريف","لا علاقة","علامة فعل"],"answer":0,"explanation":"رجلٌ وكتابٌ: المنون نكرة؛ إلا الأعلام المنونة كمحمد: فالتنوين فيها صرفي لا ينكر صاحبها."},{"question":"كيف تصير النكرة معرفة؟","options":["بأل أو بالإضافة إلى معرفة أو بالنداء المقصود","لا تصير","بلم","بالتنوين"],"answer":0,"explanation":"كتاب: نكرة؛ الكتاب وكتاب الطالب ويا كتابُ... مقصودًا: معارف؛ فالسياق ينقلها."},{"question":"لم اعتنت القواعد الآتية بباب النكرة والمعرفة؟","options":["لأن أحكامًا كثيرة مبنية عليه: الحال والنعت والمبتدأ","لا سبب","للزينة","للحفظ فقط"],"answer":0,"explanation":"الحال نكرة بعد معرفة؛ والنعت يوافق موصوفه تعريفًا وتنكيرًا؛ والمبتدأ معرفة في الأصل: فهذا الباب مفتاح."},{"question":"«يا رجلُ» ما حكم رجل هنا؟","options":["نكرة مقصودة في حكم المعرفة مبنية على الضمة في محل نصب","نكرة محضة","فعل","حرف"],"answer":0,"explanation":"المنادى نكرة لكنه مقصود بعينه: فهو في حكم المعرفة؛ ويعرب منادى مبنيًّا على الضمة في محل نصب."}]}]},{"id":"wahi-verse-013","title":"أنواع المعرفة الستة","summary":"المعارف منحصرة في ستة أنواع جمعها المؤلف بمثال واحد.","verse":{"number":13,"section":"النكرة والمعرفة","text":"مَعَارِفُ: (أَنْتُمْ، وَزَيْدٌ، وَهُنَا ثُمَّ الَّذِي، وَالْقَهْقَرَى، وَذُو الْغِيَظِ)"},"segments":[{"body":["البيت الثالث عشر: «مَعَارِفُ: (أَنْتُمْ، وَزَيْدٌ، وَهُنَا ثُمَّ الَّذِي، وَالْقَهْقَرَى، وَذُو الْغِيَظِ)». يحصر المعارف الستة بمثال واحد لكل نوع، ونفهمه كلمة كلمة.","«مَعَارِفُ»: جمع معرفة: أي أنواع المعارف؛ وخبر مبتدأ محذوف تقديره: المعارف ستة... ثم عددها بأمثلتها الستة في البيت نفسه؛ فالبيت حيلة ذكية: يعدد الأنواع بممثلاتها لتثبت في الذهن.","«أَنْتُمْ»: ضمير للمخاطبين: وهذا النوع الأول: الضمير، وهو اسم يدل على متكلم أو مخاطب أو غائب. «وَزَيْدٌ»: النوع الثاني: العلم: اسم يدل على معين بعينه من الناس أو البلاد: زيد ومكة وبغداد.","«وَهُنَا»: النوع الثالث: اسم الإشارة: اسم يدل على معين بالإشارة الحسية: هذا وهذه وهؤلاء وهنا (إشارة إلى المكان). «ثُمَّ الَّذِي»: النوع الرابع: الاسم الموصول: اسم يدل على معين بصلة تتصل به: الذي والتي والذين.","«وَالْقَهْقَرَى»: النوع الخامس: المعرَّف بـ(أل)؛ والقهقرى اسم قديم عند النحويين للام التعريف (أل)؛ فأشار بها إلى كل اسم فيه أل: الرجل والعلم والقمر. «وَذُو الْغِيَظِ»: النوع السادس: المضاف إلى معرفة: ذو مضافة إلى الغيظ، والغيظ معرف بأل؛ فكل اسم أضيف إلى معرفة صار معرفة: كتابُ الطالبِ وغلامُ زيدٍ.","فالمعنى: المعارف ستة: الضمير (أنتم)، والعلم (زيد)، واسم الإشارة (هنا)، والاسم الموصول (الذي)، والمعرف بأل (القهقرى)، والمضاف إلى معرفة (ذو الغيظ)؛ وما سوى هذه الستة فهو نكرة."],"examples":["أنتم: ضمير","زيد: علم","هنا: اسم إشارة","الذي: اسم موصول","القهقرى: المعرّف بأل","ذو الغيظ: مضاف إلى معرفة"],"questions":[{"question":"كم أنواع المعارف وما هي؟","options":["ستة: الضمير والعلم والإشارة والموصول وأل والمضاف إلى معرفة","ثلاثة","أربعة","سبعة"],"answer":0,"explanation":"حصرها البيت بأمثلتها: أنتم وزيد وهنا والذي والقهقرى وذو الغيظ؛ وما سواها نكرة."},{"question":"ما نوع «زيد» من المعارف؟","options":["علم","ضمير","موصول","نكرة"],"answer":0,"explanation":"العلم اسم وضع ليدل على معين بذاته: زيد وخالد ومكة وبغداد؛ وهو النوع الثاني."},{"question":"ما «القهقرى»؟","options":["اسم قديم عند النحويين للام التعريف يشير إلى المعرّف بأل","اسم رجل","حرف جر","ضمير"],"answer":0,"explanation":"سمى النحويون أل التعريف قهقرى؛ فذكرها المؤلف ممثلة للمعرف بأل: الرجل والقمر."},{"question":"لم «ذو الغيظ» معرفة؟","options":["لأنها مضافة إلى معرفة (الغيظ المعرف بأل)","لأنها نكرة","لأنها حرف","لأنها فعل"],"answer":0,"explanation":"النكرة إذا أضيفت إلى معرفة اكتسبت التعريف: كتاب الطالب وغلام زيد وذو الغيظ."},{"question":"ما نوع «هنا»؟","options":["اسم إشارة للمكان","علم","موصول","حرف"],"answer":0,"explanation":"هنا تدل على المكان المعين بالإشارة: اسم إشارة مبني؛ مثل هذا وهذه وهناك."}]},{"body":["تدريب التصنيف: صنف: «هو» (ضمير)؛ «بغداد» (علم)؛ «هذه» (اسم إشارة)؛ «التي» (اسم موصول)؛ «القمر» (معرف بأل)؛ «غلام زيد» (مضاف إلى معرفة: غلام مضاف وزيد مضاف إليه معرفة).","كل اسم لا يندرج تحت واحد من الستة فهو نكرة: رجل، دار، عالم، مسجد، كتاب، شجرة: لا علم ولا ضمير ولا إشارة ولا موصول ولا أل ولا مضاف إلى معرفة: فهي نكرات.","فائدة حصر المعارف: أحكام كثيرة تطلب المعرفة: المبتدأ معرفة في الأصل؛ وصاحب الحال معرفة؛ والمستثنى بغير مضاف إلى معرفة... فإذا حفظت الستة عرفت مواضع استعمالها.","الإضافة إلى نكرة لا تعرّف: «كتاب رجل»: كتاب ما زال نكرة (أي كتاب لأي رجل)؛ لكن «كتاب الرجل»: معرفة؛ فانظر دائمًا إلى المضاف إليه: معرفة؟ فالمضاف معرفة؛ نكرة؟ فالمضاف باقٍ على تنكيره.","من فروع العلم: أعلام الناس: زيد وخالد ومحمد؛ وأعلام البلاد: مكة ومصر؛ وأعلام الجبال: أحد؛ وأعلام الكتب: البخاري. كلها معارف بالعلمية ولو لم تقبل أل.","خلاصة: المعارف ستة محصورة: ضمير وعلم وإشارة وموصول وأل ومضاف إلى معرفة؛ وما عداهن نكرة؛ والبيتان القادمان يفصلان أول المعارف: الضمير تعريفًا وعددًا."],"examples":["هو ضمير وبغداد علم وهذه إشارة","التي موصول والقمر أل وغلام زيد مضاف","ما عدا الستة نكرة","كتاب رجل: نكرة؛ كتاب الرجل: معرفة","المبتدأ معرفة في الأصل","أعلام الناس والبلاد والجبال معارف"],"questions":[{"question":"صنف: «غلام زيد»:","options":["مضاف إلى معرفة","نكرة","علم","موصول"],"answer":0,"explanation":"غلام: نكرة أصلًا؛ أضيفت إلى زيد (علم معرفة) فصارت معرفة بالإضافة؛ وزيد مضاف إليه مجرور."},{"question":"«كتاب رجل» لم يبق نكرة؟","options":["لأن المضاف إليه نكرة فلا تفيد الإضافة تعريفًا","لأنه مجرور","لأنه مثنى","لأنه فعل"],"answer":0,"explanation":"الإضافة تعرّف إذا كان المضاف إليه معرفة: كتاب الرجل؛ أما كتاب رجل فأي كتاب لأي رجل: نكرة."},{"question":"اذكر فائدة لحصر المعارف الستة:","options":["أحكام تطلب المعرفة: المبتدأ وصاحب الحال ونحوهما","لا فائدة","للقافية","للعد فقط"],"answer":0,"explanation":"من لم يحصر المعارف لم يضبط شروط المبتدأ والحال والمنادى؛ فالحصر آلة ضبط للأبواب الآتية."},{"question":"صنف: «التي» و«القمر» و«هو»:","options":["موصول ومعرف بأل وضمير","كلها أعلام","كلها إشارات","نكرات"],"answer":0,"explanation":"التي: اسم موصول؛ القمر: معرف بأل؛ هو: ضمير غائب: ثلاثة أنواع من الستة."},{"question":"ما المشترك بين أنواع المعارف الستة؟","options":["كلها تدل على معين","كلها منونة","كلها أفعال","كلها حروف"],"answer":0,"explanation":"جامع المعارف: الدلالة على معين بعينه: بذاته (العلم) أو بالضم أو الإشارة أو الصلة أو أل أو الإضافة."}]}]},{"id":"wahi-verse-014","title":"الضمير: اسم يدل على متكلم أو حاضر أو غائب","summary":"تعريف الضمير وأقسامه الثلاثة: متكلم ومخاطب وغائب.","verse":{"number":14,"section":"النكرة والمعرفة","text":"فَالِاسْمُ إِنْ دَلَّ عَلَى حُضُورِ أَوْ غَائِبٍ يُعْرَفُ بِالضَّمِيرِ"},"segments":[{"body":["البيت الرابع عشر: «فَالِاسْمُ إِنْ دَلَّ عَلَى حُضُورِ أَوْ غَائِبٍ يُعْرَفُ بِالضَّمِيرِ». يعرف أول المعارف الستة: الضمير، ونفهمه كلمة كلمة.","«فَالِاسْمُ»: الفاء تفصيل؛ والاسم: مبتدأ: أي اسم من الأسماء. «إِنْ دَلَّ»: إن شرطية؛ دل: فعل الشرط ماضٍ: إذا دل ذلك الاسم. «عَلَى حُضُورِ»: على معنى اسم مجرور: على متكلم أو مخاطب حاضر؛ والحضور هنا مصدر بمعنى ذي حضور: من حضر مجلس الكلام.","«أَوْ غَائِبٍ»: أو حرف عطف؛ وغائب: معطوف على حضور مجرور: أو دل على غائب عن مجلس الكلام. «يُعْرَفُ»: جواب الشرط: مضارع مبني للمجهول: يعرف ويسمى. «بِالضَّمِيرِ»: الباء للتعدية: بأنه ضمير؛ والضمير اسم الفاعل... أي يسمى ضميرًا.","فالمعنى: أي اسم دل على متكلم (أنا) أو مخاطب (أنت) أو غائب (هو) فهو الذي يعرف بالضمير.","لم سمي ضميرًا؟ من الضمير بمعنى الخفي: لأنه يدل على معناه بلا ذكر صريح للمسمى؛ فأنا تخفي اسم المتكلم وهو يدل عليه؛ فهو اسم مضمر الدلالة... وقيل من ضمر الشيء إذا خفي.","الأقسام الثلاثة: متكلم: يتكلم عن نفسه: أنا ونحن وتاء ذهبتُ؛ ومخاطب: يكلم وهو حاضر: أنتَ وأنتِ وكاف كتابك؛ وغائب: يتكلم عنه وهو غائب: هو وهي وهاء كتابه."],"examples":["الاسم إن دل على حضور أو غائب: ضمير","المتكلم: أنا ونحن وتاء ذهبت","المخاطب: أنت وكاف كتابك","الغائب: هو وهي وهاء كتابه","سمي ضميرًا لخفاء مدلوله","يعرف بالضمير: مبني للمجهول"],"questions":[{"question":"ما تعريف الضمير؟","options":["اسم يدل على متكلم أو مخاطب أو غائب","اسم يدل على زمان","حرف جر","فعل ماضٍ"],"answer":0,"explanation":"فالاسم إن دل على حضور (متكلم أو مخاطب) أو غائب يعرف بالضمير: هذا حده الجامع."},{"question":"لم سمي الضمير ضميرًا؟","options":["لخفاء دلالته على المسمى بلا ذكر صريح له","لكبر حجمه","لطوله","بلا سبب"],"answer":0,"explanation":"من الضمير بمعنى الخفي: أنا تدل على المتكلم دون ذكر اسمه؛ فدلالته مضمرة خفية."},{"question":"اذكر الضمائر الثلاثة بأمثلتها:","options":["المتكلم: أنا؛ والمخاطب: أنت؛ والغائب: هو","الحاضر فقط","الغائب فقط","الظرف"],"answer":0,"explanation":"المتكلم يتكلم عن نفسه (أنا ونحن)؛ والمخاطب يكلم (أنت وأنتم)؛ والغائب يتكلم عنه (هو وهي وهم)."},{"question":"ما معنى «حضور» في البيت؟","options":["المتكلم والمخاطب لأنهما حاضران مجلس الكلام","الغائب","الفعل","المكان"],"answer":0,"explanation":"الحضور يشمل قسمين: المتكلم والمخاطب؛ لأن كلا منهما حاضر عند التكلم؛ مقابل الغائب."},{"question":"أعرب «غائب» في البيت:","options":["اسم معطوف على حضور مجرور بعلى بالكسرة","مرفوع","منصوب","فاعل"],"answer":0,"explanation":"أو غائب: معطوف على (حضور) المجرور بعلى: اسم مجرور وعلامة جره الكسرة."}]},{"body":["تدريب التصنيف: صنف الضمائر في الجمل: «أنا مسلم»: أنا ضمير متكلم منفصل مبتدأ. «ذهبنا»: نا ضمير متكلم متصل فاعل. «أنت مجتهد»: أنت مخاطب مبتدأ. «كتابك جديد»: الكاف مخاطب مضاف إليه. «هو قائم»: هو غائب مبتدأ. «أكرمته»: الهاء غائب مفعول به.","الضمائر كلها معارف: لأنها تدل على معين: فأنا شخص معين هو المتكلم؛ وهو شخص معين هو الغائب المقصود؛ فهي أقوى المعارف دلالة على التعيين... وهي أول الستة لذلك.","والضمائر كلها مبنية: لا يتغير آخرها بتغير موقعها: أنا في الرفع والنصب واحدة لفظًا: أنا قائم وأكرمني أنا... لكن محلها الإعرابي يتغير: مبتدأ هنا ومفعول هناك؛ فتقول: مبني في محل كذا.","الضمير يكون ظاهرًا (منفصلًا أو متصلًا) ومستترًا: «ذهبَ»: فاعله ضمير مستتر تقديره هو؛ و«أكتبُ»: فاعله مستتر تقديره أنا؛ فلا تحسبن الفعل بلا فاعل إذا لم تره ظاهرًا.","فائدة الضمير في الكلام: يوجز الكلام ويمنع التكرار: بدل «جاء خالد وأكرمت خالد وسلمت على خالد» تقول: جاء خالد وأكرمته وسلمت عليه؛ فهو آلة اختصار عظيمة.","خلاصة: الضمير اسم معرفة مبني يدل على متكلم أو مخاطب أو غائب؛ ظاهرًا كان أو مستترًا؛ والبيت القادم يعدد المنفصل منها والمتصل بالعدد."],"examples":["أنا مبتدأ ونا فاعل","الكاف مضاف إليه والهاء مفعول به","الضمائر كلها معارف مبنية","ذهب: الفاعل مستتر تقديره هو","الضمير يمنع التكرار","ظاهر: منفصل ومتصل"],"questions":[{"question":"صنف الضمائر في «أكرمته» و«ذهبنا» و«كتابك»:","options":["الهاء غائب ونا متكلم والكاف مخاطب","كلها متكلم","كلها غائب","كلها مخاطب"],"answer":0,"explanation":"أكرمته: الهاء مفعول به يدل على غائب؛ ذهبنا: نا فاعل متكلم؛ كتابك: الكاف مضاف إليه مخاطب."},{"question":"لم عدت الضمائر معارف؟","options":["لأنها تدل على معين: المتكلم أو المخاطب أو الغائب المعين","لأنها تقبل أل","لأنها أفعال","ليست معارف"],"answer":0,"explanation":"أنا: المتكلم بعينه؛ هو: الغائب المقصود بعينه؛ فدلالتها على التعيين أقوى من كثير من الأعلام."},{"question":"ما الفرق بين الضمير الظاهر والمستتر؟","options":["الظاهر منطوق منفصل أو متصل والمستتر مقدر في الفعل","لا فرق","المستتر اسم ظاهر","الظاهر محذوف"],"answer":0,"explanation":"ذهب: الفاعل مستتر تقديره هو؛ ذهبوا: الواو ضمير بارز متصل؛ هو قائم: ضمير بارز منفصل."},{"question":"ما فائدة الضمير في الكلام؟","options":["الإيجاز ومنع التكرار","الإطناب","الغموض","لا فائدة"],"answer":0,"explanation":"أكرمته وسلمت عليه: بدل تكرار الاسم الظاهر؛ فالضمير آلة اختصار وربط للكلام."},{"question":"الضمائر معربة أم مبنية؟","options":["مبنية كلها لكن محلها الإعرابي يتغير","معربة","بعضها معرب","لا إعراب لها إطلاقًا"],"answer":0,"explanation":"أنا وهو والتاء والكاف: مبنية لا يتغير لفظها؛ وتقول: مبني في محل رفع أو نصب أو جر بحسب الموقع."}]}]},{"id":"wahi-verse-015","title":"الضمائر المنفصلة والمتصلة","summary":"ستة ضمائر منفصلة وتسعة متصلة، وما تصلح له كل مجموعة.","verse":{"number":15,"section":"النكرة والمعرفة","text":"سِتَّةٌ ضَمَائِرُ مُنْفَصِلَةْ وَتِسْعَةٌ ضَمَائِرُ مُتَّصِلَةْ"},"segments":[{"body":["البيت الخامس عشر: «سِتَّةٌ ضَمَائِرُ مُنْفَصِلَةْ وَتِسْعَةٌ ضَمَائِرُ مُتَّصِلَةْ». يعدد الضمائر منفصلها ومتصلها، ونفهمه كلمة كلمة.","«سِتَّةٌ»: خبر مبتدأ محذوف أو مبتدأ: المنفصلة من الضمائر ستة. «ضَمَائِرُ مُنْفَصِلَةْ»: ضمائر: نعت أو بدل؛ ومنفصلة: نعت: التي تنفصل بنفسها ولا تتصل بغيرها؛ وحذفت التاء للوزن.","«وَتِسْعَةٌ ضَمَائِرُ مُتَّصِلَةْ»: وتسعة منها متصلة: تتصل بالأسماء والأفعال والحروف ولا تقوم بنفسها.","الستة المنفصلة أصولها: للرفع: أنا (وفرعها: نحن)، وأنتَ (وفروعها: أنتِ وأنتما وأنتم وأنتنَّ)، وهو (وفروعه: هي وهما وهم وهنَّ). وللنصب ثلاثة: إياي وإياك وإياه (وفروعها). ومعنى كونها للرفع أنها تقع مواقع الرفع: مبتدأ وخبرًا وفاعلًا، ولا تقع نصبًا ولا جرًّا؛ وللنصب بالعكس.","التسعة المتصلة: خمسة للرفع مجموعة في لفظ (تواني): تاء الفاعل (ذهبتُ)، وواو الجماعة (ذهبوا)، وألف الاثنين (ذهبا)، ونون النسوة (ذهبنَ)، وياء المخاطبة (تذهبينَ)؛ وهي تقع فاعلًا ونائب فاعل فقط.","وثلاثة للنصب والجر مجموعة في لفظ (هكي): هاء الغائب (يحبه وكتابه)، وكاف المخاطب (يحبك وكتابك)، وياء المتكلم (يحبني وكتابي). وواحد للرفع والنصب والجر: نا المتكلمين (ذهبنا ويحبنا وكتابنا)."],"examples":["ستة منفصلة وتسعة متصلة","تواني: خمسة للرفع","هكي: ثلاثة للنصب والجر","نا: للأحوال الثلاثة","أنا وأنت وهو وإياي وإياك وإياه: الستة","المتصلة لا تقوم بنفسها"],"questions":[{"question":"كم الضمائر المنفصلة والمتصلة؟","options":["ستة منفصلة وتسعة متصلة","خمسة وعشرة","ثلاثة وثلاثة","سبعة وسبعة"],"answer":0,"explanation":"ستة ضمائر منفصلة وتسعة ضمائر متصلة: كما نص البيت."},{"question":"ما الضمائر المنفصلة الستة بأصولها؟","options":["أنا وأنت وهو للرفع وإياي وإياك وإياه للنصب","التاء والكاف","نا والهاء","الواو والألف"],"answer":0,"explanation":"للرفع: أنا وأنت وهو مع فروعها (نحن وأنتم وهن...)؛ وللنصب: إياي وإياك وإياه مع فروعها."},{"question":"ما لفظ الجامع للمتصلة الرافعة؟","options":["تواني: التاء والواو والألف والنون والياء","هكي","أنيت","لم"],"answer":0,"explanation":"تاء الفاعل وواو الجماعة وألف الاثنين ونون النسوة وياء المخاطبة: خمسة للرفع جمعت في (تواني)."},{"question":"ما ضمائر النصب والجر من المتصلة؟","options":["هكي: الهاء والكاف والياء","تواني","إياي","أنا"],"answer":0,"explanation":"هاء الغائب وكاف المخاطب وياء المتكلم: تنصب مفعولًا (يحبه) وتجر مضافًا إليه أو بحرف (كتابه وله)."},{"question":"ما الضمير الجامع للأحوال الثلاثة؟","options":["نا المتكلمين","التاء","الهاء","أنا"],"answer":0,"explanation":"نا: ذهبنا (رفع: فاعل)، يحبنا (نصب: مفعول)، كتابنا ولنا (جر): فهي للرفع والنصب والجر."}]},{"body":["تدريب إعرابي على المنفصلة: «أنا مؤمن»: أنا ضمير منفصل مبني على السكون في محل رفع مبتدأ. «إياك نعبد»: إياك ضمير منفصل مبني في محل نصب مفعول به مقدم. «هو قائم»: هو مبتدأ.","تدريب على المتصلة: «كتبتُ الدرس»: التاء ضمير متصل مبني على الضم في محل رفع فاعل. «كرّموني»: الياء مفعول به مبني على السكون في محل نصب. «قلمكَ»: الكاف مضاف إليه في محل جر. «سلمتُ عليهم»: الهاء مع الميم ضمير في محل جر.","الفرق العملي بين المنفصل والمتصل: المنفصل يقوم بنفسه في أول الجملة وبعد الحروف: أنا قائم، وإنّ أنا... ولا يتصل بفعل أو اسم؛ والمتصل لا يرد إلا لاحقًا بكلمة: ذهبت وكتابك وله.","متى يجب المنفصل؟ عند التوكيد والاختصاص: «أنا قمتُ» أفاد التخصيص (أنا لا غيري)؛ وفي إياك نعبد: تقديم المفعول المنفصل أفاد الحصر: لا نعبد غيرك.","جدول الحفظ: منفصلة: أنا وأنت وهو (رفع) وإياي وإياك وإياه (نصب)؛ متصلة: تواني (رفع) وهكي (نصب وجر) ونا (الكل). احفظ الجدول بلفظيه: تواني وهكي، يثبت لك الباب كله.","خلاصة باب الضمائر: تعريفها (اسم يدل على متكلم أو مخاطب أو غائب)؛ وعددها (ستة منفصلة وتسعة متصلة)؛ وأحكامها (للرفع أو النصب والجر أو الثلاثة)؛ وهي كلها معارف مبنية."],"examples":["أنا مؤمن: مبتدأ","إياك نعبد: مفعول مقدم أفاد الحصر","كتبت: التاء فاعل","قلمك: الكاف مضاف إليه","أنا قمت: المنفصل للتخصيص","تواني وهكي ونا: جدول الحفظ"],"questions":[{"question":"أعرب «إياك» في «إياك نعبد»:","options":["ضمير منفصل مبني في محل نصب مفعول به مقدم","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"إياك: مفعول به مقدم على الفعل (نعبد)؛ والأصل: نعبدك؛ وتقديمه أفاد الحصر والاختصاص."},{"question":"أعرب التاء في «كتبت الدرس»:","options":["ضمير متصل مبني على الضم في محل رفع فاعل","مفعول به","تاء تأنيث","مضاف إليه"],"answer":0,"explanation":"التاء هنا تاء الفاعل: ضمير متكلم فاعل؛ بخلاف سجدتْ (هي): تاء تأنيث ساكنة لا محل لها."},{"question":"متى يستعمل الضمير المنفصل وجوبًا تقريبًا؟","options":["عند إفادة التخصيص والتوكيد والحصر","في كل جملة","مع الأفعال فقط","لا يستعمل"],"answer":0,"explanation":"أنا قمت: خصصت القيام بنفسي؛ إياك نعبد: حصرنا العبادة لله؛ فالمنفصل أداة تأكيد معنوي."},{"question":"أعرب الياء في «كرموني»:","options":["ياء المتكلم ضمير متصل مبني في محل نصب مفعول به","فاعل","مضاف إليه","نعت"],"answer":0,"explanation":"اتصلت الياء بفعل فهي مفعول به: كرموني: كرمني القوم؛ والواو فاعل؛ والنون للوقاية."},{"question":"لخص أقسام الضمائر المتصلة التسعة:","options":["خمسة للرفع (تواني) وثلاثة للنصب والجر (هكي) وواحد للثلاثة (نا)","كلها للرفع","كلها للنصب","اثنان وسبعة"],"answer":0,"explanation":"تاء الفاعل وواو الجماعة وألف الاثنين ونون النسوة وياء المخاطبة؛ وهاء الغائب وكاف المخاطب وياء المتكلم؛ ونا للأحوال الثلاثة."}]}]},{"id":"wahi-verse-016","title":"العلم: معرفة بذاتها","summary":"البيت السادس عشر: تعريف العلم وأمثلته من أسماء الله والملائكة والناس والبلدان.","verse":{"number":16,"section":"المعارف: العلم","text":"وَالْعَلَمُ اسْمٌ عُيِّنَ الْمُسَمَّى / بِلَفْظِهِ، كَـ(مَكَّةٍ، وَسَلْمَى)"},"segments":[{"body":["البيت السادس عشر: «وَالْعَلَمُ اسْمٌ عُيِّنَ الْمُسَمَّى بِلَفْظِهِ، كَـ(مَكَّةٍ، وَسَلْمَى)». يشرح ثاني المعارف: العلم، ونفهمه كلمة كلمة.","«وَالْعَلَمُ»: معطوف على ما قبله من المعارف؛ والعلم: مبتدأ. «اسْمٌ»: خبره. «عُيِّنَ»: فعل ماضٍ مبني للمجهول: عُيّن أي حُدِّد وعُرِف. «الْمُسَمَّى»: نائب الفاعل: الشخص أو الشيء المسمى بهذا الاسم.","«بِلَفْظِهِ»: الباء للسببية أو الوسيلة: عين المسمى بمجرد اللفظ نفسه؛ بلا حاجة إلى شيء آخر. «كَـ(مَكَّةٍ وَسَلْمَى)»: الكاف للتشبيه: مثل مكة اسم البلدة، وسلمى اسم المرأة.","فالمعنى: العلم اسم عُيِّن مسماه بمجرد لفظه: حين تسمع «مكة» تحضر في ذهنك بلدة بعينها لا غيرها، وحين تسمع «سلمى» تحضر امرأة بعينها لا أي امرأة.","الفرق بين العلم والنكرة: النكرة تدل على الشائع: «رجل» ينطبق على كل رجل؛ والعلم يدل على واحد بعينه دون حاجة إلى قرينة ولا إضافة ولا أل.","ولهذا كان العلم معرفة بذاته ولفظه؛ إذ الدلالة على المعين حاصلة من نفس اللفظ؛ فهو أظهر المعارف بعد الضمير في وضوح الدلالة على المعين."],"examples":["العلم: اسم عين المسمى بلفظه","مكة: علم بلدة","سلمى: علم امرأة","النكرة تدل على الشائع","العلم بلا قرينة ولا إضافة","معرفة بذاته"],"questions":[{"question":"ما تعريف العلم؟","options":["اسم عين المسمى بلفظه دون حاجة إلى قرينة","اسم يدل على غير معين","حرف","اسم موصول"],"answer":0,"explanation":"مكة وسلمى: تسمع اللفظ فيحضر المسمى بعينه؛ فالعلم اسم اختص بمسماه لا يشركه فيه غيره."},{"question":"ما الفرق بين العلم والنكرة؟","options":["العلم يدل على معين بذاته والنكرة على الشائع من جنسه","لا فرق","النكرة أخص","العلم حرف"],"answer":0,"explanation":"رجل: أي رجل (نكرة)؛ زيد: رجل بعينه (علم)؛ فالعلم معرفة بنفسه."},{"question":"لم كان العلم معرفة؟","options":["لأن لفظه نفسه يدل على معين بلا واسطة","لأنه منون","لأنه فعل","لأنه حرف"],"answer":0,"explanation":"لا يحتاج أل ولا إضافة ولا إشارة: مجرد قولك «مكة» كاف في تعيين المدينة."},{"question":"ما إعراب «المسمى» في البيت؟","options":["نائب فاعل مرفوع لفعل مبني للمجهول (عين)","فاعل","مفعول به","مبتدأ"],"answer":0,"explanation":"عين: مبني للمجهول؛ والمسمى نائب فاعل مرفوع بالضمة: عين المسمى = عُيّن الشيء المسمى."},{"question":"اذكر أعلامًا من أنواع مختلفة:","options":["زيد علم رجل ومكة علم بلدة وأحد علم جبل","رجل ومدينة وجبل","هذا وذلك","الذي والتي"],"answer":0,"explanation":"الأعلام تتنوع: أشخاص (زيد وسلمى) وبلدان (مكة ومصر) وجبال (أحد) وكتب (البخاري): كلها معارف."}]},{"body":["تدريب التمييز: صنف: «محمد» (علم)؛ «رجل» (نكرة)؛ «مصر» (علم)؛ «بلد» (نكرة)؛ «القرآن» (معرف بأل لا علم عند الأظهر)؛ «فاطمة» (علم مؤنث).","العلم المفرد من الأسماء الخمسة المبنية... لا: العلم معرب في الغالب: جاء زيدٌ ورأيت زيدًا وسلمت على زيدٍ؛ لكنه ممنوع من الصرف أحيانًا: فاطمة وزينب (للعلمية والتأنيث) فتجر بالفتحة: سلمت على فاطمةَ.","منع الصرف: العلم إذا اجتمع فيه سببان (كالعلمية والتأنيث في فاطمة، أو العلمية والعجمة في إبراهيم) امتنع من التنوين وجر بالفتحة؛ وهذا باب سيأتي في العلامات الفرعية (الممنوع من الصرف).","التنوين في الأعلام: «محمدٌ» علم منون: تنوينه تنوين تمكين لا تنكير؛ فلا يحسبنك أن كل منون نكرة: فالأعلام العربية تنوّن وتبقى معارف.","فائدة: العلم أصل في النداء المبني: يا محمدُ؛ لأنه معين بذاته؛ فالمنادى العلم المفرد مبني على الضمة في محل نصب كما سيأتي في باب المنادى.","خلاصة: العلم معرفة بذاته يعين مسماه بمجرد لفظه: مكة وسلمى؛ وهو معرب غالبًا، منون عربيًّا، ممنوع من الصرف إذا اجتمع سببان؛ وثالث المعارف الستة."],"examples":["محمد علم منون: تنوين تمكين","فاطمة: ممنوعة من الصرف","سلمت على فاطمةَ: جر بالفتحة","إبراهيم: علمية وعجمة","يا محمدُ: منادى مبني","القرآن: معرف بأل"],"questions":[{"question":"صنف: «مصر» و«بلد» و«فاطمة»:","options":["علم ونكرة وعلم","كلها أعلام","كلها نكرات","نكرة وعلم وعلم"],"answer":0,"explanation":"مصر علم بلد؛ بلد نكرة: أي بلد؛ فاطمة علم امرأة: فالأول والثالث معارف والثاني نكرة."},{"question":"«محمدٌ» منون فهل هو نكرة؟","options":["لا؛ علم معرفة وتنوينه تنوين تمكين لا تنكير","نعم نكرة","حرف","فعل"],"answer":0,"explanation":"الأعلام العربية تنوّن: محمد وزيد؛ وتنوينها تمكين للاسمية لا تنكير: فهي معارف منونة."},{"question":"لم جرت «فاطمة» بالفتحة في «سلمت على فاطمةَ»؟","options":["لأنها ممنوعة من الصرف للعلمية والتأنيث","لأنها منصوبة","لأنها فعل","خطأ"],"answer":0,"explanation":"العلم المؤنث بلا تاء أو بتاء زائدة... فاطمة علم مؤنث: اجتمع فيها سببان فمنعت من الصرف: تجر بالفتحة نيابة عن الكسرة."},{"question":"ما حكم العلم المفرد في النداء؟","options":["مبني على الضمة في محل نصب: يا محمدُ","منصوب بالفتحة","مجرور","معرب"],"answer":0,"explanation":"المنادى المعين باسم واحد (علم مفرد) مبني على ما يرفع به في محل نصب: يا زيدُ يا محمدُ."},{"question":"ما سببا منع الصرف في «إبراهيم»؟","options":["العلمية والعجمة","التأنيث والتنوين","الوزن","العدد"],"answer":0,"explanation":"إبراهيم: علم أعجمي: اجتمعت العلمية والعجمة فمنع من الصرف: مررت بإبراهيمَ بالفتحة."}]}]},{"id":"wahi-verse-017","title":"المعارف المحصورة والميسورة","summary":"البيت السابع عشر: المعارف المبهمة ألفاظها محضورة (معدودة)، واللام والعلم ميسورة الألفاظ.","verse":{"number":17,"section":"المعارف: المحصور والميسور","text":"وَمُبْهَمٌ أَلْفَاظُهُ مَحْضُورَهْ / وَالْقَهْقَرَى وَذُو الْغِيَابِ مَيْسُورَهْ"},"segments":[{"body":["البيت السابع عشر: «وَمُبْهَمٌ أَلْفَاظُهُ مَحْضُورَهْ وَالْقَهْقَرَى وَذُو الْغِيَابِ مَيْسُورَهْ». يقسم المعارف من حيث حصر ألفاظها، ونفهمه كلمة كلمة.","«وَمُبْهَمٌ»: المعارف المبهمة: التي لا يدل لفظها وحده على معين بل يحتاج إلى سياق: «هو» ضمير يحتاج من يعود عليه، و«هذا» اسم إشارة يحتاج مشارًا إليه، و«الذي» موصول يحتاج صلة تتممه.","«أَلْفَاظُهُ»: مبتدأ مضاف والهاء مضاف إليه: ألفاظ هذه المعارف المبهمة. «مَحْضُورَهْ»: خبره: محصورة معدودة منحصرة (حَضَرَ بمعنى أحصى وعدّ)؛ وحذفت التاء للوزن.","فألفاظ الضمائر معلومة العدد: خمسة عشر؛ وأسماء الإشارة ألفاظ قليلة محدودة: هذا وهذه وهؤلاء وذلك؛ والموصولات محصورة: الذي والتي والذين واللاتي ومن وما.","«وَالْقَهْقَرَى»: لام التعريف (أل) كما تقدم؛ وهنا تمثل المعرَّف بأل. «وَذُو الْغِيَابِ»: العلم (ذو الغيظ في البيت السابق وهنا ذو الغياب: مضاف إلى معرفة... والأظهر: العلم)؛ وهذان النوعان: «مَيْسُورَهْ»: غير محصورين: ألفاظهما سائرة ممتدة لا تنحصر.","فالمعنى: المعارف قسمان من حيث الألفاظ: مبهمة محضورة الألفاظ (الضمير والإشارة والموصول)، وميسورة غير محصورة (المعرف بأل والعلم والمضاف إلى معرفة): فالرجل والقلم وأعلام الناس والبلاد لا تعد ولا تحصى."],"examples":["مبهم: يحتاج سياقًا","محضوره: محصور معدود","الضمائر 15 والإشارات والموصولات قليلة","القهقرى: المعرّف بأل","ميسوره: غير محصور","الأعلام والمعرّفات بأل لا تحصى"],"questions":[{"question":"ما المعارف المبهمة؟","options":["الضمير واسم الإشارة والاسم الموصول تحتاج سياقًا","العلم","المعرّف بأل","النكرة"],"answer":0,"explanation":"هو تحتاج مرجعًا، وهذا تحتاج مشارًا إليه، والذي تحتاج صلة: فدلالتها مبهمة حتى يقترن بها سياق."},{"question":"ما معنى «محضوره»؟","options":["محصور معدود الألفاظ","كثير لا يحصى","محذوف","مبني"],"answer":0,"explanation":"حَضَرَ بمعنى أحصى: ألفاظ الضمائر (خمسة عشر) والإشارات والموصولات ألفاظ منحصرة معلومة العدد."},{"question":"ما الميسور من المعارف؟","options":["ما لم تنحصر ألفاظه: المعرّف بأل والعلم","الضمائر","الإشارات","الموصولات"],"answer":0,"explanation":"الأسماء المقترنة بأل وأعلام الناس والبلاد لا تنحصر: كل يوم يستجد علم: فهي ميسورة غير محضورة."},{"question":"لم عدت المبهمة محضورة؟","options":["لأن ألفاظها أقسام مغلقة معلومة لا تستجد","لأنها طويلة","لأنها نكرات","بلا سبب"],"answer":0,"explanation":"لا يستحدث العربي ضميرًا جديدًا ولا اسم إشارة جديدًا؛ فألفاظها ثابتة محصورة عبر الدهر."},{"question":"أعرب «ألفاظه محضوره»:","options":["مبتدأ مضاف وخبر مرفوع","فعل وفاعل","مفعول به","حال"],"answer":0,"explanation":"ألفاظ: مبتدأ مرفوع مضاف؛ والهاء مضاف إليه؛ ومحضورة: خبر مرفوع بالضمة؛ والجملة نعت لمبهم."}]},{"body":["تدريب الحصر: أي هذه الألفاظ محصور؟ «هو»: محضور (ضمير)؛ «زيد»: ميسور (علم)؛ «الذي»: محضور (موصول)؛ «الكتاب»: ميسور (معرف بأل)؛ «هؤلاء»: محضور (إشارة)؛ «كتاب الطالب»: ميسور (مضاف إلى معرفة).","الفرق العملي: الألفاظ المحضورة تحفظ عددًا: فتستطيع أن تقول حفظت الضمائر كلها والموصولات كلها؛ أما الميسورة فلا تستوفيها قائمة: فتتعلم ضابطها لا أفرادها.","فائدة التقسيم: الضابط في المحضور: العد والحصر؛ وفي الميسور: الوصف: فكل اسم قبل أل فهو معرفة، وكل اسم عين مسماه بلفظه فهو علم؛ فالضابط يغنيك عن حصر ما لا ينحصر.","تنبيه على «ذو الغياب»: عبارة البيت تمثل العلم (كما مثلته «ذو الغيظ» سابقًا) أو المضاف إلى معرفة: فكلاهما ميسور: لا تنحصر أعلام الناس ولا مركبات الإضافة.","تدريب: اذكر خمسة أعلام جديدة من عندك (أحمد، ليلى، القاهرة، النيل، طه): كلها ميسورة؛ واذكر الضمائر الخمسة عشر: لا تستطيع أن تزيد عليها: فهي محضورة.","خلاصة: المعارف من حيث ألفاظها: مبهمة محضورة (ضمير وإشارة وموصول) وميسورة (علم وأل ومضاف إلى معرفة)؛ وبذلك تم باب النكرة والمعرفة؛ والقادم باب المعرب والمبني."],"examples":["هو محضور وزيد ميسور","الذي محضور والكتاب ميسور","المحضور يحفظ عددًا","الميسور يضبط وصفًا","ذو الغيظ وذو الغياب: مثالان للعلم","تم باب النكرة والمعرفة"],"questions":[{"question":"صنف من حيث الحصر: «هؤلاء» و«كتاب الطالب»:","options":["محضور وميسور","كلاهما محضور","كلاهما ميسور","ميسور ومحضور"],"answer":0,"explanation":"هؤلاء اسم إشارة: ألفاظ الإشارة محصورة؛ وكتاب الطالب مضاف إلى معرفة: مركبات الإضافة لا تنحصر: ميسور."},{"question":"كيف تتعلم المعارف المحضورة والميسورة؟","options":["المحضورة بالعد والحفظ والميسورة بالضابط","كلاهما بالحفظ","كلاهما بالضابط","لا تتعلم"],"answer":0,"explanation":"احفظ ألفاظ الضمائر والإشارات والموصولات واحدًا واحدًا؛ واضبط الميسور بوصفه: ما قبل أل أو عين مسماه بلفظه."},{"question":"لم لا تحصى أعلام الناس؟","options":["لأنها ميسورة تستجد كل يوم","لأنها قليلة","لأنها حروف","تحصى فعلًا"],"answer":0,"explanation":"كل مولود يسمى باسم: فالأعلام لا تنغلق قائمتها؛ بخلاف الضمائر الثابتة."},{"question":"ما قسمتا المعارف من حيث الألفاظ؟","options":["مبهمة محضورة وميسورة غير محصورة","مفردة وجموع","مذكرة ومؤنثة","معربة فقط"],"answer":0,"explanation":"مبهم ألفاظه محضوره (الضمائر والإشارات والموصولات)؛ والقهقرى وذو الغياب ميسوره (أل والعلم والمضاف)."},{"question":"اذكر ضابط المعرّف بأل:","options":["كل اسم قبل أل التعريف","كل علم","كل ضمير","كل حرف"],"answer":0,"explanation":"الرجل والقلم والجلوس: ما اقترن بأل صار معرفة؛ وهذا ضابط يغني عن حصر أفراده الميسورة."}]}]},{"id":"wahi-verse-018","title":"المعرب والمبني","summary":"البيت الثامن عشر: الكلام قسمان: معرب يتغير آخره، ومبني لا يتغير.","verse":{"number":18,"section":"المعرب والمبني","text":"بَعْضُ الْكَلَامِ مُعْرَبٌ مُخْتَلِفُ / وَبَعْضُهُ الْمَبْنِيُّ لَا يَخْتَلِفُ"},"segments":[{"body":["البيت الثامن عشر: «بَعْضُ الْكَلَامِ مُعْرَبٌ مُخْتَلِفُ وَبَعْضُهُ الْمَبْنِيُّ لَا يَخْتَلِفُ». به يبدأ باب عظيم هو أساس الإعراب: المعرب والمبني، ونفهمه كلمة كلمة.","«بَعْضُ»: مبتدأ مضاف. «الْكَلَامِ»: مضاف إليه: بعض كلامنا. «مُعْرَبٌ»: خبر أول: معرب. «مُخْتَلِفُ»: خبر ثانٍ أو نعت: مختلف الآخر يتغير.","«وَبَعْضُهُ»: معطوف: وبعض الكلام. «الْمَبْنِيُّ»: خبره: مبني. «لَا يَخْتَلِفُ»: جملة فعلية نعت أو خبر ثانٍ: لا يتغير آخره أبدًا.","المعرب: ما تغير آخره باختلاف العوامل الداخلة عليه. جرب «محمد»: جاء محمدٌ (ضمة للرفع)، ورأيت محمدًا (فتحة للنصب)، وسلمت على محمدٍ (كسرة للجر)؛ الاسم واحد وآخره ثلاث صور.","المبني: ما ثبت آخره على حال واحدة مهما دخل عليه: جاء هذا، ورأيت هذا، وسلمت على هذا: لم تتغير الألف في هذا في المواضع الثلاثة.","فالمعنى: الكلام قسمان: معرب مختلف الآخر يتبدل بتبدل موقعه، ومبني ثابت لا يتبدل؛ وهذا التغير في آخر المعرب هو الذي نسميه الإعراب."],"examples":["بعض الكلام معرب مختلف","وبعضه المبني لا يختلف","محمدٌ محمدًا محمدٍ: معرب","هذا: ثابت في الثلاثة","الإعراب: تغير آخر الكلمة","البناء: ثبات الآخر"],"questions":[{"question":"ما المعرب وما المبني؟","options":["المعرب ما تغير آخره بالعوامل والمبني ما ثبت آخره","بالعكس","كلاهما يتغير","كلاهما ثابت"],"answer":0,"explanation":"جاء محمد ورأيت محمدًا ومررت بمحمد: معرب؛ وهذا في المواضع الثلاثة بلفظ واحد: مبني."},{"question":"ما الإعراب؟","options":["تغير أواخر الكلم باختلاف العوامل الداخلة عليها","تشكيل الحروف","ضبط المعاني","الإملاء"],"answer":0,"explanation":"الإعراب اصطلاحًا: تغيير آخر الكلمة المعربة لأجل عامل دخل عليها: رفعًا أو نصبًا أو جرًّا أو جزمًا."},{"question":"لم سمي المبني مبنيًّا؟","options":["لثباته على صورة واحدة كالبناء الثابت","لكثرته","لطوله","لقِدَمه"],"answer":0,"explanation":"البناء في اللغة اللزوم والثبات: فالمبني لازم لصورته لا يتغير آخره: هذا ولم وهو أبدًا على حالها."},{"question":"أعرب «محمد» في المواضع الثلاثة:","options":["مرفوع بالضمة ومنصوب بالفتحة ومجرور بالكسرة","مرفوع دائمًا","منصوب دائمًا","مجرور دائمًا"],"answer":0,"explanation":"جاء محمدٌ: فاعل مرفوع؛ رأيت محمدًا: مفعول منصوب؛ مررت بمحمدٍ: اسم مجرور: فتغير آخره بالعوامل."},{"question":"ما جامع القسمة في البيت؟","options":["كل كلامنا إما معرب مختلف أو مبني لا يختلف","ثلاثة أقسام","أربعة","خمسة"],"answer":0,"explanation":"بعض الكلام معرب مختلف وبعضه المبني لا يختلف: قسمة ثنائية شاملة لكل كلمة في الكلام."}]},{"body":["تدريب التمييز: صنف معربًا أو مبنيًّا: «كتاب» (معرب: كتابٌ كتابًا كتابٍ)؛ «هو» (مبني: ثابت في كل موضع)؛ «يكتب» (معرب: يكتبُ يكتبَ يكتبْ)؛ «كتب» الماضي (مبني)؛ «على» (مبني)؛ «المعلمون» (معرب: المعلمون المعلمين).","تجربة عملية سريعة لأي كلمة: أدخل عليها عاملين مختلفين (فعلًا يتعدى إليها وحرف جر): «قلم»: رأيت قلمًا ومررت بقلمٍ: تغير: معرب. «أمس»: جئت أمس ومنذ أمس: لم يتغير: مبني.","المعرب لا يتغير إلا آخره: فالأول والوسط ثابتان: محمد: الميم والحاء والميم الأولى ثابتة؛ والتغير في الدال الأخيرة حركةً أو حرفًا؛ فالإعراب عند آخر الكلمة دائمًا.","فائدة كبرى: الإعراب لغة العرب الفصحى؛ به تعرف المقاصد: «أكرمَ العالِمُ الطالبَ» و«أكرمَ العالِمَ الطالبُ»: جملتان معناهما متعاكسان والفرق حركة آخر اسمين فقط: فالإعراب حارس المعنى.","العوامل: ما يغير آخر المعرب: الفعل (يرفع الفاعل)، وحرف الجر (يجر)، وإن (تنصب)، ولم (تجزم)... وسيأتي تفصيلها بابًا بابًا في أحكام الكلام.","خلاصة: الكلام معرب يتغير آخره أو مبني يثبت؛ والبيت فاتحة باب هو رأس مال النحو كله كما يصرح البيت القادم؛ فأتقن التمييز بينهما قبل كل شيء."],"examples":["كتاب معرب وهو مبني","يكتب معرب وكتب الماضي مبني","أمس: مبني","التغير في الآخر فقط","أكرم العالمُ الطالبَ: الإعراب حارس المعنى","العوامل: فعل وحرف جر وإن ولم"],"questions":[{"question":"صنف: «يكتب» و«كتب» و«على»:","options":["معرب ومبني ومبني","كلها معربة","كلها مبنية","مبني ومعرب ومبني"],"answer":0,"explanation":"يكتب: مضارع يتغير (يكتب يكتب يكتب)؛ وكتب الماضي مبني؛ وعلى حرف مبني."},{"question":"كيف تختبر كلمة لتعرف أمعربة هي أم مبنية؟","options":["أدخل عليها عاملين فإن تغير آخرها فمعرب وإلا فمبني","انظر طولها","انظر معناها","لا طريقة"],"answer":0,"explanation":"جرب التعدي والجر: رأيت أمس ومنذ أمس: لم يتغير: مبني؛ رأيت قلمًا وبقلم: تغير: معرب."},{"question":"أين يقع التغير في الكلمة المعربة؟","options":["في آخرها فقط حركة أو حرفًا","في أولها","في وسطها","في كلها"],"answer":0,"explanation":"محمد: تغيرت الدال الأخيرة: ضمة وفتحة وكسرة؛ وأول الكلمة ووسطها ثابتان: فالإعراب في الآخر."},{"question":"ما خطورة الإعراب على المعنى؟","options":["تغيير الحركة يعكس المعنى: أكرم العالمُ الطالبَ / أكرم العالمَ الطالبُ","لا أثر","يزين الكلام فقط","للقافية"],"answer":0,"explanation":"في الأولى العالم فاعل والطالب مفعول؛ وفي الثانية بالعكس؛ والفرق ضمة وفتحة: فالإعراب حارس المعنى."},{"question":"اذكر ثلاثة عوامل تغير آخر المعرب:","options":["الفعل يرفع فاعله وحرف الجر يجر وإن تنصب اسمها","النداء يرفع","السكون يرفع","لا عوامل"],"answer":0,"explanation":"جاء زيد (الفعل رفع)؛ مررت بزيد (الباء جرت)؛ إن زيدًا (إن نصبت)؛ ولم يقمْ (لم جزمت): فالعوامل أبواب قادمة."}]}]},{"id":"wahi-verse-019","title":"أهمية باب المعرب والمبني","summary":"البيت التاسع عشر: ضبط هذا الباب رأس المال وضرورة الوصال في تعلم النحو.","verse":{"number":19,"section":"المعرب والمبني","text":"وَضَبْطُ هَذَا الْبَابِ رَأْسُ الْمَالِ / فَإِنَّهُ ضَرُورَةُ الْوِصَالِ"},"segments":[{"body":["البيت التاسع عشر: «وَضَبْطُ هَذَا الْبَابِ رَأْسُ الْمَالِ فَإِنَّهُ ضَرُورَةُ الْوِصَالِ». يبين منزلة باب المعرب والمبني، ونفهمه كلمة كلمة.","«وَضَبْطُ»: مبتدأ مضاف: إتقان وإحكام. «هَذَا الْبَابِ»: مضاف إليه: باب المعرب والمبني المتقدم. «رَأْسُ الْمَالِ»: خبره مضاف ومضاف إليه: رأس المال: أصل مال التاجر الذي يتجر به.","«فَإِنَّهُ»: الفاء تعليل؛ وإن: حرف توكيد ناصب؛ والهاء: اسمها يعود على الباب أو الضبط. «ضَرُورَةُ الْوِصَالِ»: خبر إن مضاف ومضاف إليه: الضرورة التي يوصل بها إلى المقصود.","فالمعنى: ضبط هذا الباب -باب المعرب والمبني- كرأس المال للتاجر؛ فإنه الضرورة التي تصل بها إلى إتقان النحو.","وجه التشبيه: التاجر بلا رأس مال لا تجارة له مهما عرف من فنون البيع؛ وطالب النحو بلا تمييز بين المعرب والمبني لا إعراب له مهما حفظ من الأبواب.","والسبب: الإعراب كله فرع عن هذا التمييز: فإذا وقفت على كلمة سألت أولًا: معربة أم مبنية؟ فإن معربة: بحثت عن حكمها وعلامتها؛ وإن مبنية: قلت محلها كذا؛ فكل إعراب يبدأ من هنا."],"examples":["ضبط الباب رأس المال","ضرورة الوصال: الطريق إلى الإتقان","التاجر بلا رأس مال لا تجارة","الطالب بلا تمييز لا إعراب","أول سؤال: معرب أم مبني؟","إنه ضرورة: إن والهاء اسمها"],"questions":[{"question":"بم شبه المؤلف ضبط باب المعرب والمبني؟","options":["برأس مال التاجر","بالفرع","بالربح","بالسلعة"],"answer":0,"explanation":"وضبط هذا الباب رأس المال: كما لا تجارة بلا رأس مال، لا نحو لمن لم يميز المعرب من المبني."},{"question":"ما معنى «ضرورة الوصال»؟","options":["أنه الطريق الذي لا يوصل إلى إتقان النحو إلا منه","أمر كمالي","زيادة لفظية","باب فرعي"],"answer":0,"explanation":"فإنه ضرورة الوصال: هذا الباب ضرورة لازمة يصل بها الطالب إلى مقصوده: الإعراب الصحيح."},{"question":"ما أول سؤال تسأله عن كلمة تعربها؟","options":["معربة هي أم مبنية؟","ما معناها؟","ما وزنها؟","ما أصلها؟"],"answer":0,"explanation":"إن كانت معربة: ما حكمها وما علامتها؟ وإن كانت مبنية: ما محلها من الإعراب؟ فالتمييز مفتتح كل إعراب."},{"question":"أعرب «إنه» في البيت:","options":["إن حرف توكيد ونصب والهاء اسمها في محل نصب","فعل وفاعل","حرف جر","نعت"],"answer":0,"explanation":"إن: ناصبة؛ والهاء ضمير متصل اسم إن في محل نصب؛ وضرورة: خبر إن مرفوع مضاف."},{"question":"ما الفاء في «فإنه»؟","options":["فاء التعليل: تعلل كونه رأس المال","عطف","استئناف","تفصيل"],"answer":0,"explanation":"لما أخبر أنه رأس المال علل: فإنه ضرورة الوصال: فالفاء رابطة الإخبار بالعلة."}]},{"body":["تطبيق منهجي على جملة كاملة: «كتبَ الطالبُ الدرسَ»: كتب: ماضٍ مبني (لا تبحث عن إعراب لفظي)؛ الطالب: معرب مرفوع فاعل؛ الدرس: معرب منصوب مفعول: فأول خطوة كانت التمييز معربًا ومبنيًّا.","خطأ شائع عند المبتدئين: إعراب «هذا»: فيقول: هذا مرفوع بالضمة! والصواب: هذا اسم إشارة مبني على الكسر في محل رفع؛ فالخطأ ناشئ من خلط المعرب بالمبني: وهو ما حذر منه البيت قبل قدومه.","تدريب على خمس كلمات: ميّز ثم أعرب: «المسلمون يحفظون القرآنَ في المساجدِ»: المسلمون: معرب مرفوع بالواو؛ يحفظون: مضارع معرب مرفوع بثبوت النون؛ القرآن: معرب منصوب بالفتحة؛ في: حرف مبني؛ المساجد: معرب مجرور بالفتحة للمنع من الصرف.","كل باب آتٍ يستدعي هذا الباب: الفاعل (معرب مرفوع أو مبني في محل رفع)؛ والمنادى (مبني أو معرب)؛ والممنوع من الصرف (معرب بعلامة فرعية)... فالباب حاضر في كل درس قادم.","منة النظم: حذرك المؤلف من الاستعجال: لا تحفظ الأبواب قبل ضبط الأساس؛ فمن بنى على غير هذا الأساس اضطرب إعرابه كله كتاجر يربح ثم يخسر رأس ماله.","خلاصة: ضبط المعرب والمبني رأس المال وضرورة الوصال؛ فاجعله بوابة كل تمرين إعرابي: ميّز أولًا، ثم احكم ثانيًا، ثم عيّن العلامة ثالثًا."],"examples":["كتب مبني والطالب معرب","هذا مبني في محل رفع لا مرفوع","المسلمون مرفوع بالواو","المساجد مجرور بالفتحة","كل باب قادم يستدعي التمييز","ميز ثم احكم ثم عين العلامة"],"questions":[{"question":"أعرب «كتب» في «كتب الطالب الدرس»:","options":["فعل ماضٍ مبني على الفتح لا محل له من الإعراب","مرفوع","منصوب","مجزوم"],"answer":0,"explanation":"الماضي مبني: لا يوصف بالرفع والنصب؛ يقال: مبني على الفتح لا محل له من الإعراب."},{"question":"ما الخطأ في قولنا «هذا مرفوع بالضمة»؟","options":["هذا مبني والصواب: مبني على الكسر في محل رفع","لا خطأ","الصواب منصوب","الصواب مجرور"],"answer":0,"explanation":"أسماء الإشارة مبنية: فلا توصف بالرفع اللفظي؛ يقال: مبني في محل رفع (لوقوعه موقع المرفوع)."},{"question":"أعرب «المسلمون» و«يحفظون»:","options":["فاعل مرفوع بالواو ومضارع مرفوع بثبوت النون","منصوبان","مبنيان","مجزومان"],"answer":0,"explanation":"المسلمون: جمع مذكر سالم يرفع بالواو؛ ويحفظون: من الأفعال الخمسة يرفع بثبوت النون والواو فاعل."},{"question":"ما منهج الإعراب الثلاثي المستفاد من الباب؟","options":["ميز معربًا من مبني ثم عين الحكم ثم عين العلامة","احفظ بلا فهم","ترجم أولًا","ابدأ بالعلامة"],"answer":0,"explanation":"الضبط يسبق الحكم: التمييز (معرب/مبني) ثم الحكم (رفع/نصب/جر/جزم) ثم العلامة (ضمة/واو/حذف...)."},{"question":"لم حذر النظم من الاستعجال على الأبواب؟","options":["لأن البناء على غير الأساس يضطرب معه الإعراب كله","لأن الأبواب سهلة","لا سبب","للتخويف"],"answer":0,"explanation":"كالتاجر الذي يتجر بلا رأس مال فيخسر: من حفظ الأبواب ولم يميز المعرب من المبني اختل إعرابه."}]}]},{"id":"wahi-verse-020","title":"المبني كله: الحروف والماضي والأمر","summary":"البيت العشرون: الحروف كلها مبنية، وكذلك الفعل الماضي وفعل الأمر.","verse":{"number":20,"section":"المعرب والمبني","text":"حُرُوفُنَا جَمِيعُهَا مَبْنِيٌّ / وَفِعْلُ أَمْرٍ، وَكَذَا الْمَاضِي"},"segments":[{"body":["البيت العشرون: «حُرُوفُنَا جَمِيعُهَا مَبْنِيٌّ وَفِعْلُ أَمْرٍ، وَكَذَا الْمَاضِي». يعين المبني كله: ما لا يوجد فيه معرب أبدًا، ونفهمه كلمة كلمة.","«حُرُوفُنَا»: مبتدأ مضاف: حروف كلامنا كلها: من وإلى وعن وعلى وفي وهل ولم والواو والفاء. «جَمِيعُهَا»: نعت أو توكيد: جميعها بلا استثناء. «مَبْنِيٌّ»: خبر مرفوع بالضمة المقدرة منع من ظهورها الياء: كل حرف مبني.","«وَفِعْلُ أَمْرٍ»: معطوف: وفعل الأمر أيضًا: اكتب واذهب واستغفر: كلها مبنية. «وَكَذَا الْمَاضِي»: وكذلك الفعل الماضي: كتب وذهب واستغفر: مبني أيضًا.","فالمعنى: المبني كله -الذي لا معرب فيه إطلاقًا- ثلاثة أقسام: الحروف جميعها، وفعل الأمر، والفعل الماضي.","لم بنيت الحروف؟ لأنها خادمة معنوية لا تقبل العوامل: فـ«في» على صورة واحدة في كل موضع؛ ولا معنى لأن تقول: في مرفوعة أو منصوبة: إذ لا تتغير أبدًا.","ولم بني الماضي والأمر؟ لأنهما دالان على أمر ثابت: الماضي على حدث وقع وانقضى فلا يقبل التجديد، والأمر على طلب لم يقع فلا يقبل النسبة التي يقتضيها الإعراب... والمحفوظ العملي: هذان القسمان ثابتا الآخر لا يدخلهما إعراب لفظي."],"examples":["حروفنا جميعها مبني","من وإلى وهل ولم: مبنية","فعل أمر مبني: اكتب واذهب","وكذا الماضي: كتب وذهب","ثلاثة أقسام لا معرب فيها","الحرف خادم لا يقبل العوامل"],"questions":[{"question":"ما المبني كله؟","options":["الحروف جميعها وفعل الأمر والفعل الماضي","الأسماء","المضارع","المعرب"],"answer":0,"explanation":"حروفنا جميعها مبني وفعل أمر وكذا الماضي: ثلاثة أقسام لا يوجد فيها معرب أبدًا."},{"question":"لم بنيت الحروف كلها؟","options":["لأنها خادمة معنوية لا تقبل العوامل وثباتها على صورة واحدة","لأنها أسماء","لأنها أفعال","بلا سبب"],"answer":0,"explanation":"في وهل ولم: لا تتغير في موضع من المواضع؛ فهي مبنية لا ترفع ولا تنصب ولا تجر ولا تجزم."},{"question":"هل يدخل الإعراب اللفظي على الماضي والأمر؟","options":["لا؛ ثابتا الآخر مهما دخل عليهما","نعم دائمًا","أحيانًا","الماضي فقط"],"answer":0,"explanation":"كتب واكتب: لا تتغير أواخرهما بتغير العوامل: فهما مبنيان: يقال فيهما مبني على الفتح أو السكون."},{"question":"أعرب «اكتب» و«كتب»:","options":["فعل أمر مبني على السكون وفعل ماضٍ مبني على الفتح","مرفوعان","منصوبان","مجزومان"],"answer":0,"explanation":"اكتب: أمر مبني على السكون؛ وكتب: ماضٍ مبني على الفتح؛ ولا محل لهما من الإعراب."},{"question":"ما ضابط القسمة في البيت؟","options":["ما لا معرب فيه إطلاقًا: حروف وأمر وماضٍ","ما فيه معرب","الأسماء","الضمائر"],"answer":0,"explanation":"هذه الأقسام الثلاثة مبنية بالكامل: لا يوجد في فرد منها كلمة معربة؛ بخلاف الأسماء والمضارع."}]},{"body":["تدريب التصنيف: صنف مبنيًّا أو معربًا: «هل» (حرف: مبني)؛ «أكرمَ» (ماضٍ: مبني)؛ «أكرِمْ» (أمر: مبني)؛ «يكرم» (مضارع: معرب)؛ «كريم» (اسم: معرب)؛ «الواو» (حرف: مبني).","تنبيه مهم: بناء الماضي والأمر لا يخرجهما عن التركيب الإعرابي محلًّا: فقد يتعين محلهما: «لا تُهمل وتقصرْ»: تقصر فعل مضارع معطوف مجزوم؛ والماضي يقال له لا محل له في الأصح... فالمحل للضمائر والأسماء المبنية أظهر.","على ماذا يبنى الماضي؟ على الفتح في الأصل: كتبَ وذهبَ؛ وعلى الضم إذا اتصلت به واو الجماعة: كتبوا؛ وعلى السكون إذا اتصلت به تاء التأنيث أو تاء الفاعل: كتبتْ وكتبتُ.","وعلى ماذا يبنى الأمر؟ على السكون في الأصل: اكتبْ واذهبْ؛ وعلى حذف حرف العلة إذا كان معتل الآخر: ادعُ وسعِ واغفر... أي احذف الياء أو الواو: امشِ وادعُ؛ وعلى حذف النون إذا كان من الأفعال الخمسة: اكتبوا من تكتبون.","فائدة: إذا عرفت أن هذه الأقسام مبنية لم تتكلف إعرابها: فلا تقل: كتبَ مرفوع! بل: ماضٍ مبني؛ وهذا توفير لجهدك وضبط لعباراتك الإعرابية.","خلاصة: المبني كله ثلاثة: الحروف جمعاء، وفعل الأمر، والفعل الماضي؛ والبيت القادم يؤكد استحالة دخول الإعراب عليها؛ فاحفظ القسمة وعبارتها: مبني على كذا."],"examples":["هل وأكرم وأكرم: مبنية","يكرم وكريم: معربة","الماضي: فتح أو ضم أو سكون","كتبوا: مبني على الضم","الأمر: سكون أو حذف علة أو نون","ادع وامش: مبني على حذف حرف العلة"],"questions":[{"question":"صنف: «هل» و«أكرمَ» و«يكرم» و«كريم»:","options":["مبني ومبني ومعرب ومعرب","كلها معربة","كلها مبنية","معرب ومبني ومبني ومعرب"],"answer":0,"explanation":"هل: حرف مبني؛ أكرمَ: ماضٍ مبني؛ يكرم: مضارع معرب؛ كريم: اسم معرب."},{"question":"على ماذا يبنى الفعل الماضي؟","options":["على الفتح أصلًا والضم مع واو الجماعة والسكون مع التاءين","على الكسر","على الحذف دائمًا","لا يبنى"],"answer":0,"explanation":"كتبَ: فتح؛ كتبوا: ضم لاتصال الواو؛ كتبتْ وكتبتُ: سكون لاتصال تاء التأنيث أو تاء الفاعل."},{"question":"على ماذا يبنى فعل الأمر؟","options":["على السكون أو حذف حرف العلة أو حذف النون","على الفتح دائمًا","على الضمة","لا يبنى"],"answer":0,"explanation":"اكتب: سكون؛ ادع وامش: حذف حرف العلة (الواو والياء)؛ اكتبوا: حذف النون لأنه من الأفعال الخمسة."},{"question":"لم لا نقول «كتب مرفوع»؟","options":["لأنه مبني والرفع وصف للمعرب لا للمبني","لأنه منصوب","لأنه مجرور","نقول ذلك"],"answer":0,"explanation":"المبني لا يدخله إعراب لفظي: فيقال: ماضٍ مبني على الفتح لا محل له من الإعراب."},{"question":"أعرب «امشِ»:","options":["فعل أمر مبني على حذف حرف العلة من آخره","مبني على السكون","مرفوع","منصوب"],"answer":0,"explanation":"امشِ أصله امشِي بياء حذفت للجزم... للأمر: فعل أمر مبني على حذف حرف العلة والفاعل مستتر أنت."}]}]},{"id":"wahi-verse-021","title":"لا إعراب للمبني","summary":"البيت الحادي والعشرون: الحروف والماضي والأمر لا يدخلها الإعراب ولا يحال.","verse":{"number":21,"section":"المعرب والمبني","text":"وَهَذِهِ الْإِعْرَابُ لَا يَدْخُلُهَا / يُقَالُ: لَا مَحَالَّ إِعْرَابٌ لَّهَا"},"segments":[{"body":["البيت الحادي والعشرون: «وَهَذِهِ الْإِعْرَابُ لَا يَدْخُلُهَا يُقَالُ: لَا مَحَالَّ إِعْرَابٌ لَّهَا». يؤكد القاعدة السابقة ويحسمها، ونفهمه كلمة كلمة.","«وَهَذِهِ»: اسم إشارة مبتدأ: يشير إلى الأقسام الثلاثة المتقدمة (الحروف والماضي والأمر). «الْإِعْرَابُ»: الإعراب المعروف: تغير الآخر. «لَا يَدْخُلُهَا»: لا نافية ويدخل فعل مضارع والهاء مفعول به: لا يدخل الإعرابُ هذه الأقسام.","«يُقَالُ»: مضارع مبني للمجهول: يقول النحويون. «لَا مَحَالَّ»: لا نافية ومحال: خبر مبتدأ محذوف: الأمر محال. «إِعْرَابٌ لَّهَا»: إعراب فاعل أو مبتدأ مؤخر: أن يكون لها إعراب محال.","فالمعنى: هذه الأقسام الثلاثة لا يدخلها الإعراب؛ يقول العلماء: يستحيل أن يكون لها إعراب؛ فهي لا تسبق بما يرفعها أو ينصبها أو يجرها أو يجزمها.","العلة: الإعراب تجديد لوصف الكلمة بسبب عامل جديد؛ والماضي ثابت على زمنه، والأمر طلب ثابت الصورة، والحرف خادم لا يقبل: فاستحال دخول التغيير عليها.","القاعدة العملية: إذا سئلت عن إعراب حرف أو ماضٍ أو أمر فجوابك: مبني على كذا، لا محل له من الإعراب؛ ولا تقل فيه مرفوع ولا منصوب ولا مجرور ولا مجزوم أبدًا."],"examples":["هذه: إشارة إلى الأقسام الثلاثة","لا يدخلها الإعراب","يقال: لا محال إعراب لها","لا ترفع ولا تنصب ولا تجر ولا تجزم","الجواب: مبني لا محل له","الإعراب تجديد لا يقبله الثابت"],"questions":[{"question":"ما حكم إعراب الحروف والماضي والأمر؟","options":["لا يدخلها الإعراب استحالة","تدخله أحيانًا","ترفع فقط","تنصب فقط"],"answer":0,"explanation":"وهذه الإعراب لا يدخلها يقال لا محال إعراب لها: فهي مبنية لا توصف بالأحكام الأربعة."},{"question":"ماذا تقول إذا سئلت عن إعراب «لم»؟","options":["حرف جزم مبني على السكون لا محل له من الإعراب","مرفوع","منصوب","مجرور"],"answer":0,"explanation":"لم: حرف لا يقبل العوامل: مبني على السكون لا محل له من الإعراب: هذه العبارة المحكمة."},{"question":"ماذا تقول في إعراب «ذهب» و«اذهب»؟","options":["ماضٍ مبني على الفتح وأمر مبني على السكون ولا محل لهما","مرفوعان","منصوبان","مجزومان"],"answer":0,"explanation":"الماضي والأمر مبنيان: ذهب على الفتح واذهب على السكون؛ ولا محل لهما من الإعراب."},{"question":"لم استحال دخول الإعراب على هذه الأقسام؟","options":["لأنها ثابتة الدلالة لا تقبل التجديد الذي يقتضيه الإعراب","لأنها معربة","لأنها طويلة","بلا سبب"],"answer":0,"explanation":"الماضي دل على حدث منقضٍ والأمر على طلب والحرف خادم: فلا يتغير آخرها بعامل: فاستحال إعرابها."},{"question":"ما إعراب «لا يدخلها» في البيت نفسه؟","options":["لا نافية لا عمل لها ويدخل مضارع مرفوع والهاء مفعول به","لا ناهية جازمة","منصوب","مجزوم"],"answer":0,"explanation":"لا هنا نافية (لا ناهية): لا تجزم؛ ويدخل: مضارع مرفوع بالضمة والفاعل مستتر هو (الإعراب)؛ والهاء مفعول به."}]},{"body":["تدريب العبارات المحكمة: أعرب: «من» (حرف جر مبني على السكون لا محل له)؛ «صلّى» (ماضٍ مبني على الفتح المقدر على الألف المقصورة)؛ «صلِّ» (أمر مبني على حذف حرف العلة)؛ «هل» (حرف استفهام مبني على السكون لا محل له).","خطأ مقابل شائع: يظن بعض الطلاب أن الماضي بعد لم يصير معربًا: «لم يكتبْ»: يكتب مضارع مجزوم: صح؛ لكن «لم كتب» لا تصح أصلًا: فالجزم خاص بالمضارع؛ والماضي لا يقبل الجازم.","الفرق بين «لا محل له» و«في محل»: الحروف والماضي والأمر: لا محل لها عند الجمهور لأنها لا تشبه المرفوع؛ والأسماء المبنية والضمائر: لها محل (في محل رفع ونحوه) لوقوعها مواقع المعربة.","تطبيق على بيت النظم نفسه: «يقال»: مضارع مبني للمجهول مرفوع بالضمة ونائب الفاعل مستتر... والجملة بعده (لا محال إعراب لها) في محل رفع نائب فاعل: فانظر كيف اجتمع في البيت مبني للمجهول ومعرب.","تدريب: صحح العبارات الخاطئة: «كتبَ مرفوع» → ماضٍ مبني على الفتح؛ «هل منصوبة» → حرف مبني لا محل له؛ «اذهب مجزوم» → أمر مبني على السكون.","خلاصة: الحروف والماضي والأمر لا يدخلها الإعراب استحالة؛ وعباراتها: مبني على كذا لا محل له من الإعراب؛ وبهذا ضبطت شق المبني كله؛ والقادم شق الأسماء والمضارع."],"examples":["من: حرف جر لا محل له","صلى: مبني على الفتح المقدر","لم يكتب: الجزم للمضارع فقط","لا محل له مقابل في محل","يقال: مبني للمجهول","صحح: كتب مبني لا مرفوع"],"questions":[{"question":"أعرب «من» في «من المسجد»:","options":["حرف جر مبني على السكون لا محل له من الإعراب","مرفوع","فاعل","مبتدأ"],"answer":0,"explanation":"من حرف جر: مبني على السكون لا محل له؛ والمسجد: اسم مجرور بمن وعلامة جره الكسرة."},{"question":"هل يجزم الماضي بلم؟","options":["لا؛ الجزم خاص بالمضارع","نعم دائمًا","أحيانًا","مع لن"],"answer":0,"explanation":"لا يقال لم كتب؛ الجازم يدخل على المضارع: لم يكتب؛ فالماضي مبني لا يقبل الجوازم."},{"question":"ما الفرق بين «لا محل له» و«في محل رفع»؟","options":["الأولى للحروف والماضي والأمر والثانية للأسماء المبنية والضمائر","لا فرق","بالعكس","للمعرب"],"answer":0,"explanation":"هذا فاعل مبني في محل رفع (وقع موقع المرفوع)؛ أما الحرف والماضي فلا محل لهما عند الجمهور."},{"question":"أعرب «يقال» في البيت:","options":["فعل مضارع مبني للمجهول مرفوع بالضمة","ماضٍ","أمر","حرف"],"answer":0,"explanation":"يقال: مبني للمجهول من قال؛ مرفوع بالضمة؛ وما بعده من الجملة نائب فاعل في محل رفع."},{"question":"صحح: «اذهبْ مجزوم بالسكون»:","options":["الصواب: فعل أمر مبني على السكون لا محل له","الصواب: مرفوع","الصواب: منصوب","صحيحة"],"answer":0,"explanation":"الأمر مبني على السكون بناء لا جزمًا: فالسكون هنا علامة بناء لا علامة جزم؛ فانتبه للفظين."}]}]},{"id":"wahi-verse-022","title":"المعرب من الأسماء والمضارع","summary":"البيت الثاني والعشرون: الأسماء معربة إلا عشرة أقسام، والمضارع معرب ما لم تتصل به نونان.","verse":{"number":22,"section":"المعرب والمبني","text":"وَأَعْرِبُوا الْأَسْمَاءَ إِلَّا عَشَرَةْ / وَكَلِمَ الْمُضَارِعِ الْمُحَرَّرَةْ"},"segments":[{"body":["البيت الثاني والعشرون: «وَأَعْرِبُوا الْأَسْمَاءَ إِلَّا عَشَرَةْ وَكَلِمَ الْمُضَارِعِ الْمُحَرَّرَةْ». يعين ما فيه معرب ومبني: الأسماء والمضارع، ونفهمه كلمة كلمة.","«وَأَعْرِبُوا»: فعل أمر للجماعة: اجعلوها معربة... أي اعربوا واعلموا أنها معربة. «الْأَسْمَاءَ»: مفعول به منصوب: الأسماء كلها. «إِلَّا عَشَرَةْ»: أداة استثناء ومستثنى منصوب: إلا عشرة أقسام منها.","«وَكَلِمَ»: معطوف: وكلمات؛ حذفت التاء للوزن. «الْمُضَارِعِ»: مضاف إليه: كلمات الفعل المضارع. «الْمُحَرَّرَةْ»: نعت: المحررة الخالية؛ وحذفت التاء: الخالية من النونين.","فالمعنى: اعلموا أن الأسماء معربة كلها إلا عشرة أقسام مبنية، وكذلك كلمات المضارع معربة ما خلا من النونين (نون التوكيد ونون النسوة).","العشرة المبنية من الأسماء: الضمائر، وأسماء الإشارة، والأسماء الموصولة، وأسماء الشرط، وبعض الظروف (كإذا وحيث والآن وأمس وقط)، وبعض الأعداد المركبة (كأحد عشر)، وصيغ التعجب، وأسماء الأفعال، ومركبات أخرى... يجمعها قولهم: كل اسم لم يقبل علامة من علامات الإعراب تغيرًا فهو مبني.","المضارع المحرر: ما لم تتصل به نون التوكيد ولا نون النسوة: يكتبُ ويكتبَ ويكتبْ: معرب يتغير آخره بالرفع والنصب والجزم."],"examples":["أعربوا الأسماء إلا عشرة","الأسماء معربة إلا عشرة أقسام","وكلم المضارع المحررة","المحررة: الخالية من النونين","يكتب يكتب يكتب: معرب","الضمائر والإشارات والموصولات: مبنية"],"questions":[{"question":"ما حكم الأسماء من حيث الإعراب والبناء؟","options":["معربة كلها إلا عشرة أقسام مبنية","مبنية كلها","نصفها فقط","ثلاثة أقسام مبنية"],"answer":0,"explanation":"وأعربوا الأسماء إلا عشرة: الأصل في الأسماء الإعراب؛ والمبني منها عشرة أقسام محصورة كالضمائر والإشارات."},{"question":"اذكر خمسة من الأسماء المبنية العشرة:","options":["الضمائر وأسماء الإشارة والموصولات وبعض الظروف وبعض الأعداد المركبة","الأعلام","النكرات","الجموع"],"answer":0,"explanation":"أنا وهذا والذي وأمس وأحد عشر: كلها أسماء مبنية لا يتغير آخرها؛ وهي من العشرة المستثناة."},{"question":"ما المضارع المحرر؟","options":["ما خلت كلمته من نون التوكيد ونون النسوة","الماضي","الأمر","ما اتصلت به النونان"],"answer":0,"explanation":"المحررة: الخالية من النونين؛ فالمضارع معرب ما لم تتصل به نون توكيد (ليكتبن) ولا نون نسوة (يكتبن)."},{"question":"أعرب «يكتب» بأحواله الثلاثة:","options":["مرفوع بالضمة ومنصوب بالفتحة ومجزوم بالسكون","مرفوع دائمًا","مبني","منصوب دائمًا"],"answer":0,"explanation":"يكتب الدرس: مرفوع؛ لن يكتب: منصوب بلن؛ لم يكتب: مجزوم بلم: فهو معرب يتغير آخره بالعوامل."},{"question":"أعرب «عشرة» في البيت:","options":["مستثنى منصوب بإلا","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"إلا عشرة: عشرة مستثنى منصوب بالفتحة: استثناء من الأسماء: الكلام تام موجب فالنصب واجب."}]},{"body":["تدريب التمييز في الأسماء: «قلم» (معرب: قلمٌ قلمًا قلمٍ)؛ «أنا» (مبني: ضمير)؛ «هذا» (مبني: اسم إشارة)؛ «الذي» (مبني: موصول)؛ «مكة» (معرب: مكةَ مكةِ ولو ممنوعة من الصرف: معربة بعلامة فرعية)؛ «أمس» (مبني: ظرف).","تنبيه: المبني من الأسماء له محل إعرابي: «هذا فاعل في محل رفع»؛ فالبناء لا يسقط الحكم بل يسقط تغير اللفظ؛ وهذا سر قولهم: المبني في محل.","تدريب المضارع: «يصلي» (معرب محرر: يصلي ويصليَ ويصلِ)؛ «يصلينَ» بنون النسوة (مبني على الفتح)؛ «لن يصلينَّ» بنون التوكيد (مبني على الفتح)؛ فالنونان تحولان دون الإعراب.","الفرق بين نون النسوة ونون التوكيد: نون النسوة تدل على فاعلات إناث: يكتبنَ (النساء يكتبن)؛ ونون التوكيد تؤكد الفعل: لأكتبنَّ (تأكيد)؛ وكلتاهما تبني المضارع على الفتح.","فائدة حصر العشرة: الأصل في الأسماء الإعراب؛ فإذا رأيت اسمًا فاحكم بإعرابه حتى يتبين لك أنه من العشرة: فالأصل يعمل ما لم يوجد مخصص: قاعدة تنفعك في كل باب.","خلاصة: الأسماء معربة إلا عشرة أقسام مبنية؛ والمضارع معرب إلا مع النونين؛ والبيت القادم يعين النونين بمثاليهما: «يأتين» و«لأجلسن»."],"examples":["قلم معرب وأنا مبني","مكة معربة ممنوعة من الصرف","يصلين بنون النسوة: مبني","لن يصلين: نون توكيد: مبني","نون النسوة للفاعلات ونون التوكيد للتأكيد","الأصل في الأسماء الإعراب"],"questions":[{"question":"صنف: «الذي» و«مكة» و«أمس»:","options":["مبني ومعرب ومبني","كلها معربة","كلها مبنية","معرب ومبني ومعرب"],"answer":0,"explanation":"الذي: موصول مبني؛ مكة: علم معرب (يجر بالفتحة للمنع من الصرف)؛ أمس: ظرف مبني."},{"question":"هل للأسماء المبنية محل إعرابي؟","options":["نعم؛ البناء يسقط تغير اللفظ لا الحكم","لا محل لها","محل جزم","محل سكون"],"answer":0,"explanation":"هذا فاعل في محل رفع: الحكم موجود واللفظ ثابت؛ وهذا الفرق بين المبني من الأسماء وبين الحروف."},{"question":"ما الفرق بين نون النسوة ونون التوكيد؟","options":["الأولى تدل على فاعلات إناث والثانية تؤكد الفعل وكلتاهما تبني المضارع","لا فرق","الثانية للجمع المذكر","الأولى للتوكيد"],"answer":0,"explanation":"يكتبن: النساء فاعلات؛ لأكتبن: توكيد؛ والمضارع مع كلتيهما مبني على الفتح لا معرب."},{"question":"أعرب «لن يكتبنَّ»:","options":["مضارع مبني على الفتح لاتصاله بنون التوكيد في محل نصب بلن","منصوب بالفتحة","مرفوع","مجزوم"],"answer":0,"explanation":"اتصلت به نون التوكيد فبني على الفتح؛ ومحله من الإعراب نصب بلن: فالبناء لا يسقط المحل."},{"question":"ما ضابط الحكم على اسم بأنه معرب؟","options":["الأصل الإعراب حتى يتبين أنه من العشرة المبنية","الأصل البناء","لا ضابط","كل اسم مبني"],"answer":0,"explanation":"اعمل بأصل الباب: الأسماء معربة إلا عشرة؛ فمن شككت فيه اعرضه على أقسام العشرة."}]}]},{"id":"wahi-verse-023","title":"بناء المضارع مع النونين","summary":"البيت الثالث والعشرون: المضارع يبنى إذا اتصلت به نون التوكيد أو نون النسوة.","verse":{"number":23,"section":"المعرب والمبني","text":"مِنْ نُونِ تَوْكِيدٍ وَنُونِ نِسْوَةْ / (يَأْتِيَنَ أَوْ لَأَجْلِسَنَّ ضَحْوَةْ)"},"segments":[{"body":["البيت الثالث والعشرون: «مِنْ نُونِ تَوْكِيدٍ وَنُونِ نِسْوَةْ (يَأْتِيَنَ أَوْ لَأَجْلِسَنَّ ضَحْوَةْ)». يعين النونين اللتين تبنيان المضارع بمثاليهما، ونفهمه كلمة كلمة.","«مِنْ»: حرف جر للتبعيض أو البيان: الخلاء من. «نُونِ تَوْكِيدٍ»: مجرور مضاف ومضاف إليه: نون التوكيد: النون التي تتصل بآخر المضارع لتأكيده: خفيفة (لتكتبنَ) أو ثقيلة (لتكتبنَّ).","«وَنُونِ نِسْوَةْ»: معطوف: ونون النسوة: النون الدالة على فاعل من النساء جمعًا؛ وحذفت التاء للوزن.","«(يَأْتِيَنَ أَوْ لَأَجْلِسَنَّ ضَحْوَةْ)»: المثالان: «يأتينَ»: مضارع اتصلت به نون النسوة (النساء يأتين)؛ و«لأجلسنَّ»: مضارع اتصلت به نون التوكيد الثقيلة مع لام القسم؛ و«ضحوة»: ظرف: في النهار كله أو أوله.","فالمعنى: المضارع المحرر من نون توكيد ونون نسوة هو المعرب؛ أما إذا اتصلت به إحدى النونين -كـ«يأتين» و«لأجلسن ضحوة»- بني على الفتح.","فائدة: بناء المضارع مع النونين ثبات لفظي: فلا يقال في «يأتينَ» مرفوع أو منصوب أو مجزوم؛ بل: مبني على الفتح في محل رفع أو نصب؛ لأن آخره ثابت بالفتح مهما تغيرت العوامل."],"examples":["نون توكيد: لتكتبن","نون نسوة: يكتبن","يأتين: مثال نون النسوة","لأجلسن: مثال نون التوكيد الثقيلة","ضحوة: ظرف زمان","المضارع معهما مبني على الفتح"],"questions":[{"question":"بأي شيء يبنى الفعل المضارع؟","options":["باتصال نون التوكيد أو نون النسوة: فيبنى على الفتح","بلم","بلن","بالسكون"],"answer":0,"explanation":"من نون توكيد ونون نسوة: يأتين ولأجلسن: فالمضارع مع إحدى النونين مبني على الفتح لا معرب."},{"question":"ما نون النسوة وما مثالها؟","options":["نون تدل على فاعلات إناث: يأتين","نون للمذكرين","نون الجر","نون التوكيد"],"answer":0,"explanation":"يأتين: النون دالة على جماعة النساء فاعلات؛ والفعل معها مبني على الفتح في محل رفع."},{"question":"ما نون التوكيد وما مثالها؟","options":["نون تتصل بالمضارع للتأكيد خفيفة أو ثقيلة: لأجلسن","نون النسوة","نون الجمع المذكر","نون الوقاية"],"answer":0,"explanation":"لأجلسن ضحوة: النون المشددة نون توكيد ثقيلة؛ وبها وبلام القسم تأكد الفعل وبني على الفتح."},{"question":"أعرب «يأتين»:","options":["مضارع مبني على الفتح لاتصاله بنون النسوة في محل رفع والنون فاعل","مرفوع بالضمة","مجزوم","منصوب بالفتحة"],"answer":0,"explanation":"بني على الفتح لنون النسوة؛ ونون النسوة فاعل في محل رفع؛ والفعل في محل رفع لا يرفع لفظًا."},{"question":"أعرب «ضحوة» في البيت:","options":["ظرف زمان منصوب بالفتحة","مفعول به","فاعل","نعت"],"answer":0,"explanation":"ضحوة: وقت من النهار: ظرف زمان منصوب بالفتحة: لأجلسن ضحوة = في الضحوة."}]},{"body":["تدريب التمييز: «يكتبُ الولد» (محرر: معرب مرفوع بالضمة)؛ «تكتبنَ البنات» (بنون النسوة: مبني على الفتح في محل رفع)؛ «ليكتبنَّ الولد» (بنون التوكيد: مبني على الفتح في محل نصب باللام)؛ «لن يكتبَ» (محرر: منصوب بالفتحة).","قارن الأحوال الثلاثة للمحرر: يكتبُ (رفع)؛ لن يكتبَ (نصب)؛ لم يكتبْ (جزم): ثلاث صور لآخر واحد؛ ثم انظر يكتبنَ ولن يكتبنَّ مع النونين: صورة واحدة ثابتة: هذا هو الفرق المحسوس بين المعرب والمبني.","نون التوكيد لا يتصل بها فاعل بعدها: لأجلسنَّ: الفاعل مستتر (أنا)؛ ونون النسوة نفسها فاعل: يأتينَ: النون تكفي عن ذكر الفاعلات صراحة.","لم بني المضارع معهما؟ قالوا: لثقل تغير الآخر مع النون: فالنون الثقيلة والنسوة تجعلان التغير عسرًا على اللسان فثبت الفتح تخفيفًا؛ فالبناء هنا تخفيف عذري.","تطبيق قرآني: «ولتكوننَّ من الصادقين»: تكونن: مضارع مبني على الفتح لنون التوكيد في محل نصب باللام؛ و«يستفتينك»: يستفتين مبني على الفتح لنون النسوة... (الاستفتاء من النساء) في محل رفع.","خلاصة باب المعرب والمبني كاملة: المبني كله: الحروف والماضي والأمر؛ وفيه معرب ومبني: الأسماء (معربة إلا عشرة) والمضارع (معرب إلا مع النونين)؛ والقادم: الأحكام الإعرابية الأربعة."],"examples":["يكتب الولد: محرر مرفوع","تكتبن البنات: مبني في محل رفع","ليكتبن: مبني في محل نصب","نون النسوة فاعل ونون التوكيد لا فاعل بعدها","البناء معهما تخفيف","ولتكونن من الصادقين"],"questions":[{"question":"صنف: «لن يكتب» و«ليكتبنَّ» و«تكتبنَ»:","options":["معرب منصوب ومبني في محل نصب ومبني في محل رفع","كلها معربة","كلها مبنية","مبنيان ومعرب بالعكس"],"answer":0,"explanation":"لن يكتب: محرر منصوب بالفتحة؛ ليكتبن: بنون التوكيد مبني في محل نصب؛ تكتبن: بنون النسوة مبني في محل رفع."},{"question":"أين الفاعل في «يأتين» و«لأجلسن»؟","options":["نون النسوة فاعل في الأولى ومستتر تقديره أنا في الثانية","مستتر في كلتيهما","ظاهر في كلتيهما","لا فاعل"],"answer":0,"explanation":"نون النسوة ضمير فاعل مبني في محل رفع؛ ومع نون التوكيد الفاعل مستتر قبلها: لأجلسن = لأجلسن أنا."},{"question":"لم بني المضارع مع النونين عند النحويين؟","options":["لثقل تغير الآخر معهما فثبت الفتح تخفيفًا","للقافية","بلا سبب","للجزم"],"answer":0,"explanation":"النون الثقيلة والنسوة يثقل معهما تغيير الآخر؛ فجعل الفتح لازمًا تخفيفًا على اللسان."},{"question":"أعرب «ولتكونن من الصادقين»:","options":["لام قسم وتكونن مضارع مبني على الفتح بنون التوكيد في محل نصب","مرفوع بالضمة","مجزوم","أمر"],"answer":0,"explanation":"اللام موطئة للقسم تنصب المضارع؛ واتصال نون التوكيد بنى الفعل على الفتح؛ والمحل: نصب."},{"question":"لخص باب المعرب والمبني:","options":["مبني كله: حروف وماضٍ وأمر؛ وفيه معرب ومبني: الأسماء إلا عشرة والمضارع إلا مع النونين","كل الكلام معرب","كل الكلام مبني","لا قسمة"],"answer":0,"explanation":"أربعة أبيات (٢٠-٢٣) حسمت الباب: فاحفظ قسميه: مبني كله ثلاثة أقسام، وفيه معرب ومبني قسمان."}]}]},{"id":"wahi-verse-024","title":"الأحكام الإعرابية الأربعة","summary":"البيت الرابع والعشرون: الأحكام الإعرابية أربعة: الرفع والنصب والجر والجزم.","verse":{"number":24,"section":"الأحكام الإعرابية","text":"إِعْرَابُنَا حُكْمَانِ ثُمَّ حُكْمُ / رَفْعٌ وَنَصْبٌ، ثُمَّ جَرٌّ جَزْمُ"},"segments":[{"body":["البيت الرابع والعشرون: «إِعْرَابُنَا حُكْمَانِ ثُمَّ حُكْمُ رَفْعٌ وَنَصْبٌ، ثُمَّ جَرٌّ جَزْمُ». به يبدأ فصل الأحكام الإعرابية، ونفهمه كلمة كلمة.","«إِعْرَابُنَا»: مبتدأ مضاف: إعراب كلامنا. «حُكْمَانِ»: خبره: حكمان اثنان. «ثُمَّ حُكْمُ»: ثم للعطف مع ترتيب: وحكم ثالث ورابع... والتقدير: إعرابنا حكمان ثم حكم وحكم: أربعة.","«رَفْعٌ وَنَصْبٌ»: تفصيل الحكمين الأولين: الرفع والنصب. «ثُمَّ جَرٌّ جَزْمُ»: وتفصيل الثالث والرابع: الجر (ويسمى الخفض) والجزم.","فالمعنى: أحكام الإعراب أربعة لا غير: رفع ونصب ثم جر وجزم؛ فقسمها النظم: حكمان ثم حكم فحكم لتستقيم القافية والوزن.","ما الحكم الإعرابي؟ هو الوصف الذي تستحقه الكلمة المعربة بسبب عامل دخل عليها: فالفاعل مرفوع لدخول الفعل عليه، والمفعول منصوب، والمجرور بعد حرف الجر مجرور، والمضارع بعد لم مجزوم.","لماذا أربعة فقط؟ لأنها الثابتة في كلام العرب: ما وقع موقع الرفع فمرفوع، وموقع النصب فمنصوب، وموقع الجر فمجرور، وموقع الجزم فمجزوم؛ ولا حكم خامس لمعرب."],"examples":["إعرابنا حكمان ثم حكم","رفع ونصب ثم جر جزم","أربعة أحكام لا غير","الحكم: وصف بسبب عامل","الجر يسمى الخفض","لا حكم خامس لمعرب"],"questions":[{"question":"كم أحكام الإعراب وما هي؟","options":["أربعة: الرفع والنصب والجر والجزم","ثلاثة","خمسة","ستة"],"answer":0,"explanation":"إعرابنا حكمان ثم حكم رفع ونصب ثم جر جزم: أربعة أحكام محصورة لا خامس لها."},{"question":"ما الحكم الإعرابي؟","options":["وصف تستحقه المعربة بسبب عامل دخل عليها","حركة فقط","معنى الكلمة","وزنها"],"answer":0,"explanation":"الرفع والنصب والجر والجزم أوصاف تحصل للكلمة من عواملها: فالفعل يرفع فاعله وينصب مفعوله."},{"question":"ما اسم آخر للجر؟","options":["الخفض","الجزم","النصب","الرفع"],"answer":0,"explanation":"الجر والخفض اسمان لحكم واحد: يقال مجرور ومخفوض؛ وهو حكم ما بعد حروف الجر والإضافة."},{"question":"لم قسم النظم الأحكام حكمان ثم حكم؟","options":["لضبط الوزن والقافية والعدد أربعة محفوظ","لأنها ثلاثة","خطأ","للحصر"],"answer":0,"explanation":"رفع ونصب (حكمان) ثم جر (حكم) وجزم (حكم): أربعة؛ والتقسيم لترويقة البيت والمعنى تام."},{"question":"أعرب «رفع ونصب» في البيت:","options":["بدل أو بيان من حكمان مرفوعان","مفعول به","فاعل","حال"],"answer":0,"explanation":"رفع: بدل من حكمان مرفوع بالضمة؛ ونصب: معطوف عليه مرفوع؛ يفصلان المجمل (حكمان)."}]},{"body":["تطبيق الأحكام الأربعة على اسم واحد: «محمد»: جاء محمدٌ (مرفوع: فاعل)؛ رأيت محمدًا (منصوب: مفعول)؛ مررت بمحمدٍ (مجرور: بحرف الجر)؛ والاسم لا يجزم أبدًا.","وعلى مضارع واحد: «يكتب»: يكتبُ (مرفوع)؛ لن يكتبَ (منصوب)؛ لم يكتبْ (مجزوم)؛ والفعل لا يجر أبدًا: فالتوزيع: الاسم له ثلاثة (رفع ونصب وجر) والمضارع له ثلاثة (رفع ونصب وجزم).","فائدة حصر الأحكام: إعراب أي كلمة معربة هو في الحقيقة: تعيين حكمها من هذه الأربعة ثم تعيين علامته؛ فإذا ضبطت الأربعة ضبطت مفتاح الإعراب كله.","خط الإعراب: سمى العلماء الأحكام الأربعة خط الإعراب: لأنها المسلك الذي يسير فيه المعرب؛ فكل موقع في الجملة هو محطة من محطات الرفع أو النصب أو الجر أو الجزم.","كل باب قادم مربوط بحكم: الفاعل ونائبه والمبتدأ والخبر: أبواب رفع؛ المفاعيل والحال والتمييز: أبواب نصب؛ المجرورات: باب جر؛ والمضارع المجزوم: باب جزم؛ فاحفظ الأربعة تُهْدَ للأبواب.","خلاصة: الأحكام أربعة محصورة: رفع ونصب وجر وجزم؛ والبيت القادم يبين على أي الكلمات تدخل: الاسم والمضارع دخولًا شاملًا بلا منازع."],"examples":["محمد: مرفوع ومنصوب ومجرور","يكتب: مرفوع ومنصوب ومجزوم","الاسم لا يجزم والفعل لا يجر","خط الإعراب: مسلك الأحكام","كل باب آتٍ مربوط بحكم","الإعراب: حكم ثم علامة"],"questions":[{"question":"ما الأحكام التي تدخل على الاسم؟","options":["الرفع والنصب والجر دون الجزم","الأربعة","الرفع فقط","الجزم فقط"],"answer":0,"explanation":"جاء محمد ورأيت محمدًا ومررت بمحمد: ثلاثة؛ والاسم لا يجزم: الجزم خاص بالمضارع."},{"question":"ما الأحكام التي تدخل على المضارع؟","options":["الرفع والنصب والجزم دون الجر","الأربعة","الجر","النصب فقط"],"answer":0,"explanation":"يكتب ولن يكتب ولم يكتب: ثلاثة؛ والفعل لا يجر: الجر خاص بالاسم."},{"question":"ما خط الإعراب؟","options":["الأحكام الأربعة: مسلك المعرب في الجملة","خط اليد","الرسم","الإملاء"],"answer":0,"explanation":"سميت الأحكام خط الإعراب لأن المعرب يسير فيها: فكل موقع رفع أو نصب أو جر أو جزم."},{"question":"كيف يكون إعراب الكلمة خطوتين؟","options":["تعيين حكمها من الأربعة ثم تعيين علامة الحكم","حفظها","ترجمتها","كتابتها"],"answer":0,"explanation":"مثال: الطالب في جاء الطالب: حكمه الرفع وعلامته الضمة: مرفوع بالضمة: فالإعراب حكم ثم علامة."},{"question":"اربط الأبواب الآتية بأحكامها:","options":["الفاعل والمبتدأ: رفع؛ المفاعيل والحال: نصب؛ المجرورات: جر؛ المضارع بعد لم: جزم","كلها رفع","كلها نصب","لا ربط"],"answer":0,"explanation":"كل باب من أبواب النحو القادمة تطبيق لحكم من الأربعة: فحصر الأحكام مفتاح الأبواب."}]}]},{"id":"wahi-verse-025","title":"الأحكام تدخل على الاسم والمضارع","summary":"البيت الخامس والعشرون: الأحكام الإعرابية تدخل على الأسماء والمضارعات كلها معربة ومبنية.","verse":{"number":25,"section":"الأحكام الإعرابية","text":"وَإِنَّهَا فِي الِاسْمِ وَالْمُضَارِعْ / قَدْ دَخَلَتْ حَثْثًا بِلَا مُنَازِعْ"},"segments":[{"body":["البيت الخامس والعشرون: «وَإِنَّهَا فِي الِاسْمِ وَالْمُضَارِعْ قَدْ دَخَلَتْ حَثْثًا بِلَا مُنَازِعْ». يبين على أي الكلمات تدخل الأحكام الأربعة، ونفهمه كلمة كلمة.","«وَإِنَّهَا»: إن مخففة أو مشددة للتوكيد؛ والهاء ضمير يعود على الأحكام الأربعة. «فِي الِاسْمِ وَالْمُضَارِعْ»: في الاسم وفي الفعل المضارع؛ وحذفت التاء من «جزمُ» المتقدم ومن «المضارعِ» هنا للوزن.","«قَدْ دَخَلَتْ»: قد للتحقيق؛ ودخلت: فعل ماضٍ فاعله الهاء (الأحكام). «حَثْثًا»: حال أو مفعول مطلق: دخولًا سريعًا شاملًا. «بِلَا مُنَازِعْ»: بلا معارض ولا خلاف.","فالمعنى: إن الأحكام الأربعة في الاسم والمضارع قد دخلتهما دخولًا شاملًا سريعًا لا خلاف فيه ولا استثناء.","الدقة في القاعدة: تدخل الأحكام على جميع الأسماء والأفعال المضارعة: معربة كانت أم مبنية؛ فالاسم المبني (هذا) يدخله الحكم محلًّا: هذا فاعل في محل رفع؛ والمعرب يدخله الحكم لفظًا ومحلًّا.","ولا تدخل على الحروف والماضي والأمر كما تقدم استحالة؛ فالقسمة محكمة: ما يقبل الحكم: الاسم والمضارع؛ وما لا يقبل: الحرف والماضي والأمر."],"examples":["إنها في الاسم والمضارع","قد دخلت حثا بلا منازع","دخول شامل لا خلاف فيه","المبني يدخله الحكم محلًّا","هذا فاعل في محل رفع","الحرف والماضي والأمر خارجة"],"questions":[{"question":"على أي الكلمات تدخل الأحكام الأربعة؟","options":["على الأسماء والأفعال المضارعة معربة ومبنية","على الحروف","على الماضي","على الأمر"],"answer":0,"explanation":"وإنها في الاسم والمضارع قد دخلت حثا بلا منازع: فالحكم يدخل الاسم والمضارع دون سواهما."},{"question":"ما معنى «حثا بلا منازع»؟","options":["دخولًا سريعًا شاملًا لا خلاف فيه ولا استثناء","بطيئًا مترددًا","جزئيًّا","محل خلاف"],"answer":0,"explanation":"حثًّا: الإسراع والشمول؛ وبلا منازع: لا يعارض هذا الدخول معارض: قاعدة مستقرة لا خلاف فيها."},{"question":"كيف يدخل الحكم على الاسم المبني؟","options":["محلًّا لا لفظًا: في محل رفع أو نصب أو جر","لفظًا يتغير","لا يدخله","جزمًا"],"answer":0,"explanation":"هذا فاعل: الحكم الرفع؛ واللفظ ثابت: فنقول مبني في محل رفع؛ فدخول الحكم عليه محلّي."},{"question":"لم لا تدخل الأحكام على الحرف والماضي والأمر؟","options":["لأنها لا تقبل العوامل كما تقدم استحالة","لأنها معربة","لأنها قصيرة","تدخل فعلًا"],"answer":0,"explanation":"سبق في بيت «لا محال إعراب لها»: هذه الأقسام مبنية استحال دخول الإعراب عليها."},{"question":"أعرب «دخلت» في البيت:","options":["فعل ماضٍ مبني على السكون لاتصاله بتاء التأنيث والفاعل مستتر يعود على الأحكام","مضارع","أمر","مرفوع"],"answer":0,"explanation":"دخلت: ماضٍ مبني على السكون لاتصاله تاء التأنيث الساكنة؛ والفاعل ضمير مستتر تقديره هي يعود على الأحكام."}]},{"body":["تطبيق شامل: «هذا طالبٌ مجتهدٌ»: هذا: اسم مبني دخله حكم الرفع محلًّا (مبتدأ في محل رفع)؛ طالب: معرب دخله الرفع لفظًا (خبر مرفوع بالضمة)؛ مجتهد: معرب مرفوع نعت.","وفي المضارع المبني: «لتكتبنَّ»: مضارع مبني بنون التوكيد دخله حكم النصب محلًّا باللام: في محل نصب؛ فالبناء لا يمنع دخول الحكم بل يمنع تغير اللفظ فقط.","جدول القبول: الاسم المعرب: يقبل الحكم لفظًا ومحلًّا؛ الاسم المبني: محلًّا فقط؛ المضارع المعرب: لفظًا ومحلًّا؛ المضارع المبني (مع النونين): محلًّا فقط؛ الحرف والماضي والأمر: لا يقبلان.","فائدة «بلا منازع»: إجماع النحويين على هذه القسمة: فلا تجد نحويًّا يجعل للحرف حكمًا إعرابيًّا؛ فهي من المسلمات التي يبنى عليها العلم.","تدريب: عين نوع دخول الحكم: «أنا مسلم»: أنا مبني في محل رفع (محلّي)؛ مسلم: معرب مرفوع بالضمة (لفظي)؛ «يذهبون»: مضارع معرب مرفوع بثبوت النون (لفظي بعلامة فرعية).","خلاصة: الأحكام الأربعة داخلة في الاسم والمضارع دخولًا محققًا شاملًا: المعرب لفظًا ومحلًّا والمبني محلًّا؛ والبيت القادم يوزع الأحكام الأربعة على أصناف المعرب."],"examples":["هذا مبتدأ في محل رفع","لتكتبن: في محل نصب","المعرب: لفظًا ومحلًّا","المبني: محلًّا فقط","إجماع بلا منازع","يذهبون: مرفوع بثبوت النون"],"questions":[{"question":"أعرب «هذا» في «هذا طالب»:","options":["اسم إشارة مبني على الكسر في محل رفع مبتدأ","مرفوع بالضمة","منصوب","لا محل له"],"answer":0,"explanation":"هذا: مبني دخله حكم الرفع محلًّا: مبتدأ في محل رفع؛ وطالب: خبر معرب مرفوع بالضمة."},{"question":"ما نوع دخول الحكم في «لتكتبنَّ»؟","options":["محلّي: في محل نصب باللام مع ثبات اللفظ","لفظي","لا دخول","جزم"],"answer":0,"explanation":"اتصلت به نون التوكيد فبني على الفتح؛ والحكم نصب باللام الموطئة: في محل نصب لا بالفتحة."},{"question":"املأ الجدول: من يقبل الحكم لفظًا ومحلًّا؟","options":["الاسم المعرب والمضارع المعرب","الحرف","الماضي","الأمر"],"answer":0,"explanation":"المعرب من الأسماء والمضارع يقبل الحكم لفظًا ومحلًّا؛ والمبني منهما محلًّا؛ والحرف والماضي والأمر خارجة."},{"question":"ما فائدة قوله «بلا منازع»؟","options":["الإخبار بإجماع النحويين واستقرار القاعدة","للقافية فقط","احتمال الخلاف","لا فائدة"],"answer":0,"explanation":"نفى المنازع: أي إن هذا التقسيم من مسلمات العلم لا يعارض فيه أحد من أهله: فاحفظه واثقًا."},{"question":"أعرب «يذهبون»:","options":["مضارع مرفوع بثبوت النون والواو فاعل","منصوب بحذف النون","مجزوم","مبني"],"answer":0,"explanation":"يذهبون: من الأفعال الخمسة (اتصلت به واو الجماعة): يرفع بثبوت النون؛ والواو ضمير فاعل."}]}]},{"id":"wahi-verse-026","title":"أقسام المعرب الأربعة","summary":"البيت السادس والعشرون: المعرب يكون مرفوعا أو منصوبا أو مجرورا أو مجزوما.","verse":{"number":26,"section":"الأحكام الإعرابية","text":"مَرْفُوعٌ أَوْ مَنْصُوبٌ أَوْ مَجْرُورُ / مَجْزُومُ الْمُعْرَبُ، يَا بَصِيرُ"},"segments":[{"body":["البيت السادس والعشرون: «مَرْفُوعٌ أَوْ مَنْصُوبٌ أَوْ مَجْرُورُ مَجْزُومُ الْمُعْرَبُ، يَا بَصِيرُ». يوزع الأحكام الأربعة على المعرب، ونفهمه كلمة كلمة.","«مَرْفُوعٌ أَوْ مَنْصُوبٌ أَوْ مَجْرُورُ مَجْزُومُ»: أربعة أوصاف معطوفة بأو (للتقسيم: واحد منها لا جميعها): مرفوع أو منصوب أو مجرور أو مجزوم.","«الْمُعْرَبُ»: فاعل أو مبتدأ مؤخر: الكلمة المعربة؛ فالتقدير: المعرب مرفوع أو منصوب أو مجرور أو مجزوم: لا يخرج عن واحد من الأربعة.","«يَا بَصِيرُ»: منادى مبني على الضمة في محل نصب: يا من كان بصيرًا نافذ النظر: التفاتة النظم إلى الطالب ليستيقظ لهذه القاعدة الجامعة.","فالمعنى: الكلمة المعربة لا تخلو من واحد من أربعة أوصاف: فهي مرفوعة أو منصوبة أو مجرورة أو مجزومة.","التوزيع بين الاسم والمضارع: الرفع والنصب مشتركان: للاسم والمضارع جميعًا؛ والجر مختص بالاسم: لا يقال في فعل مجرور؛ والجزم مختص بالمضارع: لا يقال في اسم مجزوم."],"examples":["مرفوع أو منصوب أو مجرور مجزوم","المعرب لا يخرج عن الأربعة","يا بصير: التفاتة للطالب","الرفع والنصب مشتركان","الجر للاسم","الجزم للمضارع"],"questions":[{"question":"بم توصف الكلمة المعربة؟","options":["بواحد من أربعة: مرفوع أو منصوب أو مجرور أو مجزوم","بخمسة","بثلاثة فقط","باثنين"],"answer":0,"explanation":"مرفوع أو منصوب أو مجرور مجزوم المعرب: أو للتقسيم: كل معرب واقع في واحد من الأربعة."},{"question":"ما الحكمان المشتركان بين الاسم والمضارع؟","options":["الرفع والنصب","الجر والجزم","الرفع فقط","الجر فقط"],"answer":0,"explanation":"الاسم يرفع وينصب والمضارع يرفع وينصب؛ فالرفع والنصب عامان لهما معًا."},{"question":"ما الحكم المختص بالاسم؟","options":["الجر","الجزم","الرفع","النصب"],"answer":0,"explanation":"لا يقال في فعل مجرور أبدًا: الجر للاسم وحده: بعد حرف الجر والإضافة والتابع لهما."},{"question":"ما الحكم المختص بالمضارع؟","options":["الجزم","الجر","الخفض","النصب فقط"],"answer":0,"explanation":"لا يقال في اسم مجزوم أبدًا: الجزم للمضارع وحده: لم يقمْ ولا تكسلْ: فهو علامة مميزة للفعل."},{"question":"ما فائدة «يا بصير» في البيت؟","options":["التفاتة تنبه الطالب على قاعدة جامعة","للقافية فقط","نداء عابر","لا فائدة"],"answer":0,"explanation":"نادى الطالب بصيرًا: صاحب نظر نافذ: ليثبت عنده أن المعرب لا يخرج عن الأوصاف الأربعة."}]},{"body":["تدريب التعيين: عين وصف كل كلمة معربة: «جاء المعلمُ»: المعلم مرفوع (فاعل)؛ «أكرمت المعلمَ»: منصوب (مفعول)؛ «سلمت على المعلمِ»: مجرور؛ «لن يهملَ»: مجزوم... بل منصوب بلن؛ «لم يهملْ»: مجزوم.","اختبار الاختصاص: لو وصفت اسمًا بأنه مجزوم فقد أخطأت حتمًا: قل مجرور أو غيره؛ ولو وصفت فعلًا بأنه مجرور فأخطأت: فالاختصاص ضابط سريع لكشف الخطأ.","أو في البيت للإباحة التقسيمية: ليست للشك: بل معناها: كل معرب واقع في واحد من الأربعة لا في جميعها: فالكلمة الواحدة لها حكم واحد في موضع واحد.","هل تتغير أوصاف الكلمة الواحدة؟ نعم بتغير المواضع: محمد مرفوع هنا ومنصوب هناك ومجرور ثالث: فالوصف للكلمة في موضعها لا لذاتها؛ فلا تحفظ الكلمات بأحكام ثابتة بل بالمواقع.","المنادى في البيت نموذج: «بصير»: علم... بل نكرة مقصودة: منادى مبني على الضمة في محل نصب: فالبيت نفسه تطبيق: البصير (أيها الطالب) واقع في محل نصب بالنداء.","خلاصة: المعرب: مرفوع أو منصوب أو مجرور أو مجزوم؛ الرفع والنصب مشتركان، والجر للاسم، والجزم للمضارع؛ والبيت القادم يحذر من خلط المعرب بالمبني في الوصف."],"examples":["المعلم: مرفوع ومنصوب ومجرور بحسب الموضع","لم يهمل: مجزوم","لا اسم مجزوم ولا فعل مجرور","أو للتقسيم لا للشك","الوصف للكلمة في موضعها","بصير: منادى في محل نصب"],"questions":[{"question":"عين وصف «المعلم» في: جاء المعلم، أكرمت المعلم، سلمت على المعلم:","options":["مرفوع ومنصوب ومجرور","مرفوع في الكل","منصوب في الكل","مجرور في الكل"],"answer":0,"explanation":"فاعل فمرفوع؛ مفعول فمنصوب؛ بعد حرف جر فمجرور: الوصف يتبع الموقع لا ذات الكلمة."},{"question":"لو قال قائل: «محمد مجزوم» فما حكمه؟","options":["خطأ حتمًا: الجزم مختص بالمضارع","صحيح","صحيح أحيانًا","معرب"],"answer":0,"explanation":"الاسم لا يجزم؛ فوصف اسم بأنه مجزوم خطأ يكشفه ضابط الاختصاص: الجزم للمضارع وحده."},{"question":"ما معنى «أو» في البيت؟","options":["للتقسيم: كل معرب في واحد من الأربعة لا جميعها","للشك","للجمع","للإبهام"],"answer":0,"explanation":"أو هنا تقسيمية: الكلمة في موضعها الواحد لها حكم واحد من الأحكام الأربعة."},{"question":"هل للكلمة الواحدة حكم ثابت ذاتي؟","options":["لا؛ الوصف لها في موضعها ويتغير بتغير المواضع","نعم ثابت","مرفوعة دائمًا","منصوبة دائمًا"],"answer":0,"explanation":"محمد: مرفوع في جاء محمد ومنصوب في رأيت محمد ومجرور في مررت بمحمد: فالوصف موقعي."},{"question":"أعرب «بصير» في «يا بصير»:","options":["منادى مبني على الضمة في محل نصب نكرة مقصودة","منصوب بالفتحة","فاعل","نعت مرفوع"],"answer":0,"explanation":"بصير: نكرة يقصد بها الطالب المعين: نكرة مقصودة: منادى مبني على الضمة في محل نصب."}]}]},{"id":"wahi-verse-027","title":"لا تخلط بين المعرب والمبني","summary":"البيت السابع والعشرون: مصطلحات المعرب تختلف عن مصطلحات المبني، والخلط بينهما محال.","verse":{"number":27,"section":"الأحكام الإعرابية","text":"مَبْنِيُّهَا -أُخَيَّ- فِي تَحَالِ / وَاخْلُطْ بَيْنَهَا مِنَ الْمُحَالِ"},"segments":[{"body":["البيت السابع والعشرون: «مَبْنِيُّهَا -أُخَيَّ- فِي تَحَالِ وَاخْلُطْ بَيْنَهَا مِنَ الْمُحَالِ». يحذر من الخلط بين المعرب والمبني في العبارة، ونفهمه كلمة كلمة.","«مَبْنِيُّهَا»: مبتدأ مضاف: مبني هذه الكلمات (الأسماء والمضارع)؛ والهاء تعود عليهما. «-أُخَيَّ-»: منادى معترض: تصغير ترخيم لأخي: يا أخي الصغير: حذفت الهمزة والياءان تخفيفًا: الأصل أخويّ.","«فِي تَحَالِ»: خبر: في حال ثابتة واحدة لا تتبدل (تحال: اسم من التحول: مبني في تحالٍ من التحول: أي ثابت). «وَاخْلُطْ بَيْنَهَا»: واخلط بينها وبين المعرب.","«مِنَ الْمُحَالِ»: الخبر الثاني أو الحال: الخلط بينهما أمر من المحال المستحيل الذي لا يجوز؛ والتقدير: وخلطك بينهما من المحال: لا يصح ولا يجوز.","فالمعنى: مبني هذه الكلمات ثابت الحال لا يتغير، وخلطك بينه وبين المعرب في الوصف مستحيل لا يجوز.","مظهر الخلط الممنوع: أن توصف المبني بأوصاف المعرب: فالمعرب يقال فيه: مرفوع ومنصوب ومجرور ومجزوم؛ والمبني يقال فيه: في محل رفع وفي محل نصب وفي محل جر وفي محل جزم."],"examples":["مبنيها في تحال: ثابت","أخي: منادى معترض مترخم","واخلط بينها من المحال","المعرب: مرفوع ومنصوب","المبني: في محل رفع ونصب","الخلط في الوصف مستحيل"],"questions":[{"question":"ما المنادى المعترض في البيت وما أصله؟","options":["أخي: تصغير ترخيم لأخي أصله أخوي","يا بصير","يا رجل","يا محمد"],"answer":0,"explanation":"أخي: منادى معترض بين الشطرين: صغّر أخي ورخّم: حذف منه حرفان تخفيفًا: وهو مبني على الضم المقدر في محل نصب."},{"question":"ما معنى «مبنيها في تحال»؟","options":["المبني ثابت على حال واحدة لا يتغير","يتغير دائمًا","معرب","مجزوم"],"answer":0,"explanation":"تحال: الثبات وعدم التحول: المبني من الأسماء والمضارع ثابت الآخر مهما دخل عليه من عوامل."},{"question":"ما الخلط المحال في البيت؟","options":["وصف المبني بأوصاف المعرب كقولك: هذا مرفوع","تمييزهما","إعراب المعرب","بناء المبني"],"answer":0,"explanation":"واخلط بينها من المحال: لا يجوز أن تقول في المبني مرفوع أو منصوب؛ بل: في محل رفع وفي محل نصب."},{"question":"ماذا يقال في المعرب وماذا يقال في المبني؟","options":["المعرب: مرفوع ومنصوب ومجرور ومجزوم؛ والمبني: في محل رفع ونحوها","بالعكس","واحد للاثنين","لا يقال شيء"],"answer":0,"explanation":"محمد مرفوع بالضمة (معرب)؛ وهذا فاعل مبني في محل رفع (مبني): فالعباراتان مختلفتان واجبًا."},{"question":"أعرب «أخي»:","options":["منادى مبني على الضم المقدر في محل نصب جاء معترضًا","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"أخي: منادى مرخم مبني على الضم المقدر على الهمزة المحذوفة في محل نصب؛ جاء معترضًا بين الشطرين."}]},{"body":["فرق ثانٍ في الألفاظ: حركات المعرب تسمى: ضمة وفتحة وكسرة؛ وحركات المبني تسمى: ضم وفتح وكسر؛ فتقول في المعرب: مرفوع بالضمة؛ وفي المبني: مبني على الضم؛ فرق يسير في اللفظ عظيم في الاصطلاح.","تدريب التصحيح: صحح: «هذا مرفوع بالضمة» ← هذا مبتدأ مبني على الكسر في محل رفع؛ «أنا منصوبة» ← أنا مبني على السكون في محل نصب (بعد إن)؛ «يأتينَ منصوب بالفتحة» ← مبني على الفتح في محل رفع.","لم عدوا الخلط محالًا مع أن المعنى يفهم؟ لأن الاصطلاح النحوي عقد مصطلحات: فوصف المبني بالرفع يلبس عليك البناء والإعراب فيظن السامع أن آخره يتغير؛ فالدقة في اللفظ دقة في الفهم.","تطبيق جامع: أعرب بعبارة محكمة: «ذهبتُ»: التاء: ضمير متصل مبني على الضم في محل رفع فاعل؛ و«كتابي»: الياء: مضاف إليه مبني على السكون في محل جر؛ و«إياك»: مفعول به مبني في محل نصب.","لاحظ سكون المبني: يبقى اسمًا للعلامة في القسمين: يقال مبني على السكون (علامة بناء) ومجزوم وعلامة جزمه السكون (علامة إعراب): فالسكون اسمه واحد واعتباره مختلف.","خلاصة: مبنيها في تحال والخلط بينها وبين المعرب من المحال؛ فالتزم عبارتي: مرفوع بالضمة للمعرب، ومبني على الضم في محل رفع للمبني؛ وبذلك يتم ضبط هذا الباب رأس المال."],"examples":["ضمة للمعرب وضم للمبني","فتحة وفتح وكسرة وكسر","هذا مبتدأ في محل رفع","أنا في محل نصب بعد إن","الخلط يلبس البناء بالإعراب","السكون: علامة بناء وعلامة جزم"],"questions":[{"question":"ما الفرق بين الضمة والضم؟","options":["الضمة علامة رفع المعرب والضم ما يبنى عليه المبني","لا فرق","بالعكس","الضم للجمع"],"answer":0,"explanation":"مرفوع بالضمة (معرب)؛ مبني على الضم (مبني): اسمان متقاربان لاعتبارين مختلفين: إعراب وبناء."},{"question":"صحح: «أنا منصوبة بالفتحة»:","options":["أنا مبني على السكون في محل نصب","صحيحة","أنا مرفوع","أنا مجرور"],"answer":0,"explanation":"الضمائر مبنية: فلا توصف بالنصب اللفظي: إن أنا: أنا اسم إن مبني على السكون في محل نصب."},{"question":"لم عدوا الخلط بين الوصفين من المحال؟","options":["لأنه يلبس البناء بالإعراب ويوهم أن المبني يتغير","لأنه لحن فقط","لا سبب","للزينة"],"answer":0,"explanation":"الاصطلاح ضابط فهم: من وصف المبني بالرفع أوهم أن آخره يتغير: فالدقة اللفظية حارسة الفهم."},{"question":"أعرب الياء في «كتابي» بعبارة محكمة:","options":["ضمير متصل مبني على السكون في محل جر مضاف إليه","مجرورة بالكسرة","مرفوعة","منصوبة"],"answer":0,"explanation":"الياء ضمير مبني: لا تقول مجرورة؛ بل: مبني على السكون في محل جر مضاف إليه: هذا ضبط الباب."},{"question":"كيف يتفق «مبني على السكون» و«مجزوم وعلامة جزمه السكون»؟","options":["السكون اسمه واحد: علامة بناء هنا وعلامة إعراب هناك","متناقضان","خطأ","لا يتفقان"],"answer":0,"explanation":"لم يقمْ: سكون جزم (معرب)؛ ومن: مبنية على السكون (حرف): فالاعتبار مختلف واللفظ واحد."}]}]},{"id":"wahi-verse-028","title":"العلامات دليل الحكم","summary":"البيت الثامن والعشرون: علامات الإعراب دلائل واضحة تعرف بها الأحكام.","verse":{"number":28,"section":"علامات الإعراب الأصلية","text":"وَذِي الْعَلَامَاتُ دَلِيلُ الْحُكْمِ / أَدِلَّةً وَاضِحَةً لِلْفَهْمِ"},"segments":[{"body":["البيت الثامن والعشرون: «وَذِي الْعَلَامَاتُ دَلِيلُ الْحُكْمِ أَدِلَّةً وَاضِحَةً لِلْفَهْمِ». به يبدأ فصل علامات الإعراب، ونفهمه كلمة كلمة.","«وَذِي»: الواو عاطفة؛ وذي: بمعنى صاحب: مبتدأ مبني على الضم في محل رفع؛ وهو من الأسماء الستة (أبو أخو حمو فو ذو وهن).","«الْعَلَامَاتُ»: مضاف إليه مجرور؛ فالتقدير: صاحب العلامات. «دَلِيلُ الْحُكْمِ»: خبر: دليل الحكم الإعرابي. «أَدِلَّةً وَاضِحَةً لِلْفَهْمِ»: حال: في صورة أدلة واضحة للفهم.","فالمعنى: صاحب العلامات (المعرب) دليلُ حكمِه، أدلةً واضحةً للفهم: فعلامات الإعراب هي الدليل الظاهر على حكم الكلمة.","تقرير العلاقة: تقدم أن الإعراب خطوتان: حكم ثم علامة؛ فالحكم معنى خفي (الرفع أثر عامل لا تراه العين)، والعلامة صورة مرئية مسموعة؛ فالعلامة تهديك إلى الحكم.","فائدة الوضوح: العربي إذا سمع «جاء محمدٌ» بالضم عرف الرفع بلا تفكير: فالعلامة مفتاح فطري سريع، ولهذا صار تعلم العلامات بابًا مستقلًّا."],"examples":["وذي العلامات دليل الحكم","ذو: من الأسماء الستة","أدلة واضحة للفهم: حال","الحكم خفي والعلامة ظاهرة","العلامة تدل على الحكم","سماع الضم يهدي إلى الرفع"],"questions":[{"question":"ما موضوع البيت الثامن والعشرين؟","options":["علامات الإعراب ودلالتها على الأحكام","أقسام الكلام","المبني","الأفعال الخمسة"],"answer":0,"explanation":"وذي العلامات دليل الحكم: انتقل النظم من الأحكام الأربعة إلى العلامات الدالة عليها."},{"question":"ما إعراب «ذي» في البيت؟","options":["مبتدأ مبني على الضم في محل رفع من الأسماء الستة","مرفوع بالضمة","حرف","مضاف إليه"],"answer":0,"explanation":"ذو بمعنى صاحب: من الأسماء الستة: ترفع بالواو وتنصب بالألف وتجر بالياء؛ وهنا مبتدأ في محل رفع مضاف."},{"question":"ما العلاقة بين الحكم والعلامة؟","options":["الحكم معنى خفي والعلامة صورة ظاهرة تدل عليه","لا علاقة","العلامة خفية","متطابقان لفظًا"],"answer":0,"explanation":"الرفع أثر عامل لا تراه؛ والضمة ترى وتسمع فتدل عليه: فالعلامة دليل الحكم الواضح للفهم."},{"question":"لم وصف الأدلة بأنها واضحة للفهم؟","options":["لأن العربي يعرف الحكم من العلامة بلا تفكير","للقافية","لأنها خفية","لا سبب"],"answer":0,"explanation":"من سمع جاء محمدٌ بالضم عرف الرفع فطرة: فالعلامة مفتاح سريع واضح يهدي إلى الحكم مباشرة."},{"question":"أعرب «أدلة» في البيت:","options":["حال منصوبة بالفتحة","مفعول به","خبر","نعت مرفوع"],"answer":0,"explanation":"أدلةً واضحةً: حال من دليل: أي في صورة أدلة واضحة؛ منصوبة بالفتحة الظاهرة، وواضحة نعتها."}]},{"body":["تطبيق الدلالة: «كتب الطالبُ الدرسَ»: الضمة على الطالب دليل الرفع (فاعل)؛ والفتحة على الدرس دليل النصب (مفعول)؛ فكل علامة شاهد على حكم.","والعلامات قسمان كما سيجيء: أصلية وهي الحركات والسكون: ضمة للرفع وفتحة للنصب وكسرة للجر وسكون للجزم؛ وفرعية: حروف وثبوت نون وحذف حرف وحذف نون.","قاعدة الاستدلال: انظر العلامة أولًا فتدلك على الحكم: رأيت ضمة فمرفوع؛ ورأيت سكونًا على مضارع فمجزوم: فالعلامة بادئة في طريق الإعراب.","لكن انتبه: العلامة الواحدة قد تتعدد أحكامها بالأسباب: فالكسرة جر أصلًا، وقد تكون علامة نصب في جمع المؤنث السالم نيابة عن الفتحة لعذر؛ فالسبب يقيد الدلالة كما سيجيء.","فالضابط: العلامة الأصلية تدل على حكمها ما لم يوجد عذر صارف إلى النيابة؛ والأعذار تضبطها الأبواب القادمة بيتًا بيتًا.","خلاصة: العلامات أدلة واضحة على الأحكام؛ فاجعل طريقك: من العلامة إلى الحكم إلى الموقع (فاعل، مفعول...)؛ والبيت القادم يبدأ بيان العلامات الأصلية: الحركات الثلاث."],"examples":["الضمة دليل رفع والفتحة دليل نصب","العلامات: أصلية وفرعية","ابدأ بالعلامة يهدك الحكم","الكسرة قد تنوب عن الفتحة","السبب يقيد دلالة العلامة","الطريق: علامة فحكم فموقع"],"questions":[{"question":"بم عرفت أن الطالب فاعل في «كتب الطالبُ»؟","options":["بالضمة الظاهرة: علامة الرفع الأصلية","بالفتحة","بالكسرة","بالسكون"],"answer":0,"explanation":"الضمة على باء الطالب دليل الرفع؛ والفاعل من أبواب الرفع: فالعلامة هدت إلى الحكم فالموقع."},{"question":"ما القسمان الكبيران للعلامات؟","options":["أصلية وهي الحركات والسكون، وفرعية وهي الحروف وثبوت النون والحذف","ظاهرة وخفية","كبيرة وصغيرة","ثلاثة أقسام"],"answer":0,"explanation":"الأصلية: ضمة وفتحة وكسرة وسكون؛ والفرعية: واو وألف وياء وثبوت نون وحذف حرف علة وحذف نون."},{"question":"ما طريق الإعراب الصحيح؟","options":["النظر في العلامة أولًا فتدل على الحكم ثم الموقع","تخمين الحكم","حفظ الجمل","ترجمة المعنى"],"answer":0,"explanation":"رأيت سكونًا على مضارع لم يسبق بناصب فمجزوم: فالعلامة بادئة في الطريق ثم الحكم ثم تعيين الموقع."},{"question":"هل تدل العلامة الواحدة على حكم واحد دائمًا؟","options":["لا؛ قد تنوب عن غيرها لعذر كالكسرة عن الفتحة في جمع المؤنث","نعم دائمًا","أبدًا تتعدد","في الجمع فقط تثبت"],"answer":0,"explanation":"أكرمت المسلماتِ: منصوب وعلامة نصبه الكسرة نيابة عن الفتحة: فالدلالة الأصلية تقيدها الأسباب."},{"question":"لم قيل للعلامات أدلة؟","options":["لأنها تهدي إلى الحكم الخفي كما يهدي الدليل إلى المطلوب","لأنها حركات","لأنها كثيرة","تسمية بلا معنى"],"answer":0,"explanation":"الحكم معنى لا يدرك بالحواس؛ والعلامة محسوسة تدل عليه: فهي دليل واضح للفهم كما قال النظم."}]}]},{"id":"wahi-verse-029","title":"العلامات الأصلية: الحركات","summary":"البيت التاسع والعشرون: علامة الإعراب الأصلية: الضمة للرفع والفتحة للنصب والكسرة للجر.","verse":{"number":29,"section":"علامات الإعراب الأصلية","text":"عَلَامَةُ الْإِعْرَابِ كُلَّ مَرَّةٍ / بِضَمَّةٍ وَفَتْحَةٍ وَكَسْرَةْ"},"segments":[{"body":["البيت التاسع والعشرون: «عَلَامَةُ الْإِعْرَابِ كُلَّ مَرَّةٍ بِضَمَّةٍ وَفَتْحَةٍ وَكَسْرَةْ». يبين العلامات الأصلية، ونفهمه كلمة كلمة.","«عَلَامَةُ»: مبتدأ مرفوع مضاف. «الْإِعْرَابِ»: مضاف إليه. «كُلَّ مَرَّةٍ»: مفعول به لفعل محذوف وجوبًا تقديره أعني: أعني كل مرة.","«بِضَمَّةٍ»: متعلق بمحذوف خبر: علامة الإعراب بضمة. «وَفَتْحَةٍ وَكَسْرَةْ»: معطوفتان؛ وحذفت التاء من كسرة للوزن.","فالمعنى: أعني بعلامة الإعراب كل مرة ذكرت: الضمة والفتحة والكسرة: العلامات الأصلية الثلاث، ثم السكون للجزم في البيت القادم.","توزيعها على الأحكام: الضمة علامة الرفع الأصلية؛ والفتحة علامة النصب الأصلية؛ والكسرة علامة الجر الأصلية؛ والسكون علامة الجزم الأصلية: أربع علامات لأربعة أحكام.","لم سميت أصلية؟ لأنها الأصل الذي يقاس عليه وترجع إليه العلامات الفرعية بالنيابة: فكل علامة فرعية تنوب عن حركة أو سكون لعذر."],"examples":["علامة الإعراب كل مرة","بضمة وفتحة وكسرة","الضمة للرفع والفتحة للنصب","الكسرة للجر والسكون للجزم","أربع علامات لأربعة أحكام","أصلية: يقاس عليها الفرعية"],"questions":[{"question":"ما العلامات الأصلية للإعراب؟","options":["الضمة والفتحة والكسرة والسكون","الواو والألف والياء","ثبوت النون","حذف النون"],"answer":0,"explanation":"علامة الإعراب كل مرة بضمة وفتحة وكسرة ثم سكون: أربع علامات أصلية للأحكام الأربعة."},{"question":"ما علامة كل حكم أصلًا؟","options":["الرفع بالضمة والنصب بالفتحة والجر بالكسرة والجزم بالسكون","كلها بالضمة","بالعكس","بالألف"],"answer":0,"explanation":"جاء محمدٌ ورأيت محمدًا ومررت بمحمدٍ ولم يقمْ: ضمة وفتحة وكسرة وسكون: الأصل في كل حكم."},{"question":"ما إعراب «كل» في البيت؟","options":["مفعول به لفعل محذوف تقديره أعني","مبتدأ","فاعل","حال"],"answer":0,"explanation":"كلَّ مرة: مفعول به منصوب بالفتحة لفعل محذوف وجوبًا تقديره أعني؛ وهي مضافة إلى مرة."},{"question":"لم سميت هذه العلامات أصلية؟","options":["لأنها الأصل الذي ترجع إليه الفرعية بالنيابة","لأنها قديمة","لأنها كثيرة","لا سبب"],"answer":0,"explanation":"كل علامة فرعية تنوب عن حركة أو سكون لعذر: فالحركات أصل القياس؛ ومن ثم بدأ بها النظم."},{"question":"لم حذفت التاء من «كسرة» في البيت؟","options":["للوزن والقافية","خطأ مطبعي","للمعنى","لا سبب"],"answer":0,"explanation":"حذفت تاء التأنيث للضرورة الشعرية ليتم مجزوء الرجز وقافية الراء الساكنة مع سائر الأبيات."}]},{"body":["تطبيقات العلامات الأصلية: الرفع بالضمة: الفاعل (جاء الطالبُ)، نائب الفاعل (كُتب الدرسُ)، المبتدأ والخبر (العلمُ نافعٌ).","النصب بالفتحة: المفعول به (أكرمت المعلمَ)، المفعول المطلق (ضربته ضربًا)، الظرف (جلست يومًا)، الحال (جاء راكبًا)، التمييز (اشتريت رطلًا زيتًا).","الجر بالكسرة: بعد حرف الجر (مررت برجلٍ)، والمضاف إليه (كتابُ الطالبِ)، والتابع لهما (مررت برجلٍ كريمٍ).","الجزم بالسكون: المضارع بعد لم ولا الناهية ولام الأمر: لم يكتبْ، لا تكسلْ، لْيقمْ.","فائدة النيابة: هذه الأحكام نفسها قد تكون بعلامات فرعية: مرفوع بالواو أو الألف أو ثبوت النون؛ منصوب بالكسرة أو الياء أو الألف أو حذف النون أو حذف حرف العلة؛ مجرور بالياء أو الفتحة؛ مجزوم بحذف النون أو حذف حرف العلة.","خلاصة: العلامات الأصلية أربع: ضمة للرفع وفتحة للنصب وكسرة للجر وسكون للجزم؛ والبيت القادم يخص السكون بالبيان مع مثال مركب: إن عمرًا في البيت لم يقم."],"examples":["جاء الطالبُ: رفع بالضمة","أكرمت المعلمَ: نصب بالفتحة","مررت برجلٍ: جر بالكسرة","لم يكتبْ: جزم بالسكون","الفرعية تنوب عن الأصلية","منصوب بالكسرة في جمع المؤنث"],"questions":[{"question":"اذكر ثلاثة أبواب ترفع بالضمة:","options":["الفاعل ونائب الفاعل والمبتدأ والخبر","المفعول والحال","المضاف إليه","المجزوم"],"answer":0,"explanation":"جاء الطالبُ وكُتب الدرسُ والعلمُ نافعٌ: كلها مرفوعة وعلامة رفعها الضمة الظاهرة على آخرها."},{"question":"اذكر ثلاثة أبواب تنصب بالفتحة:","options":["المفعول به والحال والتمييز","الفاعل","المبتدأ","المضاف إليه"],"answer":0,"explanation":"أكرمت المعلمَ وجاء راكبًا واشتريت رطلًا زيتًا: منصوبات بالفتحة: مفعول وحال وتمييز."},{"question":"بم جررت «رجل» في «مررت برجلٍ»؟","options":["بالكسرة الظاهرة بعد الباء حرف الجر","بالفتحة","بالضمة","بالسكون"],"answer":0,"explanation":"رجل: اسم مجرور بالباء وعلامة جره الكسرة الظاهرة على آخره: العلامة الأصلية للجر."},{"question":"بم جزم المضارع في «لم يكتبْ»؟","options":["بالسكون الظاهر على آخره","بالفتحة","بحذف النون","بالكسرة"],"answer":0,"explanation":"لم جازمة تجزم المضارع؛ وعلامة جزمه السكون الظاهر على الباء: لم يكتبْ."},{"question":"متى يكون النصب بالكسرة؟","options":["في جمع المؤنث السالم نيابة عن الفتحة","في المفرد","في المثنى","أبدًا"],"answer":0,"explanation":"أكرمت المسلماتِ: مفعول به منصوب وعلامة نصبه الكسرة نيابة عن الفتحة لعذر يأتي بيانه في أبوابه."}]}]},{"id":"wahi-verse-030","title":"السكون علامة الجزم","summary":"البيت الثلاثون: السكون علامة الجزم، مع مثال جامع للعلامات الأصلية الأربع.","verse":{"number":30,"section":"علامات الإعراب الأصلية","text":"ثُمَّ سُكُونٍ، نَحْوُ: (إِنَّ عَمْرَا / فِي الْبَيْتِ لَمْ يَقُمْ، وَزَيْدٌ أَدْرَى)"},"segments":[{"body":["البيت الثلاثون: «ثُمَّ سُكُونٍ، نَحْوُ: (إِنَّ عَمْرَا فِي الْبَيْتِ لَمْ يَقُمْ، وَزَيْدٌ أَدْرَى)». يكمل العلامات الأصلية بالسكون، ونفهمه كلمة كلمة.","«ثُمَّ سُكُونٍ»: ثم عاطفة: وعلامة الإعراب بسكون؛ أي السكون علامة رابعة تتمم الحركات الثلاث، وهي للجزم.","«نَحْوُ»: كلمة تعليمية للتمثيل: مثله وشبهه: أي ومثال ذلك. «إِنَّ عَمْرَا»: إن حرف توكيد ونصب؛ وعمرا: اسمها منصوب بالفتحة المقدرة على الألف المقصورة (عمرو مقصور).","«فِي الْبَيْتِ»: جار ومجرور متعلق بمحذوف خبر إن. «لَمْ يَقُمْ»: لم جازمة؛ ويقم: مضارع مجزوم وعلامة جزمه السكون الظاهر على الميم. «وَزَيْدٌ أَدْرَى»: جملة معطوفة: زيد مبتدأ، وأدرى: خبره: أعلم أو أولى بالقيام.","فالمعنى: ثم السكون علامة للجزم، ومثال هذه الأحكام مجتمعة: إن عمرًا في البيت لم يقمْ وزيدٌ أدرى.","لم هذا المثال الجامع؟ لأنه يجمع العلامات الأصلية في جملة واحدة: فتحة مقدرة (عمرا)، وكسرة (البيت)، وسكون جزم (يقم)، وضمة رفع (زيد): تدريب مركب عليها كلها."],"examples":["ثم سكون: علامة الجزم","نحو: كلمة التمثيل","إن عمرا: فتحة مقدرة","في البيت: جر بالكسرة","لم يقم: جزم بالسكون","زيد أدرى: رفع بالضمة"],"questions":[{"question":"ما العلامة الرابعة المتممة للعلامات الأصلية؟","options":["السكون وهو علامة الجزم","الواو","الألف","النون"],"answer":0,"explanation":"ثم سكون: عطف على ضمة وفتحة وكسرة: فالعلامات الأصلية أربع، والسكون للجزم خاصة."},{"question":"بم نصب «عمرًا» في مثال البيت؟","options":["بالفتحة المقدرة على الألف المقصورة","بالفتحة الظاهرة","بالكسرة","بالألف"],"answer":0,"explanation":"عمرى مقصور آخره ألف مقصورة تمنع ظهور الحركة: اسم إن منصوب وعلامة نصبه الفتحة المقدرة على الألف."},{"question":"بم جزم «يقم» ولم؟","options":["بالسكون الظاهر على الميم لدخول لم الجازمة","بالفتحة","بحذف النون","بالضمة"],"answer":0,"explanation":"لم حرف نفي وجزم وقلب: يقم: مضارع مجزوم بلم وعلامة جزمه السكون الظاهر على آخره."},{"question":"ما إعراب «زيد أدرى» في المثال؟","options":["زيد مبتدأ مرفوع بالضمة وأدرى خبره مرفوع بالضمة","زيد فاعل","أدرى نعت","معطوف على عمرا"],"answer":0,"explanation":"وزيدٌ أدرى: الواو عاطفة؛ زيد مبتدأ مرفوع بالضمة الظاهرة؛ أدرى: خبر مرفوع بالضمة: أي أعلم أو أولى."},{"question":"لم اختار النظم هذا المثال المركب؟","options":["لأنه يجمع نماذج العلامات الأصلية الأربع في جملة واحدة","للقافية فقط","عشوائي","للحفظ فقط"],"answer":0,"explanation":"فيه فتحة مقدرة وكسرة وسكون جزم وضمة رفع: تدريب واحد على العلامات الأصلية مجتمعة."}]},{"body":["تدريب على المثال كلمة كلمة: «إن»: حرف مشبه بالفعل مبني على الفتح لا محل له؛ «عمرا»: اسم إن منصوب وعلامة نصبه الفتحة المقدرة على الألف للتعذر؛ «في»: حرف جر؛ «البيت»: مجرور بالكسرة؛ والجار والمجرور متعلق بمحذوف خبر إن.","«لم»: حرف نفي وقلب وجزم مبني على السكون؛ «يقم»: مضارع مجزوم بلم وعلامة جزمه السكون، وفاعله مستتر تقديره هو يعود على عمرو؛ «و»: عاطفة؛ «زيد»: مبتدأ مرفوع بالضمة؛ «أدرى»: خبر مرفوع بالضمة.","التعذر: الفتحة على الألف المقصورة مقدرة للتعذر: يمتنع ظهورها عليها امتناعًا ذاتيًّا؛ وستأتي الأعذار مفصلة في أبوابها القادمة.","لاحظ دقة القراءة: تقرأ «عمرا» في الوصل بفتحة مقدرة لا تلفظها؛ ولهذا سميت مقدرة: تقدرها في الإعراب ولا تنطقها: وهذا سر دقة أهل الإعراب.","تطبيق توليدي: صغ مثالًا جامعًا على طريقته: «إن هدى في الدار لم تخرجْ، وخالد أبقى»: هدى: فتحة مقدرة؛ الدار: كسرة؛ تخرج: سكون جزم بلم؛ وخالد: ضمة رفع.","خلاصة: تمت العلامات الأصلية أربعًا: ضمة وفتحة وكسرة وسكون؛ ومثال البيت تدريب مركب عليها؛ والأبواب القادمة تنتقل إلى العلامات المقدرة وأعذارها ثم الفرعية بيتًا بيتًا."],"examples":["إن مبنية على الفتح","عمرا: فتحة مقدرة للتعذر","يقم: فاعله مستتر هو","التقدير: تقدرها ولا تنطقها","إن هدى في الدار لم تخرجْ","خالد أبقى: ضمة رفع"],"questions":[{"question":"أعرب «إن» في المثال:","options":["حرف توكيد ونصب مشبه بالفعل مبني على الفتح لا محل له من الإعراب","فعل ماضٍ","اسم معرب","حرف جر"],"answer":0,"explanation":"إن: حرف ناسخ مشبه بالفعل ينصب الاسم ويرفع الخبر: مبني على الفتح لا محل له: الحروف لا محل لها."},{"question":"ما الفاعل في «لم يقم»؟","options":["ضمير مستتر تقديره هو يعود على عمرو","عمرا ظاهرًا","البيت","لا فاعل"],"answer":0,"explanation":"يقم: فاعله مستتر وجوبًا تقديره هو؛ لأن عمرًا اسم إن لا فاعل للمضارع؛ والضمير يعود عليه."},{"question":"ما معنى «مقدرة للتعذر»؟","options":["يمتنع ظهور الحركة على الألف المقصورة امتناعًا ذاتيًّا فتقدر","تظهر بوضوح","تحذف الكلمة","تثقل فقط"],"answer":0,"explanation":"عمرى آخره ألف: لا تنطق عليها حركة: فنقول منصوب بالفتحة المقدرة على الألف للتعذر: تقدير لا لفظ."},{"question":"كوّن جملة على نمط المثال فيها فتحة مقدرة:","options":["إن هدى في الدار","إن هندًا في الدار","رأيت هندًا","هند في الدار"],"answer":0,"explanation":"إن هدى: هدى مقصور: اسم إن منصوب بالفتحة المقدرة على الألف؛ أما هند فتظهر عليها الفتحة لأنها غير مقصورة."},{"question":"ما الذي تم ببيت السكون؟","options":["العلامات الأصلية الأربع: ضمة وفتحة وكسرة وسكون","الأبواب كلها","الفرعية","التوابع"],"answer":0,"explanation":"ببيت «ثم سكون» اكتملت العلامات الأصلية أربعًا؛ وبعدها تبدأ الأعذار والعلامات الفرعية في النظم."}]}]},{"id":"wahi-verse-031","title":"العلامات المقدرة: حركات نحكم بها ولا نسمعها","summary":"البيت الحادي والثلاثون: العلامة قد تكون مقدرة لا تظهر على الحرف، والناظم يعدد أبوابها القادمة.","verse":{"number":31,"section":"علامات الإعراب المقدرة","text":"تَقْدِيرُهَا لِمَانِعٍ فِي الْجَائِي / فِي الْقَصِرِ وَالتَّنْقِيصِ وَقَبْلَ الْيَاءِ"},"segments":[{"body":["البيت الحادي والثلاثون: «تَقْدِيرُهَا لِمَانِعٍ فِي الْجَائِي فِي الْقَصِرِ وَالتَّنْقِيصِ وَقَبْلَ الْيَاءِ». يبين علة تقدير العلامات، ونفهمه كلمة كلمة.","«تَقْدِيرُهَا»: مبتدأ مضاف: تقدير العلامات (الحركات)؛ أي الحكم بوجودها مع عدم سماعها. «لِمَانِعٍ»: خبر: لسبب مانع يمنع ظهورها.","«فِي الْجَائِي»: في الجائي: وهو الاسم المعتل الآخر: نحو الفتى؛ سمي جائيًّا لمجيء حرف العلة في آخره.","«فِي الْقَصِرِ»: في الاسم المقصور: المنتهي بألف مقصورة: نحو هدى وفاطى؛ سمي مقصورًا لقصره على الألف.","«وَالتَّنْقِيصِ»: في الاسم المنقوص: المنتهي بياء مكسور ما قبلها: نحو القاضي والساري. «وَقَبْلَ الْيَاءِ»: وقبل ياء المتكلم: نحو كتابي ومسلمي.","فالمعنى: تقدير الحركات على آخر الكلمة يكون لمانع في أربعة مواضع: الجائي والمقصور والمنقوص وما قبل ياء المتكلم؛ فهذه الأربعة لا تظهر عليها الحركات."],"examples":["تقديرها لمانع","الجائي: الفتى","القصر: هدى وفاطى","التنقيص: القاضي","وقبل الياء: كتابي","أربعة مواضع للتقدير"],"questions":[{"question":"ما مواضع تقدير الحركات الأربعة؟","options":["الجائي والمقصور والمنقوص وما قبل ياء المتكلم","الصحيح والمعتل","المفرد والجمع","المذكر والمؤنث"],"answer":0,"explanation":"تقديرها لمانع في الجائي في القصر والتنقيص وقبل الياء: أربعة مواضع لا تظهر فيها الحركات."},{"question":"ما الاسم المقصور؟","options":["المنتهي بألف مقصورة نحو هدى","المنتهي بياء","المعتل الأول","المضعف"],"answer":0,"explanation":"المقصور: ما آخره ألف لازمة: هدى وفاطى: قصر آخره على الألف فتعذرت عليه الحركات."},{"question":"ما الاسم المنقوص؟","options":["المنتهي بياء مكسور ما قبلها نحو القاضي","المنتهي بألف","الصحيح","الجامد"],"answer":0,"explanation":"المنقوص: ما آخره ياء لازمة مكسور ما قبلها: القاضي والساري: نقص آخره عن تمام الحروف."},{"question":"لم سميت الحركات هنا مقدرة؟","options":["لأنها تحكم بها ولا تسمع لمانع يمنع ظهورها","لأنها محذوفة","لأنها ظاهرة","لا سبب"],"answer":0,"explanation":"تقديرها لمانع: المانع يمنع نطق الحركة على الآخر فيقدرها المعرب: يحكم بها ولا يسمعها."},{"question":"أعرب «تقدير» في البيت:","options":["مبتدأ مرفوع بالضمة وهو مضاف والهاء مضاف إليه","خبر","مفعول به","حال"],"answer":0,"explanation":"تقديرها: مبتدأ مرفوع بالضمة الظاهرة وهو مضاف؛ والهاء ضمير متصل مبني في محل جر مضاف إليه يعود على العلامات."}]},{"body":["تطبيق على المقصور: هدى قائمة: مبتدأ مرفوع بالضمة المقدرة على الألف المقصورة للتعذر؛ ورأيت هدى: منصوب بالفتحة المقدرة للتعذر؛ وسلمت على هدى: مجرور بالكسرة المقدرة للتعذر.","وعلى المنقوص: جاء القاضي: مرفوع بالضمة المقدرة على الياء للثقل؛ ورأيت القاضي: منصوب بالفتحة المقدرة للثقل؛ وسلمت على القاضي: مجرور بالكسرة الظاهرة: الكسرة وحدها تظهر على المنقوص.","وقبل ياء المتكلم: كتابي جديد: مبتدأ مرفوع بالضمة المقدرة من قبل ياء المتكلم للاستثقال؛ ورأيت كتابي: منصوب بالفتحة المقدرة؛ ومررت بكتابي: مجرور بالكسرة الظاهرة.","الأعذار الثلاثة: التعذر: امتناع ذاتي كالألف المقصورة؛ والثقل: ثقل نسبي كالضمة على ياء المنقوص؛ والاستثقال: الثقل المطلق كالحركة قبل ياء المتكلم.","قاعدة: المقصور تقدر عليه الحركات الثلاث كلها؛ والمنقوص وما قبل ياء المتكلم تقدر عليهما الضمة والفتحة وتظهر الكسرة.","خلاصة: أربعة مواضع تقدر فيها الحركات لمانع: الجائي والمقصور والمنقوص وما قبل ياء المتكلم؛ والبيت القادم يمثل لها بأمثلة مركبة."],"examples":["هدى: ثلاث مقدرة للتعذر","القاضي: كسرة ظاهرة","كتابي: ضمة وفتحة مقدرتان","الأعذار: تعذر وثقل واستثقال","سلمت على القاضي: كسرة","بكتابي: كسرة ظاهرة"],"questions":[{"question":"بم رفعت «هدى» في «هدى قائمة»؟","options":["بالضمة المقدرة على الألف المقصورة للتعذر","بالضمة الظاهرة","بالواو","بالفتحة"],"answer":0,"explanation":"هدى مقصور: الألف المقصورة يمتنع ظهور الحركة عليها امتناعًا ذاتيًّا: مبتدأ مرفوع بالضمة المقدرة للتعذر."},{"question":"ما عذر تقدير الضمة على «القاضي»؟","options":["الثقل: ثقل الضمة على الياء الساكنة بعد كسرة","التعذر","الاستثقال","لا عذر"],"answer":0,"explanation":"القاضي منقوص: ياء ساكنة مكسور ما قبلها: الضمة عليها ثقيلة نسبيًّا فتقدر للثقل."},{"question":"أي حركة تظهر على المنقوص؟","options":["الكسرة: سلمت على القاضي بكسرة ظاهرة","الضمة","الفتحة","لا حركة"],"answer":0,"explanation":"المنقوص تظهر عليه الكسرة في الجر، وتقدر عليه الضمة والفتحة للثقل."},{"question":"بم رفع «كتاب» في «كتابي جديد»؟","options":["بالضمة المقدرة من قبل ياء المتكلم للاستثقال","بالضمة الظاهرة","بالواو","بالألف"],"answer":0,"explanation":"كتابي: ياء المتكلم أوجبت تقدير الحركات قبلها للاستثقال؛ وتظهر الكسرة في الجر: بكتابي."},{"question":"ما الأعذار الثلاثة لمنع ظهور الحركة؟","options":["التعذر والثقل والاستثقال","النصب والجر والجزم","الرفع فقط","البناء"],"answer":0,"explanation":"التعذر: امتناع ذاتي كالألف؛ والثقل: نسبي كياء المنقوص؛ والاستثقال: مطلق كالحركة قبل ياء المتكلم."}]}]},{"id":"wahi-verse-032","title":"أبواب العلامات المقدرة بأمثلتها","summary":"البيت الثاني والثلاثون: أمثلة النظم على أبواب التقدير: المضاف إلى ياء المتكلم، والمقصور، والمنقوص، والمضارع المعتل الآخر.","verse":{"number":32,"section":"علامات الإعراب المقدرة","text":"كَـ(جَاءَ أَخِي) ثُمَّ أَلْقَى وَالرَّاوِي / يَسْعَى وَيَدْعُو لَهُمْ أَوْ يَأْوِي"},"segments":[{"body":["البيت الثاني والثلاثون: «كَـ(جَاءَ أَخِي) ثُمَّ أَلْقَى وَالرَّاوِي يَسْعَى وَيَدْعُو لَهُمْ أَوْ يَأْوِي». يمثل لمواضع التقدير، ونفهمه كلمة كلمة.","«كَـ(جَاءَ أَخِي)»: الكاف للتشبيه أي كقولك: جاء أخي: أخي من الأسماء الستة مضاف إلى ياء المتكلم: مرفوع بالواو المقدرة من قبل ياء المتكلم.","«ثُمَّ أَلْقَى»: ثم عاطفة؛ وألقى: فعل ماضٍ معتل الآخر بالألف المقصورة: دخل في التمثيل ليضبط المتعلم صور المعتل.","«وَالرَّاوِي»: معطوف: الراوي: اسم منقوص: آخره ياء مكسور ما قبلها: تقدر عليه الضمة والفتحة للثقل وتظهر الكسرة.","«يَسْعَى وَيَدْعُو»: مضارعان معتلان: يسعى بالألف ويدعو بالواو: تقدر عليهما الفتحة في النصب: لن يسعى ولن يدعو.","«لَهُمْ أَوْ يَأْوِي»: يدعو لهم أو يأوي: يأوي: معتل الآخر بالياء: فتمت صور الاعتلال الآخر: ألف وواو وياء."],"examples":["كجاء أخي: واو مقدرة","ألقى: معتل بالألف","الراوي: منقوص","يسعى: فتحة مقدرة على الألف","يدعو: فتحة مقدرة على الواو","يأوي: معتل بالياء"],"questions":[{"question":"بم رفع «أخي» في «جاء أخي»؟","options":["بالواو المقدرة من قبل ياء المتكلم لأنه من الأسماء الستة","بالضمة الظاهرة","بالألف","بالفتحة"],"answer":0,"explanation":"أخو من الأسماء الستة: يرفع بالواو؛ وهنا مضاف إلى ياء المتكلم فقدرت الواو من قبل الياء."},{"question":"ما نوع «الراوي» وبم يعرب؟","options":["اسم منقوص: تقدر عليه الضمة والفتحة وتظهر الكسرة","مقصور","صحيح","ممدود"],"answer":0,"explanation":"الراوي منقوص: جاء الراوي (ضمة مقدرة) ورأيت الراوي (فتحة مقدرة) وسلمت على الراوي (كسرة ظاهرة)."},{"question":"بم نصب «يسعى» و«يدعو»؟","options":["بالفتحة المقدرة على الألف في يسعى وعلى الواو في يدعو","بالفتحة الظاهرة","بالكسرة","بحذف النون"],"answer":0,"explanation":"لن يسعى: فتحة مقدرة على الألف للتعذر؛ ولن يدعو: فتحة مقدرة على الواو للثقل."},{"question":"ما فائدة جمع الأمثلة في البيت؟","options":["ضبط صور الاعتلال الآخر كلها: ألف وواو وياء في اسم وفعل","للقافية فقط","زيادة عدد","لا فائدة"],"answer":0,"explanation":"أخي وألقى والراوي ويسعى ويدعو ويأوي: نماذج تغطي المقصور والمنقوص وما قبل الياء في الأسماء والأفعال."},{"question":"أعرب «يسعى» في «لن يسعى»:","options":["مضارع منصوب بلن وعلامة نصبه الفتحة المقدرة على الألف","مرفوع","مجزوم","مبني"],"answer":0,"explanation":"لن يسعى: لن ناصبة؛ ويسعى معتل الآخر بالألف: منصوب بالفتحة المقدرة على الألف للتعذر."}]},{"body":["جدول التقدير الجامع: المقصور (هدى): تقدر عليه الحركات الثلاث كلها للتعذر؛ المنقوص (الراوي): تقدر الضمة والفتحة وتظهر الكسرة؛ ما قبل ياء المتكلم (كتابي): تقدر الضمة والفتحة وتظهر الكسرة.","المعتل الآخر في الأفعال: يدعو: ضمة مقدرة على الواو للثقل في الرفع، وفتحة مقدرة في النصب، ويحذف الواو في الجزم: لم يدعُ؛ ويسعى: الحركات مقدرة على الألف للتعذر، وتحذف الألف في الجزم: لم يسعَ.","تدريب التعيين: عين العلامة: جاء الراوي (ضمة مقدرة للثقل)؛ رأيت هدى (فتحة مقدرة للتعذر)؛ هذا كتابي (ضمة مقدرة قبل الياء)؛ لم يدعُ (حذف الواو للجزم).","قاعدة نطقية: في الوقف تقف على هدى وعلى الراوي بلا حركة؛ وفي الوصل تنطق ما يمكن (الكسرة على المنقوص) وتقدر ما يمتنع: فالتقدير حكم إعرابي لا صوتي.","تنبيه: لا تخلط التقدير بالنيابة: المقدرة حركة أصلية منعها عذر؛ والنائبة علامة فرعية قامت مقام أصلية كالكسرة عن الفتحة في جمع المؤنث: يأتي في أبوابها.","خلاصة: بيتا التقدير ضبطا المواضع الأربعة وأمثلتها؛ والبيت القادم ينتقل إلى القسم الثاني من العلامات: الفرعية في سبعة أبواب."],"examples":["المقصور: ثلاث مقدرة","المنقوص: كسرة ظاهرة","كتابي: ضمة وفتحة مقدرتان","لم يدعُ: حذف الواو","التقدير حكم لا صوت","لا تخلط التقدير بالنيابة"],"questions":[{"question":"أي اسم تقدر عليه الحركات الثلاث كلها؟","options":["المقصور نحو هدى","المنقوص","الصحيح","المثنى"],"answer":0,"explanation":"هدى: مقصور: الألف المقصورة تعذر عليها الحركات كلها: ضمة وفتحة وكسرة مقدرة للتعذر."},{"question":"ما الذي يظهر على المنقوص وما الذي يقدر؟","options":["تظهر الكسرة وتقدر الضمة والفتحة","كلها ظاهرة","كلها مقدرة","الفتحة تظهر"],"answer":0,"explanation":"سلمت على الراوي: كسرة ظاهرة؛ وجاء الراوي ورأيت الراوي: ضمة وفتحة مقدرتان للثقل."},{"question":"كيف يجزم «يدعو»؟","options":["بحذف الواو: لم يدعُ","بالسكون","بالفتحة","بالكسرة"],"answer":0,"explanation":"المضارع المعتل الآخر يجزم بحذف حرف العلة: لم يدعُ ولم يسعَ ولم يخشَ: كما يأتي في بابه."},{"question":"ما الفرق بين التقدير والنيابة؟","options":["المقدرة حركة أصلية منعها عذر والنائبة فرعية مقام أصلية","لا فرق","بالعكس","التقدير نيابة"],"answer":0,"explanation":"الضمة المقدرة على هدى: أصلية منعها التعذر؛ والكسرة في مسلمات منصوبة: فرعية نائبة عن الفتحة."},{"question":"أعرب «كتاب» في «هذا كتابي»:","options":["خبر مرفوع بالضمة المقدرة من قبل ياء المتكلم والياء مضاف إليه","مرفوع بالضمة الظاهرة","منصوب","مبني"],"answer":0,"explanation":"هذا كتابي: كتاب: خبر مرفوع وعلامة رفعه الضمة المقدرة من قبل ياء المتكلم؛ والياء ضمير مبني في محل جر مضاف إليه."}]}]},{"id":"wahi-verse-033","title":"العلامات الفرعية وأبوابها السبعة","summary":"البيت الثالث والثلاثون: علامة الإعراب قد تجيء فرعية في سبعة أبواب خاصة.","verse":{"number":33,"section":"علامات الإعراب الفرعية","text":"وَقَدْ تَجِي عَلَامَةُ الْإِعْرَابِ / فَرْعِيَّةً فِي سَبْعَةِ الْأَبْوَابِ"},"segments":[{"body":["البيت الثالث والثلاثون: «وَقَدْ تَجِي عَلَامَةُ الْإِعْرَابِ فَرْعِيَّةً فِي سَبْعَةِ الْأَبْوَابِ». به يبدأ قسم العلامات الفرعية، ونفهمه كلمة كلمة.","«وَقَدْ تَجِي»: قد للتحقيق؛ وتجي: فعل مضارع أصله تجيء حذفت همزته تخفيفًا: تأتي وتقع. «عَلَامَةُ الْإِعْرَابِ»: فاعل مضاف: علامة الإعراب.","«فَرْعِيَّةً»: حال منصوبة: تأتي العلامة في صورة فرعية: أي غير أصلية تنوب عن الحركات. «فِي سَبْعَةِ الْأَبْوَابِ»: متعلق بتجي: في سبعة أبواب معلومة.","فالمعنى: وقد تأتي علامة الإعراب فرعية - نائبة عن الأصلية - في سبعة أبواب معدودة ستذكر.","ما العلامة الفرعية؟ هي التي تقوم مقام الحركات والسكون في مواضع خاصة: الواو والألف والياء (حروف)، وثبوت النون وحذفها، وحذف حرف العلة، والكسرة نيابة عن الفتحة، والفتحة نيابة عن الكسرة.","الأبواب السبعة: خمسة الأسماء، وجمع المذكر السالم، والمثنى، وجمع المؤنث السالم، والممنوع من الصرف، والأفعال الخمسة، والمضارع المعتل الآخر: تفصيلها في البيوت القادمة بابًا بابًا."],"examples":["وقد تجي علامة الإعراب","فرعية: نائبة عن الأصلية","في سبعة الأبواب","الفرعية: حروف ونون وحذف","تجي أصلها تجيء","الأبواب السبعة معدودة"],"questions":[{"question":"ما موضوع البيت الثالث والثلاثين؟","options":["العلامات الفرعية وأبوابها السبعة","الأحكام","المبني","التقدير"],"answer":0,"explanation":"وقد تجي علامة الإعراب فرعية في سبعة الأبواب: انتقال من العلامات الأصلية إلى الفرعية وأبوابها."},{"question":"ما العلامة الفرعية؟","options":["علامة تنوب عن الحركات والسكون في مواضع خاصة","الضمة","الفتحة","السكون"],"answer":0,"explanation":"كالواو في جمع المذكر والألف في المثنى وثبوت النون في الأفعال الخمسة: نائبة عن الأصلية لأسباب."},{"question":"ما معنى «تجي»؟","options":["تأتي وتقع: مضارع أصله تجيء خففت همزته","تذهب","تحذف","تثبت"],"answer":0,"explanation":"تجي: أصلها تجيء من الجيء (المجيء)؛ حذفت الهمزة تخفيفًا كما جاء في الاستعمال."},{"question":"كم أبواب العلامات الفرعية؟","options":["سبعة أبواب","خمسة","أربعة","عشرة"],"answer":0,"explanation":"في سبعة الأبواب: خمسة الأسماء وجمع المذكر والمثنى وجمع المؤنث والممنوع من الصرف والأفعال الخمسة والمعتل الآخر."},{"question":"أعرب «فرعية» في البيت:","options":["حال منصوبة بالفتحة من فاعل تجي","نعت مرفوع","خبر","مفعول به"],"answer":0,"explanation":"فرعية: حال من العلامة: تأتي في صورة فرعية؛ منصوبة بالفتحة الظاهرة على التاء المربوطة."}]},{"body":["عد الأبواب السبعة بالترتيب: الأول: خمسة الأسماء (أبوك وأخوك...): ترفع بالواو وتنصب بالألف وتجر بالياء. الثاني: جمع المذكر السالم: يرفع بالواو وينصب ويجر بالياء.","الثالث: المثنى: يرفع بالألف وينصب ويجر بالياء. الرابع: جمع المؤنث السالم: ينصب بالكسرة نيابة عن الفتحة.","الخامس: الممنوع من الصرف: يجر بالفتحة نيابة عن الكسرة إذا لم يضف ولم يعرف بأل. السادس: الأفعال الخمسة: ترفع بثبوت النون وتنصب وتجزم بحذفها.","السابع: المضارع المعتل الآخر: يجزم بحذف حرف العلة: لم يدعُ ولم يرمِ.","سر العدد: سبعة أبواب لا ثامن لها؛ وهي التي خرجت فيها العلامة عن أصلها الحركي إلى حرف أو حذف أو نيابة؛ فحصرها يحفظ عليك الفرعية كلها.","خلاصة: العلامات الفرعية في سبعة أبواب محصورة؛ والبيت القادم يبدأ تفصيلها من باب خمسة الأسماء: فمدها في خمسة الأسماء."],"examples":["خمسة الأسماء: واو وألف وياء","جمع المذكر: واو وياء","المثنى: ألف وياء","جمع المؤنث: كسرة نيابة","الممنوع من الصرف: فتحة نيابة","الأفعال الخمسة والمعتل: نون وحذف"],"questions":[{"question":"عد أبواب العلامات الفرعية السبعة:","options":["خمسة الأسماء وجمع المذكر والمثنى وجمع المؤنث والممنوع من الصرف والأفعال الخمسة والمعتل الآخر","الأحكام الأربعة","أقسام الكلام","الحركات"],"answer":0,"explanation":"سبعة محصورة: ثلاثة فيها حروف، وواحد نيابة نصب (جمع المؤنث)، وواحد نيابة جر (الممنوع)، واثنان فيهما نون وحذف."},{"question":"ما علامات خمسة الأسماء؟","options":["الواو للرفع والألف للنصب والياء للجر","الضمة والفتحة والكسرة","النون","الحذف"],"answer":0,"explanation":"أبوك وأخوك وحموك وفوك وذو: ترفع بالواو نيابة عن الضمة وتنصب بالألف وتجر بالياء."},{"question":"ما علامة نصب جمع المؤنث السالم؟","options":["الكسرة نيابة عن الفتحة","الفتحة","الياء","الألف"],"answer":0,"explanation":"أكرمت المسلماتِ: منصوب بالكسرة نيابة عن الفتحة: علامة فرعية في الباب الرابع."},{"question":"ما علامة رفع الأفعال الخمسة؟","options":["ثبوت النون","الضمة","الواو","الألف"],"answer":0,"explanation":"تؤمنون ويؤمنون: مرفوعة بثبوت النون؛ وتنصب وتجزم بحذفها: لن تؤمنوا، لم تؤمنوا."},{"question":"بم جزم المضارع المعتل الآخر؟","options":["بحذف حرف العلة: لم يدعُ","بالسكون","بحذف النون","بالكسرة"],"answer":0,"explanation":"الباب السابع: لم يدعُ ولم يرمِ: حذفت الواو والياء للجزم: علامة فرعية هي الحذف."}]}]},{"id":"wahi-verse-034","title":"خمسة الأسماء","summary":"البيت الرابع والثلاثون: الرفع بالواو في خمسة أسماء: أب وأخ وحم وفو وذو.","verse":{"number":34,"section":"علامات الإعراب الفرعية","text":"فَمَدُّهَا فِي خَمْسَةِ الْأَسْمَاءِ / كَـ(لَمْ يَزَلْ أَخُوكَ ذَا إِخَاءِ)"},"segments":[{"body":["البيت الرابع والثلاثون: «فَمَدُّهَا فِي خَمْسَةِ الْأَسْمَاءِ كَـ(لَمْ يَزَلْ أَخُوكَ ذَا إِخَاءِ)». يبدأ تفصيل الفرعية بباب خمسة الأسماء، ونفهمه كلمة كلمة.","«فَمَدُّهَا»: الفاء تفصيلية؛ ومدها: مبتدأ مضاف: إمدادها وإطالتها بالحروف؛ والهاء تعود على العلامات الفرعية.","«فِي خَمْسَةِ الْأَسْمَاءِ»: خبر: في خمسة أسماء معلومة هي: أب وأخ وحم وذو؛ وقيل ستة بإلحاق هن، وفو عند الكوفيين.","«كَـ(لَمْ يَزَلْ أَخُوكَ ذَا إِخَاءِ)»: كقولك: لم يزل أخوك ذا إخاء: مثال الباب: لم: جازمة؛ يزل: مضارع مجزوم ناسخ (كان وأخواتها)... بل لم يزل بمعنى ما زال؛ أخوك: اسم كان... اسم يزل مرفوع بالواو؛ ذا: خبرها منصوب بالألف.","فالمعنى: فمد العلامات بالحروف (الواو والألف والياء) يكون في خمسة الأسماء، كقولك: لم يزل أخوك ذا إخاء: فالواو في أخو علامة رفع، والألف في ذا علامة نصب.","خمسة الأسماء: أب وأخ وحم وذو (بمعنى صاحب) وهن (بمعنى صاحب المال عند كثيرين... بل هن: اسم جاء فيها)؛ شروطها: الإضافة، وألا تضاف إلى ياء المتكلم، وأن تكون مفردة غير مثناة ولا مجموعة، وعدم التنوين."],"examples":["فمدها في خمسة الأسماء","أب وأخ وحم وذو وهن","لم يزل أخوك ذا إخاء","أخوك: رفع بالواو","ذا: نصب بالألف","الشروط: إضافة بلا ياء وتنوين"],"questions":[{"question":"ما خمسة الأسماء في النظم؟","options":["أب وأخ وحم وذو وهن","الضمائر","الأسماء الموصولة","الممنوع من الصرف"],"answer":0,"explanation":"فمدها في خمسة الأسماء: أب وأخ وحم وذو بمعنى صاحب وهن: تمد بالواو والألف والياء بدل الضمة والفتحة والكسرة."},{"question":"بم رفع «أخوك» في «لم يزل أخوك»؟","options":["بالواو نيابة عن الضمة لأنه من خمسة الأسماء","بالضمة","بالألف","بالياء"],"answer":0,"explanation":"أخوك: اسم كان الناقصة (يزل) مرفوع وعلامة رفعه الواو نيابة عن الضمة؛ والكاف مضاف إليه."},{"question":"بم نصب «ذا» في المثال؟","options":["بالألف نيابة عن الفتحة لأنه ذو من خمسة الأسماء","بالفتحة","بالياء","بالواو"],"answer":0,"explanation":"ذا: خبر كان منصوب وعلامة نصبه الألف نيابة عن الفتحة لأنه ذو من خمسة الأسماء مضاف إلى إخاء."},{"question":"ما معنى «فمدها»؟","options":["إمداد العلامات بالحروف بدل الحركات","حذفها","تقديرها","تقصيرها"],"answer":0,"explanation":"مدها: إطالتها بالحروف: الواو للرفع والألف للنصب والياء للجر: بدل الضمة والفتحة والكسرة في هذا الباب."},{"question":"ما شروط إعراب خمسة الأسماء بالحروف؟","options":["الإضافة وعدم الإضافة إلى ياء المتكلم وعدم التنوين","التنوين","الجمع","التعريف بأل"],"answer":0,"explanation":"إن أضيفت إلى ياء المتكلم (أبي) أو نوّنت رجعت للحركات: جاء أبٌ: مرفوع بالضمة؛ فالشروط ضابط الباب."}]},{"body":["تطبيقات: جاء أبوك: فاعل مرفوع بالواو؛ رأيت أخاك: مفعول به منصوب بالألف؛ مررت بحميك: مجرور بالياء؛ هذا ذو علم: خبر مرفوع بالواو.","وهن (السادس): مررت بذي مالٍ... وهن: بمعنى صاحب في قولهم: ذو هنٍ (صاحب مال): تجري بالياء كأخواتها عند من ألحقها.","فو: اسم بمعنى الفم؛ ألحقه الكوفيون بأخواتها فقالوا: رفع بالواو... والجمهور على أنه معرب بالحركات: فوك: مرفوع بالضمة الظاهرة.","إذا أضيفت إلى ياء المتكلم: جاء أبي: فاعل مرفوع بالضمة المقدرة من قبل ياء المتكلم: رجعت الحركات وخرجت عن الباب؛ وهذا معنى قولهم: إلا عن ياء المتكلم.","إذا ثنيت أو جمعت أو لم تضف: جاء أخواك: بالألف لأنه مثنى؛ وجاء الآباء: جمع بالحركات؛ وجاء أبٌ: بتنوينه: بالضمة.","خلاصة: خمسة الأسماء تمد علاماتها: واو للرفع وألف للنصب وياء للجر بشروطها؛ والبيت القادم: باب جمع المذكر السالم: رفع لجمع سالم المذكر بالواو وانصبه بياء واجرر."],"examples":["جاء أبوك: رفع بالواو","رأيت أخاك: نصب بالألف","مررت بحميك: جر بالياء","أبي مع الياء: ضمة مقدرة","جاء أخواك: مثنى بالألف","جاء أبٌ منون: بالضمة"],"questions":[{"question":"أعرب «أبوك» في «جاء أبوك»:","options":["فاعل مرفوع بالواو نيابة عن الضمة والكاف مضاف إليه","مرفوع بالضمة","منصوب","مجرور"],"answer":0,"explanation":"أبوك: فاعل مرفوع وعلامة رفعه الواو نيابة عن الضمة لأنه من خمسة الأسماء؛ والكاف ضمير مبني في محل جر مضاف إليه."},{"question":"أعرب «حميك» في «مررت بحميك»:","options":["اسم مجرور بالباء وعلامة جره الياء نيابة عن الكسرة","مجرور بالكسرة","مرفوع بالواو","منصوب بالألف"],"answer":0,"explanation":"حميك: مجرور بالباء وعلامة جره الياء نيابة عن الكسرة لأنه من خمسة الأسماء؛ والياء الأخيرة مضاف إليه."},{"question":"كيف يعرب «أبي» في «جاء أبي»؟","options":["فاعل مرفوع بالضمة المقدرة من قبل ياء المتكلم","بالواو","بالألف","بالياء"],"answer":0,"explanation":"أضيف إلى ياء المتكلم فخرج عن باب خمسة الأسماء ورجعت إليه الحركات: مرفوع بالضمة المقدرة قبل الياء."},{"question":"كيف يعرب «أخواك» في «جاء أخواك»؟","options":["فاعل مرفوع بالألف لأنه مثنى لا من خمسة الأسماء","بالواو","بالضمة","بالياء"],"answer":0,"explanation":"أخواك: مثنى: والتثنية تخرجه عن الباب: مرفوع بالألف علامة المثنى كما يأتي في باب المثنى."},{"question":"ما موقف الجمهور من «فو»؟","options":["معرب بالحركات وليس من خمسة الأسماء","يرفع بالواو","مبني","من المثنى"],"answer":0,"explanation":"فو بمعنى الفم: ألحقه الكوفيون بأخواتها؛ والجمهور يعربونه بالحركات: جاء فوك: مرفوع بالضمة الظاهرة."}]}]},{"id":"wahi-verse-035","title":"جمع المذكر السالم","summary":"البيت الخامس والثلاثون: جمع المذكر السالم يُرفع بالواو ويُنصب ويُجر بالياء.","verse":{"number":35,"section":"علامات الإعراب الفرعية","text":"رَفْعٌ لِجَمْعِ سَالِمِ الْمُذَكَّرِ / بِالْوَاوِ، وَانْصِبْهُ بِيَاءٍ وَاجْرُرْ"},"segments":[{"body":["البيت الخامس والثلاثون: «رَفْعٌ لِجَمْعِ سَالِمِ الْمُذَكَّرِ بِالْوَاوِ، وَانْصِبْهُ بِيَاءٍ وَاجْرُرْ». يبين علامات جمع المذكر السالم، ونفهمه كلمة كلمة.","«رَفْعٌ»: مبتدأ أو خبر مقدم: الرفع ثابت. «لِجَمْعِ سَالِمِ الْمُذَكَّرِ»: لجمع المذكر السالم: وهو ما دل على أكثر من اثنين بزيادة واو ونون في الرفع وياء ونون في النصب والجر.","«بِالْوَاوِ»: متعلق بمحذوف صفة أو حال: رفع ثابت بالواو: علامة رفعه الواو نيابة عن الضمة.","«وَانْصِبْهُ بِيَاءٍ وَاجْرُرْ»: وانصبه واجرره بالياء: علامة نصبه وجره الياء نيابة عن الفتحة والكسرة: مسلمين ومسلمين.","فالمعنى: جمع المذكر السالم: يرفع بالواو نيابة عن الضمة، وينصب ويجر بالياء نيابة عن الفتحة والكسرة.","سمي سالمًا لسلامة مفرده: يبقى بناء المفرد سالما لا يتغير: مسلم ← مسلمون: لم تحذف منه حروف ولم تتغير حركاته؛ بخلاف جمع التكسير: كتاب ← كتب: تكسر بناؤه."],"examples":["رفع لجمع سالم المذكر","بالواو نيابة عن الضمة","وانصبه بياء واجرر","مسلمون ومسلمين","السالم: سلامة بناء المفرد","مسلم ← مسلمون"],"questions":[{"question":"ما علامات جمع المذكر السالم؟","options":["الواو للرفع والياء للنصب والجر","الضمة والفتحة والكسرة","الألف","النون"],"answer":0,"explanation":"رفع لجمع سالم المذكر بالواو وانصبه بياء واجرر: الواو نيابة عن الضمة والياء نيابة عن الفتحة والكسرة."},{"question":"ما جمع المذكر السالم؟","options":["ما دل على أكثر من اثنين بزيادة واو ونون أو ياء ونون مع سلامة بناء المفرد","كل جمع","المثنى","جمع التكسير"],"answer":0,"explanation":"مسلم ← مسلمون: زيدت واو ونون وبقي بناء مسلم سالما؛ بخلاف كتاب ← كتب: تكسر البناء فهو جمع تكسير."},{"question":"لم سمي جمع المذكر سالمًا؟","options":["لسلامة بناء مفرده من التغيير عند الجمع","لكثرته","لقلة استعماله","لا سبب"],"answer":0,"explanation":"معلم ← معلمون: بقيت حروف المفرد وحركاته على حالها: سالم البناء؛ وهذا ضابط يفرقه عن جمع التكسير."},{"question":"بم نصب وجر جمع المذكر السالم؟","options":["بالياء نيابة عن الفتحة في النصب وعن الكسرة في الجر","بالواو","بالألف","بالكسرة"],"answer":0,"explanation":"رأيت المسلمين: منصوب بالياء؛ ومررت بالمسلمين: مجرور بالياء: علامة واحدة للنصب والجر في هذا الجمع."},{"question":"أعرب «مسلمون» في «جاء المسلمون»:","options":["فاعل مرفوع بالواو نيابة عن الضمة والنون عوض عن التنوين","مرفوع بالضمة","منصوب بالياء","مبني"],"answer":0,"explanation":"المسلمون: جمع مذكر سالم: فاعل مرفوع وعلامة رفعه الواو نيابة عن الضمة؛ والنون عوض عن التنوين في الاسم المفرد."}]},{"body":["تطبيقات الأحكام الثلاثة: حضر المعلمون: مرفوع بالواو؛ أكرمت المعلمين: منصوب بالياء؛ سلمت على المعلمين: مجرور بالياء.","النون عوض: قالوا: الواو والياء علامتان، والنون عوض عن التنوين في الاسم المفرد؛ ولهذا تحذف عند الإضافة: معلمو المدرسة حضروا.","متى تحذف النون؟ عند إضافة الجمع: معلمو المدرسة (مرفوع بلا نون)؛ رأيت معلمي المدرسة؛ مررت بمعلمي المدرسة: تحذف النون للإضافة وتبقى العلامة.","جمع المذكر السالم أبوابه: يلحق بالجمع: المؤمنون والمسلمون؛ ويجمع به ما صح تذكير مفرده وكان عاقلًا غالبًا: مهندسون ومدرسون.","تنبيه: الملحق بجمع المذكر السالم: نحو عشرون وثلاثون: تعرب إعرابه: رأيت عشرين ومررت بعشرين: بالياء؛ ومنه: أولو ومنه: بنو: يجريان مجراه.","خلاصة: جمع المذكر السالم يرفع بالواو وينصب ويجر بالياء؛ والبيت القادم يبين باب المثنى: أما المثنى فارفعه بالألف وانصبه واجرره بياء."],"examples":["حضر المعلمون: رفع بالواو","أكرمت المعلمين: نصب بالياء","سلمت على المعلمين: جر بالياء","النون عوض عن التنوين","تحذف النون للإضافة","معلمو المدرسة: بلا نون"],"questions":[{"question":"أعرب «المعلمين» في «أكرمت المعلمين»:","options":["مفعول به منصوب بالياء نيابة عن الفتحة","منصوب بالفتحة","مرفوع بالواو","مجرور بالكسرة"],"answer":0,"explanation":"المعلمين: جمع مذكر سالم: مفعول به منصوب وعلامة نصبه الياء نيابة عن الفتحة؛ والنون عوض عن التنوين."},{"question":"متى تحذف نون جمع المذكر السالم؟","options":["عند إضافته: معلمو المدرسة","في الرفع دائمًا","عند التنوين","أبدًا"],"answer":0,"explanation":"معلمو المدرسة حضروا: حذفت النون للإضافة وبقيت الواو علامة الرفع؛ ورأيت معلمي المدرسة: بقيت الياء."},{"question":"ما حكم عشرين في «رأيت عشرين»؟","options":["ملحق بجمع المذكر: منصوب بالياء","منصوب بالفتحة","مبني","مرفوع"],"answer":0,"explanation":"عشرون وإخوتها ملحقة بجمع المذكر السالم: تعرب بعلاماته: حضر عشرون بالواو ورأيت عشرين بالياء."},{"question":"بم رفع «معلمو» في «معلمو المدرسة حضروا»؟","options":["بالواو نيابة عن الضمة مع حذف النون للإضافة","بالضمة","بالألف","بالياء"],"answer":0,"explanation":"معلمو: مبتدأ مرفوع بالواو نيابة عن الضمة وهو مضاف؛ وحذفت النون للإضافة؛ والمدرسة مضاف إليه مجرور."},{"question":"ما الفرق بين جمع المذكر السالم وجمع التكسير؟","options":["السالم يسلم فيه بناء المفرد والتكسير يتغير بناؤه","لا فرق","بالعكس","السالم للمؤنث"],"answer":0,"explanation":"مسلم ← مسلمون: بناء سالم؛ وكتاب ← كتب: تغير البناء وتكسر: فالأول سالم والثاني مكسر يعرب بالحركات."}]}]},{"id":"wahi-verse-036","title":"المثنى","summary":"البيت السادس والثلاثون: المثنى يُرفع بالألف ويُنصب ويُجر بالياء.","verse":{"number":36,"section":"علامات الإعراب الفرعية","text":"أَمَّا الْمُثَنَّى فَارْفَعْهُ بِالْأَلِفْ / وَانْصِبْهُ وَاجْرُرْهُ بِيَاءٍ قَدْ أُلِفْ"},"segments":[{"body":["البيت السادس والثلاثون: «أَمَّا الْمُثَنَّى فَارْفَعْهُ بِالْأَلِفِ وَانْصِبْهُ وَاجْرُرْهُ بِيَاءٍ قَدْ أُلِفْ». يبين علامات المثنى، ونفهمه كلمة كلمة.","«أَمَّا الْمُثَنَّى»: أما: أداة شرط وتفصيل وتوكيد؛ والمثنى: مبتدأ: ما دل على اثنين بزيادة ألف ونون في الرفع وياء ونون في النصب والجر.","«فَارْفَعْهُ»: فاء جواب الشرط؛ وارفعه: فعل أمر: ارفع المثنى. «بِالْأَلِفِ»: متعلق بارفعه: علامة رفعه الألف نيابة عن الضمة: مسلمان.","«وَانْصِبْهُ وَاجْرُرْهُ»: وانصبه واجرره: فعلا أمر معطوفان. «بِيَاءٍ»: بالياء نيابة عن الفتحة والكسرة: مسلمين ومسلمين.","«قَدْ أُلِفْ»: قد للتحقيق؛ وألف: فعل ماضٍ مبني للمجهول من ألِف الشيء: اعتاده واستأنس به: أي بياء قد ألفه المتكلمون وتعارفوه في هذا الباب.","فالمعنى: أما المثنى فعلامة رفعه الألف نيابة عن الضمة، وعلامة نصبه وجره الياء نيابة عن الفتحة والكسرة: ياء قد تعارفها أهل العربية."],"examples":["أما المثنى فارفعه بالألف","الألف نيابة عن الضمة","وانصبه واجرره بياء","مسلمان ومسلمين","قد ألف: تعارفه المتكلمون","المثنى: دلالة على اثنين"],"questions":[{"question":"ما علامات المثنى؟","options":["الألف للرفع والياء للنصب والجر","الواو","الضمة والفتحة والكسرة","النون"],"answer":0,"explanation":"أما المثنى فارفعه بالألف وانصبه واجرره بياء: الألف نيابة عن الضمة والياء نيابة عن الفتحة والكسرة."},{"question":"ما المثنى؟","options":["ما دل على اثنين بزيادة ألف ونون أو ياء ونون","ما دل على ثلاثة","الجمع","المفرد"],"answer":0,"explanation":"مسلم ← مسلمان: زيدت ألف ونون فدل على اثنين؛ وفي النصب والجر: مسلمين: بياء ونون."},{"question":"ما معنى «قد ألف»؟","options":["بياء قد ألفها المتكلمون وتعارفوها علامة للنصب والجر","محذوفة","مقدرة","لا معنى"],"answer":0,"explanation":"ألف: ماضٍ مبني للمجهول من ألِف: اعتاد؛ أي ياء مستأنس بها معروفة في هذا الباب لا يستغربها السامع."},{"question":"ما الفرق بين المثنى وجمع المذكر في الرفع؟","options":["المثنى يرفع بالألف وجمع المذكر بالواو","كلاهما بالواو","كلاهما بالألف","بالضمة"],"answer":0,"explanation":"مسلمان بالألف للاثنين؛ ومسلمون بالواو لما زاد على الاثنين: فرق العلامة فرق المعنى."},{"question":"أعرب «مسلمان» في «جاء مسلمان»:","options":["فاعل مرفوع بالألف نيابة عن الضمة والنون عوض عن التنوين","مرفوع بالضمة","مرفوع بالواو","منصوب"],"answer":0,"explanation":"مسلمان: مثنى: فاعل مرفوع وعلامة رفعه الألف نيابة عن الضمة؛ والنون عوض عن التنوين في الاسم المفرد."}]},{"body":["تطبيقات الأحكام الثلاثة: حضر المهندسان: مرفوع بالألف؛ أكرمت المهندسين: منصوب بالياء؛ سلمت على المهندسين: مجرور بالياء.","التثنية من المفرد: تزاد ألف ونون ساكنة مكسور ما قبلها في الرفع: كتاب ← كتابان؛ وفي النصب والجر: كتابين؛ ويقلب ما قبل الألف إلى ما كان عليه في المفرد: فتوى ← فتويان.","النون في المثنى عوض عن التنوين كما في الجمع؛ وتحذف للإضافة: كتابا الطالب وكتابي الطالب.","الملحق بالمثنى: الاثنان والاثنتان: تعربان إعراب المثنى: حضر الاثنان بالألف؛ ورأيت الاثنين بالياء.","تنبيه: لا يثنى إلا ما صح تفريده: فلا مثنى من جمع؛ والمثنى يطابق مفرده في التذكير والتأنيث: مسلم ← مسلمان، ومسلمة ← مسلمتان.","خلاصة: المثنى يرفع بالألف وينصب ويجر بالياء بياء مألوفة؛ والبيت القادم يمثل للمثنى والجمع معًا: نحو بنى المهندسون بيتين وتكرم الهندان خير البنتين."],"examples":["حضر المهندسان: رفع بالألف","أكرمت المهندسين: نصب بالياء","سلمت على المهندسين: جر بالياء","النون عوض عن التنوين","تحذف للإضافة: كتابا الطالب","الاثنان ملحق بالمثنى"],"questions":[{"question":"أعرب «المهندسين» في «أكرمت المهندسين»:","options":["مفعول به منصوب بالياء نيابة عن الفتحة لأنه مثنى","منصوب بالفتحة","مرفوع بالألف","مجرور"],"answer":0,"explanation":"المهندسين: مثنى: مفعول به منصوب وعلامة نصبه الياء نيابة عن الفتحة؛ والنون عوض عن التنوين."},{"question":"كيف تثني «كتاب»؟","options":["كتابان في الرفع وكتابين في النصب والجر","كتابون","كتب","كتابات"],"answer":0,"explanation":"تزاد ألف ونون ساكنة مكسور ما قبلها: كتابان؛ وفي النصب والجر تقلب الألف ياء: كتابين."},{"question":"متى تحذف نون المثنى؟","options":["عند الإضافة: كتابا الطالب","أبدًا","في الرفع","عند الوقف"],"answer":0,"explanation":"كتابا الطالب جديدان: حذفت النون للإضافة وبقيت الألف علامة الرفع؛ وكتابي الطالب: بقيت الياء."},{"question":"ما حكم الاثنين في «رأيت الاثنين»؟","options":["ملحق بالمثنى: منصوب بالياء","منصوب بالفتحة","مبني","جمع تكسير"],"answer":0,"explanation":"الاثنان والاثنتان ملحقان بالمثنى: يعربان إعرابه: حضر الاثنان بالألف ورأيت الاثنين بالياء."},{"question":"ما شرط التثنية؟","options":["أن يصح تفريد المثنى فلا يثنى الجمع","أن يكون جمعًا","أن يكون مؤنثًا","لا شرط"],"answer":0,"explanation":"لا يثنى إلا المفرد: مسلم ← مسلمان؛ ولا يقال تثنية الجموع؛ ويطابق المثنى مفرده في التذكير والتأنيث."}]}]},{"id":"wahi-verse-037","title":"أمثلة المثنى في النظم","summary":"البيت السابع والثلاثون: مثالا النظم على المثنى: «بنى المهندسون بيتين» و«تكرم الهندان خير البنتين».","verse":{"number":37,"section":"علامات الإعراب الفرعية","text":"نَحْو: (بَنَى الْمُهَنْدِسُونَ بَيْتَيْنِ) / وَ(تُكْرِمُ الْهِنْدَانِ خَيْرَ الْبِنْتَيْنِ)"},"segments":[{"body":["البيت السابع والثلاثون: «نَحْو: (بَنَى الْمُهَنْدِسُونَ بَيْتَيْنِ) وَ(تُكْرِمُ الْهِنْدَانِ خَيْرَ الْبِنْتَيْنِ)». يمثل للجمع والمثنى، ونفهمه كلمة كلمة.","«نَحْو»: كلمة التمثيل: مثله. «بَنَى الْمُهَنْدِسُونَ بَيْتَيْنِ»: بنى: فعل ماضٍ؛ والمهندسون: فاعل مرفوع بالواو: جمع مذكر سالم؛ وبيتين: مفعول به منصوب بالياء: مثنى.","«وَتُكْرِمُ الْهِنْدَانِ خَيْرَ الْبِنْتَيْنِ»: تكرم: مضارع مرفوع؛ والهندان: فاعل مرفوع بالألف: مثنى مؤنث (هندان: اثنتان من هند)؛ وخير: مفعول به منصوب بالفتحة؛ والبنتين: مضاف إليه مجرور بالياء: مثنى.","فالمعنى: مثال ما تقدم: بنى المهندسون بيتين، وتكرم الهندان خير البنتين: جمع مذكر سالم مرفوع بالواو، ومثنى منصوب ومجرور بالياء، ومثنى مرفوع بالألف.","المثنى المؤنث: هندان: تثنية هند: بألف ونون كالمذكر في الرفع؛ والبنتين: تثنية بنت: بالياء في الجر: فالتثنية لا تفرق بين مذكر ومؤنث في العلامة.","فائدة الجمع بين المثالين: ضبط المواضع الثلاثة: رفع الجمع بالواو (المهندسون) ورفع المثنى بالألف (الهندان) ونصب المثنى وجره بالياء (بيتين والبنتين): تدريب واحد جامع."],"examples":["بنى المهندسون بيتين","المهندسون: رفع بالواو","بيتين: نصب بالياء","تكرم الهندان خير البنتين","الهندان: رفع بالألف","البنتين: جر بالياء"],"questions":[{"question":"بم رفع «المهندسون» في المثال؟","options":["بالواو نيابة عن الضمة لأنه جمع مذكر سالم","بالضمة","بالألف","بالياء"],"answer":0,"explanation":"المهندسون: جمع مذكر سالم: فاعل مرفوع وعلامة رفعه الواو نيابة عن الضمة؛ والنون عوض عن التنوين."},{"question":"بم نصب «بيتين»؟","options":["بالياء نيابة عن الفتحة لأنه مثنى","بالفتحة","بالكسرة","بالألف"],"answer":0,"explanation":"بيتين: مثنى: مفعول به منصوب وعلامة نصبه الياء نيابة عن الفتحة؛ والنون عوض عن التنوين."},{"question":"بم رفع «الهندان»؟","options":["بالألف نيابة عن الضمة لأنه مثنى مؤنث","بالواو","بالضمة","بالياء"],"answer":0,"explanation":"الهندان: تثنية هند: فاعل مرفوع وعلامة رفعه الألف نيابة عن الضمة: التثنية لا تفرق بين مذكر ومؤنث في العلامة."},{"question":"بم جر «البنتين»؟","options":["بالياء نيابة عن الكسرة لأنه مثنى مضاف إليه","بالكسرة","بالفتحة","بالألف"],"answer":0,"explanation":"البنتين: مضاف إليه مجرور وعلامة جره الياء نيابة عن الكسرة لأنه مثنى: تثنية بنت."},{"question":"ما فائدة جمع المثالين في البيت؟","options":["ضبط علامات الجمع والمثنى في مواضع الرفع والنصب والجر معًا","للقافية فقط","زيادة","لا فائدة"],"answer":0,"explanation":"المهندسون: واو رفع؛ والهندان: ألف رفع؛ وبيتين والبنتين: ياء نصب وجر: تدريب جامع على البابين."}]},{"body":["تدريب محكَم على المثال الأول: «بنى»: ماضٍ مبني على الفتح؛ «المهندسون»: فاعل مرفوع بالواو والنون عوض عن التنوين؛ «بيتين»: مفعول به منصوب بالياء والنون عوض عن التنوين.","وعلى الثاني: «تكرم»: مضارع مرفوع بالضمة؛ «الهندان»: فاعل مرفوع بالألف؛ «خير»: مفعول به منصوب بالفتحة وهو مضاف؛ «البنتين»: مضاف إليه مجرور بالياء.","قاعدة الفرق السريع: انظر المعنى: اثنان فالألف في الرفع والياء في النصب والجر؛ أكثر من اثنين مذكر فالواو في الرفع والياء في النصب والجر: فالعدد يوجه العلامة.","توليد: صغ على النمط: كتب المدرسون رسالتين: المدرسون بالواو ورسالتين بالياء؛ ونجح الطالبان في الامتحانين: الطالبان بالألف والامتحانين بالياء.","تنبيه: بنت أصلها بنت بفتح الباء وكسر النون؛ وثنيتها: بنتان بقلب التاء تاء مفتوحة: بنتان وبنتين؛ والنون محذوفة عند الإضافة: بنتا الملك.","خلاصة: مثالا البيت ضبطا الجمع والمثنى معًا؛ والبيت القادم يفرد باب جمع المؤنث السالم: جمع الإناث نصبه بالكسرة."],"examples":["بنى: ماض مبني على الفتح","تكرم: مضارع مرفوع","خير: مفعول مضاف","العدد يوجه العلامة","كتب المدرسون رسالتين","بنتا الملك: نون محذوفة"],"questions":[{"question":"أعرب «خير» في «تكرم الهندان خير البنتين»:","options":["مفعول به منصوب بالفتحة وهو مضاف","فاعل","مضاف إليه","نعت"],"answer":0,"explanation":"خير: مفعول به منصوب بالفتحة الظاهرة وهو مضاف؛ والبنتين: مضاف إليه مجرور بالياء لأنه مثنى."},{"question":"كيف توجه العلامة بسرعة بين المثنى والجمع؟","options":["بالعدد: اثنان فألف وياء؛ وأكثر مذكر فواو وياء","بالطول","بالتأنيث","عشوائي"],"answer":0,"explanation":"المعنى يحكم: اثنان: مسلمان ومسلمين؛ وأكثر: مسلمون ومسلمين: فاضبط العدد تضبط العلامة."},{"question":"أعرب «المدرسون» في «كتب المدرسون رسالتين»:","options":["فاعل مرفوع بالواو نيابة عن الضمة","مرفوع بالضمة","منصوب","مجرور"],"answer":0,"explanation":"المدرسون: جمع مذكر سالم: فاعل مرفوع وعلامة رفعه الواو نيابة عن الضمة؛ والنون عوض عن التنوين."},{"question":"أعرب «رسالتين» في المثال نفسه:","options":["مفعول به منصوب بالياء نيابة عن الفتحة لأنه مثنى","منصوب بالفتحة","مرفوع بالألف","مجرور"],"answer":0,"explanation":"رسالتين: تثنية رسالة: مفعول به منصوب وعلامة نصبه الياء نيابة عن الفتحة؛ والنون عوض عن التنوين."},{"question":"كيف تضيف المثنى؟","options":["بحذف النون: بنتا الملك وكتابا الطالب","بثبوت النون","بتنوينه","بأل"],"answer":0,"explanation":"بنتا الملك: حذفت النون للإضافة وبقيت الألف علامة الرفع: وبنتي الملك: بقيت الياء علامة النصب والجر."}]}]},{"id":"wahi-verse-038","title":"جمع المؤنث السالم","summary":"البيت الثامن والثلاثون: جمع المؤنث السالم يُنصب بالكسرة، ويُرفع بالضمة ويُجر بالكسرة.","verse":{"number":38,"section":"علامات الإعراب الفرعية","text":"جَمْعُ الْأُنَاثِ نَصْبُهُ بِالْكِسْرَةْ / كَـ(إِنَّ هِنْدَاتٍ أَكَلْنَ تَمْرَهْ)"},"segments":[{"body":["البيت الثامن والثلاثون: «جَمْعُ الْأُنَاثِ نَصْبُهُ بِالْكِسْرَةْ كَـ(إِنَّ هِنْدَاتٍ أَكَلْنَ تَمْرَهْ)». يبين علامة نصب جمع المؤنث السالم، ونفهمه كلمة كلمة.","«جَمْعُ الْأُنَاثِ»: مبتدأ مضاف: جمع المؤنث السالم: ما دل على أكثر من اثنتين بزيادة ألف وتاء: مسلمات.","«نَصْبُهُ»: خبر مقدم... والتقدير: جمع الإناث نصبه بالكسرة: علامة نصبه الكسرة نيابة عن الفتحة.","«بِالْكِسْرَةْ»: متعلق بنصبه؛ وحذفت التاء للوزن. «كَـ(إِنَّ هِنْدَاتٍ أَكَلْنَ تَمْرَهْ)»: كقولك: إن هندات أكلن تمره: مثال الباب.","فالمعنى: جمع المؤنث السالم علامة نصبه الكسرة نيابة عن الفتحة، كقولك: إن هنداتٍ أكلن تمره: هندات: اسم إن منصوب بالكسرة.","سر النيابة: نابت الكسرة عن الفتحة لعذر قاله العلماء: إن جمع المؤنث كثير في الكلام فخفف بكسرة هي أخف الحركات؛ والنون فيه عوض عن التنوين كأختيها."],"examples":["جمع الإناث نصبه بالكسرة","الكسرة نيابة عن الفتحة","إن هندات أكلن تمره","هندات: اسم إن منصوب","مسلم ← مسلمات","النون عوض عن التنوين"],"questions":[{"question":"ما علامة نصب جمع المؤنث السالم؟","options":["الكسرة نيابة عن الفتحة","الفتحة","الكسرة الأصلية","الياء"],"answer":0,"explanation":"جمع الإناث نصبه بالكسرة: أكرمت المسلماتِ: منصوب بالكسرة نيابة عن الفتحة: علامة فرعية خاصة بهذا الباب."},{"question":"ما جمع المؤنث السالم؟","options":["ما دل على أكثر من اثنتين بزيادة ألف وتاء","المثنى","جمع التكسير","جمع المذكر"],"answer":0,"explanation":"مسلمة ← مسلمات: زيدت ألف وتاء على المفرد المؤنث فدل على جمع من الإناث مع سلامة البناء."},{"question":"لم نابت الكسرة عن الفتحة في نصبه؟","options":["لعذر التخفيف: كثرة دورانه في الكلام والكسرة أخف الحركات","للقافية","لا سبب","خطأ"],"answer":0,"explanation":"العلماء عللوا النيابة بكثرة استعمال جمع المؤنث فخفف نصبه بالكسرة وهي أخف الحركات نطقًا."},{"question":"أعرب «هندات» في المثال:","options":["اسم إن منصوب وعلامة نصبه الكسرة نيابة عن الفتحة","منصوب بالفتحة","مرفوع","مجرور"],"answer":0,"explanation":"إن هندات: اسم إن منصوب وعلامة نصبه الكسرة نيابة عن الفتحة لأنه جمع مؤنث سالم؛ والنون عوض عن التنوين."},{"question":"أعرب «أكلن» في المثال:","options":["فعل ماض مبني على السكون والنون نون النسوة في محل رفع فاعل","مضارع","أمر","مبني لا محل له"],"answer":0,"explanation":"أكلن: ماضٍ مبني على السكون لاتصاله بنون النسوة؛ ونون النسوة ضمير مبني في محل رفع فاعل."}]},{"body":["تطبيقات الأحكام الثلاثة على جمع المؤنث: حضر المعلماتُ: مرفوع بالضمة (رفعه أصلي بالحركات)؛ أكرمت المعلماتِ: منصوب بالكسرة؛ سلمت على المعلماتِ: مجرور بالكسرة.","لاحظ: الرفع بالضمة والنصب والجر بالكسرة: فالكسرة فيه علامة لحكمين: النصب والجر؛ والسياق يميز: بعد حرف جر فجر، وبعد ناصب فنصب.","النون عوض عن التنوين وتحذف للإضافة كأختيها: مسلمات مصرَ: حذفت النون للإضافة: مسلماتُ (مرفوع) ومسلماتِ (منصوب ومجرور).","الملحق بجمع المؤنث السالم: ما جمع بألف وتاء ولم يصح له مفرد مؤنث على وزنه كآيات وسنين... بل الملحق: الأسماء المعربة إعرابه: أيام: أيامي زماننا: تعرب بالكسرة في النصب والجر.","تنبيه: لا يلزم من كونه مؤنثًا أن يكون سالمًا: نساء: جمع تكسير يعرب بالحركات: رأيت النساءَ بالفتحة؛ فالسالم ما كانت صورته: ألف وتاء زائدتان.","خلاصة: جمع المؤنث السالم يرفع بالضمة وينصب ويجر بالكسرة: نصبه بالكسرة فرعي نائب؛ والبيت القادم: باب الممنوع من الصرف: وجر بالفتحة غير المنصرف."],"examples":["حضر المعلماتُ: رفع بالضمة","أكرمت المعلماتِ: نصب بالكسرة","سلمت على المعلماتِ: جر بالكسرة","السياق يميز النصب من الجر","مسلمات مصر: نون محذوفة","نساء: تكسير بالفتحة"],"questions":[{"question":"بم رفع «المعلمات» في «حضر المعلمات»؟","options":["بالضمة الأصلية","بالكسرة","بالواو","بالفتحة"],"answer":0,"explanation":"المعلمات: جمع مؤنث سالم: فاعل مرفوع وعلامة رفعه الضمة الظاهرة: الرفع فيه بالعلامة الأصلية لا الفرعية."},{"question":"بم نصب «المسلمات» في «أكرمت المسلمات»؟","options":["بالكسرة نيابة عن الفتحة","بالفتحة","بالكسرة الأصلية للجر","بالياء"],"answer":0,"explanation":"أكرمت المسلماتِ: مفعول به منصوب وعلامة نصبه الكسرة نيابة عن الفتحة لأنه جمع مؤنث سالم."},{"question":"كيف يميز نصبه من جره والعلامة واحدة؟","options":["بالسياق: بعد ناصب فنصب وبعد حرف جر فجر","بالنون","بالتنوين","لا يميز"],"answer":0,"explanation":"أكرمت المسلماتِ: نصب؛ ومررت بالمسلماتِ: جر؛ والكسرة واحدة: فالعامل الداخل هو الذي يعين الحكم."},{"question":"أعرب «أيام» في «صمت أيام»:","options":["ظرف زمان منصوب بالكسرة نيابة عن الفتحة ملحق بجمع المؤنث","منصوب بالفتحة","مرفوع","مجرور"],"answer":0,"explanation":"أيام: ملحق بجمع المؤنث السالم: منصوب وعلامة نصبه الكسرة نيابة عن الفتحة وهو مضاف."},{"question":"ما حكم «نساء» في «رأيت النساء»؟","options":["جمع تكسير منصوب بالفتحة الأصلية","جمع مؤنث سالم بالكسرة","مثنى","مبني"],"answer":0,"explanation":"نساء: جمع تكسير لا سالم: لم يجمع بألف وتاء زائدتين: مفعول به منصوب بالفتحة الظاهرة."}]}]},{"id":"wahi-verse-039","title":"الممنوع من الصرف","summary":"البيت التاسع والثلاثون: الاسم الممنوع من الصرف يُجر بالفتحة بدلا من الكسرة.","verse":{"number":39,"section":"علامات الإعراب الفرعية","text":"وَجُرَّ بِالْفَتْحَةِ غَيْرُ الْمُنْصَرِفْ / كَـ(حَضْرَمَوْتُ أَوْ يَزِيدُ أَوْ دُلَفْ)"},"segments":[{"body":["البيت التاسع والثلاثون: «وَجُرَّ بِالْفَتْحَةِ غَيْرُ الْمُنْصَرِفْ كَـ(حَضْرَمَوْتُ أَوْ يَزِيدُ أَوْ دُلَفْ)». يبين علامة جر الممنوع من الصرف، ونفهمه كلمة كلمة.","«وَجُرَّ»: فعل ماضٍ مبني للمجهول: ويجر. «بِالْفَتْحَةِ»: متعلق بجر: بالفتحة نيابة عن الكسرة. «غَيْرُ الْمُنْصَرِفْ»: فاعل مرفوع: الاسم الممنوع من الصرف.","«كَـ(حَضْرَمَوْتُ أَوْ يَزِيدُ أَوْ دُلَفْ)»: كقولك: مررت بحضرموتَ أو بيزيدَ أو بدلفَ: أمثلة للممنوع من الصرف المجرور بالفتحة.","فالمعنى: ويجر بالفتحة - نيابة عن الكسرة - الاسم الممنوع من الصرف، كحضرموت ويزيد ودلف إذا جرت.","ما الممنوع من الصرف؟ هو ما اجتمع فيه سببان من تسعة يقتضيان صرفه (تنوينه) ومع ذلك مُنع التنوين؛ وسمي منصرفًا ما ينصرف: يقبل التنوين؛ فغير المنصرف: الممنوع منه.","الأسباب التسعة: العلمية والتأنيث والعجمة والعدل وتركيب مزجي وصيغة منتهى الجموع وألف ونون زائدتان والتعريف ووزن الفعل؛ سببان منها أو سبب مختص (العلمية مع التأنيث أو العجمة) تمنع الصرف."],"examples":["وجر بالفتحة غير المنصرف","الفتحة نيابة عن الكسرة","حضرموت ويزيد ودلف","الممنوع: اجتماع سببين","المنصرف: يقبل التنوين","الأسباب تسعة"],"questions":[{"question":"ما علامة جر الممنوع من الصرف؟","options":["الفتحة نيابة عن الكسرة بشرطه الآتي","الكسرة","الياء","الألف"],"answer":0,"explanation":"وجر بالفتحة غير المنصرف: مررت بحضرموتَ: مجرور بالفتحة نيابة عن الكسرة لأنه ممنوع من الصرف."},{"question":"ما الممنوع من الصرف؟","options":["اسم اجتمع فيه سببان من تسعة يقتضيان الصرف فمنع التنوين","كل علم","كل معرب","الجمع"],"answer":0,"explanation":"الصرف: التنوين؛ فالممنوع منه ما اجتمع فيه سببان (كالعلمية والعجمة في يعقوب) فمنع التنوين."},{"question":"لم مثل بحضرموت؟","options":["لاجتماع العلمية وتركيب مزجي فيه: اسم مركب من حضر وموت","لكثرته","للقافية فقط","عشوائي"],"answer":0,"explanation":"حضرموت: علم مركب تركيبًا مزجيًّا من كلمتين: اجتمع سببان: العلمية والتركيب المزجي: فمنع الصرف."},{"question":"لم مثل بيزيد ودلف؟","options":["يزيد: علم على وزن الفعل؛ ودلف: علم أعجمي","للجمع","للتثنية","لا سبب"],"answer":0,"explanation":"يزيد: علمية مع وزن الفعل (يفعل)؛ ودلف: علمية مع العجمة: كل منهما سببان مانعان من الصرف."},{"question":"أعرب «حضرموت» في «مررت بحضرموت»:","options":["اسم مجرور بالباء وعلامة جره الفتحة نيابة عن الكسرة","مجرور بالكسرة","منصوب","مبني"],"answer":0,"explanation":"حضرموت: ممنوع من الصرف للعلمية والتركيب المزجي: مجرور وعلامة جره الفتحة نيابة عن الكسرة لعدم الإضافة وأل."}]},{"body":["أنواع الأمثلة: سعاد: علم مؤنث: العلمية والتأنيث؛ ويوسف: علم أعجمي: العلمية والعجمة؛ ومكة: علم معدول عن مككة... بل مكة: علمية وعجمة.","صيغة منتهى الجموع: مساجد ومصابيح: العلمية... بل تمنع ولو نكرة: مررت بمساجدَ: لاجتماع صيغة منتهى الجموع مع وصفيتها أو علميتها.","ألف ونون زائدتان: سلمان وعثمان: علمية وزيادة ألف ونون؛ وقثطام... وغطفان: الوصفية مع الزيادة تكفي.","العدل: عُمَر معدول عن عامر... المعدول: ما نقل عن وضعه الأول كعُمَر عن عامر وثلاثة عن ثلاث: يلتحق بالمانع مع العلمية.","التعريف بأل مع العلمية لا يمنع... بل التعريف سبب يجتمع مع غيره: والعلم الواحد بسبب واحد كزيد وعمرو ينصرفان: زيدٌ بتنوين؛ فالمقصود سببان.","خلاصة: الممنوع من الصرف يجر بالفتحة نيابة عن الكسرة؛ والبيت القادم يبين شرط ذلك: ما لم يكن بأل ولا مضافًا."],"examples":["سعاد: علمية وتأنيث","يوسف: علمية وعجمة","مساجد: صيغة منتهى الجموع","سلمان: ألف ونون زائدتان","زيدٌ: منصرف بالتنوين","السببان شرط المنع"],"questions":[{"question":"علام منع «سعاد» الصرف؟","options":["للعلمية والتأنيث: علم مؤنث","للعجمة","للعدل","لا يمنع"],"answer":0,"explanation":"سعاد: علم لمؤنث: العلمية سبب والتأنيث سبب: اجتمعا فمنعا الصرف: مررت بسعادَ بالفتحة."},{"question":"علام منع «مساجد» الصرف؟","options":["لصيغة منتهى الجموع مع العلمية أو الوصفية","للعجمة","للتأنيث","لا يمنع"],"answer":0,"explanation":"مساجد: صيغة منتهى الجموع (مفاعل) مع كونه وصفًا أو علمًا: سببان: مررت بمساجدَ بالفتحة."},{"question":"هل كل علم ممنوع من الصرف؟","options":["لا؛ العلم بسبب واحد منصرف كزيد وعمرو","نعم كل علم","الأعلام كلها مبنية","المذكر فقط"],"answer":0,"explanation":"زيد وعمرو: علمية محضة بلا سبب ثانٍ: منصرفان: هذا زيدٌ بالتنوين ومررت بزيدٍ بالكسرة."},{"question":"علام منع «سلمان» الصرف؟","options":["للعلمية وزيادة ألف ونون","للتأنيث","للعدل","لا يمنع"],"answer":0,"explanation":"سلمان: علم زيدت فيه ألف ونون بعد ثلاثة أحرف: سببان مانعان: مررت بسلمانَ بالفتحة."},{"question":"أعرب «يوسف» في «مررت بيوسف»:","options":["مجرور بالفتحة نيابة عن الكسرة للعلمية والعجمة","مجرور بالكسرة","منصرف بالتنوين","مرفوع"],"answer":0,"explanation":"يوسف: علم أعجمي: العلمية والعجمة سببان: مجرور وعلامة جره الفتحة نيابة عن الكسرة إذا تجرد من أل والإضافة."}]}]},{"id":"wahi-verse-040","title":"شرط جر الممنوع من الصرف بالفتحة","summary":"البيت الأربعون: الممنوع من الصرف يُجر بالفتحة ما لم يقترن بـ(أل) أو يُضاف.","verse":{"number":40,"section":"علامات الإعراب الفرعية","text":"مَا لَمْ يَكُنْ بِـ(أَلْ) وَلَا مُضَافَا / كَـ(نُورُ سَلَّمَتْ عَلَى عَفَافَا)"},"segments":[{"body":["البيت الأربعون: «مَا لَمْ يَكُنْ بِـ(أَلْ) وَلَا مُضَافَا كَـ(نُورُ سَلَّمَتْ عَلَى عَفَافَا)». يبين شرط جر الممنوع من الصرف بالفتحة، ونفهمه كلمة كلمة.","«مَا لَمْ يَكُنْ»: ما مصدرية أو موصولة... الأشهر: ما نافية تعمل عمل ليس أو شرطية: ما لم يكن: أي إن لم يكن؛ ولم: جازمة؛ ويكن: مضارع مجزوم ناسخ ناقص.","«بِـ(أَلْ)»: متعلق بمحذوف خبر كان: معرفًا بأل؛ والخبر محذوف: كائنًا بأل.","«وَلَا مُضَافَا»: ولا معطوفة؛ ومضافا: خبر ثانٍ منصوب بالفتحة المقدرة على الألف المقصورة: ولا مضافًا إلى غيره.","«كَـ(نُورُ سَلَّمَتْ عَلَى عَفَافَا)»: كقولك: نورُ سلمت على عفافا... المعنى: مثال المضاف: سلمت على نورِ عفاف... بل المثال: «نور سلمت على عفاف»: عفاف مضاف إليه مجرور بالكسرة لأنه مضاف.","فالمعنى: شرط جر الممنوع من الصرف بالفتحة: ألا يكون معرفًا بأل ولا مضافًا؛ فإن عرف بأل أو أضيف جر بالكسرة كسائر الأسماء."],"examples":["ما لم يكن بأل ولا مضافا","الشرط: التجرد من أل والإضافة","بأل أو مضاف: جر بالكسرة","المساجد: بالكسرة","مساجد مصر: بالكسرة","عفافا: مضاف فجر بالكسرة"],"questions":[{"question":"ما شرط جر الممنوع من الصرف بالفتحة؟","options":["ألا يكون معرفًا بأل ولا مضافًا","أن يكون علمًا","أن ينون","أن يضاف"],"answer":0,"explanation":"ما لم يكن بأل ولا مضافا: فإن دخلته أل (المساجد) أو أضيف (مساجد مصر) جر بالكسرة كسائر الأسماء."},{"question":"كيف يجر «مساجد» إذا دخلته أل؟","options":["بالمساجدِ: مجرور بالكسرة الظاهرة","بالفتحة","بالألف","لا يجر"],"answer":0,"explanation":"مررت بالمساجدِ: التعريف بأل أخرجه عن حكم المنع في الجر: مجرور بالكسرة كسائر الأسماء."},{"question":"كيف يجر «مساجد» إذا أضيف؟","options":["مساجدِ مصر: مجرور بالكسرة للإضافة","بالفتحة","بالضمة","لا يتغير"],"answer":0,"explanation":"صليت في مساجدِ مصر: الإضافة أخرجته عن حكم المنع في الجر: مجرور بالكسرة كسائر الأسماء."},{"question":"ما إعراب «مضافا» في البيت؟","options":["خبر كان منصوب بالفتحة المقدرة على الألف للتعذر","منصوب بالفتحة الظاهرة","مرفوع","مجرور"],"answer":0,"explanation":"ولا مضافا: مضاف: خبر كان منصوب وعلامة نصبه الفتحة المقدرة على الألف المقصورة... على الألف للتعذر."},{"question":"هل تبقى حرمة التنوين مع أل والإضافة؟","options":["نعم؛ المنع من التنوين ثابت والفتحة تختص بالجر المجرد","لا يبقى","ينون بأل","كلها تنون"],"answer":0,"explanation":"المساجدُ ومساجدُ مصر: لا تنوين فيهما أبدًا؛ لكن الجر بالكسرة مع أل والإضافة، وبالفتحة مع التجرد."}]},{"body":["تطبيق الشرط: مررت بمساجدَ (مجرد: بالفتحة)؛ ومررت بالمساجدِ (بأل: بالكسرة)؛ ومررت بمساجدِ مصر (مضاف: بالكسرة): ثلاث صور لاسم واحد.","وكذلك الأعلام: مررت بسعادَ (مجردة: بالفتحة)؛ وما تدخلها أل غالبًا لكن: سلمت على سعادَ بنت فلان: أضيفت... بل الإضافة تكفي: على سعادَ بنتِ فلان؟ لا: إذا أضيفت جرت بالكسرة.","قاعدة الشطرين معًا: الممنوع من الصرف: في الرفع والنصب كسائر الأسماء (ضمة وفتحة)؛ وفي الجر: بالفتحة إن تجرد، وبالكسرة مع أل أو الإضافة.","سر الحكمة: الفتحة في الجر مع التجرد علامة فارقة تنبه على المنع من الصرف؛ فإذا دخلته أل أو أضيف احتاج إلى الكسرة لتتميز الإضافة والتعريف.","تدريب: عين علامة الجر: حضرموتَ في مررت بحضرموت (فتحة: مجرد)؛ ومساجدِ المدينة (كسرة: مضاف)؛ والمصابيحِ (كسرة: أل)؛ ويزيدَ في سلمت على يزيد (فتحة).","خلاصة: باب الممنوع من الصرف تم بشرطه: الفتحة للمجرد والكسرة للمقيد بأل أو إضافة؛ والبيت القادم ينتقل إلى الأفعال: وخمسة الأفعال تعطي النونا."],"examples":["مررت بمساجدَ: مجرد","بالمساجدِ: بأل","مساجدِ مصر: مضاف","سلمت على يزيدَ: فتحة","الرفع والنصب كسائر الأسماء","الفتحة علامة فارقة للمنع"],"questions":[{"question":"بم جر «مساجد» في «مررت بمساجد»؟","options":["بالفتحة نيابة عن الكسرة لأنه مجرد من أل والإضافة","بالكسرة","بالياء","بالضمة"],"answer":0,"explanation":"بمساجدَ: ممنوع من الصرف مجرد: مجرور وعلامة جره الفتحة نيابة عن الكسرة لصيغة منتهى الجموع مع الوصفية."},{"question":"بم جر «مساجد» في «صليت في مساجد مصر»؟","options":["بالكسرة الظاهرة لأنه مضاف","بالفتحة","بالألف","بالسكون"],"answer":0,"explanation":"مساجدِ مصر: الإضافة أخرجته عن حكم المنع في الجر: مجرور بالكسرة كسائر الأسماء، ومصر مضاف إليه."},{"question":"بم جر «المصابيح» في «أنرت بالمصابيح»؟","options":["بالكسرة الظاهرة لدخول أل","بالفتحة","بالألف","بالياء"],"answer":0,"explanation":"بالمصابيحِ: التعريف بأل أخرجه عن حكم المنع في الجر: مجرور بالكسرة كسائر الأسماء."},{"question":"كيف يعرب الممنوع من الصرف في الرفع والنصب؟","options":["كسائر الأسماء: بالضمة والفتحة","بالفتحة في الكل","بالكسرة","مبني"],"answer":0,"explanation":"حضرت مساجدُ كثيرة (رفع بالضمة) ورأيت مساجدَ (نصب بالفتحة): المنع خاص بالتنوين وعلامة الجر المجردة."},{"question":"أعرب «يكن» في «ما لم يكن»:","options":["مضارع مجزوم بلم ناسخ ناقص واسمه مستتر تقديره هو","مرفوع","منصوب","ماضٍ"],"answer":0,"explanation":"لم يكن: يكن: مضارع ناقص (كان وأخواتها) مجزوم بلم وعلامة جزمه السكون؛ واسمه مستتر تقديره هو يعود على الممنوع."}]}]},{"id":"wahi-verse-041","title":"الأفعال الخمسة","summary":"البيت الحادي والأربعون: الأفعال الخمسة تُرفع بثبوت النون.","verse":{"number":41,"section":"علامات الإعراب الفرعية","text":"وَخَمْسَةُ الْأَفْعَالِ تُعْطِي النُّونَا / عَلَامَةَ الرَّفْعِ، كَـ(تُؤْمِنُونَا)"},"segments":[{"body":["البيت الحادي والأربعون: «وَخَمْسَةُ الْأَفْعَالِ تُعْطِي النُّونَا عَلَامَةَ الرَّفْعِ، كَـ(تُؤْمِنُونَا)». يبدأ باب الأفعال الخمسة، ونفهمه كلمة كلمة.","«وَخَمْسَةُ الْأَفْعَالِ»: مبتدأ مضاف: الأفعال الخمسة: كل مضارع اتصلت به ألف الاثنين أو واو الجماعة أو ياء المؤنثة المخاطبة: يفعلان وتفعلان ويفعلون وتفعلون وتفعلين.","«تُعْطِي»: خبر: فعل مضارع فاعله مستتر يعود على خمسة: تعطي النون. «النُّونَا»: مفعول به: النون الثابتة في آخرها.","«عَلَامَةَ الرَّفْعِ»: مفعول به ثانٍ أو حال: النون علامة رفع لها؛ فهي تعطي ثبوت النون علامةً للرفع.","«كَـ(تُؤْمِنُونَا)»: كقولك: أنتم تؤمنون: تؤمنون: مضارع مرفوع بثبوت النون؛ والواو فاعل؛ وحذفت الألف بعد الواو للكتابة لا للفظ.","فالمعنى: والأفعال الخمسة تعطي ثبوت النون علامة للرفع، كقولك: تؤمنون؛ وعلة ذلك: النون دالة على الفاعل فشغلت محل العلامة الأصلية."],"examples":["وخمسة الأفعال تعطي النونا","علامة الرفع: ثبوت النون","كتؤمنونا","يفعلان وتفعلان ويفعلون","وتفعلون وتفعلين","النون دالة على الفاعل"],"questions":[{"question":"ما الأفعال الخمسة؟","options":["كل مضارع اتصلت به ألف الاثنين أو واو الجماعة أو ياء المؤنثة المخاطبة","الماضي الخمسة","أفعال الأمر","المجردة"],"answer":0,"explanation":"يفعلان وتفعلان ويفعلون وتفعلون وتفعلين: خمسة صيغ للمضارع اتصلت بها الضمائر الثلاثة: ألف وواو وياء."},{"question":"ما علامة رفع الأفعال الخمسة؟","options":["ثبوت النون","الضمة","الواو","الألف"],"answer":0,"explanation":"وخمسة الأفعال تعطي النونا علامة الرفع: تؤمنون: مرفوع بثبوت النون؛ والواو ضمير متصل في محل رفع فاعل."},{"question":"لم كانت النون علامة الرفع فيها؟","options":["لأنها دالة على الفاعل فشغلت محل الحركة","للقافية","لا سبب","للزينة"],"answer":0,"explanation":"النون دلت على الفاعل (واو الجماعة ونحوه) فشغلت محل الضمة: فكان ثبوتها علامة الرفع نيابة عنها."},{"question":"أعرب «تؤمنون» في «أنتم تؤمنون»:","options":["مضارع مرفوع بثبوت النون والواو فاعل","مرفوع بالضمة","منصوب","مجزوم"],"answer":0,"explanation":"تؤمنون: مضارع مرفوع وعلامة رفعه ثبوت النون لأنه من الأفعال الخمسة؛ والواو ضمير متصل مبني في محل رفع فاعل."},{"question":"أي الضمائر يتصل بالمضارع فيجعله من الخمسة؟","options":["ألف الاثنين وواو الجماعة وياء المؤنثة المخاطبة","تاء المتكلم","نون النسوة","همزة المتكلم"],"answer":0,"explanation":"يفعلان وتفعلان (ألف الاثنين)؛ يفعلون وتفعلون (واو الجماعة)؛ تفعلين (ياء المخاطبة): ثلاثة ضمائر خمس صيغ."}]},{"body":["تطبيق الصيغ الخمس: يكتبان (الغائب المثنى) وتكتبان (المخاطب المثنى) ويكتبون (الغائب الجمع) وتكتبون (المخاطب الجمع) وتكتبين (المخاطبة المفردة): كلها مرفوعة بثبوت النون.","المضارع المجرد من هذه الضمائر: يكتب وتكتب ونكتب وأكتب: يرفع بالضمة الظاهرة أو المقدرة: فالضمة أصل، وثبوت النون فرع خاص بالخمسة.","تنبيه: نون النسوة في يكتبْن: ليست من الأفعال الخمسة: يكتبْنَ مبني على السكون لاتصاله بنون النسوة؛ فلا تخلط بين النونين: نون الرفع هنا ونون النسوة المبنية هناك.","نون التوكيد: يكتبنَّ ويكتبَنِ: مبني على الفتح أو الكسر لاتصاله بنون التوكيد: أيضًا خارج عن الخمسة؛ فالضابط: ضمائر الرفع الثلاثة فقط.","تدريب التمييز: عين الحكم والعلامة: يصلون (مرفوع بثبوت النون)؛ يصلينَّ (مبني على الكسر)؛ يصليْنَ (مبني على السكون لنون النسوة)؛ تصلين (مرفوع بثبوت النون).","خلاصة: الأفعال الخمسة ترفع بثبوت النون؛ والبيت القادم يبين نصبها وجزمها: وحذفها للجزم والنصب سمة."],"examples":["يكتبان وتكتبان: ألف","يكتبون وتكتبون: واو","تكتبين: ياء المخاطبة","يكتب: رفع بالضمة","يكتبْنَ: نون نسوة مبني","يكتبنَّ: نون توكيد مبني"],"questions":[{"question":"أعرب «يكتبون» في «يكتبون الدرس»:","options":["مضارع مرفوع بثبوت النون والواو فاعل","مرفوع بالضمة","مبني","مجزوم"],"answer":0,"explanation":"يكتبون: من الأفعال الخمسة لاتصال واو الجماعة: مرفوع وعلامة رفعه ثبوت النون؛ والواو ضمير فاعل."},{"question":"بم رفع «تكتبين» في «أنتِ تكتبين»؟","options":["بثبوت النون لأنه من الأفعال الخمسة","بالضمة","بالكسرة","بالسكون"],"answer":0,"explanation":"تكتبين: اتصلت به ياء المؤنثة المخاطبة: مضارع مرفوع وعلامة رفعه ثبوت النون؛ والياء ضمير فاعل."},{"question":"ما حكم «يكتبْنَ» بنون النسوة؟","options":["مبني على السكون لاتصاله بنون النسوة وليس من الخمسة","مرفوع بثبوت النون","مجزوم","منصوب"],"answer":0,"explanation":"يكتبْنَ: نون النسوة ضمير مبني في محل رفع فاعل؛ والفعل مبني على السكون لاتصاله بها: خارج عن الخمسة."},{"question":"ما حكم «يكتبنَّ» بنون التوكيد؟","options":["مبني على الفتح لاتصاله بنون التوكيد الثقيلة","مرفوع بالنون","مجزوم","منصوب"],"answer":0,"explanation":"يكتبنَّ: نون التوكيد لا محل لها؛ والفعل مبني على الفتح لاتصاله بها: خارج عن الأفعال الخمسة."},{"question":"متى يرفع المضارع بالضمة؟","options":["إذا تجرد من الناصب والجازم ومن ضمائر الأفعال الخمسة","دائمًا","مع واو الجماعة","مع ألف الاثنين"],"answer":0,"explanation":"يكتب الولد: مرفوع بالضمة الظاهرة: تجرد من نواصب و جوازم ومن الألف والواو والياء: فالضمة أصله."}]}]},{"id":"wahi-verse-042","title":"حذف النون للجزم والنصب","summary":"البيت الثاني والأربعون: الأفعال الخمسة تُنصب وتُجزم بحذف النون.","verse":{"number":42,"section":"علامات الإعراب الفرعية","text":"وَحَذْفُهَا لِلْجَزْمِ وَالنَّصْبِ سِمَةْ / كَـ(لَمْ يَعُودُوا لِتَسِيرِي فِي عَمَّةْ)"},"segments":[{"body":["البيت الثاني والأربعون: «وَحَذْفُهَا لِلْجَزْمِ وَالنَّصْبِ سِمَةْ كَـ(لَمْ يَعُودُوا لِتَسِيرِي فِي عَمَّةْ)». يبين علامة نصب الأفعال الخمسة وجزمها، ونفهمه كلمة كلمة.","«وَحَذْفُهَا»: مبتدأ مضاف: وحذف النون؛ والهاء تعود على النون. «لِلْجَزْمِ وَالنَّصْبِ»: متعلق بحذفها: الحذف للجزم وللنصب.","«سِمَةْ»: خبر: علامة وسمة: حذف النون علامة الجزم والنصب في الأفعال الخمسة؛ وحذفت التاء للوزن.","«كَـ(لَمْ يَعُودُوا لِتَسِيرِي فِي عَمَّةْ)»: كقولك: لم يعودوا لتسيري في عمة: لم يعودوا: حذفت النون للجزم؛ لتسيري: مضارع مؤنث مخاطب... مثال مركب.","فالمعنى: وحذف النون من الأفعال الخمسة علامة للجزم والنصب معًا، كقولك: لم يعودوا: مجزوم بحذف النون، ولن يعودوا: منصوب بحذف النون.","فالأفعال الخمسة: ترفع بثبوت النون، وتنصب وتجزم بحذف النون: يؤمنون (رفع)، لن يؤمنوا (نصب)، لم يؤمنوا (جزم): ثلاث صور لفعل واحد."],"examples":["وحذفها للجزم والنصب سمة","كلم يعودوا: جزم بحذف النون","لن يعودوا: نصب بحذف النون","يؤمنون: رفع بثبوتها","ثلاث صور لفعل واحد","الحذف علامة فرعية"],"questions":[{"question":"ما علامة نصب الأفعال الخمسة وجزمها؟","options":["حذف النون","الفتحة والسكون","الواو","ثبوت النون"],"answer":0,"explanation":"وحذفها للجزم والنصب سمة: لن تؤمنوا: منصوب بحذف النون؛ ولم تؤمنوا: مجزوم بحذف النون."},{"question":"أعرب «يعودوا» في «لم يعودوا»:","options":["مضارع مجزوم بلم وعلامة جزمه حذف النون والواو فاعل","مرفوع بثبوت النون","منصوب بالفتحة","مبني"],"answer":0,"explanation":"لم يعودوا: يعودوا: مضارع مجزوم بلم وعلامة جزمه حذف النون لأنه من الأفعال الخمسة؛ والواو ضمير فاعل."},{"question":"ما معنى «سمة» في البيت؟","options":["علامة وأمارة: حذف النون علامة النصب والجزم","قافية","زيادة","لا معنى"],"answer":0,"explanation":"سمة: علامة مميزة: كما كانت الضمة سمة الرفع الأصلية كان حذف النون سمة النصب والجزم في الخمسة."},{"question":"بم نصب «يعودوا» في «لن يعودوا»؟","options":["بحذف النون لأنه من الأفعال الخمسة","بالفتحة","بالسكون","بحذف حرف العلة"],"answer":0,"explanation":"لن يعودوا: لن ناصبة؛ ويعودوا: من الأفعال الخمسة: منصوب وعلامة نصبه حذف النون؛ والواو فاعل."},{"question":"أعرب «تسيري» في «لتسيري»:","options":["مضارع منصوب بلام الأمر أو لام التعليل وعلامة نصبه حذف النون","مرفوع","مجزوم بالسكون","مبني"],"answer":0,"explanation":"لتسيري: مضارع من الأفعال الخمسة (ياء المخاطبة): منصوب باللام وعلامة نصبه حذف النون؛ والياء ضمير فاعل."}]},{"body":["جدول الصيغ الثلاث: يفعلان: مرفوع بثبوت النون؛ لن يفعلا: منصوب بحذف النون؛ لم يفعلا: مجزوم بحذف النون؛ وهكذا تفعلان ويفعلون وتفعلون وتفعلين.","الواو والألف والياء تبقى بعد الحذف: لأنها ضمائر فاعل لا تحذف: لم يفعلوا: حذفت النون وبقيت الواو؛ لم تفعلي: بقيت الياء.","تنبيه الإعلال: لم يقولوا: حذفت النون ثم حذفت الواو (حرف العلة) وسكن ما قبلها وألقيت حركتها على العين: يقولوا ← يقولُوا ← يقولوا: لا تخلط بين الحذفين.","تطبيق النواصب: أن ولن وإذن وكي ولام التعليل: لن يكتبوا الدرس: منصوب بحذف النون؛ والجوازم: لم ولما ولا الناهية ولام الأمر: لم يكتبوا: مجزوم بحذف النون.","تدريب الفرق: عين الحكم: إنهم يؤمنون (رفع: ثبوت النون)؛ ولن يؤمنوا (نصب: حذف)؛ ولم يؤمنوا (جزم: حذف): فالعامل يعين الحكم والحذف يعين العلامة.","خلاصة: الأفعال الخمسة: رفع بثبوت النون ونصب وجزم بحذفها؛ والبيت القادم يبين جزم المعتل الآخر: واحذف لجزم ناقص آخره."],"examples":["لن يفعلا: نصب بحذف النون","لم يفعلا: جزم بحذف النون","الضمائر تبقى بعد الحذف","لم يقولوا: حذفان","النواصب والجوازم تعين الحكم","إنهم يؤمنون: ثبوت"],"questions":[{"question":"أعرب «يفعلوا» في «لم يفعلوا»:","options":["مضارع مجزوم بلم وعلامة جزمه حذف النون والواو فاعل","مرفوع","منصوب","مبني"],"answer":0,"explanation":"لم يفعلوا: مجزوم بلم وعلامة جزمه حذف النون؛ والواو ضمير متصل مبني في محل رفع فاعل باقية بعد الحذف."},{"question":"لم قيل في «لم يقولوا» حذفان؟","options":["حذفت النون للجزم وحذفت الواو (حرف العلة) للتخفيف","حذف واحد","حذف الفاء","لا حذف"],"answer":0,"explanation":"يقولون: يقولوا بحذف النون؛ ثم حذفت الواو المنقلبة عن ضمة وقلبت حركتها للقاف: يقولوا: حذف النون علامة والواو للتخفيف."},{"question":"متى يكون حذف النون علامة نصب ومتى علامة جزم؟","options":["مع النواصب علامة نصب ومع الجوازم علامة جزم","دائمًا نصب","دائمًا جزم","لا يتغير"],"answer":0,"explanation":"لن يؤمنوا: لن ناصبة فالحذف علامة نصب؛ ولم يؤمنوا: لم جازمة فالحذف علامة جزم: العامل يوجه الحكم."},{"question":"أعرب «تكتبي» في «لم تكتبي»:","options":["مضارع مجزوم بلم وعلامة جزمه حذف النون والياء فاعل","مرفوع","منصوب","مبني"],"answer":0,"explanation":"لم تكتبي: مجزوم بلم وعلامة جزمه حذف النون لأنه من الأفعال الخمسة؛ والياء ضمير متصل مبني في محل رفع فاعل."},{"question":"اذكر نواصب تدخل على الأفعال الخمسة فتحذف نونها:","options":["أن ولن وإذن وكي ولام التعليل","لم ولا الناهية","قد والسين","إن وأخواتها"],"answer":0,"explanation":"لن يؤمنوا وكي تؤمنوا وإذن يؤمنوا: النواصب تحذف نون الأفعال الخمسة؛ والجوازم: لم يؤمنوا: تحذفها أيضًا."}]}]},{"id":"wahi-verse-043","title":"الجزم بحذف حرف العلة","summary":"البيت الثالث والأربعون: المضارع المعتل الآخر يُجزم بحذف حرف العلة.","verse":{"number":43,"section":"علامات الإعراب الفرعية","text":"وَاحْذِفْ لِجَزْمِ نَاقِصٍ آخِرُهُ / كَـ(مَنْ أَتَادِ يَعْدُ لِي أَوْ أَرَهْ)"},"segments":[{"body":["البيت الثالث والأربعون: «وَاحْذِفْ لِجَزْمِ نَاقِصٍ آخِرُهُ كَـ(مَنْ أَتَادِ يَعْدُ لِي أَوْ أَرَهْ)». يبين جزم المضارع المعتل الآخر، ونفهمه كلمة كلمة.","«وَاحْذِفْ»: فعل أمر: واحذف حرف العلة. «لِجَزْمِ»: متعلق باحذف: لجزم. «نَاقِصٍ»: مضاف إليه... بل فاعل... التقدير: واحذف آخر الناقص لجزمه: المعتل الآخر: الفعل الناقص.","«آخِرُهُ»: مفعول به: آخره: حرف العلة الواقع في آخر الفعل: الواو أو الياء أو الألف: يدعو ويرمي ويسعى.","«كَـ(مَنْ أَتَادِ يَعْدُ لِي أَوْ أَرَهْ)»: كقولك: مَن أتاك... المثال فيه يعد: مجزوم بحذف الواو: لم يعدْ ← يعدُ؛ وأره: مجزوم بحذف الياء: لم يرَ.","فالمعنى: واحذف حرف العلة من آخر الفعل الناقص لجزمه، كقولك: يعد (بحذف الواو) وأره (بحذف الياء).","علة الحذف: اجتماع الساكنين: حرف العلة ساكن والجزم يقتضي سكون آخر: يدعوْ: سكونان يلتقيان فحذف حرف العلة تخفيفًا: لم يدعُ."],"examples":["واحذف لجزم ناقص آخره","الناقص: المعتل الآخر","يعد: حذف الواو","أره: حذف الياء","لم يدعُ ولم يرمِ","علة الحذف: التقاء الساكنين"],"questions":[{"question":"بم يجزم المضارع المعتل الآخر؟","options":["بحذف حرف العلة من آخره","بالسكون","بحذف النون","بالكسرة"],"answer":0,"explanation":"واحذف لجزم ناقص آخره: لم يدعُ بحذف الواو؛ ولم يرمِ بحذف الياء؛ ولم يسعَ بحذف الألف."},{"question":"ما الفعل الناقص؟","options":["المعتل الآخر بالواو أو الياء أو الألف","المعتل الأول","الصحيح","المضعف"],"answer":0,"explanation":"الناقص: ما آخره حرف علة: يدعو ويرمي ويسعى: نقص آخره عن تمام صحته؛ ويجزم بحذف حرف العلة."},{"question":"لم حذف حرف العلة عند الجزم؟","options":["للتخفيف من التقاء الساكنين: سكون العلة وسكون الجزم","للقافية","لا سبب","للزينة"],"answer":0,"explanation":"يدعوْ: الواو ساكنة والجزم يقتضي السكون: التقى ساكنان فحذف حرف العلة وتحرك ما قبله: لم يدعُ."},{"question":"أعرب «يعد» في «لم يعد»:","options":["مضارع مجزوم بلم وعلامة جزمه حذف حرف العلة (الواو)","مرفوع","منصوب","مجزوم بالسكون"],"answer":0,"explanation":"لم يعد: يعد: أصله يعدو: مجزوم بلم وعلامة جزمه حذف الواو حرف العلة؛ والفاعل مستتر تقديره هو."},{"question":"أعرب «أره» في المثال:","options":["مضارع مجزوم وعلامة جزمه حذف حرف العلة (الياء)","مرفوع بالضمة","منصوب","مبني"],"answer":0,"explanation":"أو أره: أره: أصله أري: مضارع مجزوم وعلامة جزمه حذف الياء حرف العلة؛ والهاء مفعول به."}]},{"body":["تطبيق الأحوال الثلاث: يدعو: رفع بالضمة المقدرة على الواو للثقل؛ لن يدعو: نصب بالفتحة المقدرة على الواو للثقل؛ لم يدعُ: جزم بحذف الواو.","ويرمي: رفع بالضمة المقدرة على الياء للثقل؛ لن يرمي: نصب بالفتحة المقدرة؛ لم يرمِ: جزم بحذف الياء.","ويسعى: رفع بالضمة المقدرة على الألف للتعذر؛ لن يسعى: نصب بالفتحة المقدرة للتعذر؛ لم يسعَ: جزم بحذف الألف.","قاعدة الحركة قبل الحذف: تحرك الحرف قبل المحذوف بما يناسب المحذوف: يدعو: حذفت الواو وضم ما قبلها (يدعُ) لأن الضمة تدل على الواو؛ يرمي: كسرت الراء (يرمِ) للياء؛ يسعى: فتحت العين (يسعَ) للألف.","تنبيه: هذا الحذف للأفعال المعتلة الآخر غير الأفعال الخمسة؛ فإن اتصلت بها ضمائر الرفع فحكمها حكمها: لم يدعوا: بحذف النون لا الواو ثم حذفت الواو تخفيفًا.","خلاصة: المضارع المعتل الآخر يجزم بحذف حرف العلة؛ وبذلك تمت أبواب العلامات الفرعية السبعة؛ والبيت القادم يحصر عددها: وذي العلامات إذا عددتها."],"examples":["يدعو: ضمة مقدرة","لن يدعو: فتحة مقدرة","لم يدعُ: حذف الواو","لم يرمِ: حذف الياء","لم يسعَ: حذف الألف","الحركة تدل على المحذوف"],"questions":[{"question":"أعرب «يدعو» في «يدعو ربه»:","options":["مضارع مرفوع بالضمة المقدرة على الواو للثقل","مرفوع بالضمة الظاهرة","منصوب","مجزوم"],"answer":0,"explanation":"يدعو: معتل الآخر بالواو: مضارع مرفوع وعلامة رفعه الضمة المقدرة على الواو منع ظهورها الثقل."},{"question":"أعرب «يسعى» في «لن يسعى»:","options":["مضارع منصوب بالفتحة المقدرة على الألف للتعذر","مرفوع","مجزوم","منصوب بالفتحة الظاهرة"],"answer":0,"explanation":"لن يسعى: لن ناصبة؛ ويسعى معتل بالألف: منصوب وعلامة نصبه الفتحة المقدرة على الألف للتعذر."},{"question":"لم ضمت الدال في «لم يدعُ»؟","options":["لتدل على الواو المحذوفة: الضمة أنسب بالواو","للقافية","خطأ","لا سبب"],"answer":0,"explanation":"حذفت الواو للجزم فحرك ما قبلها بالضمة الدالة عليها: يدعو ← يدعُ؛ وكذلك يرمِ بالكسرة للياء ويسعَ بالفتحة للألف."},{"question":"كيف يجزم «يرمي»؟","options":["بحذف الياء: لم يرمِ","بالسكون","بحذف النون","بالكسرة"],"answer":0,"explanation":"يرمي: معتل الآخر بالياء: مجزوم بحذف حرف العلة: لم يرمِ؛ وكسرت الراء دلالة على الياء المحذوفة."},{"question":"ما فرق جزم «يدعون» عن «يدعو»؟","options":["يدعون من الخمسة: بحذف النون؛ ويدعو ناقص مجرد: بحذف الواو","كلاهما بحذف النون","كلاهما بحذف الواو","بالسكون"],"answer":0,"explanation":"لم يدعوا: حذفت النون لأنه من الخمسة ثم الواو تخفيفًا؛ ولم يدعُ: حذفت الواو علامة الجزم لأنه ناقص مجرد."}]}]},{"id":"wahi-verse-044","title":"العلامات الفرعية محصورة العدد","summary":"البيت الرابع والأربعون: العلامات الفرعية إذا عددتها وجدتها محصورة بعدد معلوم.","verse":{"number":44,"section":"علامات الإعراب الفرعية","text":"وَذِي الْعَلَامَاتُ إِذَا عَدَدْتَهَا / مَحْضُورَةً بِالْعَدِّ فَقَدْ وَجَدْتَهَا"},"segments":[{"body":["البيت الرابع والأربعون: «وَذِي الْعَلَامَاتُ إِذَا عَدَدْتَهَا مَحْضُورَةً بِالْعَدِّ فَقَدْ وَجَدْتَهَا». يحصر عدد العلامات الفرعية، ونفهمه كلمة كلمة.","«وَذِي»: وصاحب: مبتدأ مضاف: وذو العلامات (الإعراب)؛ وذي: مبني في محل رفع مبتدأ.","«الْعَلَامَاتُ»: مضاف إليه مجرور. «إِذَا»: ظرف لما يستقبل من الزمان خافض لشرطه: إذا عددتها.","«عَدَدْتَهَا»: فعل ماض وفاعل ومفعول: عددت العلامات؛ وهي في محل جزم فعل الشرط.","«مَحْضُورَةً»: حال منصوبة... بل التقدير: إذا عددتها وجدتها محصورة بالعد: «محضورة» بالضاد: محصورة ومعدودة. «بِالْعَدِّ»: بالعد والإحصاء. «فَقَدْ وَجَدْتَهَا»: فقد وجدتها: جواب الشرط: فقد أحصيتها.","فالمعنى: وصاحب العلامات - أي العلامات الفرعية - إذا عددتها وجدتها محصورة بالعدد معلومة المقدار لا تزيد ولا تنقص."],"examples":["وذي العلامات إذا عددتها","محصورة بالعد","فقد وجدتها","الفرعية محصورة العدد","إذا: شرطية","فقد وجدتها: جواب الشرط"],"questions":[{"question":"ما موضوع البيت الرابع والأربعين؟","options":["حصر عدد العلامات الفرعية","الأحكام","المبني","التوابع"],"answer":0,"explanation":"وذي العلامات إذا عددتها محصورة بالعد فقد وجدتها: الفرعية معدودة محصورة يأتي تفصيل عددها في البيت القادم."},{"question":"ما معنى «محضورة بالعد»؟","options":["محصورة معروفة العدد لا تزيد ولا تنقص","غائبة","كثيرة بلا حد","مقدرة"],"answer":0,"explanation":"محضورة (بالمعجمة): محصورة: عددها معلوم محفوظ: أربع وخمس وثلاث وثلاث كما يأتي: فمن عدها وجدها."},{"question":"ما إعراب «إذا عددتها»؟","options":["إذا ظرف شرط وعددت: فعل الشرط في محل جزم","ظرف زمان خالص","استئناف","جواب"],"answer":0,"explanation":"إذا: ظرف لما يستقبل خافض لشرطه منصوب بجوابه؛ وعددت: فعل الشرط ماضٍ في محل جزم؛ والتاء فاعل والهاء مفعول."},{"question":"ما جواب الشرط في البيت؟","options":["فقد وجدتها","محصورة","عددتها","وذي"],"answer":0,"explanation":"فقد وجدتها: الفاء رابطة لجواب الشرط؛ وقد للتحقيق؛ ووجدتها: ماضٍ والتاء فاعل والهاء مفعول: وجدتها محصورة."},{"question":"أي علامات يقصد البيت بحصرها؟","options":["العلامات الفرعية لا الأصلية","الحركات","الأحكام","الأقسام"],"answer":0,"explanation":"الأصلية معروفة: أربع؛ والمراد بالحصر هنا الفرعية: لأنها متفرقة في سبعة أبواب فحاجت إلى العد والإحصاء."}]},{"body":["فائدة الحصر: العلم المحصور أسهل حفظًا وأبعد عن النسيان: فإذا عرفت أن الفرعية أربع عشرة علامة (أربع وخمس وثلاث وثلاث... كما يأتي تفصيلها) راجعت نفسك عند كل إعراب.","كيف تحصيها عمليًّا: أربع في الرفع (ضمة وواو وألف وثبوت نون)؛ وخمس في النصب (فتحة وألف وياء وكسرة وحذف نون... وحذف حرف علة للمعتل)؛ وثلاث في الجر؛ وثلاث في الجزم.","تطبيق العد على الأمثلة: مسلمون: رفع بالواو (ضمن الأربع)؛ مسلمين: نصب بالياء (ضمن الخمس)؛ مسلماتِ: نصب بالكسرة (ضمن الخمس)؛ مسلمين: جر بالياء (ضمن الثلاث).","قاعدة المراجعة: إذا أعربت كلمة فعلامتها إما أصلية (حركة أو سكون) أو فرعية محصورة؛ فإن لم تقع في واحدة منها فراجع إعرابك: فالحصر محكَم ضبط.","تنبيه: الحصر هنا للعلامات لا للأحكام: الأحكام أربعة سبقت؛ والعلامات الأصلية أربع سبقت؛ والفرعية تفصيل عددها في البيت القادم: فأربع فالخمس هن الكثرى.","خلاصة: العلامات الفرعية محصورة بالعد لمن عدها؛ والبيت القادم يفصيل... يفصل العدد: أربع فخمس فثلاث فثلاث."],"examples":["الحصر يسهل الحفظ","أربع في الرفع","خمس في النصب","ثلاث في الجر وثلاث في الجزم","الحصر محكم ضبط","الأحكام سبقت أربعة"],"questions":[{"question":"ما فائدة حصر العلامات الفرعية؟","options":["سهولة الحفظ وضبط الإعراب والمراجعة","للقافية","زيادة علم","لا فائدة"],"answer":0,"explanation":"المحصور يحفظ ويراجع: إن لم تقع العلامة في أصلية ولا فرعية محصورة فالإعراب خطأ: فالعد محكم ضبط."},{"question":"كم علامة للرفع في الجملة (أصلية وفرعية)؟","options":["أربع: الضمة والواو والألف وثبوت النون","ثلاث","خمس","ست"],"answer":0,"explanation":"الرفع: بالضمة (محمدٌ) وبالواو (مسلمون) وبالألف (مسلمان) وبثبوت النون (يؤمنون): أربع علامات."},{"question":"لم احتاجت الفرعية إلى العد دون الأصلية؟","options":["لتفرقها في سبعة أبواب بخلاف الأصلية المعلومة","لكثرتها المطلقة","للقافية","لا سبب"],"answer":0,"explanation":"الأصلية أربع مشهورة؛ والفرعية متفرقة: حروف ونون وحذف ونيابة: فحاجت إلى الإحصاء لئلا يفوت منها شيء."},{"question":"صنف علامة «يؤمنون» في العد:","options":["من علامات الرفع الأربع: ثبوت النون","من علامات النصب","من علامات الجر","من علامات الجزم"],"answer":0,"explanation":"يؤمنون: من الأفعال الخمسة: مرفوع بثبوت النون: وهي العلامة الرابعة من علامات الرفع بعد الضمة والواو والألف."},{"question":"ما الحصر الذي تقدم هذا البيت في النظم؟","options":["حصر الأحكام الأربعة ثم العلامات الأصلية الأربع","حصر الأقسام","حصر التوابع","لم يسبقه حصر"],"answer":0,"explanation":"سبق: إعرابنا حكمان ثم حكم (الأحكام أربعة)؛ وعلامة الإعراب كل مرة بضمة وفتحة وكسرة ثم سكون (الأصلية أربع)؛ وهذا حصر الفرعية."}]}]},{"id":"wahi-verse-045","title":"عدد العلامات الفرعية: أربع وخمس وثلاث وثلاث","summary":"البيت الخامس والأربعون: عدد علامات الفرعية: أربع للرفع وخمس للنصب وثلاث للجر وثلاث للجزم.","verse":{"number":45,"section":"علامات الإعراب الفرعية","text":"فَأَرْبَعٌ، فَالْخَمْسُ هُنَّ الْكُثْرَى / ثُمَّ ثَلَاثٌ، فَثَلَاثٌ أُخْرَى"},"segments":[{"body":["البيت الخامس والأربعون: «فَأَرْبَعٌ، فَالْخَمْسُ هُنَّ الْكُثْرَى ثُمَّ ثَلَاثٌ، فَثَلَاثٌ أُخْرَى». يفصل عدد العلامات الفرعية، ونفهمه كلمة كلمة.","«فَأَرْبَعٌ»: الفاء تفصيلية؛ وأربع: خبر مبتدأ محذوف: فهي أربع: علامات الرفع أربع: الضمة والواو والألف وثبوت النون.","«فَالْخَمْسُ هُنَّ الْكُثْرَى»: فالخمس هن الكثرى: علامات النصب خمس وهي الكثيرات: الفتحة والألف والياء والكسرة وحذف النون وحذف حرف العلة... ضبطها الشرح: فتحة وكسرة وألف وياء وحذف: خمس.","«ثُمَّ ثَلَاثٌ»: ثم ثلاث: علامات الجر ثلاث: الكسرة والياء والفتحة.","«فَثَلَاثٌ أُخْرَى»: فثلاث أخرى: علامات الجزم ثلاث: السكون وحذف النون وحذف حرف العلة.","فالمعنى: فعلامات الرفع أربع، والنصب خمس وهي الكثرى، ثم الجر ثلاث، فالجزم ثلاث أخرى: المجموع خمس عشرة علامة."],"examples":["فأربع: علامات الرفع","فالخمس هن الكثرى: النصب","ثم ثلاث: الجر","فثلاث أخرى: الجزم","المجموع خمس عشرة","النصب أكثرها عددًا"],"questions":[{"question":"كم علامات كل حكم كما فصلها البيت؟","options":["الرفع أربع والنصب خمس والجر ثلاث والجزم ثلاث","أربع للكل","خمس للكل","ثلاث للكل"],"answer":0,"explanation":"فأربع فالخمس هن الكثرى ثم ثلاث فثلاث أخرى: الرفع أربع والنصب خمس والجر ثلاث والجزم ثلاث: خمس عشرة علامة."},{"question":"ما علامات الرفع الأربع؟","options":["الضمة والواو والألف وثبوت النون","الحركات فقط","الفتحة وأخواتها","الكسرة"],"answer":0,"explanation":"محمدٌ بالضمة؛ ومسلمون بالواو؛ ومسلمان بالألف؛ ويؤمنون بثبوت النون: أربع علامات للرفع."},{"question":"ما علامات النصب الخمس؟","options":["الفتحة والألف والكسرة والياء وحذف النون","ثلاث فقط","الضمة","السكون"],"answer":0,"explanation":"محمدًا بالفتحة؛ وأخاك بالألف؛ ومسلماتٍ بالكسرة؛ ومسلمين بالياء؛ ولن يؤمنوا بحذف النون: خمس علامات وهي الكثرى."},{"question":"ما علامات الجر الثلاث؟","options":["الكسرة والياء والفتحة","الضمة","الألف","النون"],"answer":0,"explanation":"بمحمدٍ بالكسرة؛ وبمسلمين بالياء؛ وبحضرموتَ بالفتحة (للممنوع من الصرف المجرد): ثلاث علامات للجر."},{"question":"ما علامات الجزم الثلاث؟","options":["السكون وحذف النون وحذف حرف العلة","الفتحة","الكسرة","الواو"],"answer":0,"explanation":"لم يقمْ بالسكون؛ ولم يؤمنوا بحذف النون؛ ولم يدعُ بحذف حرف العلة: ثلاث علامات للجزم."}]},{"body":["لم كانت علامات النصب الكثرى؟ لكثرة أبوابه: المفعولات والحال والتمييز والمستثنى واسم إن وخبر كان وغيرها: فاحتاجت أبوابه الفرعية (المثنى والجمعان وخمسة الأسماء والأفعال الخمسة) إلى علامات كثيرة.","جدول جامع للعلامات الخمس عشرة: الرفع: ضمة (محمدٌ) وواو (مسلمون وأبوك) وألف (مسلمان وأخاك في الرفع... الألف للمثنى والخمسة أنصاب... اضبط: الواو للجمع والخمسة رفعًا) وثبوت نون (يؤمنون).","النصب: فتحة (محمدًا) وكسرة (مسلماتٍ) وألف (أخاك ومسلمين؟ لا: ألف للمثنى؟ المثنى ينصب بالياء... الألف للنصب في خمسة الأسماء: رأيت أخاك) وياء (مسلمين) وحذف نون (لن يؤمنوا).","الجر: كسرة (بمحمدٍ) وياء (بمسلمين وبأخيك) وفتحة (بحضرموتَ). الجزم: سكون (لم يقمْ) وحذف نون (لم يؤمنوا) وحذف حرف علة (لم يدعُ).","تدريب التصنيف: صنف العلامة في حكمها: الواو في مسلمون (رفع)؛ الكسرة في مسلماتٍ منصوبة (نصب)؛ الفتحة في حضرموتَ مجرورة (جر)؛ حذف النون في لم يكتبوا (جزم).","خلاصة: تم باب العلامات: أصلية أربع وفرعية محصورة: أربع وخمس وثلاث وثلاث؛ وبه يستعد المتعلم لأبواب الإعراب القادمة: الفاعل ونائبه وما بعدهما."],"examples":["النصب كثرى لكثرة أبوابه","محمدٌ ومسلمون ومسلمان ويؤمنون","محمدًا ومسلماتٍ وأخاك ومسلمين ولن يؤمنوا","بمحمدٍ وبمسلمين وبحضرموتَ","لم يقمْ ولم يؤمنوا ولم يدعُ","خمس عشرة علامة محصورة"],"questions":[{"question":"لم كانت علامات النصب أكثر العلامات؟","options":["لكثرة أبواب النصب: المفعولات والحال والتمييز وغيرها","للقافية","صدفة","لا سبب"],"answer":0,"explanation":"أبواب النصب كثيرة: مفعول به ومطلق وله وفيه وحال وتمييز ومستثنى وأسماء النواسخ: فكثرت علاماته الفرعية."},{"question":"صنف: الكسرة في «أكرمت المسلماتِ»:","options":["علامة نصب فرعية نيابة عن الفتحة","علامة جر","علامة رفع","علامة جزم"],"answer":0,"explanation":"المسلمات: جمع مؤنث سالم مفعول به: منصوب بالكسرة نيابة عن الفتحة: فالكسرة هنا من علامات النصب الخمس لا الجر."},{"question":"صنف: الفتحة في «مررت بحضرموتَ»:","options":["علامة جر فرعية نيابة عن الكسرة","علامة نصب","علامة رفع","أصلية"],"answer":0,"explanation":"حضرموت: ممنوع من الصرف مجرد: مجرور بالفتحة نيابة عن الكسرة: فالفتحة هنا من علامات الجر الثلاث لا النصب."},{"question":"احسب مجموع علامات الإعراب كلها:","options":["خمس عشرة: أربع للرفع وخمس للنصب وثلاث للجر وثلاث للجزم","أربع فقط","سبع","عشرون"],"answer":0,"explanation":"فأربع فالخمس هن الكثرى ثم ثلاث فثلاث أخرى: 4+5+3+3 = خمس عشرة علامة أصلية وفرعية محصورة."},{"question":"أعرب «الكثرى» في البيت:","options":["خبر مبتدأ محذوف مرفوع بالضمة المقدرة على الألف: هن الكثرى","مرفوع بالضمة الظاهرة","منصوب","نعت"],"answer":0,"explanation":"فالخمس هن الكثرى: هن: ضمير فصل أو مبتدأ؛ والكثرى: خبر مرفوع وعلامة رفعه الضمة المقدرة على الألف للتعذر: أي الكثيرات."}]}]},{"id":"wahi-verse-046","title":"الفاعل: من الذي فعل؟","summary":"البيت السادس والأربعون: تعريف الفاعل وضابطه، وأنه يأتي اسمًا ظاهرًا أو ضميرًا.","verse":{"number":46,"section":"الفاعل ونائبه","text":"الْفَاعِلُ اسْمٌ مُسْنَدٌ مُؤَخَّرُ / لِلْفِعْلِ، وَهُوَ ظَاهِرٌ وَمُضْمَرُ"},"segments":[{"body":["وصلنا الآن إلى أبواب إعراب الجمل، ونبدأ بالجملة الفعلية: فعلٌ ثم فاعل.","الفاعل هو: اسم مرفوع يأتي بعد الفعل، ويُسند الفعل إليه، أي: يدل على من قام بالفعل.","تقول: كتبَ المعلمُ الدرسَ. فالكتابة حدثت، والذي قام بها هو المعلم، فـ«المعلمُ» فاعل.","والضابط السهل الذي يكشف لك الفاعل دائمًا: اسأل بعد الفعل: من الذي فعل؟ فجوابك هو الفاعل. مثال: صلّى الإمامُ بالناس. من الذي صلّى؟ الإمام. إذًا «الإمامُ» فاعل مرفوع.","وتنبيه مهم: الفاعل لا يكون إلا اسمًا؛ فلا يكون فعلًا ولا حرفًا ولا جملة، ومكانه بعد الفعل، فإن تقدّم عليه صار مبتدأ كما سيأتي."],"examples":["قامَ زيدٌ — زيد: فاعل مرفوع.","نجحَ الطالبُ — الطالب: فاعل.","يحفظُ الأولادُ القرآنَ — الأولاد: فاعل.","خرجَ الرجلانِ — الرجلان: فاعل مرفوع بالألف.","اجتمعَ المسلمونَ — المسلمون: فاعل مرفوع بالواو.","ماتَ الرجلُ — الرجل: فاعل وإن لم يفعل فعلًا باختياره؛ يكفي أن يُسند إليه الفعل."],"questions":[{"question":"الفاعل هو:","options":["اسم مرفوع يُسند إليه الفعل قبله","اسم منصوب يقع عليه الفعل","حرف يأتي بعد الفعل","كل ما جاء بعد الفعل"],"answer":0,"explanation":"الفاعل: اسم مرفوع مسند إليه الفعل، مثل: قام زيدٌ — زيد: فاعل مرفوع."},{"question":"ما ضابط معرفة الفاعل؟","options":["أن تسأل: من الذي فعل؟","أن تسأل: ماذا فعل؟","أن تنظر إلى آخر الكلمة","أن تعدّ حروف الكلمة"],"answer":0,"explanation":"اسأل: من الذي قام بالفعل؟ فالجواب فاعل، مثل: من الذي نجح؟ الطالبُ — فاعل مرفوع."},{"question":"في جملة «يسافرُ المهندسونَ» الفاعل هو:","options":["المهندسون","يسافر","لا فاعل في الجملة","الجملة كلها"],"answer":0,"explanation":"المهندسون: فاعل مرفوع وعلامة رفعه الواو؛ لأنه جمع مذكر سالم."},{"question":"لماذا صار «الرجلُ» فاعلًا في «ماتَ الرجلُ» مع أن الموت ليس فعلًا يختاره؟","options":["لأن الفعل أُسند إليه، ويكفي الإسناد","لأنه اسم قصير","لأن مات فعل أمر","لأن الرجل لا يموت"],"answer":0,"explanation":"الفاعل من أُسند إليه الفعل، فعله حقيقة أم لا؛ الرجلُ: فاعل مرفوع بالضمة."},{"question":"لو قلنا «محمدٌ قامَ» فإن «محمدًا» هنا:","options":["مبتدأ وليس فاعلًا؛ لأنه تقدم على الفعل","فاعل لأنه قبل قام","مفعول به","خبر كان"],"answer":0,"explanation":"الفاعل يتأخر عن فعله؛ وإن تقدم عليه صار مبتدأ مرفوعًا، والفاعل ضمير مستتر يعود عليه."}]},{"body":["يقول الناظم: «وَهُوَ ظَاهِرٌ وَمُضْمَرُ» أي: الفاعل نوعان.","النوع الأول: فاعل ظاهر، وهو اسم صريح تسمعه وتقرأه، نحو: قرأ المعلمُ القرآنَ.","النوع الثاني: فاعل مضمر، وهو ضمير؛ قد يكون بارزًا متصلًا بالفعل تسمعه مثل تاء المتكلم في «كتبتُ»، وقد يكون مستترًا خفيًّا تقدّره أنت، مثل «كتبَ» أي: كتب هو.","والضمائر البارزة التي تكون فاعلًا هي ضمائر الرفع المتصلة: تاء المتكلم (كتبتُ)، ونا (كتبنا)، وواو الجماعة (كتبوا)، وألف الاثنين (كتبا)، ونون النسوة (كتبنَ).","فانتبه: الضمير المستتر لا يُقرأ ولا يُرى، لكن النحويين يقدّرونه ليكتمل معنى الجملة."],"examples":["ظاهر: صلّى الإمامُ بالناس — الإمام: فاعل ظاهر.","بارز متصل: كتبتُ الدرسَ — التاء: فاعل في محل رفع.","بارز متصل: كتبنا — نا: فاعل.","بارز متصل: كتبوا — واو الجماعة: فاعل.","مستتر: كتبَ — فاعله ضمير مستتر تقديره: هو.","مستتر: يكتبُ — فاعله ضمير مستتر تقديره: هو.","مستتر: اكتبْ — فاعله ضمير مستتر تقديره: أنت."],"questions":[{"question":"نوعا الفاعل هما:","options":["ظاهر ومضمر","مفرد وجمع","ماضٍ ومضارع","مذكر ومؤنث"],"answer":0,"explanation":"الفاعل إما اسم ظاهر صريح، وإما ضمير بارز أو مستتر."},{"question":"في «كتبتُ الواجبَ» الفاعل هو:","options":["تاء المتكلم: ضمير بارز في محل رفع","الواجب","ضمير مستتر تقديره هو","لا فاعل"],"answer":0,"explanation":"التاء ضمير بارز متصل مبني على الضم في محل رفع فاعل."},{"question":"الفاعل المستتر هو:","options":["ضمير خفي لا يُنطق ونقدّره نحن","اسم مكتوب بخط صغير","ضمير منفصل مثل هو","اسم محذوف من الكتاب"],"answer":0,"explanation":"المستتر يقدَّر ولا يظهر، مثل: كتبَ أي كتب هو."},{"question":"في «يحفظنَ القرآنَ» الفاعل هو:","options":["نون النسوة في محل رفع","ضمير مستتر تقديره هنّ","القرآن","الياء"],"answer":0,"explanation":"نون النسوة ضمير بارز متصل مبني على الفتح في محل رفع فاعل."},{"question":"قدّر الفاعل المستتر في «أكرمَ الضيفَ»:","options":["هو","أنا","نحن","هم"],"answer":0,"explanation":"أكرمَ فعل ماضٍ غائب، ففاعله مستتر تقديره: هو، والضيفُ: مفعول به منصوب."}]}]},{"id":"wahi-verse-047","title":"الفاعل الضمير: نصف الباب ينضبط بالضمائر","summary":"البيت السابع والأربعون: الفاعل المضمر كثير في كلامنا، وضمائر الرفع تضبطه كله.","verse":{"number":47,"section":"الفاعل ونائبه","text":"وَنِصْفُ هَذَا الْبَابِ جَا مُنْضَبِطًا / كَـ(أَهْتَدِي، وَنَهْتَدِي، وَأَغْتَبِطًا)"},"segments":[{"body":["قال الناظم إن نصف باب الفاعل جاء منضبطًا بالضمائر؛ لأننا في كلامنا اليومي نستخدم الضمائر فاعلًا أكثر مما نستخدم الأسماء الظاهرة.","تأمل أفعالك: أكتب، نكتب، كتبتُ، كتبنا، كتبوا، كتبنَ... كلها فاعلها ضمير لا اسم ظاهر.","فالفاعل المضمر نوعان: بارز متصل بالفعل مثل تاء المتكلم وواو الجماعة، ومستتر لا يظهر نحو: أكتبُ أي أكتب أنا.","ومثال البيت: «أَهْتَدِي» فاعلها ضمير مستتر تقديره أنا، و«نَهْتَدِي» فاعلها مستتر تقديره نحن، و«أَغْتَبِطَ» أي: فرحت وسررت، فاعلها أيضًا مستتر تقديره أنا."],"examples":["أَهْتَدِي — الفاعل: ضمير مستتر تقديره أنا.","نَهْتَدِي — الفاعل: ضمير مستتر تقديره نحن.","أَغْتَبِطَ — أي فرحتُ؛ الفاعل: مستتر تقديره أنا.","تكتبُ — مستتر تقديره أنت.","يكتبُ — مستتر تقديره هو.","كتبتُ — التاء: فاعل بارز متصل.","كتبوا — واو الجماعة: فاعل بارز متصل."],"questions":[{"question":"لماذا قال الناظم إن نصف باب الفاعل منضبط بالضمائر؟","options":["لكثرة استعمال الضمائر فاعلًا في الكلام","لأن الفاعل نصفه مبتدأ","لأن الضمائر لا تُعرب","لأن الفاعل نصف الجملة"],"answer":0,"explanation":"كلامنا مليء بأمثال: أكتب وكتبتُ وكتبوا؛ فاعلها ضمير لا اسم ظاهر."},{"question":"الفاعل في «أَهْتَدِي» هو:","options":["ضمير مستتر تقديره أنا","ضمير بارز هو الألف","اسم ظاهر","لا فاعل في الفعل المضارع"],"answer":0,"explanation":"أَهْتَدِي مضارع للمتكلم، فاعله مستتر تقديره أنا، والفعل مرفوع بالضمة."},{"question":"معنى «أَغْتَبِطَ» في البيت:","options":["فرحتُ وسررتُ","غضبتُ","كتبتُ","ذهبتُ"],"answer":0,"explanation":"اغتبطَ بمعنى فرح؛ والفاعل مستتر تقديره أنا، والفعل ماضٍ مبني على الفتح."},{"question":"الفاعل في «نَهْتَدِي» تقديره:","options":["نحن","أنا","هو","هم"],"answer":0,"explanation":"نَهْتَدِي مضارع بنا الدالة على الجمع، فاعله مستتر تقديره نحن."},{"question":"أي جملة فاعلها ضمير بارز متصل؟","options":["كتبوا الدرسَ","يكتبُ الدرسَ","اكتبِ الدرسَ","كتبَ الدرسَ"],"answer":0,"explanation":"كتبوا: واو الجماعة ضمير بارز متصل مبني على السكون في محل رفع فاعل."}]},{"body":["ولضبط الفاعل الضمير احفظ ضمائر الرفع المتصلة، وهي خمسة: تاء المتكلم (كتبتُ)، ونا (كتبنا)، وواو الجماعة (كتبوا)، وألف الاثنين (كتبا)، ونون النسوة (كتبنَ).","والضمائر المستترة تقدَّر بحسب الفعل: فالماضي الغائب (كتبَ) تقديره هو، والمضارع بحسب أوله: أكتب (أنا)، نكتب (نحن)، تكتب (أنت أو هي)، يكتب (هو).","وقاعدة مفيدة: إعراب هذه الضمائر لا يخرج عن ثلاثة أحوال: فاعل في الغالب، أو اسم كان وأخواتها إذا اتصلت بها مثل «كنتُ مسافرًا»، أو نائب فاعل إذا اتصلت بفعل مبني للمجهول مثل «أُكرمتُ».","فإذا ضبطت الضمائر ضبطت نصف باب الفاعل كما قال الناظم."],"examples":["كتبتُ — التاء: فاعل.","كنتُ مسافرًا — التاء: اسم كان.","أُكرمتُ — التاء: نائب فاعل.","كتبا — ألف الاثنين: فاعل.","كتبنَ — نون النسوة: فاعل.","درستَ — التاء: فاعل (للمخاطب).","نجحنا — نا: فاعل."],"questions":[{"question":"ضمائر الرفع المتصلة التي تكون فاعلًا هي:","options":["التاء ونا وواو الجماعة وألف الاثنين ونون النسوة","الهاء والكاف والياء","إياي وإياك","حروف الجر"],"answer":0,"explanation":"الخمسة تسمى ضمائر الرفع البارزة، وإعرابها: في محل رفع فاعل."},{"question":"في «أُكرمتُ» إعراب التاء:","options":["نائب فاعل","فاعل","اسم كان","مفعول به"],"answer":0,"explanation":"أُكرمتُ مبني للمجهول، فالتاء ضمير بارز في محل رفع نائب فاعل."},{"question":"في «كنتَ مجتهدًا» إعراب التاء:","options":["اسم كان في محل رفع","فاعل","خبر كان","مفعول به"],"answer":0,"explanation":"التاء اتصلت بكان فهي اسمها: ضمير بارز في محل رفع اسم كان."},{"question":"قدّر الفاعل المستتر في «تَقْرَأُ»:","options":["أنتَ","أنا","نحن","هو"],"answer":0,"explanation":"تقرأُ للمخاطب المفرد، فاعله مستتر تقديره أنت، والفعل مرفوع بالضمة."},{"question":"جملة «سافرَ» فاعلها:","options":["ضمير مستتر تقديره هو","ضمير بارز","اسم ظاهر محذوف","لا فاعل لها"],"answer":0,"explanation":"الفعل الماضي الغائب المفرد فاعله مستتر تقديره هو."}]}]},{"id":"wahi-verse-048","title":"نائب الفاعل: مفعول حُذف فاعله فرُفع","summary":"البيت الثامن والأربعون: تعريف نائب الفاعل، وكيف نبني الفعل للمجهول.","verse":{"number":48,"section":"الفاعل ونائبه","text":"وَنَائِبُ الْفَاعِلِ مَفْعُولٌ رُفِعْ / لِحَذْفِ فَاعِلٍ، كَـ(يُغْبَطُ الْوَرِعْ)"},"segments":[{"body":["أحيانًا نريد أن نخبر عن الحدث دون أن نذكر من فعله؛ فنحذف الفاعل ونضع المفعول به مكانه ونرفعه، فيصير «نائب الفاعل».","فبدل: قرأ الإمامُ القرآنَ، نقول: قُرئَ القرآنُ. حذفنا «الإمام»، ورفعنا «القرآن» فصار نائب فاعل.","وإذا حذفنا الفاعل تغيّر بناء الفعل أيضًا، ويسمى ذلك: بناء الفعل للمجهول.","في الفعل الماضي: نضم أوله ونكسر ما قبل آخره: قرأَ → قُرئَ، كتبَ → كُتبَ، فتحَ → فُتحَ.","وفي الفعل المضارع: نضم أوله ونفتح ما قبل آخره: يقرأُ → يُقرَأُ، يكتبُ → يُكتَبُ.","ومثال البيت: «يُغْبَطُ الْوَرِعْ» أي: يُغبط عليه صلاحه؛ الورعُ نائب فاعل مرفوع، والأصل: يغبطِ الناسُ الورعَ."],"examples":["قرأ الإمامُ القرآنَ → قُرئَ القرآنُ — القرآن: نائب فاعل.","فتحَ الحارسُ البابَ → فُتحَ البابُ — الباب: نائب فاعل.","يكرمُ الناسُ المهندسَ → يُكرَمُ المهندسُ — المهندس: نائب فاعل.","كتبَ الطالبُ الدرسَ → كُتبَ الدرسُ — الدرس: نائب فاعل.","شرحَ المعلمُ القاعدةَ → شُرحَتِ القاعدةُ — القاعدة: نائب فاعل.","يُغْبَطُ الورعُ — الورع: نائب فاعل مرفوع بالضمة."],"questions":[{"question":"نائب الفاعل هو:","options":["مفعول به حُذف الفاعل فرُفع مكانه","فاعل تقدم على فعله","اسم منصوب دائمًا","خبر مقدم"],"answer":0,"explanation":"نحذف الفاعل وننيب المفعول منابه ونعطيه حكمه: الرفع."},{"question":"كيف نبني الفعل الماضي للمجهول؟","options":["نضم أوله ونكسر ما قبل آخره","نفتح أوله ونكسر ما قبل آخره","نضمه كله","لا يتغير بناؤه"],"answer":0,"explanation":"قرأَ → قُرئَ: ضممنا الأول وكسرنا ما قبل الآخر."},{"question":"كيف نبني الفعل المضارع للمجهول؟","options":["نضم أوله ونفتح ما قبل آخره","نضم أوله ونكسر ما قبل آخره","نسكن أوله","نحذف حرف المضارعة"],"answer":0,"explanation":"يكتبُ → يُكتَبُ: ضم الأول وفتح ما قبل الآخر."},{"question":"في «فُتحَ البابُ» إعراب «البابُ»:","options":["نائب فاعل مرفوع بالضمة","مفعول به منصوب","فاعل مرفوع","مبتدأ"],"answer":0,"explanation":"حُذف الفاعل، فالباب نائب فاعل مرفوع وعلامة رفعه الضمة."},{"question":"أصل «يُغْبَطُ الورعُ» قبل حذف الفاعل:","options":["يغبطِ الناسُ الورعَ","غبطَ الورعُ الناسَ","يغبطُ الورعُ الناسَ","الورعُ يغبطُ"],"answer":0,"explanation":"الورع مفعول به في الأصل، فلما حذف الفاعل رُفع نائبًا عنه."}]},{"body":["لماذا نبني الفعل للمجهول؟ لأسباب كثيرة منها: ألا نعرف الفاعل، أو لا يهمنا ذكره، أو نريد الاهتمام بالحدث نفسه لا بفاعله.","تقول: أُكرمَ المهندسونَ. المهم عندك أن الإكرام وقع عليهم، لا من الذي أكرمهم.","وحكم نائب الفاعل الرفع دائمًا: إن كان معربًا فهو مرفوع بعلامته، وإن كان ضميرًا مبنيًّا فهو في محل رفع.","وتنبيه: فعل الأمر لا يُبنى للمجهول؛ البناء للماضي والمضارع فقط.","وإن كان قبل آخر الماضي ألف قُلبت ياء: باعَ → بيعَ، وفي المضارع إن كان قبل آخره واو أو ياء قُلبتا ألفًا: يبيعُ → يُباعُ."],"examples":["أُكرمَ المهندسونَ — المهندسون: نائب فاعل مرفوع بالواو.","أُكرموا — واو الجماعة: نائب فاعل في محل رفع.","باعَ التاجرُ السلعةَ → بيعَتِ السلعةُ — قلبت الألف ياء.","يبيعُ التاجرُ السلعةَ → تُباعُ السلعةُ — قلبت الياء ألفًا.","شُوهدَ الهلالُ — الهلال: نائب فاعل.","تُقرأُ الآياتُ — الآيات: نائب فاعل مرفوع بالكسرة؛ لأنه جمع مؤنث سالم."],"questions":[{"question":"متى نبني الفعل للمجهول؟","options":["عندما لا نريد ذكر الفاعل أو لا نعرفه","عندما يكون الفاعل اسمًا طويلًا","في كل جملة فعلية","عندما يكون الفعل أمرًا"],"answer":0,"explanation":"نبني للمجهول لاهتمامنا بالحدث لا بفاعله، أو لجهل الفاعل."},{"question":"حكم نائب الفاعل الإعرابي:","options":["الرفع دائمًا","النصب دائمًا","الجر","الجزم"],"answer":0,"explanation":"نائب الفاعل مرفوع إن كان معربًا، وفي محل رفع إن كان مبنيًّا."},{"question":"ما نائب الفاعل في «تُقرأُ الآياتُ»؟","options":["الآيات","تقرأ","النون","لا نائب فاعل"],"answer":0,"explanation":"الآياتُ: نائب فاعل مرفوع وعلامة رفعه الكسرة؛ لأنه جمع مؤنث سالم."},{"question":"بناؤ «باعَ» للمجهول يصير:","options":["بيعَ","بُوعَ","بُيِّعَ","باعَ لا يتغير"],"answer":0,"explanation":"قبل آخره ألف فتقلب ياء مع ضم الأول وكسر ما قبل الآخر: بيعَ."},{"question":"أي فعل لا يبنى للمجهول؟","options":["فعل الأمر","الفعل الماضي","الفعل المضارع","فعل المفرد"],"answer":0,"explanation":"البناء للمجهول خاص بالماضي والمضارع."}]}]},{"id":"wahi-verse-049","title":"نائب الفاعل بلا مفعول: شبه الجملة والمفعول المطلق","summary":"البيت التاسع والأربعون: إذا لم يوجد مفعول به ناب عن الفاعل جار ومجرور أو ظرف أو مفعول مطلق.","verse":{"number":49,"section":"الفاعل ونائبه","text":"وَنَائِبُ اللَّازِمِ شِبْهُ جُمْلَةْ / أَوْ مُطْلَقٌ، كَـ(سِيرَ نَحْوُ الْقِبْلَةْ)"},"segments":[{"body":["تعلمنا أن نائب الفاعل هو المفعول به بعد حذف الفاعل. لكن ماذا لو لم يكن في الجملة مفعول به أصلًا؟","هذا يحدث مع الفعل اللازم الذي لا يتعدى إلى مفعول، مثل: جلسَ الطالبُ على الكرسي. لو حذفنا الفاعل فلا مفعول ننيبه.","القاعدة: إذا لم يوجد مفعول به ناب عن الفاعل واحد من ثلاثة: الجار والمجرور، أو الظرف، أو المفعول المطلق، ويرتفع كل منهم في محل رفع نائب فاعل.","فنقول: جُلسَ على الكرسيِ — «على الكرسي» جار ومجرور نائب فاعل في محل رفع. ونقول: صِيمَ رمضانُ — «رمضان» ظرف نائب فاعل مرفوع.","ومثال البيت: «سِيرَ نَحْوُ الْقِبْلَةْ» أي: سارَ الناسُ نحوَ القبلة، فحذف الفاعل وبُني (سارَ) للمجهول فصار «سِيرَ»، وارتفع الظرف «نحوُ» نائبًا عن الفاعل."],"examples":["جلسَ الطالبُ على الكرسيِ → جُلسَ على الكرسيِ — الجار والمجرور: نائب فاعل في محل رفع.","صامَ المسلمونَ رمضانَ → صِيمَ رمضانُ — الظرف: نائب فاعل مرفوع.","صليتُ خلفَ الإمامِ → صُليَّ خلفَ الإمامِ — خلف: ظرف نائب فاعل.","قرأَ المسلمُ قراءةً خاشعةً → قُرئَتْ قراءةٌ خاشعةٌ — المفعول المطلق: نائب فاعل.","سارَ الجيشُ نحوَ القبلةِ → سِيرَ نحوُ القبلةِ — نحو: ظرف نائب فاعل.","سجدَ المصلي سجودًا طويلًا → سُجدَ سجودٌ طويلٌ — المفعول المطلق: نائب فاعل."],"questions":[{"question":"إذا لم يوجد في الجملة مفعول به، فمن ينوب عن الفاعل بعد حذفه؟","options":["الجار والمجرور أو الظرف أو المفعول المطلق","المبتدأ","الخبر","حرف الجر"],"answer":0,"explanation":"ثلاثة تنوب عن الفاعل: شبه الجملة من جار ومجرور أو ظرف، أو مفعول مطلق."},{"question":"في «صِيمَ رمضانُ» كلمة «رمضان» تعرب:","options":["ظرف زمان نائب فاعل مرفوع","مفعول به منصوب","فاعل","مضاف إليه"],"answer":0,"explanation":"لا مفعول به في الجملة، فناب الظرف عن الفاعل وارتفع: رمضانُ ظرف نائب فاعل."},{"question":"في «جُلسَ على الكرسيِ» الجار والمجرور:","options":["نائب فاعل في محل رفع","متعلق بالفعل فقط","خبر مقدم","حال"],"answer":0,"explanation":"شبه الجملة نابت عن الفاعل فهي في محل رفع نائب فاعل."},{"question":"ما الأصل قبل البناء للمجهول في «سِيرَ نحوُ القبلةِ»؟","options":["سارَ الناسُ نحوَ القبلةِ","سارَ نحوُ القبلةِ","سارَتِ القبلةُ نحوَ الناسِ","نحوُ القبلةِ سارَ"],"answer":0,"explanation":"نحوَ كان منصوبًا ظرفًا، فلما حذف الفاعل ارتفع نائبًا عنه: نحوُ."},{"question":"أي جملة فيها مفعول مطلق نائب فاعل؟","options":["قُرئَتْ قراءةٌ خاشعةٌ","قُرئَ القرآنُ","صِيمَ رمضانُ","جُلسَ على الكرسيِ"],"answer":0,"explanation":"قراءةٌ مفعول مطلق ناب عن الفاعل فهو نائب فاعل مرفوع بالضمة."}]},{"body":["لاحظ أن الناظم سمى هذا الباب «نائب اللازم»؛ لأن الفعل اللازم هو الذي لا يتعدى إلى مفعول به، فلا يجد المبني للمجهول مفعولًا ينيبه.","والمتعدي الذي له مفعول به يسلك الطريق الأسهل: يرفع مفعوله نائبًا كما في البيت السابق.","فالقاعدة الجامعة: انظر أولًا: هل في الجملة مفعول به؟ فإن وجد فهو النائب، وإلا فانظر إلى الجار والمجرور أو الظرف أو المفعول المطلق.","وتذكّر أن نائب الفاعل مرفوع أبًدا أو في محل رفع، وأن الفعل يبنى للمجهول كما تعلمت: ضم أول الماضي وكسر ما قبل آخره، وضم أول المضارع وفتح ما قبل آخره.","تدريب سريع: حوّل «نامَ الطفلُ ليلًا» إلى المجهول: نِيمَ ليلٌ — الظرف «ليل» نائب فاعل."],"examples":["متعدٍّ: أكرمني الأستاذُ → أُكرمتُ — التاء: نائب فاعل.","لازم مع ظرف: نامَ الطفلُ ليلًا → نِيمَ ليلٌ.","لازم مع جار ومجرور: ذهبَ الطلابُ إلى المدرسةِ → ذُهبَ إلى المدرسةِ.","لازم مع مفعول مطلق: فرحَ الولدُ فرحًا شديدًا → فُرحَ فرحًا شديدًا... والأصح: فُرحَ فرحٌ شديدٌ.","سِيرَ نحوُ القبلةِ — نحو: ظرف مكان نائب فاعل مرفوع بالضمة.","عُملَ عملًا صالحًا — عملٌ: مفعول مطلق نائب فاعل."],"questions":[{"question":"الفعل اللازم هو:","options":["فعل لا يتعدى إلى مفعول به","فعل له مفعولان","فعل أمر","فعل ناسخ"],"answer":0,"explanation":"اللازم يكتفي بفاعله نحو: جلسَ ونامَ وذهبَ."},{"question":"في «نِيمَ ليلٌ» كلمة «ليلٌ» تعرب:","options":["ظرف زمان نائب فاعل مرفوع","مفعول فيه منصوب","فاعل","تمييز"],"answer":0,"explanation":"الظرف ناب عن الفاعل المحذوف فارتفع: ليلٌ ظرف نائب فاعل علامة رفعه الضمة."},{"question":"رتّب خطوات إيجاد نائب الفاعل:","options":["ابحث عن مفعول به أولًا، فإن لم يوجد فالجار والمجرور أو الظرف أو المطلق","ارفع أول اسم بعد الفعل دائمًا","احذف الفعل نفسه","قدّم الخبر"],"answer":0,"explanation":"المفعول به أولى بالنيابة، فإن تعذر ناب أحد الثلاثة."},{"question":"حوّل إلى المجهول: «سجدَ المصلي سجودًا طويلًا»:","options":["سُجدَ سجودٌ طويلٌ","سُجدَ المصلي","سجدَ سجودًا","سَجدَ سجودٌ"],"answer":0,"explanation":"بنينا الماضي للمجهول: سُجدَ، ورفعنا المفعول المطلق نائبًا: سجودٌ."},{"question":"لماذا لم نرفع «القبلة» في «سِيرَ نحوُ القبلةِ»؟","options":["لأنها مضاف إليه مجرور، والنائب هو المضاف «نحو»","لأنها اسم مبني","لأنها فاعل","لأنها مفعول به"],"answer":0,"explanation":"نحوُ: ظرف نائب فاعل مرفوع وهو مضاف، والقبلةِ: مضاف إليه مجرور."}]}]},{"id":"wahi-verse-050","title":"المبتدأ والخبر: بداية الجملة الاسمية","summary":"البيت الخمسون: تعريف المبتدأ والخبر، وكيف تجدهما في أي جملة اسمية.","verse":{"number":50,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"الْمُبْتَدَأ اسْمٌ مَّا أَعْتَرَاهُ عَامِلْ / تُكْمِلُهُ الْأَخْبَارُ، (زَيْدٌ عَاقِلْ)"},"segments":[{"body":["انتهينا من الجملة الفعلية، ونبدأ الجملة الاسمية: جملة تبدأ باسم، مثل: العلمُ نافعٌ.","أول الجملة الاسمية اسمه «المبتدأ»، وهو اسم مرفوع لم يسبقه عامل لفظي، أي: لم يجرّه حرف جر، ولم يعمل فيه فعل قبله، ولم ينصبه ناسخ.","والعوامل اللفظية ثلاثة: الأفعال كلها، والحروف العاملة كحروف الجر وإنَّ وأخواتها، والاسم المضاف.","فإذا وجدت اسمًا لم يسبقه شيء من هذه الثلاثة فهو مبتدأ، ثم ابحث عن خبره.","والخبر: هو الذي نخبر به عن المبتدأ ويُتمّ المعنى. ومثال البيت: «زَيْدٌ عَاقِلْ»: زيد مبتدأ، وعاقل خبر أخبرنا به عن زيد، وكلاهما مرفوع."],"examples":["محمدٌ قائمٌ — محمد: مبتدأ، قائم: خبر.","العلمُ نافعٌ — العلم: مبتدأ، نافع: خبر.","المسلمُ أمينٌ — المسلم: مبتدأ، أمين: خبر.","السماءُ صافيةٌ — السماء: مبتدأ، صافية: خبر.","الطريقُ طويلٌ — الطريق: مبتدأ، طويل: خبر.","زيدٌ عاقلٌ — زيد: مبتدأ، عاقل: خبر؛ كلاهما مرفوع بالضمة."],"questions":[{"question":"المبتدأ هو:","options":["اسم مرفوع لم يسبقه عامل لفظي","اسم منصوب بعد فعل","كل اسم في أول الكلام","اسم مجرور بحرف"],"answer":0,"explanation":"المبتدأ: اسم مرفوع لا عامل لفظي قبله، ويأتي غالبًا أول الجملة الاسمية."},{"question":"الخبر هو:","options":["ما نخبر به عن المبتدأ ويتم به المعنى","أول كلمة في الجملة","الفعل الماضي","حرف النفي"],"answer":0,"explanation":"في «زيدٌ عاقلٌ» أخبرنا عن زيد بأنه عاقل، فعاقل: خبر مرفوع."},{"question":"أي مما يلي من العوامل اللفظية التي تمنع الابتداء؟","options":["الأفعال والحروف العاملة والاسم المضاف","التنوين","الضمائر","أدوات الاستفهام فقط"],"answer":0,"explanation":"ثلاثة: الأفعال كلها، والحروف العاملة كحروف الجر وإنَّ، والاسم المضاف."},{"question":"في «جاءَ محمدٌ» لماذا ليس «محمدٌ» مبتدأ؟","options":["لأنه سبق بفعل فهو فاعل","لأنه معرفة","لأنه مرفوع","لأنه آخر الجملة"],"answer":0,"explanation":"الاسم المسبوق بفعل فاعلٌ له، لا مبتدأ: محمدٌ فاعل مرفوع."},{"question":"حكم المبتدأ والخبر الإعرابي:","options":["الرفع","النصب","الجر","الجزم"],"answer":0,"explanation":"كلاهما مرفوع: زيدٌ مبتدأ مرفوع بالضمة، وعاقلٌ خبر مرفوع بالضمة."}]},{"body":["كيف تجد المبتدأ والخبر بسهولة؟ خطوتان: أولًا ابحث عن اسم لم يسبقه عامل، فإذا وجدته فهو المبتدأ.","ثانيًا اسأل عن هذا الاسم: «أخبر عنه بأنه ماذا؟» فالجواب هو الخبر.","مثال: الكتابُ مفيدٌ. الكتاب: اسم لم يسبقه عامل، فهو مبتدأ. أخبر عن الكتاب بأنه ماذا؟ مفيد. إذًا مفيد: خبر.","تنبيه: قد يكون المبتدأ ضميرًا مبنيًّا مثل: هو قائمٌ، فيكون في محل رفع. وقد يتعدد الخبر: جاري عالمٌ يساعدني.","وقد يتقدم الخبر إذا كان شبه جملة، فيكثر تقديمه على المبتدأ المعرفة، ويجب على النكرة: في البيتِ رجلٌ."],"examples":["الطالبُ مجتهدٌ — مبتدأ وخبر مرفوعان بالضمة.","هذا سيبويهُ — هذا: مبتدأ في محل رفع مبني، سيبويه: خبر في محل رفع.","هو الفائزُ — هو: مبتدأ في محل رفع، الفائز: خبر مرفوع بالضمة.","في البيتِ رجلٌ — في البيت: خبر مقدم في محل رفع، رجل: مبتدأ مؤخر.","جاري عالمٌ يساعدني — عالم: خبر أول، وجملة يساعدني: خبر ثانٍ في محل رفع.","الفائزُ هذا — الفائز: مبتدأ مرفوع بالضمة، هذا: خبر في محل رفع."],"questions":[{"question":"ما طريقة استخراج الخبر بعد إيجاد المبتدأ؟","options":["اسأل: أخبر عن المبتدأ بأنه ماذا؟","انظر إلى آخر الجملة دائمًا","احذف المبتدأ","ابحث عن الفعل"],"answer":0,"explanation":"الجواب عن «بأنه ماذا؟» هو الخبر؛ كقولنا في «الكتاب مفيد»: مفيد."},{"question":"في «هو الفائزُ» المبتدأ هو:","options":["هو: ضمير مبني في محل رفع","الفائز","لا مبتدأ","الجملة ليس فيها مبتدأ"],"answer":0,"explanation":"هو: مبتدأ في محل رفع مبني على الفتح، والفائزُ: خبر مرفوع بالضمة."},{"question":"في «في البيتِ رجلٌ» ترتيب المبتدأ والخبر:","options":["الخبر شبه جملة مقدم، والمبتدأ مؤخر","المبتدأ مقدم والخبر مؤخر","كلاهما محذوف","لا مبتدأ في الجملة"],"answer":0,"explanation":"تقديم الخبر شبه الجملة على المبتدأ النكرة واجب: في البيتِ خبر مقدم، رجلٌ مبتدأ مؤخر."},{"question":"في «جاري عالمٌ يساعدني» جملة «يساعدني» تعرب:","options":["خبر ثانٍ في محل رفع","حال","نعت","لا محل لها"],"answer":0,"explanation":"يجوز تعدد الخبر: عالمٌ خبر أول، والجملة الفعلية خبر ثانٍ في محل رفع."},{"question":"أي جملة مبتدؤها مبني في محل رفع؟","options":["هذا كتابٌ","الكتابُ مفيدٌ","محمدٌ قائمٌ","العلمُ نورٌ"],"answer":0,"explanation":"هذا: اسم إشارة مبني على السكون في محل رفع مبتدأ."}]}]},{"id":"wahi-verse-051","title":"أنواع الخبر: مفرد وجملة وشبه جملة","summary":"البيت الحادي والخمسون: الخبر يأتي اسمًا مفردًا أو جملة أو شبه جملة، وأحكام كل نوع.","verse":{"number":51,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"وَمُفْرَدًا تَأْتِي، وَتَأْتِي جُمْلَةْ / وَشِبْهَهَا، كَـ(زَيْدٌ بَاغٍ رَحْلَةْ)"},"segments":[{"body":["المبتدأ لا يكون إلا اسمًا، أما الخبر فأوسع: يأتي على ثلاثة أنواع.","النوع الأول: خبر مفرد، أي اسم واحد ليس جملة ولا شبه جملة، مثل: العلمُ نافعٌ. ومن المفرد المضاف مثل: القمرُ زينةُ السماءِ.","النوع الثاني: خبر شبه جملة، وهو جار ومجرور أو ظرف، مثل: القمرُ في السماءِ، ومحمدٌ عندَك.","النوع الثالث: خبر جملة؛ جملة فعلية مثل: القمرُ ينيرُ السماءَ، أو جملة اسمية مثل: محمدٌ أخوه ناجحٌ.","ومثال البيت: «زَيْدٌ بَاغٍ رَحْلَةْ» أي: زيد طالبٌ رحلة، فـ«باغٍ» خبر مفرد وهو اسم فاعل من بغى بمعنى طلب، ويعمل عمل فعله فنصب «رحلة» مفعولًا به."],"examples":["خبر مفرد: العلمُ نافعٌ.","خبر مفرد مضاف: القمرُ زينةُ السماءِ.","خبر شبه جملة جار ومجرور: القمرُ في السماءِ.","خبر شبه جملة ظرف: محمدٌ عندَك.","خبر جملة فعلية: القمرُ ينيرُ السماءَ.","خبر جملة اسمية: محمدٌ أخوه ناجحٌ.","زيدٌ باغٍ رحلةً — باغٍ: خبر مفرد عامل عمل فعله، ورحلةً: مفعول به منصوب."],"questions":[{"question":"أنواع الخبر ثلاثة:","options":["مفرد وشبه جملة وجملة","ماضٍ ومضارع وأمر","رفع ونصب وجر","ظاهر ومضمر"],"answer":0,"explanation":"الخبر أوسع من المبتدأ: يكون اسمًا مفردًا أو شبه جملة أو جملة."},{"question":"الخبر في «القمرُ في السماءِ» نوعه:","options":["شبه جملة جار ومجرور","مفرد","جملة فعلية","جملة اسمية"],"answer":0,"explanation":"في السماءِ: جار ومجرور، وهو خبر المبتدأ في محل رفع."},{"question":"الخبر في «محمدٌ أخوه ناجحٌ» نوعه:","options":["جملة اسمية","مفرد","شبه جملة","ظرف"],"answer":0,"explanation":"أخوه مبتدأ ثانٍ وناجح خبره، والجملة الاسمية في محل رفع خبر المبتدأ الأول."},{"question":"في «القمرُ ينيرُ السماءَ» إعراب جملة «ينيرُ السماءَ»:","options":["جملة فعلية في محل رفع خبر","مفعول به","حال","لا محل لها"],"answer":0,"explanation":"الفعل المضارع وفاعله المستتر والمفعول كوّنوا جملة فعلية خبر المبتدأ في محل رفع."},{"question":"في مثال البيت «زيدٌ باغٍ رحلةً» كلمة «رحلةً» تعرب:","options":["مفعول به لاسم الفاعل «باغٍ» منصوب","خبر مقدم","مبتدأ ثانٍ","نعت"],"answer":0,"explanation":"باغٍ اسم فاعل بمعنى طالب يعمل عمل فعله، فنصب رحلةً مفعولًا به."}]},{"body":["مسائل مكملة تفيدك في هذا الباب:","أولًا: يجوز تعدد الخبر، مثل: جاري عالمٌ يساعدني؛ فعالم خبر أول، وجملة يساعدني خبر ثانٍ في محل رفع.","ثانيًا: يجوز تقديم الخبر إذا كان شبه جملة، ويكثر تقديمه على المبتدأ المعرفة، ويجب على النكرة، مثل: في المسجدِ أخي، وفي البيتِ رجلٌ.","ثالثًا: يُحذف المبتدأ كثيرًا في العناوين وما في حكمها، مثل لافتة: «مسجد الإيمان» أي: هذا مسجد الإيمان، ولافتة: «زاد المعاد» أي: هذا زاد المعاد.","وأخيرًا: الجملة الاسمية قد تكون غير منسوخة كما هنا، وقد تدخل عليها نواسخ الابتداء الثلاثة فتغير إعرابها، وهي موضوع الأبيات القادمة."],"examples":["تعدد الخبر: جاري عالمٌ يساعدني.","تقديم الخبر: في المسجدِ أخي — أصلها: أخي في المسجدِ.","وجوب التقديم على النكرة: في البيتِ رجلٌ.","حذف المبتدأ في عنوان: «زاد المعاد» أي: هذا زاد المعاد.","حذف المبتدأ في عنوان: «كتاب الصلاة» أي: هذا كتاب الصلاة.","خبران مفردان: محمدٌ كريمٌ رؤوفٌ."],"questions":[{"question":"في «جاري عالمٌ يساعدني» عدد الأخبار:","options":["خبران: عالم وجملة يساعدني","خبر واحد","ثلاثة أخبار","لا خبر"],"answer":0,"explanation":"عالمٌ: خبر أول مرفوع، وجملة يساعدني: خبر ثانٍ في محل رفع."},{"question":"متى يجب تقديم الخبر على المبتدأ؟","options":["إذا كان الخبر شبه جملة والمبتدأ نكرة","دائمًا","إذا كان المبتدأ ضميرًا","لا يجب أبدًا"],"answer":0,"explanation":"نقول: في البيتِ رجلٌ، ولا نقول: رجلٌ في البيتِ."},{"question":"لافتة «جامعة الإمام» تقديرها:","options":["هذه جامعة الإمام — بحذف المبتدأ","جامعة الإمام كبيرة","لا تقدير لها","هذا جامع الإمام"],"answer":0,"explanation":"يكثر حذف المبتدأ في العناوين وما في حكمها."},{"question":"نواسخ الابتداء التي ستغير إعراب الجملة الاسمية هي:","options":["كان وأخواتها وإنَّ وأخواتها وظننتُ وأخواتها","حروف الجر","حروف العطف","الأسماء الخمسة"],"answer":0,"explanation":"ثلاثة نواسخ تأتي في الأبيات القادمة: كان وإنَّ وظننتُ وأخواتهن."},{"question":"في «في المسجدِ أخي» إعراب «أخي»:","options":["مبتدأ مؤخر مرفوع","خبر مقدم","مفعول به","مضاف إليه"],"answer":0,"explanation":"أخي: مبتدأ مؤخر مرفوع وعلامة رفعه الضمة، والجار والمجرور خبر مقدم في محل رفع."}]}]},{"id":"wahi-verse-052","title":"كان وأخواتها: ترفع الاسم وتنصب الخبر","summary":"البيت الثاني والخمسون: كان وأخواتها تدخل على الجملة الاسمية فترفع الأول وتنصب الثاني.","verse":{"number":52,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"مَرْفُوعَةٌ مَّنْصُوبَةٌ بِـ(كَانَّا) / كَـ(لَيْسَ زَيْدٌ رَّجُلًا جَبَانَا)"},"segments":[{"body":["الجملة الاسمية الأصلية مرفوعة الجزأين: المبتدأ مرفوع والخبر مرفوع، مثل: الجوُّ جميلٌ.","لكن إذا دخلت عليها «كان» أو إحدى أخواتها تغيّر إعرابها: يبقى الأول مرفوعًا ويسمى «اسم كان»، وينصب الثاني ويسمى «خبر كان».","فنقول: كانَ الجوُّ جميلًا. الجوُّ: اسم كان مرفوع، وجميلًا: خبر كان منصوب.","وكان وأخواتها ثلاثة عشر لفظًا: كان، وأصبح، وأضحى، وظلَّ، وأمسى، وباتَ، وصارَ، وليسَ، وما زالَ، وما انفكَّ، وما فتئَ، وما برحَ، وما دامَ.","وهي أفعال ناسخة تفيد تحويل المعنى أو تقييده بزمان أو نفيه؛ وتعرب إعراب الأفعال: ماضية ومضارعة وأمر."],"examples":["كانَ بلالٌ مؤمنًا — بلال: اسم كان مرفوع، مؤمنًا: خبر كان منصوب.","أصبحَ الجوُّ معتدلًا — الجو: اسم أصبح، معتدلًا: خبرها.","ظلَّ الرجلُ متعبًا — الرجل: اسم ظلَّ، متعبًا: خبرها.","صارَ الطينُ حجرًا — الطين: اسم صار، حجرًا: خبرها.","ما زالَ صابرًا — اسمها ضمير مستتر تقديره هو، صابرًا: خبرها.","تصيرُ البناتُ أمهاتٍ — البنات: اسم تصير مرفوع بالضمة، أمهاتٍ: خبرها منصوب بالكسرة."],"questions":[{"question":"عمل كان وأخواتها في الجملة الاسمية:","options":["ترفع المبتدأ وتنصب الخبر","تنصبهما معًا","ترفعهما معًا","تجرهما معًا"],"answer":0,"explanation":"يرتفع المبتدأ ويسمى اسمها، وينصب الخبر ويسمى خبرها: كان الجوُّ جميلًا."},{"question":"عدد ألفاظ كان وأخواتها:","options":["ثلاثة عشر لفظًا","ستة ألفاظ","عشرة ألفاظ","خمسة ألفاظ"],"answer":0,"explanation":"كان وأصبح وأضحى وظل وأمسى وبات وصار وليس وما زال وما انفك وما فتئ وما برح وما دام."},{"question":"في «كانَ بلالٌ مؤمنًا» إعراب «بلالٌ»:","options":["اسم كان مرفوع بالضمة","خبر كان منصوب","فاعل","مبتدأ"],"answer":0,"explanation":"بلالٌ: اسم كان مرفوع وعلامة رفعه الضمة، ومؤمنًا: خبر كان منصوب بالفتحة."},{"question":"أي الألفاظ التالية ليس من أخوات كان؟","options":["إنَّ","أصبحَ","باتَ","ما زالَ"],"answer":0,"explanation":"إنَّ من النواسخ الحرفية التي تنصب الاسم وترفع الخبر، وعملها معكوس عمل كان."},{"question":"في «لَيْسَتِ المسلمةُ متراجعةً» إعراب «متراجعةً»:","options":["خبر ليس منصوب بالفتحة","اسم ليس مرفوع","حال","نعت"],"answer":0,"explanation":"المسلمةُ: اسم ليس مرفوع، ومتراجعةً: خبر ليس منصوب."}]},{"body":["مثال البيت: «لَيْسَ زَيْدٌ رَّجُلًا جَبَانَا» أي: زيد ليس رجلًا جبانًا.","زيدٌ: اسم ليس مرفوع، ورجلًا: خبر ليس منصوب، وجبانًا: نعت لـ«رجلًا» منصوب مثله.","ولاحظ دقة النظم: قال «بِـ(كَانَّا)» جامعًا بين كان وإنَّ؛ لأنهما أشهر الناسختين، وخص في هذا البيت صورة «مرفوعة منصوبة» أي: مرفوعة الأول منصوبة الثاني.","ومن فوائد الباب: اسم كان وأخواتها يجري مجرى الفاعل في أحكامه: يلزم التأخر عن فعله ويعرب بحسب فعله، والخبر يجري مجرى خبر المبتدأ: يكون مفردًا وشبه جملة وجملة.","فتصح: كان الرجلُ مسرورًا، وكان الرجلُ في البيتِ، وكان الرجلُ يركضُ، وكان الرجلُ أخوه كريمٌ... أي: أخوه كريمًا بعد النسخ."],"examples":["ليسَ زيدٌ رجلًا جبانًا — زيد: اسم ليس، رجلًا: خبرها، جبانًا: نعت منصوب.","كانَ الرجلُ مسرورًا — خبر مفرد.","كانَ الرجلُ في البيتِ — خبر شبه جملة.","كانَ الرجلُ يركضُ — خبر جملة فعلية.","كونوا إخوةً — كونوا: فعل أمر ناسخ، وواو الجماعة: اسمها، إخوةً: خبرها منصوب بالكسرة.","لا يزالونَ مختلفينَ — يزالون: مضارع ناسخ مرفوع بثبوت النون، والواو: اسمها، مختلفين: خبرها منصوب بالياء."],"questions":[{"question":"في مثال البيت «ليس زيدٌ رجلًا جبانًا» إعراب «جبانًا»:","options":["نعت لـ«رجلًا» منصوب","خبر ثانٍ","اسم ليس","حال"],"answer":0,"explanation":"جبانًا نعت منصوب يتبع رجلًا خبر ليس في النصب."},{"question":"لماذا قال الناظم «بِـ(كَانَّا)»؟","options":["جمع بين كان وإنَّ أشهر ناسختين","لأن كان أخت إنَّ في اللفظ","لأن معناهما واحد","للقافية فقط"],"answer":0,"explanation":"كان ترفع الاسم وتنصب الخبر، وإنَّ تعكس، وكلتاهما تنسخ الجملة الاسمية."},{"question":"خبر كان يأتي على أنواع:","options":["مفرد وشبه جملة وجملة كخبر المبتدأ","مفرد فقط","جملة فقط","شبه جملة فقط"],"answer":0,"explanation":"الاسم والخبر في باب كان يجريان مجرى المبتدأ والخبر في أنواعهما."},{"question":"في «كونوا إخوةً» إعراب «إخوةً»:","options":["خبر كونوا منصوب بالكسرة","اسم كونوا","مفعول به بالفتحة","نعت"],"answer":0,"explanation":"إخوةً: خبر كونوا منصوب وعلامة نصبه الكسرة؛ لأنه جمع مؤنث سالم."},{"question":"اسم كان يجري مجرى:","options":["الفاعل في أحكامه","المفعول به","الحال","الخبر"],"answer":0,"explanation":"يلزم التأخر عن فعله ويعرب بحسب فعله، مثل: كان الرجلُ مسرورًا."}]}]},{"id":"wahi-verse-053","title":"إنَّ وأخواتها: تعكس عمل كان","summary":"البيت الثالث والخمسون: إنَّ وأخواتها تنصب المبتدأ وترفع الخبر، ومعاني كل حرف منها.","verse":{"number":53,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"مَعْكُوسَةُ الْجَزْأَيْنِ بَعْدَ (إِنَّا) / كَـ(إِنَّ زَيْدًا رَجُلٌ مُعِقًّا)"},"segments":[{"body":["رأينا أن كان ترفع الأول وتنصب الثاني. أما إنَّ وأخواتها فتعكس العمل تمامًا: تنصب المبتدأ ويسمى «اسم إنَّ»، وترفع الخبر ويسمى «خبر إنَّ».","فنقول: العلمُ نافعٌ، فإذا دخلت إنَّ صارت: إنَّ العلمَ نافعٌ. العلمَ: اسم إنَّ منصوب، ونافعٌ: خبر إنَّ مرفوع.","وإنَّ وأخواتها ستة حروف: إنَّ وأنَّ للتوكيد، وكأنَّ للتشبيه، ولكنَّ للاستدراك، وليتَ للتمني، ولعلَّ للترجي.","فالتوكيد تقوية للخبر: إنَّ الصدقَ منجاةٌ. والتشبيه: كأنَّ العلمَ نورٌ. والاستدراك إصلاح ما سبق: الطريقُ طويلٌ ولكنَّه واضحٌ. والتمني طلب المحبوب البعيد: ليتَ الشبابَ عائدٌ. والترجي طمع أو خوف: لعلَّ المطرَ هاطلٌ.","وهي حروف مبنية لا تعرب إعراب الأفعال، بل هي في محلها من الكلام حروف ناسخة لا محل لها من الإعراب."],"examples":["إنَّ اللهَ لكلِّ شيءٍ عليمٌ — اسم الله: اسم إنَّ منصوب.","علمتُ أنَّكَ مجتهدٌ — الكاف: اسم أنَّ في محل نصب.","كأنَّ عليًّا أسدٌ — عليًّا: اسم كأنَّ منصوب، أسدٌ: خبرها مرفوع.","الطريقُ طويلٌ ولكنَّه واضحٌ — الهاء: اسم لكنَّ، واضحٌ: خبرها.","ليتَ الشبابَ عائدٌ — الشبابَ: اسم ليتَ منصوب.","لعلَّ المطرَ هاطلٌ — المطرَ: اسم لعلَّ منصوب، هاطلٌ: خبرها مرفوع."],"questions":[{"question":"عمل إنَّ وأخواتها في الجملة الاسمية:","options":["تنصب المبتدأ وترفع الخبر","ترفع المبتدأ وتنصب الخبر","تنصبهما معًا","ترفعهما معًا"],"answer":0,"explanation":"عملها معكوس عمل كان: إنَّ العلمَ نافعٌ — العلمَ اسمها منصوب، نافعٌ خبرها مرفوع."},{"question":"عدد حروف إنَّ وأخواتها وأسماؤها:","options":["ستة: إنَّ وأنَّ وكأنَّ ولكنَّ وليتَ ولعلَّ","ثلاثة عشر","أربعة","خمسة"],"answer":0,"explanation":"ستة حروف ناسخة لكل منها معنى: توكيد أو تشبيه أو استدراك أو تمنٍّ أو ترجٍّ."},{"question":"معنى «ليتَ» في «ليتَ الشبابَ عائدٌ»:","options":["التمني: طلب المحبوب البعيد أو المستحيل","التوكيد","الترجي","الاستدراك"],"answer":0,"explanation":"ليتَ حرف تمنٍّ، والتمني: طلب المستحيل أو الصعب."},{"question":"معنى «لعلَّ» في «لعلَّ العدوَّ قريبٌ»:","options":["الترجي، وهو هنا في المخوف","التشبيه","التمني","النفي"],"answer":0,"explanation":"لعلَّ للترجي: يكون في المحبوب طمعًا وفي المكروه خوفًا."},{"question":"في «إنَّ نورًا جميلةٌ» إعراب «جميلةٌ»:","options":["خبر إنَّ مرفوع بالضمة","اسم إنَّ منصوب","نعت منصوب","خبر كان"],"answer":0,"explanation":"نورًا: اسم إنَّ منصوب بالفتحة، وجميلةٌ: خبر إنَّ مرفوع بالضمة."}]},{"body":["مثال البيت: «إِنَّ زَيْدًا رَجُلٌ مُعِقًّا» أي: إن زيدًا رجل فطن حاذق.","زيدًا: اسم إنَّ منصوب، ورجلٌ: خبر إنَّ مرفوع، ومُعِقًّا: نعت لـ«رجلٍ» مرفوع مثله. ومُعِقّ: الفطِن الحاذق.","ولاحظ وصف الناظم للجملة بأنها «معكوسة الجزأين»: أي إن إعرابها مقلوب بالنسبة إلى باب كان: هناك الأول مرفوع والثاني منصوب، وهنا الأول منصوب والثاني مرفوع.","وإعراب هذه الحروف ثابت: حرف توكيد أو تشبيه أو استدراك أو تمنٍّ أو ترجٍّ ينصب اسمه ويرفع خبره، مبني على الفتح، لا محل له من الإعراب.","واسم إنَّ قد يكون ضميرًا مبنيًّا في محل نصب، مثل: إنِّي مجتهدٌ، وإنَّه مجتهدٌ، وإنَّك مجتهدٌ."],"examples":["إنَّ زيدًا رجلٌ معقًّا — زيدًا: اسم إنَّ، رجلٌ: خبرها، معقًّا: نعت مرفوع.","إنِّي مجتهدٌ — الياء: اسم إنَّ في محل نصب.","كأنَّها بدرٌ — الهاء: اسم كأنَّ في محل نصب، بدرٌ: خبرها مرفوع.","ليتَ الصيفَ بارٌّ — الصيفَ: اسم ليتَ منصوب.","إنَّ الشمسَ والقمرَ آيتانِ — اسم إنَّ ومعطوف منصوبان.","إنَّ الخطَّينِ مستقيمانِ — الخطين: اسم إنَّ منصوب بالياء، مستقيمان: خبرها مرفوع بالألف."],"questions":[{"question":"معنى «مُعِقًّا» في مثال البيت:","options":["فطنًا حاذقًا","ضعيفًا","غنيًّا","صامتًا"],"answer":0,"explanation":"المُعِقّ: الفطن الحاذق، وهو نعت لـ«رجلٍ» مرفوع بالضمة."},{"question":"لماذا وصف الناظم الجملة بأنها «معكوسة الجزأين»؟","options":["لأن إعرابها مقلوب عن باب كان: الأول منصوب والثاني مرفوع","لأن كلماتها مقلوبة الترتيب","لأن معناها معكوس","لأنها منسوخة مرتين"],"answer":0,"explanation":"كان: مرفوعة الأول منصوبة الثاني؛ وإنَّ: منصوبة الأول مرفوعة الثاني."},{"question":"إعراب «إنَّ» نفسها:","options":["حرف توكيد مبني على الفتح لا محل له من الإعراب","فعل ماضٍ","حرف جر","اسم مرفوع"],"answer":0,"explanation":"إنَّ حرف ناسخ مبني، ينصب اسمه ويرفع خبره."},{"question":"في «إنَّك مجتهدٌ» إعراب الكاف:","options":["ضمير مبني في محل نصب اسم إنَّ","فاعل","مضاف إليه","خبر إنَّ"],"answer":0,"explanation":"الكاف ضمير بارز متصل مبني على الفتح في محل نصب اسم إنَّ."},{"question":"في «إنَّ الخطين مستقيمان» علامة نصب «الخطين»:","options":["الياء لأنه مثنى","الفتحة","الكسرة","الألف"],"answer":0,"explanation":"الخطينِ: اسم إنَّ منصوب وعلامة نصبه الياء؛ لأنه مثنى."}]}]},{"id":"wahi-verse-054","title":"لا النافية للجنس: نفي على وجه العموم","summary":"البيت الرابع والخمسون: لا النافية للجنس تعمل عمل إنَّ بشروط، وتنفي الجنس كله.","verse":{"number":54,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"وَمِثْلُ (إِنَّ) (لَا) لِنَفْيِ الْجِنْسِ / كَـ(لَا نَجَاحَ مُمْكِنٌ فِي الْيَأْسِ)"},"segments":[{"body":["«لا» حروفها كثيرة، أشهرها: لا النافية العادية مثل: ما زيدٌ جالسٌ... أي لَا زيدٌ جالسٌ، ولا النافية للجنس موضوع بيتنا.","لا النافية للجنس تنفي الحكم عن الجنس كله نفيًا عامًّا: لا رجلَ في الدارِ أي: لا يوجد رجل واحد أصلًا.","وهي تعمل عمل إنَّ: تنصب اسمها وترفع خبرها، لكن بشروط أربعة: أن يكون اسمها وخبرها نكرتين، وأن تتصل باسمها، وألا تُسبق بحرف جر، وألا تتكرر.","فإذا تحققت الشروط نصبت الاسم بلا تنوين في الغالب: لا رجلَ في الدارِ، ولا طلابَ في الفصلِ.","ومثال البيت: «لَا نَجَاحَ مُمْكِنٌ فِي الْيَأْسِ» أي: مع اليأس لا يمكن نجاح أبدًا؛ نجاحَ: اسم لا منصوب، وممكنٌ: خبرها مرفوع، وفي اليأس متعلق بممكن."],"examples":["لا رجلَ في الدارِ — رجلَ: اسم لا منصوب، في الدار: خبرها.","لا طلابَ في الفصلِ — طلابَ: اسم لا منصوب.","لا كريمَ مذمومٌ — كريمَ: اسم لا منصوب، مذمومٌ: خبرها مرفوع.","لا متوازيينِ متقاطعانِ — متوازيين: اسم لا منصوب بالياء، متقاطعان: خبرها مرفوع بالألف.","لا طالباتِ مهملاتٌ — طالباتِ: اسم لا منصوب بالكسرة، مهملاتٌ: خبرها مرفوع بالضمة.","لا نجاحَ ممكنٌ في اليأسِ — نجاحَ: اسم لا منصوب، ممكنٌ: خبرها مرفوع."],"questions":[{"question":"لا النافية للجنس تعمل عمل:","options":["إنَّ: تنصب الاسم وترفع الخبر","كان: ترفع الاسم وتنصب الخبر","حروف الجر","لا تعمل شيئًا"],"answer":0,"explanation":"تنصب اسمها وترفع خبرها إذا تحققت شروطها: لا رجلَ في الدارِ."},{"question":"فائدة لا النافية للجنس:","options":["نفي الحكم عن الجنس كله على العموم","نفي حادثة واحدة","التوكيد","التمني"],"answer":0,"explanation":"لا نجاحَ في اليأس: أي لا يوجد نجاح واحد ممكن مع اليأس."},{"question":"من شروط عمل لا النافية للجنس:","options":["أن يكون اسمها وخبرها نكرتين وأن تتصل باسمها","أن يكون اسمها معرفة","أن تتكرر مرتين","أن يسبقها حرف جر"],"answer":0,"explanation":"أربعة شروط: نكرتان، واتصال، وعدم التسبق بحرف جر، وعدم التكرار."},{"question":"في «لا نجاحَ ممكنٌ في اليأسِ» إعراب «ممكنٌ»:","options":["خبر لا النافية للجنس مرفوع بالضمة","اسم لا منصوب","نعت منصوب","حال"],"answer":0,"explanation":"نجاحَ: اسم لا منصوب بالفتحة، وممكنٌ: خبرها مرفوع بالضمة."},{"question":"في «لا طالباتِ مهملاتٌ» علامة نصب «طالباتِ»:","options":["الكسرة لأنه جمع مؤنث سالم","الفتحة","الياء","الضمة"],"answer":0,"explanation":"يجوز في جمع المؤنث السالم اسم لا النصب بالكسرة وبالفتحة."}]},{"body":["متى يبطل عمل لا النافية للجنس؟ في ثلاثة أحوال:","الحال الأولى: إذا كان اسمها معرفة أو انفصلت عنه، بطل عملها ووجب تكرارها، مثل: لا خالدٌ في البيتِ ولا فهدٌ، ولا في البيتِ رجلٌ ولا امرأةٌ.","الحال الثانية: إذا سُبقت بحرف جر بطل عملها وأجرّت ما بعدها، مثل: جئتُ بلا زادٍ، وغضبتُ من لا شيءَ.","الحال الثالثة: إذا تكررت جاز إعمالها وإهمالها، مثل: لا حولَ ولا قوةَ إلا بالله، ويجوز: لا حولَ ولا قوةٌ إلا بالله.","فاحفظ: عملها نصب الاسم ورفع الخبر بشروط، وبطلانها يردها إلى نفي عادي بلا عمل.","وخير ما تختم به: قولنا جميعًا كل يوم: لا إلهَ إلا الله؛ فإلهَ اسم لا النافية للجنس منصوب، وخبرها محذوف تقديره: موجودٌ أو حقٌّ."],"examples":["بطل العمل بالمعرفة: لا خالدٌ في البيتِ ولا فهدٌ — وجب التكرار.","بطل العمل بالانفصال: لا في البيتِ رجلٌ ولا امرأةٌ.","بطل العمل بحرف الجر: جئتُ بلا زادٍ — زادٍ: مجرور بالباء.","التكرار يجيز الوجهين: لا حولَ ولا قوةَ إلا بالله / لا حولَ ولا قوةٌ.","لا مؤمنينَ كذابونَ — مؤمنين: اسم لا منصوب بالياء، كذابون: خبرها مرفوع بالواو.","لا إلهَ إلا الله — إلهَ: اسم لا منصوب، وخبرها محذوف."],"questions":[{"question":"متى يجب تكرار لا النافية للجنس؟","options":["إذا كان اسمها معرفة أو انفصلت عنه","إذا كان اسمها نكرة","إذا اتصلت باسمها","إذا جاءت أول الكلام"],"answer":0,"explanation":"نقول: لا خالدٌ في البيتِ ولا فهدٌ؛ لأن خالدًا معرفة بطل العمل ووجب التكرار."},{"question":"في «جئتُ بلا زادٍ» لماذا جرّت «زادٍ»؟","options":["لأن لا سبقت بحرف جر فبطل عملها","لأن زادًا ممنوع من الصرف","لأنها خبر","لأنها مفعول به"],"answer":0,"explanation":"إذا سبقت لا بحرف جر بطل عملها وأجرّت ما بعدها حرف الجر."},{"question":"إذا تكررت لا النافية للجنس:","options":["جاز إعمالها وإهمالها","وجب إعمالها","وجب إهمالها","بطلت الجملة"],"answer":0,"explanation":"يجوز: لا حولَ ولا قوةَ، ويجوز: لا حولَ ولا قوةٌ إلا بالله."},{"question":"في «لا إلهَ إلا الله» خبر لا النافية للجنس:","options":["محذوف تقديره موجودٌ أو حقٌّ","إلا الله","إلهَ","لا خبر لها"],"answer":0,"explanation":"إلهَ: اسم لا منصوب، وخبرها محذوف تقديره: لا إلهَ حقٌّ إلا الله."},{"question":"في «لا مؤمنينَ كذابونَ» إعراب «كذابونَ»:","options":["خبر لا مرفوع وعلامة رفعه الواو","اسم لا منصوب","نعت منصوب","فاعل"],"answer":0,"explanation":"مؤمنينَ: اسم لا منصوب بالياء، وكذابونَ: خبرها مرفوع بالواو؛ لأنه جمع مذكر سالم."}]}]},{"id":"wahi-verse-055","title":"ظننتُ وأخواتها: تنصب المبتدأ والخبر معًا","summary":"البيت الخامس والخمسون: ظننتُ وأخواتها تنصب الجزأين: المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا.","verse":{"number":55,"section":"المبتدأ والخبر ونواسخ الابتداء","text":"مَنْصُوبَةُ الْجَزْأَيْنِ بَعْدَ (ظَنَّا) / كَـ(خَالَ زَيْدٌ عَامِرًا مُسِنًّا)"},"segments":[{"body":["الناسخ الثالث: ظننتُ وأخواتها، وهي أفعال تنصب المبتدأ والخبر معًا: الأول مفعول به أول، والثاني مفعول به ثانٍ.","فبدل: معاذٌ مسافرٌ، نقول: ظنَّ قيسٌ معاذًا مسافرًا. معاذًا: مفعول به أول منصوب، ومسافرًا: مفعول به ثانٍ منصوب.","وألفاظها كثيرة بمعنى (ظنَّ): حسبَ وخالَ، وبمعناها: علمَ، وبمعنى علم: رأى ووجد وألفى، وبمعنى (صيّر): صيّر، وبمعنى صيّر: جعل واتخذ.","ومثال البيت: «خَالَ زَيْدٌ عَامِرًا مُسِنًّا» أي: ظن زيد أن عامر شيخ كبير؛ خالَ بمعنى ظنَّ، وزيدٌ: فاعل، وعامرًا: مفعول أول، ومسنًّا: مفعول ثانٍ.","وهذه الأفعال لا تعمل إلا بعد توفر فاعلها، لأنها أفعال تصرف واعتقاد تصدر من شخص."],"examples":["ظنَّ قيسٌ معاذًا مسافرًا — معاذًا: مفعول أول، مسافرًا: مفعول ثانٍ.","حسبتُك صديقًا — الكاف: مفعول أول في محل نصب، صديقًا: مفعول ثانٍ.","خالَ المهملُ النجاحَ بعيدًا — النجاحَ: مفعول أول، بعيدًا: مفعول ثانٍ.","يعلمُ المسلمُ الصدقَ منجيًا — الصدقَ: مفعول أول، منجيًا: مفعول ثانٍ.","رأيتُ العلمَ نافعًا — العلمَ: مفعول أول، نافعًا: مفعول ثانٍ.","اتخذَ اللهُ إبراهيمَ خليلًا — إبراهيمَ: مفعول أول، خليلًا: مفعول ثانٍ."],"questions":[{"question":"عمل ظننتُ وأخواتها في الجملة الاسمية:","options":["تنصب المبتدأ مفعولًا أول والخبر مفعولًا ثانيًا","ترفع الجزأين","تنصب الخبر فقط","ترفع الخبر وتنصب الاسم"],"answer":0,"explanation":"ظنَّ قيسٌ معاذًا مسافرًا: الجزءان منصوبان مفعولان."},{"question":"معنى «خالَ» في مثال البيت:","options":["ظنَّ","رأى بعينه","خلق","ترك"],"answer":0,"explanation":"خالَ بمعنى ظنَّ: خال زيدٌ عامرًا مسنًّا أي ظنه شيخًا كبيرًا."},{"question":"أي فعل مما يلي بمعنى (صيّر)؟","options":["جعلَ","ظنَّ","حسبَ","خالَ"],"answer":0,"explanation":"جعل واتخذ بمعنى صيّر: جعلَ الصلصالَ تينًا."},{"question":"في «حسبتُك صديقًا» إعراب الكاف:","options":["مفعول به أول في محل نصب","فاعل","مضاف إليه","مفعول ثانٍ"],"answer":0,"explanation":"الكاف: كاف المخاطب مفعول به أول في محل نصب مبني على الفتح."},{"question":"في «خال زيدٌ عامرًا مسنًّا» إعراب «مسنًّا»:","options":["مفعول به ثانٍ منصوب بالفتحة","مفعول أول","فاعل","نعت للفاعل"],"answer":0,"explanation":"عامرًا: مفعول أول، ومسنًّا: مفعول ثانٍ منصوب وعلامة نصبه الفتحة."}]},{"body":["قاعدة لطيفة في هذا الباب: يجوز أن تسد (أنَّ) ومعمولاها — أي اسمها وخبرها — مسد المفعولين الأول والثاني معًا.","فبدل: ظننتُ معاذًا مسافرًا، تقول: ظننتُ أنَّ معاذٌ مسافرٌ، وتعرب: أنَّ ومعمولاها سدّت مسد المفعولين.","وكذلك: علمَ الطالبُ أنَّ العلمَ نافعٌ.","وهذا يفيدك في الفهم: فمعنى الجملتين واحد، لكن الصورة الأولى نصبت اسمين، والثانية جاءت بجملة كاملة بعد أنَّ.","ولإعراب هذه الأفعال: تعرب إعراب الأفعال ماضية ومضارعة وأمرًا، ويزاد أنها تنصب مفعولين، مثل: صيِّرِ الصلصالَ تينًا: فعل أمر ينصب مفعولين."],"examples":["ظننتُ أنَّ معاذًا مسافرٌ — أنَّ ومعمولاها سدت مسد المفعولين.","علمَ الطالبُ أنَّ العلمَ نافعٌ — المصدر المؤول سد مسد المفعولين.","ألفيتُه حائرًا — النون حرف وقاية، والياء: مفعول أول في محل نصب، حائرًا: مفعول ثانٍ.","صيِّرِ الصلصالَ تينًا — فعل أمر ناسخ، الصلصالَ: مفعول أول، تينًا: مفعول ثانٍ.","السواكُ يجعلُ فاكَ نظيفًا — فاكَ: مفعول أول منصوب بالألف (من الأسماء الخمسة)، نظيفًا: مفعول ثانٍ.","أعدَّ المؤمنُ الصلاحَ سرَّ النجاحِ — الصلاحَ: مفعول أول، سرَّ: مفعول ثانٍ."],"questions":[{"question":"ما الذي يسد مسد المفعولين في «ظننتُ أنَّ معاذًا مسافرٌ»؟","options":["أنَّ ومعمولاها: اسمها وخبرها","أنَّ وحدها","الفعل ظننت","الفاعل"],"answer":0,"explanation":"نقول في الإعراب: أنَّ ومعمولاها سدت مسد المفعولين الأول والثاني."},{"question":"في «ألفيتُه حائرًا» المفعول الأول هو:","options":["الياء: ياء المتكلم في محل نصب","حائرًا","النون","التاء"],"answer":0,"explanation":"التاء: فاعل، والنون: حرف وقاية، والياء: مفعول أول، وحائرًا: مفعول ثانٍ."},{"question":"إعراب «صيِّرْ» في «صيِّرِ الصلصالَ تينًا»:","options":["فعل أمر ينصب مفعولين مبني على السكون","فعل ماضٍ","فعل مضارع مرفوع","حرف"],"answer":0,"explanation":"صيِّرْ: فعل أمر ناسخ مبني، فاعله مستتر تقديره أنت."},{"question":"في «يجعلُ فاكَ نظيفًا» علامة نصب «فاكَ»:","options":["الألف لأنه من الأسماء الخمسة","الفتحة","الياء","الكسرة"],"answer":0,"explanation":"فاكَ: مفعول به أول منصوب وعلامة نصبه الألف؛ لأنه من الأسماء الخمسة."},{"question":"جملة «علم الطالب أنَّ العلم نافع» بصورة المفعولين:","options":["علمَ الطالبُ العلمَ نافعًا","علمَ الطالبُ أنَّ العلمَ نافعٌ","الطالبُ علمَ العلمَ","علمَ العلمُ الطالبَ"],"answer":0,"explanation":"العلمَ: مفعول أول منصوب، ونافعًا: مفعول ثانٍ منصوب."}]}]},{"id":"wahi-verse-056","title":"المكملات المنصوبات: مدخل إلى المفاعيل","summary":"البيت السادس والخمسون: ما زاد على أركان الجملة مكملات، والمفاعيل كلها منصوبة.","verse":{"number":56,"section":"المكملات المنصوبة: المفاعيل","text":"كُلُّ الْمَفَاعِيلِ إِذَا فَهِمْتَهَا / مَنْصُوبَةٌ بِالْفِعْلِ قَدْ وَجَدْتَهَا"},"segments":[{"body":["الجملة الفعلية لها ركنان: الفعل ومرفوعه (فاعل أو نائب فاعل)، والجملة الاسمية لها ركنان: المبتدأ والخبر.","فما زاد على هذه الأركان من أسماء تُتمم المعنى يسمى «مكملات»، وهي ثلاثة أضرب: منصوبات، ومجرورات، وتوابع.","الضرب الأول: المكملات المنصوبات، وهي: المفاعيل الخمسة، والحال، والنعت، والمستثنى، والمنادى.","والمفاعيل الخمسة: المفعول به، والمفعول فيه، والمفعول له، والمفعول معه، والمفعول المطلق.","ويقول الناظم: «كلُّ المفاعيلِ إذا فهمتَها منصوبةٌ بالفعلِ قد وجدتَها» أي: حكمها كلها النصب؛ فإن كانت معربة فهي منصوبة بعلامة، وإن كانت مبنية فهي في محل نصب، ونسبتها إلى الفعل لأنها تتمم معناه."],"examples":["أركان فعلية: كتبَ المعلمُ — فعل وفاعل.","أركان اسمية: العلمُ نافعٌ — مبتدأ وخبر.","مكمل منصوب: قرأتُ الكتابَ — الكتابَ: مفعول به.","مكمل مجرور: ذهبتُ إلى المدرسةِ — إلى المدرسة: جار ومجرور.","مكمل تابع: جاءَ زيدٌ العالمُ — العالمُ: نعت تابع.","المفاعيل الخمسة كلها منصوبة أو في محل نصب."],"questions":[{"question":"المكملات هي:","options":["ما زاد على أركان الجملة من متممات المعنى","أركان الجملة نفسها","حروف الجر فقط","الضمائر"],"answer":0,"explanation":"الأركان: الفعل والفاعل، والمبتدأ والخبر؛ وما سواها مكملات."},{"question":"أضرب المكملات ثلاثة:","options":["منصوبات ومجرورات وتوابع","رفع ونصب وجر","فعل واسم وحرف","ماضٍ ومضارع وأمر"],"answer":0,"explanation":"منصوبات كالمفاعيل، ومجرورات بالحرف والإضافة، وتوابع كالنعت والعطف."},{"question":"المفاعيل الخمسة هي:","options":["به وفيه وله ومعه والمطلق","الفاعل ونائبه والمبتدأ والخبر والحال","النعت والعطف والتوكيد والبدل والحال","الماضي والمضارع والأمر والنهي والمصدر"],"answer":0,"explanation":"المفعول به والمفعول فيه والمفعول له والمفعول معه والمفعول المطلق."},{"question":"حكم المفاعيل كلها:","options":["النصب أو محل النصب","الرفع","الجر","الجزم"],"answer":0,"explanation":"كل المفاعيل منصوبة بالفعل: معربة منصوبة بعلامة أو مبنية في محل نصب."},{"question":"أي مما يلي من المكملات المنصوبات غير المفاعيل؟","options":["الحال والنعت والمستثنى والمنادى","المجرور بالحرف","المضاف إليه","المعطوف"],"answer":0,"explanation":"المنصوبات: المفاعيل الخمسة والحال والنعت والمستثنى والمنادى."}]},{"body":["لماذا سميت مكملات؟ لأن الجملة تمّت بأركانها، ثم جاءت هذه الزيادات تكمل معناها وتزيده بيانًا.","مثال: كتبَ المعلمُ. جملة تامة. ثم نزيد: كتبَ المعلمُ الدرسَ مساءً إرضاءً للطلابِ معَ زميلِه كتابةً واضحةً؛ كل زيادة مكمل منصوب: الدرسَ مفعول به، ومساءً مفعول فيه، وإرضاءً مفعول له، ومعَ زميله مفعول معه، وكتابةً مفعول مطلق.","وقد جمع الشبراوي المفاعيل الخمسة في بيت مشهور بأمثلتها: شرَّمتْ ضربًا عمرًا إذ أتتْ ونحن واليلُ خوفًا من عتابك لي.","وسندرس كل مفعول منها في بيت أو بيتين قادمين: تعريفه وضابطه وأمثلته.","فتذكر القاعدة الجامعة: إذا رأيت اسمًا زائدًا على الأركان يتصل بالفعل ويتمم معناه فهو غالبًا من المكملات المنصوبات."],"examples":["كتبَ المعلمُ الدرسَ — مفعول به.","كتبَ المعلمُ مساءً — مفعول فيه (ظرف زمان).","كتبَ إرضاءً للطلابِ — مفعول له.","كتبَ معَ زميلِه — مفعول معه.","كتبَ كتابةً واضحةً — مفعول مطلق.","بيت الشبراوي الجامع: شرَّمتْ ضربًا عمرًا إذ أتتْ ونحن واليلُ خوفًا من عتابك لي."],"questions":[{"question":"لماذا سميت المكملات بهذا الاسم؟","options":["لأنها تكمل معنى الجملة بعد تمامها بأركانها","لأنها تكمل حروف الكلمة","لأنها أركان أصلية","لأنها آخر الكتاب"],"answer":0,"explanation":"الجملة تتم بركنيها ثم تأتي المكملات تزيد المعنى بيانًا."},{"question":"في «كتبَ المعلمُ مساءً» كلمة «مساءً» تعرب:","options":["مفعول فيه منصوب","مفعول به","فاعل","مفعول له"],"answer":0,"explanation":"مساءً ظرف زمان منصوب، وهو المفعول فيه."},{"question":"في «كتبَ إرضاءً للطلابِ» كلمة «إرضاءً» تعرب:","options":["مفعول له منصوب","مفعول به","حال","مفعول مطلق"],"answer":0,"explanation":"إرضاءً مصدر يبين سبب الكتابة، فهو مفعول لأجله منصوب."},{"question":"في «كتبَ كتابةً واضحةً» كلمة «كتابةً» تعرب:","options":["مفعول مطلق منصوب","مفعول به","مفعول فيه","نعت فقط"],"answer":0,"explanation":"كتابةً مصدر من جنس الفعل يؤكده: مفعول مطلق منصوب بالفتحة."},{"question":"أي مكمل يدل على المصاحبة؟","options":["المفعول معه","المفعول به","المفعول له","المفعول المطلق"],"answer":0,"explanation":"المفعول معه: اسم منصوب بعد واو بمعنى مع، مثل: سرتُ والنيلَ."}]}]},{"id":"wahi-verse-057","title":"المفعول به: على ماذا وقع الفعل؟","summary":"البيت السابع والخمسون: تعريف المفعول به وضابطه، وأنه اسم منصوب وقع عليه الفعل.","verse":{"number":57,"section":"المكملات المنصوبة: المفاعيل","text":"فَوَاقِعُ عَلَيْهِ مَفْعُولٌ بِهِ / كَـ(أَنْصُرْ أَخَاكَ وَاهْدِهْ فِي كَرْبِهْ)"},"segments":[{"body":["أول المفاعيل وأشهرها: المفعول به، وهو اسم منصوب يبين من وقع عليه الفعل.","تقول: فتحَ الحارسُ البابَ. الفتح حدث، فاعله الحارس، والذي وقع عليه الفتح هو الباب؛ فالبابَ: مفعول به منصوب.","والضابط الذهبي: اسأل بعد الفعل والفاعل: على ماذا وقع الفعل؟ فالجواب هو المفعول به.","وضابط آخر أن تسأل: من الفاعل وما المفعول؟ فتقول في «يقرأ أخي القرآنَ»: من القارئ؟ أخي. وما المقروء؟ القرآن.","ومثال البيت: «أَنْصُرْ أَخَاكَ وَاهْدِهْ فِي كَرْبِهْ» أي: انصر أخاك واهده في كربه؛ أخاكَ: مفعول به منصوب بالفتحة، والهاء في «اهدِهْ»: مفعول به ثانٍ في محل نصب."],"examples":["قرأتُ الكتابَ — الكتابَ: مفعول به؛ وقعت عليه القراءة.","فتحَ الحارسُ البابَ — البابَ: مفعول به.","يحفظُني اللهُ — ياء المتكلم: مفعول به في محل نصب مقدم.","أكرمتُكَ — الكاف: مفعول به في محل نصب.","أحبُّ نورًا — نورًا: مفعول به منصوب بالفتحة.","انصرْ أخاكَ — أخاكَ: مفعول به منصوب، والكاف: مضاف إليه."],"questions":[{"question":"المفعول به هو:","options":["اسم منصوب يبين من وقع عليه الفعل","اسم مرفوع فاعل للفعل","اسم مجرور بحرف","ظرف زمان"],"answer":0,"explanation":"قرأتُ الكتابَ: الكتاب وقعت عليه القراءة فهو مفعول به منصوب."},{"question":"ما ضابط المفعول به؟","options":["أن تسأل: على ماذا وقع الفعل؟","أن تسأل: من الذي فعل؟","أن تسأل: متى وقع الفعل؟","أن تسأل: لماذا وقع الفعل؟"],"answer":0,"explanation":"على ماذا وقع الفعل؟ فالجواب مفعول به: على الكتاب، على الباب، على الدرس."},{"question":"في «يحفظُني اللهُ» إعراب «ني»:","options":["ياء متكلم مفعول به مقدم في محل نصب","فاعل","مضاف إليه","نعت"],"answer":0,"explanation":"الياء: مفعول به في محل نصب مبني على السكون، واسم الله: فاعل مرفوع."},{"question":"في «يأكلُ التفاحةَ الولدُ» إعراب «التفاحةَ» و«الولدُ»:","options":["التفاحة: مفعول به مقدم، والولد: فاعل مؤخر","التفاحة: فاعل، والولد: مفعول","كلاهما فاعل","كلاهما مفعول"],"answer":0,"explanation":"يجوز تقديم المفعول على الفاعل: التفاحةَ منصوبة، والولدُ مرفوع."},{"question":"في مثال البيت «واهدِهْ في كربه» الهاء في «اهدِهْ» تعرب:","options":["مفعول به في محل نصب مبني على الضم","فاعل","مضاف إليه","حرف"],"answer":0,"explanation":"اهدِهْ: اهدِ فعل أمر، والهاء ضمير مفعول به في محل نصب."}]},{"body":["حكم المفعول به: النصب أبدًا؛ فإن كان معربًا فهو منصوب بعلامته، وإن كان ضميرًا مبنيًّا فهو في محل نصب.","فنقول: نصرَ اللهُ المسلمينَ — المسلمين: مفعول به منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم.","ونقول: أكرمتُ محمدًا — محمدًا: مفعول به منصوب بالفتحة. وأكرمتُكَ — الكاف: مفعول به في محل نصب مبني على الفتح.","ومن فوائد الباب ضبط ضمائر (هَيْكَ): ياء المتكلم وكاف المخاطب وهاء الغائب؛ فإذا اتصلت بفعل كانت مفعولًا به: أكرمني، يعرفك، أكرمه.","وإياك وأخواتها ضمائر نصب منفصلة لا تكون إلا مفعولًا به غالبًا، مثل: إياكَ نعبدُ — مفعول به مقدم."],"examples":["نصرَ اللهُ المسلمينَ — المسلمين: مفعول به منصوب بالياء.","انصرْ أخاكَ — أخاكَ: مفعول به منصوب بالفتحة.","أكرمتُكَ — الكاف: مفعول به في محل نصب.","يعرفُكَ المعلمُ — الكاف: مفعول به مقدم في محل نصب.","إياكَ نعبدُ وإياكَ نستعينُ — إياك: مفعول به مقدم منصوب.","أحبُّ زيدًا — زيدًا: مفعول به منصوب بالفتحة."],"questions":[{"question":"حكم المفعول به الإعرابي:","options":["النصب دائمًا","الرفع دائمًا","الجر دائمًا","الجزم"],"answer":0,"explanation":"المفعول به منصوب أو في محل نصب إن كان مبنيًّا."},{"question":"في «نصرَ اللهُ المسلمينَ» علامة نصب «المسلمينَ»:","options":["الياء لأنه جمع مذكر سالم","الفتحة","الكسرة","الضمة"],"answer":0,"explanation":"المسلمينَ: مفعول به منصوب وعلامة نصبه الياء."},{"question":"ضمائر (هَيْكَ) إذا اتصلت بفعل أعربت:","options":["مفعولًا به في محل نصب","فاعلًا","مضافًا إليه","خبرًا"],"answer":0,"explanation":"ياء المتكلم وكاف المخاطب وهاء الغائب تكون مفعولًا به مع الفعل: أكرمني وأكرمك وأكرمه."},{"question":"في «إياكَ نعبدُ» إعراب «إياكَ»:","options":["مفعول به مقدم منصوب","فاعل","مبتدأ","نعت"],"answer":0,"explanation":"إياك: ضمير نصب منفصل مفعول به مقدم، والأصل: نعبدُ إياك."},{"question":"أي جملة فيها مفعول به ضمير متصل؟","options":["يعرفُكَ المعلمُ","المعلمُ يعرفُ الدرسَ","كتبتُ الدرسَ","الدرسُ مكتوبٌ"],"answer":0,"explanation":"الكاف في يعرفك: ضمير متصل مفعول به في محل نصب مبني على الفتح."}]}]},{"id":"wahi-verse-058","title":"المفعول فيه: ظرف الزمان وظرف المكان","summary":"البيت الثامن والخمسون: المفعول فيه اسم يدل على زمان الفعل أو مكانه ويكون بمعنى (في).","verse":{"number":58,"section":"المكملات المنصوبة: المفاعيل","text":"وَوَاقِعٌ فِيهِ هُوَ الْمَفْعُولُ فِيهْ / فِيهِ الزَّمَانِ وَالْمَكَانِ تَحْتَوِيهْ"},"segments":[{"body":["المفعول الثاني: المفعول فيه، وهو اسم منصوب يدل على زمان الفعل أو مكانه، ويأتي بمعنى (في).","فإذا دل على الزمان سمي ظرف زمان، مثل: لقيتُ فهدًا صباحًا أي: في صباح.","وإذا دل على المكان سمي ظرف مكان، مثل: لقيتُ فهدًا أمامَ المسجدِ أي: في المكان الذي هو أمام المسجد.","وعلامته السهلة: جرّب أن تضع (في) قبله؛ فإن استقام المعنى فهو مفعول فيه.","ويقول الناظم: «فيهِ الزمانِ والمكانِ تحتويهْ» أي: هذا الباب يحتوي النوعين: ظرف الزمان وظرف المكان."],"examples":["ظرف زمان: لقيتُ فهدًا صباحًا — أي: في صباح.","ظرف زمان: سأزورُكَ غدًا — أي: في الغد.","ظرف مكان: لقيتُ فهدًا أمامَ المسجدِ.","ظرف مكان: جلستُ تحتَ الشجرةِ.","ظرف مكان: صليتُ خلفَ الإمامِ.","ظرف زمان: صامَ المسلمونَ رمضانَ."],"questions":[{"question":"المفعول فيه هو:","options":["اسم يدل على زمان الفعل أو مكانه بمعنى (في)","اسم يقع عليه الفعل","اسم يبين سبب الفعل","اسم بعد واو المعية"],"answer":0,"explanation":"ظرف زمان أو ظرف مكان منصوب بمعنى في: صباحًا أي في صباح."},{"question":"نوعا المفعول فيه هما:","options":["ظرف الزمان وظرف المكان","المعرب والمبني","الظاهر والمضمر","المفرد والجمع"],"answer":0,"explanation":"فيه الزمان والمكان تحتويه: ظرف زمان وظرف مكان."},{"question":"علامة معرفة المفعول فيه السهلة:","options":["أن يصح وضع (في) قبله","أن يكون أول الجملة","أن يكون معرفة","أن ينتهي بتاء مربوطة"],"answer":0,"explanation":"لقيته صباحًا = لقيته في صباح؛ إذا صحت (في) فهو مفعول فيه."},{"question":"في «جلستُ تحتَ الشجرةِ» كلمة «تحتَ» تعرب:","options":["ظرف مكان منصوب","مفعول به","حرف جر","فاعل"],"answer":0,"explanation":"تحتَ: ظرف مكان منصوب بالفتحة، والشجرةِ: مضاف إليه مجرور."},{"question":"في «صامَ المسلمونَ رمضانَ» كلمة «رمضانَ» تعرب:","options":["ظرف زمان منصوب","مفعول به","فاعل","مبتدأ"],"answer":0,"explanation":"رمضانَ: ظرف زمان منصوب؛ لأنه بمعنى (في رمضان)."}]},{"body":["كيف تفرق بين المفعول فيه والمفعول به؟ الضابط هو معنى (في):","إذا كان الاسم بمعنى (في) فهو مفعول فيه، وإذا وقع عليه الفعل مباشرة فهو مفعول به.","قارن: «المؤمنُ يخافُ يومَ القيامةِ» و«الكافرُ يخافُ يومَ القيامةِ». مع المؤمن: يومٌ مفعول به؛ لأنه يخاف اليوم نفسه ويستعد له. ومع الكافر: يومٌ ظرف زمان؛ لأنه يخاف في يوم القيامة لما يلقاه فيه.","وضابط ظرف الزمان: اسأل متى وقع الفعل؟ وضابط ظرف المكان: اسأل أين وقع الفعل؟","وحكمهما النصب: إن كانا معربين فمنصوبان بعلامة، وإن كانا مبنيين ففي محل نصب، مثل: متى تسافرُ؟ وأينَ تسكنُ؟"],"examples":["متى وقع الفعل؟ جاءَ ضيوفُنا قبلَ العصرِ — قبل: ظرف زمان.","أين وقع الفعل؟ قامَ العادلُ تحتَ الشجرةِ — تحت: ظرف مكان.","المؤمن يخافُ يومَ القيامةِ — يومَ: مفعول به (يخاف اليوم نفسه).","الكافر يخافُ يومَ القيامةِ — يومَ: ظرف زمان (يخاف فيه).","متى تسافرُ؟ — متى: ظرف زمان في محل نصب مبني على السكون.","أينَ تسكنُ؟ — أين: ظرف مكان في محل نصب مبني على الفتح."],"questions":[{"question":"ضابط ظرف الزمان أن تسأل:","options":["متى وقع الفعل؟","أين وقع الفعل؟","على ماذا وقع الفعل؟","لماذا وقع الفعل؟"],"answer":0,"explanation":"متى لقيتَ فهدًا؟ صباحًا — فصباحًا ظرف زمان منصوب."},{"question":"ضابط ظرف المكان أن تسأل:","options":["أين وقع الفعل؟","متى وقع الفعل؟","من فعل؟","كيف وقع الفعل؟"],"answer":0,"explanation":"أين لقيتَ فهدًا؟ أمامَ المسجدِ — فأمام ظرف مكان منصوب."},{"question":"لماذا أعرب «يومَ» مفعولًا به مع المؤمن وظرفًا مع الكافر في «يخاف يوم القيامة»؟","options":["المؤمن يخاف اليوم نفسه، والكافر يخاف في اليوم","لا فرق بينهما","لأن المؤمن أقوى","لأن الكافر لا يخاف"],"answer":0,"explanation":"المعيار معنى (في): الكافر يخاف في يوم القيامة، والمؤمن يخاف اليوم ذاته."},{"question":"إعراب «أينَ» في «أينَ تسكنُ؟»:","options":["ظرف مكان مبني على الفتح في محل نصب","مفعول به","حرف استفهام فقط","فاعل"],"answer":0,"explanation":"أين: ظرف مكان مبني في محل نصب، تدل على مكان السكنى."},{"question":"حكم ظرفي الزمان والمكان:","options":["النصب أو محل النصب","الرفع","الجر دائمًا","الجزم"],"answer":0,"explanation":"الظرف منصوب إن كان معربًا، وفي محل نصب إن كان مبنيًّا مثل: متى وأين."}]}]},{"id":"wahi-verse-059","title":"أسماء الزمان وأسماء المكان: المطلق والمبهم","summary":"البيت التاسع والخمسون: أسماء الزمان كلها تنتصب ظرفًا، ومن أسماء المكان لا ينتصب إلا المبهم.","verse":{"number":59,"section":"المكملات المنصوبة: المفاعيل","text":"فِي مُطْلَقِ الزَّمَانِ (سِرْتُ وَقْتَا) / وَمُبْهَمِ الْمَكَانِ (نِمْتُ تَحْتَا)"},"segments":[{"body":["ظرف الزمان أوسع من ظرف المكان: فكل أسماء الزمان يجوز أن تنتصب على الظرفية الزمانية.","منها: ساعةً ويومًا وليلةً وأسبوعًا وشهرًا وعامًا، وصباحًا وظهيرةً ومساءً وبُكرةً وعشيًّا، وأبدًا وحينًا ووقتًا ودهرًا، ومتى وأيان وإذْ وإذا.","ومثال البيت: «سِرْتُ وَقْتَا» أي: سرت مدة من الزمان؛ فوقتًا ظرف زمان منصوب.","أما أسماء المكان فلا ينتصب منها على الظرفية إلا المبهم، وهو ما ليس له حدود محصورة، مثل: أمام وخلف وفوق وتحت ويمين وشمال.","فلا يصح أن تقول: جلستُ مسجدًا أو مدرسةً؛ لأنها أماكن محدودة محصورة، وإنما تقول: جلستُ في المسجدِ.","ومثال البيت: «نِمْتُ تَحْتَا» أي: نمت في مكان أسفل؛ فتحتًا ظرف مكان مبهم منصوب."],"examples":["أسماء زمان: يومًا وليلةً وساعةً وعامًا ودهرًا.","أوقات اليوم: صباحًا وظهيرةً ومساءً وبُكرةً وعشيًّا.","مبهم من الزمان: أبدًا وحينًا ووقتًا ومتى وأيان.","جهات مبهمة: أمامَ وخلفَ وفوقَ وتحتَ ويمينَ وشمالَ.","سرتُ وقتًا — وقتًا: ظرف زمان منصوب.","نمتُ تحتًا — تحتًا: ظرف مكان منصوب."],"questions":[{"question":"ما الذي يجوز انتصابه على الظرفية الزمانية؟","options":["كل أسماء الزمان","بعض أسماء الزمان فقط","أسماء المكان","لا شيء"],"answer":0,"explanation":"ظرف الزمان أوسع: كل أسماء الزمان يجوز أن تنتصب ظرفًا."},{"question":"من أسماء المكان لا ينتصب ظرفًا إلا:","options":["المبهم الذي لا حدود محصورة له","المحدود مثل المسجد","كل أسماء المكان","أسماء البلاد"],"answer":0,"explanation":"المبهم مثل: أمام وخلف وفوق وتحت؛ فلا يقال: جلستُ مسجدًا."},{"question":"في «سرتُ وقتًا» إعراب «وقتًا»:","options":["ظرف زمان منصوب بالفتحة","مفعول به","فاعل","حال"],"answer":0,"explanation":"وقتًا: اسم زمان مبهم انتصب على الظرفية الزمانية."},{"question":"لماذا لا يصح «جلستُ مسجدًا»؟","options":["لأن المسجد مكان محدود محصور لا يبهم","لأن المسجد معرفة","لأن جلست فعل لازم","يصح في كل الأحوال"],"answer":0,"explanation":"أسماء المكان المحصورة لا تنتصب ظرفًا، وإنما تقال بحرف جر: في المسجد."},{"question":"أي كلمة مما يلي ظرف مكان مبهم؟","options":["تحتَ","مسجدَ","مدرسةَ","بيتَ"],"answer":0,"explanation":"تحت من أسماء الجهات المبهمة فتنتصب ظرفًا: نمتُ تحتًا."}]},{"body":["من أسماء المكان التي تنتصب ظرفًا أيضًا: أسماء المقادير مثل: ميلًا وفرسخًا وذراعًا، فتقول: سرتُ ميلًا.","ومنها أسماء الجهات الست: أمام (وقدام)، وخلف (ووراء)، وفوق (وأعلى)، وتحت (وأسفل)، ويمين (وذات اليمين)، وشمال (ويسار).","ومنها أسماء المكان المشتقة مثل: جلستُ مجلسَ الخطيبِ، وأسماء الإشارة للمكان: هنا وثمَّ.","وقاعدة مهمة: من الأسماء أسماء ينحصر إعرابها في حالين: تُجر بحرف الجر إذا سبقت به، وتنتصب ظرفًا إذا لم تسبق به، مثل: عندَ وقبلَ وبعدَ ولدى ولدُنْ ومتى وأين وحيث.","فتقول: جلستُ عندَك ظرفًا، وجئتُ من عندِك مجرورًا. وتقول: أين تسكن؟ ظرفًا، وإلى أينَ تذهب؟ مجرورًا في محل جر."],"examples":["مقادير: سرتُ ميلًا وفرسخًا.","جهات: جلستُ أمامَ المدرسةِ وخلفَ البيتِ.","مشتقة: جلستُ مجلسَ الخطيبِ.","إشارة: اجلسْ هنا.","عندَك ظرفًا / من عندِك مجرورًا.","قبلَك ظرفًا / من قبلِك مجرورًا."],"questions":[{"question":"أسماء الجهات الست هي:","options":["أمام وخلف وفوق وتحت ويمين وشمال","شرق وغرب وشمال وجنوب وفوق وتحت","ميل وفرسخ وذراع وكيل وساعة ويوم","هنا وثم وأين وحيث وعند ولدى"],"answer":0,"explanation":"الجهات الست النسبية: أمام وخلف وفوق وتحت ويمين وشمال، وكلها مبهمة تنتصب ظرفًا."},{"question":"في «سرتُ ميلًا» إعراب «ميلًا»:","options":["ظرف مكان منصوب من أسماء المقادير","مفعول به","حال","تمييز"],"answer":0,"explanation":"ميلًا: اسم مقادير انتصب على الظرفية المكانية."},{"question":"في «جئتُ من عندِك» إعراب «عندِ»:","options":["اسم مجرور بحرف الجر","ظرف مكان منصوب","مفعول به","فاعل"],"answer":0,"explanation":"عند ينحصر إعرابها في الجر بعد حرف الجر والانتصاب ظرفًا بغيره."},{"question":"في «اجلسْ حيثُ شئتَ» إعراب «حيثُ»:","options":["ظرف مكان مبني على الضم في محل نصب","مفعول به","حرف","مبتدأ"],"answer":0,"explanation":"حيث: ظرف مكان مبني على الضم في محل نصب."},{"question":"أي تركيب صحيح الاستعمال؟","options":["جلستُ أمامَ المسجدِ","جلستُ مسجدًا","جلستُ مدرسةً","جلستُ بيتًا"],"answer":0,"explanation":"أمام ظرف مبهم يصح، أما المسجد والمدرسة والبيت فمحصورة تحتاج إلى (في)."}]}]},{"id":"wahi-verse-060","title":"المفعول لأجله: لماذا وقع الفعل؟","summary":"البيت الستون: المفعول له مصدر منصوب يكشف سبب الفعل وعلته.","verse":{"number":60,"section":"المكملات المنصوبة: المفاعيل","text":"وَكَاشِفُ الْأَسْبَابِ مَفْعُولٌ لَّهُ / بِمَصْدَرٍ، كَـ(اِسْتُرْ حَيَاءً وَبُخْلَهْ)"},"segments":[{"body":["المفعول الثالث: المفعول له، ويسمى أيضًا المفعول لأجله والمفعول من أجله.","وهو مصدر منصوب يبين سبب وقوع الفعل وعلته، أي: يجيب عن سؤال: لماذا فُعل الفعل؟","تقول: جاءَ زهيرٌ طلبًا للعلمِ. لماذا جاء؟ طلبًا للعلم. فـ«طلبًا» مصدر منصوب يكشف السبب، فهو مفعول لأجله.","ووصفه الناظم بأنه «كاشف الأسباب» لأنه يكشف علة الحدث: فالطلب علة المجيء، والرجاء علة الجلوس، والحياء علة الترك، والخوف والطمع علة الدعاء.","ومثال البيت: «اِسْتُرْ حَيَاءً وَبُخْلَهْ» أي: استر عيب صاحبك حياءً منه وصونًا لعرضه رغم بخله؛ فحياءً مصدر منصوب مفعول لأجله: أي بسبب الحياء."],"examples":["جاءَ زهيرٌ طلبًا للعلمِ — طلبًا: مفعول لأجله.","اجلسْ رجاءَ المنفعةِ — رجاءَ: مفعول لأجله.","تركتُه حياءً — حياءً: مفعول لأجله.","قمتُ عنك رجاءَ رحمةِ اللهِ — رجاءَ: مفعول لأجله.","حضرتُ إكرامًا لك — إكرامًا: مفعول لأجله.","نصحتُك حرصًا على مصلحتِك — حرصًا: مفعول لأجله."],"questions":[{"question":"المفعول لأجله هو:","options":["مصدر منصوب يبين سبب الفعل وعلته","اسم يقع عليه الفعل","ظرف زمان","اسم بعد واو المعية"],"answer":0,"explanation":"جاء طلبًا للعلم: طلبًا مصدر يكشف سبب المجيء."},{"question":"ضابط المفعول لأجله أن تسأل:","options":["لماذا فُعل الفعل؟","متى وقع الفعل؟","أين وقع الفعل؟","من فعل الفعل؟"],"answer":0,"explanation":"لماذا جئتَ؟ طلبًا للعلم — فطلبًا مفعول لأجله منصوب."},{"question":"في «تركتُه حياءً» علة الترك هي:","options":["الحياء","الترك نفسه","الهاء","لا علة"],"answer":0,"explanation":"حياءً: مصدر منصوب مفعول لأجله؛ هو سبب ترك الرجل."},{"question":"في مثال البيت «استرْ حياءً وبُخْلَه» إعراب «حياءً»:","options":["مفعول لأجله منصوب","مفعول به","حال","فاعل"],"answer":0,"explanation":"حياءً: مصدر منصوب يبين سبب الستر: مفعول لأجله."},{"question":"في «حضرتُ إكرامًا لك» لماذا حضرت المتكلم؟","options":["إكرامًا للمخاطب","حضورًا","خوفًا","لا سبب"],"answer":0,"explanation":"إكرامًا: مصدر منصوب مفعول لأجله، يبين علة الحضور."}]},{"body":["شرط مهم في المفعول لأجله: لا يكون إلا مصدرًا قلبيًّا، أي مصدرًا لما يقع في القلب من معانٍ كالحياء والخوف والرجاء والطمع والحرص والإكرام.","فلا يصح أن تجعل مصدرًا حسيًّا مفعولًا لأجله؛ لأن السبب الدافع للفعل إنما هو ما يحرك النفس.","والتدقيق في هذا الشرط يسير: انظر هل المصدر معنى قلبي يدفع إلى الفعل؟ فإن كان كذلك صح انتصابه مفعولًا لأجله.","ومن صوره الكثيرة في كلامنا: تعبتُ عنك رجاءَ رحمةِ اللهِ، وتركتُ المعصيةَ خوفًا من اللهِ، وأحسنتُ إليه رحمةً به.","وبهذا تمّت ثلاثة من المفاعيل الخمسة: المفعول به، والمفعول فيه، والمفعول له، ويبقى المفعول معه والمفعول المطلق في البيتين القادمين."],"examples":["قلبي: تركتُ المعصيةَ خوفًا من اللهِ.","قلبي: أحسنتُ إليه رحمةً به.","قلبي: يُدعى رغبةً ورهبةً.","قلبي: سافرَ طمعًا في الرزقِ الحلالِ.","قلبي: صبرَ احتسابًا للأجرِ.","قلبي: عملَ الصالحاتِ ابتغاءَ مرضاةِ اللهِ."],"questions":[{"question":"شرط المفعول لأجله:","options":["أن يكون مصدرًا قلبيًّا","أن يكون اسم فاعل","أن يكون جمعًا","أن يكون معرفة"],"answer":0,"explanation":"المصدر القلبي كالحياء والخوف والرجاء يصحب الفعل علة له."},{"question":"أي المصادر التالية يصح أن يكون مفعولًا لأجله؟","options":["خوفًا من الله","ضربًا","أكلًا","مشيًا"],"answer":0,"explanation":"الخوف معنى قلبي يدفع إلى الفعل، أما الضرب والأكل والمشي فمصادر حسية."},{"question":"في «تركتُ المعصيةَ خوفًا من اللهِ» إعراب «خوفًا»:","options":["مفعول لأجله منصوب","مفعول به","حال","مفعول مطلق"],"answer":0,"explanation":"خوفًا: مصدر قلبي منصوب يبين علة الترك."},{"question":"المفاعيل التي درسناها حتى هذا البيت هي:","options":["المفعول به وفيه وله","المفعول به ومعه والمطلق","فيه وله ومعه","المطلق وبه فقط"],"answer":0,"explanation":"ثلاثة مضت: به وفيه وله، ويبقى معه والمطلق في البيتين القادمين."},{"question":"في «صبرَ احتسابًا للأجرِ» علة الصبر هي:","options":["احتساب الأجر","الصبر نفسه","الأجر مفعول به","لا علة"],"answer":0,"explanation":"احتسابًا: مصدر قلبي منصوب مفعول لأجله يبين سبب الصبر."}]}]},{"id":"wahi-verse-061","title":"المفعول معه: «سِرْتُ وَالشَّاطِئَ»","summary":"البيت الحادي والستون: تعريف المفعول معه، وواو المعيّة، وفرقه عن العطف.","verse":{"number":61,"section":"المفعول معه","text":"وَ(سِرْتُ وَالشَّاطِئَ) مَفْعُولٌ مَّعَهْ / (فِي صُحْبَةٍ) لِلْوَاوِ تَأْتِي مَوْضِعَهْ"},"segments":[{"body":["نقول أحيانًا: «سِرْتُ والشاطئَ»، فما معنى الواو هنا؟ ولماذا نصبنا «الشاطئ»؟","هذا هو «المفعول معه»: اسمٌ منصوب يقع بعد واوٍ بمعنى (مَعَ)؛ أي: فعلتُ الفعل ومعي هذا الشيء.","فقولك: «سِرْتُ والشاطئَ» = سِرْتُ مَعَ الشاطئِ. والواو هنا تسمى «واو المعيّة»: حرفٌ مبنيٌّ لا محل له من الإعراب، تأتي مَوْضِعَ (مَعَ) كما قال الناظم.","وإعراب الاسم بعدها دائمًا: مفعول معه منصوب، وعلامة نصبه الفتحة."],"examples":["سِرْتُ والشاطئَ — الشاطئَ: مفعول معه منصوب = مَعَ الشاطئِ.","اسْتَذْكَرْتُ والمصباحَ — أي: استذكرتُ مع مصاحبة المصباح.","سافرَ أخي والحقيبةَ — الحقيبةَ: مفعول معه.","رَكَضْتُ والسُّورَ — السُّورَ: مفعول معه.","سِرْتُ والقمرَ — أي: مَعَ القمرِ.","سَهِرْتُ وكتابًا ممتعًا — أي: مَعَ كتابٍ ممتعٍ."],"questions":[{"question":"المفعول معه هو:","options":["اسم منصوب يقع بعد واو بمعنى (مَعَ)","اسم مرفوع يقع بعد واو العطف","اسم مجرور يقع بعد حرف جر","مصدر منصوب بعد فعله"],"answer":0,"explanation":"المفعول معه: اسم منصوب بعد واو المعيّة، مثل: سِرْتُ والشاطئَ — الشاطئَ: مفعول معه منصوب."},{"question":"معنى الواو في «سِرْتُ والشاطئَ»:","options":["مَعَ — وهي واو المعيّة","العطف والمشاركة","القَسَم","الحال"],"answer":0,"explanation":"واو المعيّة تأتي مَوْضِعَ (مَعَ)؛ فالمعنى: سرتُ مع الشاطئ."},{"question":"إعراب «الشاطئَ» في «سِرْتُ والشاطئَ»:","options":["مفعول معه منصوب وعلامة نصبه الفتحة","مفعول به منصوب","معطوف على فاعل","حال منصوبة"],"answer":0,"explanation":"الاسم المنصوب بعد واو المعيّة يُعرب مفعولًا معه، والواو: حرف مبني لا محل له من الإعراب."},{"question":"الفرق بين «سِرْتُ والشاطئَ» و«سِرْتُ وأنا والشاطئُ»:","options":["الأولى بالمعيّة ونصب، والثانية عطف ورفع ومشاركة","لا فرق بينهما أبدًا","الأولى عطف والثانية معيّة","كلتاهما مفعول معه"],"answer":0,"explanation":"في المفعول معه يُنصب الاسم والمعنى (مع)، وفي العطف يتبع الاسم ما قبله ويشاركه في الحكم."},{"question":"واو المعيّة إعرابها:","options":["حرف مبني لا محل له من الإعراب","حرف جر","حرف نصب","حرف عطف محله نصب"],"answer":0,"explanation":"واو المعيّة حرف مبني على الفتح لا محل له من الإعراب، والاسم بعدها مفعول معه منصوب."}]},{"body":["للمفعول معه نوعان لطيفان ذكرهما الشارح، وضابطٌ سهل يميّز بينهما.","النوع الأول: اسمٌ لم يشارك في الفعل أصلًا، لكنه كان موجودًا في أثنائه؛ مثل: «تَمَشَّيْتُ والشاطئَ»، فالشاطئ لم يتمشَّ معي! وضابطه: لا يصح أن تكرر الفعل معه، فلا يقال: «وتمشّى الشاطئُ».","النوع الثاني: اسمٌ فعل الفعلَ بلا قصدٍ، تبعًا للفاعل؛ مثل: «تَمَشَّيْتُ والهِرَّةَ»، فالهرة تمشّت تبعًا لي، ولو لم أتمشَّ لم تتمشَّ. وضابطه: يصح تكرير الفعل معه: «وتمشّت الهرةُ».","ومنه: «جاء الأميرُ والجيشَ»؛ فالجيش جاء تبعًا للأمير، ولو ذهب الأمير إلى مكان آخر لتبعه. ولاحظ الفرق: «سافرتُ وصلاحًا» = سافر تبعًا لي، أما «سافرتُ أنا وصلاحٌ» بالعطف = سافرنا معًا بلا تبعية."],"examples":["تَمَشَّيْتُ والشاطئَ — لم يشارك في الفعل؛ لا يصح: وتمشّى الشاطئ.","تَمَشَّيْتُ والهِرَّةَ — فعلت الفعل بلا قصد تبعًا؛ يصح: وتمشّت الهرة.","جاء الأميرُ والجيشَ — الجيش تبع للأمير.","سافرتُ وصلاحًا — صلاح سافر لمصاحبتي لا بقصد منه.","سِرْتُ والناقةَ — الناقة تبعت سيري.","أَقْبَلَ الربيعُ وتفتُّحَ الأزهارَ — أي: مع تفتّح الأزهار."],"questions":[{"question":"نوعا المفعول معه:","options":["ما لم يفعل الفعل، وما فعله بلا قصد تبعًا","المعرفة والنكرة","المفرد والجمع","الظاهر والضمير فقط"],"answer":0,"explanation":"قسّم الشارح المفعول معه إلى: ما لم يشارك في الفعل (الشاطئ)، وما فعله بلا قصد تبعًا (الهرة)."},{"question":"ضابط النوع الأول (لم يشارك في الفعل):","options":["لا يصح تكرير الفعل معه","يصح تكرير الفعل معه","يكون معرفة دائمًا","يكون جمعًا دائمًا"],"answer":0,"explanation":"تمشيت والشاطئ: لا يقال (وتمشّى الشاطئ)؛ لأن الشاطئ لم يفعل شيئًا."},{"question":"في «جاء الأميرُ والجيشَ» الجيش:","options":["فعل المجيء تبعًا للأمير بلا قصد مستقل","لم يجئ أصلًا","فاعل مشارك بالعطف","مفعول به"],"answer":0,"explanation":"يصح تكرير العامل: وجاء الجيش؛ فهو من النوع الثاني: فعل الفعل تبعًا بلا قصد."},{"question":"الفرق بين «سافرتُ وصلاحًا» و«سافرتُ وصلاحٌ»:","options":["الأولى: سافر تبعًا لي، والثانية: سافرنا معًا مشاركة","لا فرق","الأولى عطف والثانية معية","الثانية خطأ إعرابي"],"answer":0,"explanation":"بالنصب (مفعول معه): التبعية، وبالعطف والرفع: المشاركة بين المتعاطفين."},{"question":"في «أقبل الربيعُ وتفتُّحَ الأزهارَ» إعراب «تفتُّحَ الأزهارَ»:","options":["مفعول معه منصوب = مع تفتّح الأزهار","مفعول به","فاعل","معطوف على الربيع"],"answer":0,"explanation":"المعنى: أقبل الربيع مع تفتّح الأزهار؛ فهو مفعول معه منصوب بالفتحة."}]}]},{"id":"wahi-verse-062","title":"المفعول المطلق: المصدر بعد فعله","summary":"البيت الثاني والستون: تعريف المفعول المطلق والمصدر، وفوائده الثلاث.","verse":{"number":62,"section":"المفعول المطلق","text":"وَالْمَصْدَرُ الْمَنْصُوبُ بَعْدَ فِعْلِهْ / مُطْلَقُهَا، كَـ(صَامَ صَوْمَ أَهْلِهْ)"},"segments":[{"body":["إذا قلتَ: «صامَ صَوْمًا» فما إعراب «صَوْمًا»؟ إنه آخر المفاعيل: المفعول المطلق.","المصدر أولًا: هو التصريف الثالث للفعل، كقولك: ضَرَبَ يَضْرِبُ ضَرْبًا، وجَلَسَ يَجْلِسُ جُلُوسًا، واسْتَخْرَجَ يَسْتَخْرِجُ اسْتِخْرَاجًا.","فإذا جاء المصدر منصوبًا بعد فعله (من لفظه) فهو «مفعول مطلق»، كمثال البيت: «صامَ صَوْمَ أَهْلِهْ».","وسمي مطلقًا؛ لأنه غير مقيّد بفاعل ولا مفعول به، بل جاء من فعله مباشرة."],"examples":["ضَرَبَ يَضْرِبُ ضَرْبًا — ضربًا: مصدر منصوب بعد فعله.","دَعَا يَدْعُو دُعَاءً — دعاءً: مفعول مطلق.","جَلَسَ يَجْلِسُ جُلُوسًا — جلوسًا: مفعول مطلق.","تَكَلَّمَ اللهُ موسى تَكْلِيمًا — تكليمًا: مفعول مطلق منصوب.","حَفِظْتُ القرآنَ حِفْظًا — حفظًا: مفعول مطلق.","صامَ صَوْمَ أَهْلِهْ — مثال البيت: صومَ: مفعول مطلق مضاف، وأهلِه: مضاف إليه."],"questions":[{"question":"المصدر هو:","options":["التصريف الثالث للفعل مثل: ضرب يضرب ضربًا","اسم الفاعل","الفعل الماضي","المفعول به"],"answer":0,"explanation":"المصدر: التصريف الثالث للفعل: دعا يدعو دعاءً، جلس يجلس جلوسًا."},{"question":"المفعول المطلق هو:","options":["المصدر المنصوب بعد فعله","أي مصدر في الجملة","الاسم المنصوب بعد حرف الجر","الفاعل المرفوع"],"answer":0,"explanation":"إذا جاء المصدر منصوبًا بعد فعله فهو مفعول مطلق: صام صومًا — صومًا: مفعول مطلق."},{"question":"إعراب «صَوْمَ» في «صامَ صَوْمَ أهله»:","options":["مفعول مطلق منصوب، وهو مضاف","مفعول به","حال","فاعل"],"answer":0,"explanation":"صومَ: مفعول مطلق منصوب بالفتحة وهو مضاف، وأهلِه: مضاف إليه مجرور."},{"question":"استخرج المفعول المطلق من: «وقَعَدَ قُعُودًا»:","options":["قعودًا","وقعد","لا يوجد","قاعدًا"],"answer":0,"explanation":"قعودًا: مصدر منصوب بعد فعله = مفعول مطلق."},{"question":"لماذا سمي المفعول المطلق «مطلقًا»؟","options":["لأنه غير مقيد بفاعل ولا مفعول به","لأنه دائمًا نكرة","لأنه لا يُنصب","لأنه لا يجوز حذفه"],"answer":0,"explanation":"أُطلق من قيود الفاعلية والمفعولية؛ فهو مصدر من فعله مباشرة: حفظت القرآن حفظًا."}]},{"body":["للمفعول المطلق ثلاث فوائد، احفظها فهي مفتاح الباب.","الأولى: بيان النوع؛ ويكون بالنعت نحو: «دعوتُ اللهَ دُعاءً خاشعًا»، أو بالإضافة نحو: «جَلَسْتُ جُلُوسَ المؤدبِ».","الثانية: بيان العدد؛ نحو: «دعوتُ اللهَ دَعْوَةً» (مرة)، و«دعوتُه دَعْوَتَيْنِ»، و«دعوتُه ثلاثَ دَعَوَاتٍ».","الثالثة: التأكيد فيما سوى ذلك؛ نحو: «حفظتُ القرآنَ حِفْظًا»، فهو يؤكد وقوع الفعل ويقوّي معناه.","ويكثر حذف الفعل قبل المفعول المطلق: «سُبْحَانَ اللهِ» أي: أُسَبِّحُهُ تسبيحًا، و«حَمْدًا لله» أي: أحمدُه حمدًا، و«صَبْرًا على المكاره» أي: اصبِرْ صبرًا."],"examples":["دعوتُ اللهَ دُعاءً خاشعًا — بيان النوع بالنعت: خاشعًا.","جَلَسْتُ جُلُوسَ المؤدبِ — بيان النوع بالإضافة.","دعوتُ اللهَ دَعْوَةً — بيان العدد: مرة واحدة.","دعوتُ اللهَ ثلاثَ دَعَوَاتٍ — بيان العدد: ثلاث مرات.","حَفِظْتُ القرآنَ حِفْظًا — تأكيد.","سُبْحَانَ اللهِ — حُذف الفعل؛ التقدير: أسبّح الله تسبيحًا."],"questions":[{"question":"فوائد المفعول المطلق الثلاث:","options":["بيان النوع، بيان العدد، التأكيد","الرفع والنصب والجر","التقديم والتأخير والحذف","التعريف والتنكير والإضافة"],"answer":0,"explanation":"ذكر الشارح ثلاث فوائد: بيان النوع (دعاءً خاشعًا)، بيان العدد (دعوةً، دعوتين)، والتأكيد (حفظًا)."},{"question":"في «جلستُ جلوسًا طويلًا» فائدة المفعول المطلق:","options":["بيان النوع بالنعت","بيان العدد","التأكيد","بيان المكان"],"answer":0,"explanation":"جلوسًا مفعول مطلق وصفته (طويلًا)؛ فهو لبيان النوع."},{"question":"في «دعوتُ اللهَ دَعْوَتَيْنِ» إعراب دعوتين:","options":["مفعول مطلق منصوب وعلامة نصبه الياء لأنه مثنى","مفعول به بالفتحة","مضاف إليه مجرور","حال منصوبة بالفتحة"],"answer":0,"explanation":"دعوتين: مفعول مطلق لبيان العدد، منصوب بالياء لأنه مثنى."},{"question":"التقدير في «حَمْدًا لله»:","options":["أحمدُ اللهَ حمدًا — حُذف الفعل قبل المفعول المطلق","الحمد لله ثابت","لا تقدير له","هو مبتدأ وخبر"],"answer":0,"explanation":"يكثر حذف الفعل قبل المطلق: حمدًا لله = أحمده حمدًا، وسبحان الله = أسبّحه."},{"question":"«أكرمتُه إكرامًا» فائدة المفعول المطلق هنا:","options":["التأكيد","بيان النوع","بيان العدد","بيان الزمان"],"answer":0,"explanation":"لم يُقيَّد بنعت ولا إضافة ولا عدد؛ فهو لتأكيد الفعل وتقويته."}]}]},{"id":"wahi-verse-063","title":"الحال والنعت: وصفان لسابق","summary":"البيت الثالث والستون: الحال والنعت وصفان لاسم سابق، ويختلفان في المعنى واللفظ.","verse":{"number":63,"section":"الحال والنعت","text":"الْحَالُ وَالنَّعْتُ هُمَا وَصْفَانِ / لِسَابِقٍ، مُخْتَلِفَا الْمَعَانِي"},"segments":[{"body":["انظر إلى هاتين الجملتين: «جاء الطالبُ الضاحكُ» و«جاء الطالبُ ضاحكًا». الضحك فيهما من صفة الطالب، لكن الإعراب مختلف!","الحال والنعت كلاهما «وصفٌ» لاسمٍ سابقٍ قبله: يبيّن صفة من صفاته. والوصف: اسم يدل على صفة كـ«ضاحك» و«خائف» و«مكسور»، بخلاف الجوامد كـ«باب» و«كرسي» فلا صفة فيها.","فإن وافق الوصفُ الموصوفَ في التعريف أو التنكير (الطالبُ الضاحكُ) كان نعتًا، وإن خالفه فيهما (الطالبُ ضاحكًا) كان حالًا.","وهما «مختلفا المعاني» كما قال الناظم: النعت يدل على صفة ثابتة معروفة، والحال يدل على هيئة صاحبه زمن الفعل فقط."],"examples":["جاء الطالبُ الضاحكُ — الضاحك: نعت؛ وافق موصوفه تعريفًا.","جاء الطالبُ ضاحكًا — ضاحكًا: حال؛ خالف موصوفه: نكرة بعد معرفة.","أكلتُ الفاكهةَ الناضجةَ — نعت.","أكلتُ الفاكهةَ ناضجةً — حال.","اشترِيتُ السيارةَ جديدةً — حال.","مررتُ بهندٍ المتحجّبةِ — نعت؛ وافقها تنكيرًا."],"questions":[{"question":"الحال والنعت كلاهما:","options":["وصف لاسم سابق قبله","فعل ماضٍ","حرف جر","مصدر"],"answer":0,"explanation":"الحال والنعت وصفان يبيّنان صفة من صفات الموصوف السابق، مثل: جاء الطالب الضاحك / ضاحكًا."},{"question":"الوصف هو:","options":["اسم يدل على صفة كضاحك وخائف","كل اسم جامد كباب وكرسي","كل فعل","كل حرف"],"answer":0,"explanation":"الوصف اسم فيه صفة؛ أما الجوامد (باب، كرسي، أرض) فلا تصلح وصفًا."},{"question":"الفرق اللفظي بين الحال والنعت:","options":["النعت يوافق موصوفه تعريفًا أو تنكيرًا، والحال يخالفه فيهما","الحال يوافق والنعت يخالف","لا فرق","النعت منصوب دائمًا"],"answer":0,"explanation":"الطالبُ الضاحكُ: وافق فصار نعتًا؛ الطالبُ ضاحكًا: خالف فصار حالًا."},{"question":"في «جاء الطالبُ ضاحكًا» كلمة «ضاحكًا»:","options":["حال منصوبة","نعت مرفوع","مفعول به","فاعل"],"answer":0,"explanation":"نكرة وقعت بعد معرفة وخالفتها؛ فهي حال منصوبة بالفتحة."},{"question":"الفرق المعنوي بينهما:","options":["النعت صفة ثابتة معروفة، والحال هيئة زمن الفعل","الحال صفة ثابتة والنعت مؤقتة","كلاهما ثابت","كلاهما مؤقت"],"answer":0,"explanation":"الحال يدل على اتصاف صاحبه به زمن الفعل فقط؛ أما النعت فيثبت الصفة معروفة قبل الفعل وبعده."}]},{"body":["كيف نعرف الفرق عمليًّا؟ لكل واحد منهما ضابطٌ سهل تحفظه.","ضابط الحال: أن تضع قبله عبارة «حالة كونه»؛ فتقول: «جاء الأستاذُ مبتسمًا» = جاء الأستاذ حالة كونه مبتسمًا زمن مجيئه.","وضابط النعت: أن تضع قبله عبارة «الموصوف بأنه»؛ فتقول: «جاء الأستاذُ المبتسمُ» = جاء الأستاذ الموصوف بأنه المبتسم.","فالابتسام في الأولى هيئته لحظة المجيء فحسب، وفي الثانية صفة معروفة له مطلقًا."],"examples":["جاء الأستاذُ مبتسمًا — حال؛ يصح: حالة كونه مبتسمًا.","جاء الأستاذُ المبتسمُ — نعت؛ يصح: الموصوف بأنه المبتسم.","ركبتُ الفرسَ مسرجًا — حال: حالة كونه مسرجًا.","ركبتُ الفرسَ المسرجَ — نعت: الموصوف بأنه المسرج.","اشترِيتُ السيارةَ جديدةً — حال.","اشترِيتُ السيارةَ الجديدةَ — نعت."],"questions":[{"question":"ضابط الحال أن تضع قبله:","options":["حالة كونه","الموصوف بأنه","من جهة","مَعَ"],"answer":0,"explanation":"جاء الأستاذ مبتسمًا = جاء حالة كونه مبتسمًا زمن المجيء."},{"question":"ضابط النعت أن تضع قبله:","options":["الموصوف بأنه","حالة كونه","من","إنّ"],"answer":0,"explanation":"جاء الأستاذ المبتسم = الموصوف بأنه المبتسم؛ فالابتسام من صفاته المعروفة."},{"question":"«أكلتُ الفاكهةَ ناضجةً» تُحوَّل إلى نعت هكذا:","options":["أكلتُ الفاكهةَ الناضجةَ","أكلتُ فاكهةً ناضجةً","أكلتُ الناضجةَ الفاكهةَ","لا تُحوَّل"],"answer":0,"explanation":"بتعريف الوصف ليطابق معرفة المنعوت ينقلب الحال نعتًا: الناضجةَ: نعت منصوب."},{"question":"الحال يثبت الصفة لصاحبها:","options":["زمن الفعل فقط","قبل الفعل فقط","بعد الفعل فقط","دائمًا أبدًا"],"answer":0,"explanation":"الحال يدل على أن صاحبه اتصف بها زمن الفعل؛ وأما قبله وبعده فلا يثبتها ولا ينفيها."},{"question":"أي جملة فيها نعت؟","options":["مررتُ بهندٍ المتحجّبةِ","مررتُ بهندٍ متحجّبةً","جاء الأستاذُ مبتسمًا","اشتريتُ السيارةَ جديدةً"],"answer":0,"explanation":"المتحجّبة: وافقت هندًا في التنكير والجر؛ فهي نعت مجرور."}]}]},{"id":"wahi-verse-064","title":"النعت: الوصف التابع","summary":"البيت الرابع والستون: النعت وصف تابع يوافق منعوته تعريفًا وتنكيرًا وإعرابًا.","verse":{"number":64,"section":"الحال والنعت","text":"فَالنَّعْتُ وَصْفٌ تَابَعَ الْمَوْصُوفَا / وَافَقَهُ، تَنْكِيرًا أَوْ تَعْرِيفَا"},"segments":[{"body":["النعت: وصفٌ يبيّن صفة من صفات صاحبه، ويوافقه في التعريف أو التنكير.","وقال الناظم: «تابعَ الموصوفَ»؛ فالنعت من «التوابع»: يتبع المنعوت في إعرابه رفعًا ونصبًا وجرًّا.","فإن كان المنعوت معرفة كان النعت معرفة: «جاء أوسٌ الضاحكُ»، وإن كان نكرة كان النعت نكرة: «جاء رجلٌ ضاحكٌ».","ويتبعه في الحركة أيضًا: جاء العاملُ الفرحُ (مرفوع)، ورأيتُ العاملَ الفرحَ (منصوب)، ومررتُ بالعاملِ الفرحِ (مجرور)."],"examples":["جاء أوسٌ الضاحكُ — معرفة بعد معرفة: نعت مرفوع.","جاء رجلٌ ضاحكٌ — نكرة بعد نكرة: نعت مرفوع.","رأيتُ العاملَ الفرحَ — نعت منصوب تابع للمفعول به.","مررتُ بالعاملِ الفرحِ — نعت مجرور تابع للمجرور.","جاء العمالُ الفرحُونَ — نعت مرفوع وعلامته الواو.","قرأتُ الكتابَ الممتعَ — نعت منصوب."],"questions":[{"question":"النعت هو:","options":["وصف يوافق صاحبه في التعريف أو التنكير","وصف يخالف صاحبه فيهما","اسم منصوب دائمًا","جملة فعلية"],"answer":0,"explanation":"النعت: وصف يبيّن صفة من صفات صاحبه ويوافقه تعريفًا أو تنكيرًا: جاء رجل ضاحكٌ."},{"question":"النعت تابع؛ يتبع المنعوت في:","options":["إعرابه رفعًا ونصبًا وجرًّا","النصب فقط","الجر فقط","لا يتبعه في شيء"],"answer":0,"explanation":"النعت من التوابع: جاء العامل الفرحُ / رأيت العامل الفرحَ / مررت بالعامل الفرحِ."},{"question":"إعراب «الفرحِ» في «مررتُ بالعاملِ الفرحِ»:","options":["نعت مجرور وعلامة جره الكسرة","حال منصوبة","مفعول به","مضاف إليه"],"answer":0,"explanation":"الفرحِ: نعت تابع لموصوفه المجرور، مجرور بالكسرة."},{"question":"«جاء رجلٌ ضاحكٌ» — لماذا ضاحكٌ نعت وليس حالًا؟","options":["لأنه نكرة وافقت نكرة قبلها","لأنه معرفة","لأنه منصوب","لأنه مجرور"],"answer":0,"explanation":"النعت يوافق المنعوت في التنكير؛ رجلٌ نكرة وضاحكٌ نكرة مرفوعة مثله."},{"question":"إعراب «الفرحُونَ» في «جاء العمالُ الفرحُونَ»:","options":["نعت مرفوع وعلامة رفعه الواو","حال منصوبة بالياء","فاعل","خبر"],"answer":0,"explanation":"الفرحون: نعت مرفوع تبعًا للعمال، وعلامة رفعه الواو لأنه جمع مذكر سالم."}]},{"body":["ضابط النعت كما تعلمنا: تضع قبله «الموصوف بأنه»؛ فإن صحّ فهو نعت.","ومعلومٌ أن المنعوت (الاسم الموصوف بالنعت) لا يكون إلا اسمًا ظاهرًا: «جاء أوسُ الضاحكُ»، «جاء رجلٌ ضاحكٌ».","ولا يأتي المنعوت ضميرًا؛ لأن الضمير لا يُنعت، فلا تقول: «جاء هو الضاحكُ».","ويجوز تعدد النعوت لمنعوتٍ واحد: «جاء أوسُ الفرحُ المسرعُ»؛ فالفرحُ نعت أول، والمسرعُ نعت ثانٍ، وكلاهما مرفوع تبعًا لأوس."],"examples":["جاء العاملُ الذي أحبُّه — الذي أحبّه: نعت في محل رفع مبني على السكون.","انقُلِ الخبرَ الصحيحَ — الصحيح: نعت منصوب.","جاء أوسُ الفرحُ المسرعُ — نعتان مرفوعان لمنعوت واحد.","بَعَثَ اللهُ النبيّينَ المبشّرينَ — نعت منصوب بالياء.","وسَّرَ لكمُ الشمسَ والقمرَ الدّائبينِ — نعت منصوب.","جاء الولدُ الخائفُ الباكي — نعتان متعاقبان."],"questions":[{"question":"المنعوت لا يكون:","options":["ضميرًا؛ لأن الضمير لا يُنعت","اسمًا ظاهرًا","معرفة","نكرة"],"answer":0,"explanation":"المنعوت اسم ظاهر دائمًا؛ فالضمير لا يوصف بنعت: لا يصح (جاء هو الضاحك)."},{"question":"«جاء أوسُ الفرحُ المسرعُ» — المسرعُ إعرابه:","options":["نعت ثانٍ مرفوع","حال","خبر","مفعول به"],"answer":0,"explanation":"يجوز تعدد النعوت: الفرحُ نعت أول والمسرعُ نعت ثانٍ، كلاهما مرفوع تبعًا لأوس."},{"question":"ضابط النعت:","options":["الموصوف بأنه","حالة كونه","من جهة","كأنّ"],"answer":0,"explanation":"تضع قبل النعت عبارة (الموصوف بأنه): جاء الأستاذ الموصوف بأنه المبتسم."},{"question":"«جاء العاملُ الذي أحبُّه» — «الذي» إعرابها:","options":["نعت في محل رفع مبني على السكون","حال منصوبة","فاعل مرفوع","مبتدأ"],"answer":0,"explanation":"الأسماء الموصولة تصلح نعتًا وتُعرب في محل رفع هنا تبعًا للعامل، وهي مبنية."},{"question":"«انقُلِ الخبرَ الصحيحَ» — الصحيحَ:","options":["نعت منصوب وعلامة نصبه الفتحة","حال","مفعول به","تمييز"],"answer":0,"explanation":"الصحيحَ: نعت تابع للخبرَ المفعول به؛ منصوب بالفتحة."}]}]},{"id":"wahi-verse-065","title":"الحال: الوصف المخالف","summary":"البيت الخامس والستون: الحال وصف نكرة يخالف موصوفه، حكمه النصب دائمًا.","verse":{"number":65,"section":"الحال والنعت","text":"وَالْحَالُ وَصْفٌ خَالَفَ الْمَوْصُوفَا / لِلنَّصْبِ وَالتَّنْكِيرِ جَا أَلُوفَا"},"segments":[{"body":["الحال: وصفٌ نكرة يبيّن حالَ صاحبه المعرفةِ زمنَ الفعل؛ مثل: «جاء أوسٌ ضاحكًا».","وقال الناظم: «خالفَ الموصوفَ»؛ فالحال نكرة وصاحبه معرفة: نقيضان في اللفظ، وهذا عكس النعت تمامًا.","وقال: «للنصب والتنكير جاء ألوفًا» أي: مُلازِمًا لهما دائمًا؛ فالحال حكمُه النصبُ أبدًا: إن كان معرِبًا فمنصوب، وإن كان مبنيًّا ففي محل نصب.","فالفتحة على كل حالٍ مفرد: «جاء العاملُ فرحًا»، والياء في المثنى وجمع المذكر: «جاء العمالُ فرحِينَ»، والمبني في محل نصب: «كيفَ جاء العاملُ؟»."],"examples":["جاء أوسٌ ضاحكًا — حال منصوبة بالفتحة.","اشترِيتُ السيارةَ جديدةً — حال.","جاء العمالُ فرحِينَ — حال منصوبة بالياء.","كيفَ جاء العاملُ؟ — كيف: حال في محل نصب مبنية على الفتح.","ركبتُ الفرسَ مسرجًا — حال.","مررتُ بهندٍ صائمةً — حال."],"questions":[{"question":"الحال هو:","options":["وصف نكرة يبيّن هيئة صاحبه المعرفة زمن الفعل","وصف معرفة يوافق موصوفه","اسم مرفوع دائمًا","مصدر منصوب"],"answer":0,"explanation":"الحال: وصف نكرة يخالف صاحبه المعرفة، مثل: جاء أوس ضاحكًا — ضاحكًا: حال منصوبة."},{"question":"حكم الحال الإعرابي:","options":["النصب دائمًا","الرفع دائمًا","يتبع صاحبه","الجر"],"answer":0,"explanation":"الحال منصوب أبدًا: فرحًا بالفتحة، فرحين بالياء، والمبني (كيف) في محل نصب."},{"question":"الأصل في صاحب الحال أن يكون:","options":["معرفة","نكرة","ضميرًا فقط","جمعًا"],"answer":0,"explanation":"صاحب الحال معرفة في الأصل؛ فهو يخالف الحال النكرة في التعريف."},{"question":"إعراب «فرحِينَ» في «جاء العمالُ فرحِينَ»:","options":["حال منصوبة وعلامة نصبه الياء","نعت مرفوعة","مفعول به","فاعل"],"answer":0,"explanation":"فرحين: حال منصوبة بالياء لأنها جمع مذكر سالم."},{"question":"«كيفَ» في «كيفَ جاء العاملُ؟»:","options":["حال في محل نصب، مبنية على الفتح","نعت مرفوع","اسم استفهام مرفوع","مفعول فيه"],"answer":0,"explanation":"الحال المبني يكون في محل نصب: كيف: حال مبنية على الفتح في محل نصب."}]},{"body":["ضابط الحال: تضع قبله «حالة كونه»؛ «جاء الأستاذ مبتسمًا» = حالة كونه مبتسمًا زمن مجيئه.","وصاحب الحال يأتي اسمًا ظاهرًا كما سبق، وضميرًا بارزًا نحو: «جِئْتُ ضاحكًا» و«اذهبوا مسرعين»، وضميرًا مستترًا نحو: «أوسٌ جاءَ ضاحكًا»؛ فصاحب الحال فاعل (جاء) المستتر تقديره هو.","ويُقلَب الحال نعتًا إذا عرّفته: «اشتريت السيارة جديدةً» حال، و«اشتريت السيارة الجديدةَ» نعت. ويُقلَب النعت حالًا إذا نكّرته.","فالقاعدة الذهبية: عرّفْ الوصفَ بعد نكرةٍ أو نكّرْهُ بعد معرفةٍ تغيّرْ حكمَه."],"examples":["جِئْتُ ضاحكًا — صاحب الحال: تاء المتكلم (ضمير بارز).","اذهَبْ متعجِّلًا — صاحب الحال: ضمير مستتر تقديره أنت.","أوسٌ جاء ضاحكًا — صاحب الحال: فاعل (جاء) المستتر (هو).","اشتريتُ السيارةَ الجديدةَ — عرّفنا الوصف فانقلب نعتًا.","مررتُ بهندٍ صائمةً — نكّرنا الوصف فصار حالًا.","وسَّرَ لكمُ الشمسَ والقمرَ دائبينِ — دائبين: حال منصوبة (لو عرّفناها لصارت نعتًا)."],"questions":[{"question":"صاحب الحال يأتي:","options":["اسمًا ظاهرًا وضميرًا بارزًا وضميرًا مستترًا","اسمًا ظاهرًا فقط","ضميرًا فقط","لا يأتي إلا فاعلًا"],"answer":0,"explanation":"صاحب الحال: ظاهر (أوس)، بارز (جئتُ ضاحكًا: التاء)، مستتر (جاء ضاحكًا: هو)."},{"question":"في «جئتُ ضاحكًا» صاحب الحال:","options":["تاء المتكلم","ضاحكًا","جئت","لا صاحب له"],"answer":0,"explanation":"صاحب الحال هو الاسم الموصوف بالحال؛ هنا التاء الضمير البارز، وضاحكًا: حال منصوبة."},{"question":"حوّلْ «أكلتُ التمرَ الناضجَ» إلى حال:","options":["أكلتُ التمرَ ناضجًا","أكلتُ تمرًا ناضجًا","أكلتُ الناضجَ التمرَ","أكلتُ التمرَ ناضجٌ"],"answer":0,"explanation":"بتنكير الوصف ينقلب النعت حالًا: ناضجًا: حال منصوبة بالفتحة."},{"question":"«انقُلِ الخبرَ صحيحًا» — صحيحًا:","options":["حال منصوبة","نعت","مفعول به","تمييز"],"answer":0,"explanation":"صحيحًا: نكرة بعد معرفة (الخبر)؛ فهي حال، ولو قلت الصحيحَ لكان نعتًا."},{"question":"الحال والنعت يتبادلان الحكم بـ:","options":["التعريف والتنكير","التقديم والتأخير","الحذف","الإضافة"],"answer":0,"explanation":"الحال النكرة ينقلب نعتًا عند تعريفه، والنعت المعرفة ينقلب حالًا عند تنكيره: مررت بهند المتحجبة / متحجبةً."}]}]},{"id":"wahi-verse-066","title":"نعت وحال في مثال واحد","summary":"البيت السادس والستون: تحليل مثالي النظم: جاء زيد الشريف خائفًا، وعاد عمرو البطيء راجفًا.","verse":{"number":66,"section":"الحال والنعت","text":"كَـ(جَاءَ زَيْدٌ الشَّرِيفُ خَائِفًا) / وَ(عَادَ عَمْرٌو الْبَطِيءُ رَاجِفًا)"},"segments":[{"body":["جاء الناظم بالمثال الجامع: «جاء زيدٌ الشريفُ خائفًا». ثلاث كلمات بعد الفعل، ولكلٍّ منها حكم!","«زيدٌ»: فاعل مرفوع، وهو معرفة (اسم علم)، وهو صاحب الحال والمنعوت معًا.","«الشريفُ»: وصف معرفة وافق موصوفه تعريفًا ورفعًا؛ فهو نعت مرفوع.","«خائفًا»: وصف نكرة خالف موصوفه، منصوب؛ فهو حال. فلاحظ: النعت رفع، والحال نصب، وكلاهما يصف زيدًا."],"examples":["جاء زيدٌ الشريفُ خائفًا — الشريف: نعت مرفوع، وخائفًا: حال منصوبة.","جاء الطالبُ المجتهدُ فرحًا — المجتهد: نعت، وفرحًا: حال.","عاد الجيشُ الكبيرُ منتصرًا — الكبير: نعت، ومنتصرًا: حال.","ركب الفارسُ الشجاعُ مسرعًا — الشجاع: نعت، ومسرعًا: حال.","قرأ الطفلُ الصغيرُ مستمتعًا — الصغير: نعت، ومستمتعًا: حال.","سافر أخي الكريمُ مبتهجًا — الكريم: نعت، ومبتهجًا: حال."],"questions":[{"question":"في «جاء زيدٌ الشريفُ خائفًا» إعراب «الشريفُ»:","options":["نعت مرفوع","حال منصوبة","فاعل","بدل"],"answer":0,"explanation":"الشريف: وصف معرفة وافق زيدًا (معرفة مرفوعة)؛ فهو نعت مرفوع بالضمة."},{"question":"في المثال نفسه إعراب «خائفًا»:","options":["حال منصوبة وعلامة نصبه الفتحة","نعت","مفعول به","تمييز"],"answer":0,"explanation":"خائفًا: وصف نكرة بعد معرفة، منصوب؛ فهو حال."},{"question":"صاحب الحال في «جاء زيدٌ الشريفُ خائفًا»:","options":["زيدٌ","الشريفُ","خائفًا","جاء"],"answer":0,"explanation":"صاحب الحال هو الموصوف بالحال: زيد (الفاعل المعرفة)، والحال: خائفًا."},{"question":"لماذا كان «الشريف» نعتًا و«خائفًا» حالًا وهما يصفان اسمًا واحدًا؟","options":["لأن الشريف معرفة وافق موصوفه، وخائفًا نكرة خالفه ونُصب","لا سبب","لأن خائفًا فعل","لأن الشريف منصوب"],"answer":0,"explanation":"النعت يوافق (معرفة بعد معرفة، مرفوع)، والحال يخالف (نكرة منصوبة بعد معرفة)."},{"question":"استخرج الحال من: «عاد الجيشُ الكبيرُ منتصرًا»:","options":["منتصرًا","الكبيرُ","الجيشُ","عاد"],"answer":0,"explanation":"منتصرًا: حال منصوبة؛ والكبيرُ: نعت مرفوع؛ والجيشُ: فاعل."}]},{"body":["المثال الثاني: «عادَ عَمْرٌو البطيءُ راجِفًا»، وهو على نمط الأول تمامًا.","«عمرو»: فاعل مرفوع، معرفة، صاحب الحال والمنعوت. و«البطيءُ»: نعت مرفوع. و«راجفًا»: حال منصوبة.","وتأمل الفرق في المعنى: البطء صفة لازمة لعمرو يُعرف بها (نعت)، أما الرَّجَفان فهيئة طرأت عليه حين عاد (حال).","واحفظ القالب: فعل + فاعل معرفة + نعت معرفة مرفوع + حال نكرة منصوبة."],"examples":["عاد عمرو البطيءُ راجفًا — البطيء: نعت، وراجفًا: حال.","دخل المعلمُ الحكيمُ مبتسمًا — الحكيم: نعت، ومبتسمًا: حال.","خرج الجنديُّ الشجاعُ متأهبًا — الشجاع: نعت، ومتأهبًا: حال.","جلس التاجرُ الأمينُ حاسبًا — الأمين: نعت، وحاسبًا: حال.","نجح الطالبُ المثابرُ متفوقًا — المثابر: نعت، ومتفوقًا: حال.","سار القائدُ الشهمُ مطمئنًّا — الشهم: نعت، ومطمئنًّا: حال."],"questions":[{"question":"في «عاد عمرو البطيءُ راجفًا» إعراب «البطيءُ»:","options":["نعت مرفوع وعلامة رفعه الضمة","حال منصوبة","فاعل","خبر"],"answer":0,"explanation":"البطيء: وصف معرفة تابع لعمرو المعرفة؛ نعت مرفوع بالضمة."},{"question":"إعراب «راجفًا» في المثال نفسه:","options":["حال منصوبة بالفتحة","نعت مرفوع","مفعول به","حال مجرورة"],"answer":0,"explanation":"راجفًا: نكرة منصوبة بعد معرفة تصف هيئة عمرو زمن العودة؛ حال."},{"question":"الفرق المعنوي بين «البطيء» و«راجفًا»:","options":["البطيء صفة ثابتة معروفة، وراجفًا هيئة زمن العودة","كلاهما صفة ثابتة","كلاهما هيئة مؤقتة","البطيء مؤقت وراجفًا ثابت"],"answer":0,"explanation":"النعت يثبت الصفة معروفة، والحال يدل على هيئة صاحبه زمن الفعل فقط."},{"question":"القالب الإعرابي للمثالين:","options":["فعل + فاعل معرفة + نعت مرفوع + حال منصوبة","فعل + مفعول + حال + نعت","فاعل + نعت + فعل","مبتدأ + خبر + حال"],"answer":0,"explanation":"جاء زيد الشريف خائفًا، وعاد عمرو البطيء راجفًا: الفاعل معرفة، فالوصف المعرفة نعت، والنكرة المنصوبة حال."},{"question":"«دخل المعلمُ الحكيمُ مبتسمًا» — النعت هو:","options":["الحكيمُ","مبتسمًا","المعلمُ","دخل"],"answer":0,"explanation":"الحكيم: وصف معرفة مرفوع تابع للمعلم؛ ومبتسمًا: حال منصوبة."}]}]},{"id":"wahi-verse-067","title":"الجملة وشبهها حالًا ونعتًا","summary":"البيت السابع والستون: الجملة وشبهها (الظرف والجار والمجرور) يأتيان حالًا بعد المعرفة ونعتًا بعد النكرة.","verse":{"number":67,"section":"الحال والنعت","text":"وَجُمْلَةٌ وَشِبْهُهَا كَالنَّكِرَةْ / أَحْكَامُهَا فِي بَابِنَا مُقَرَّرَهْ"},"segments":[{"body":["تعلمنا الحال والنعت وصفًا مفردًا (كلمة واحدة). فهل يكون الوصف جملةً كاملة أو شبه جملة؟ نعم!","شبه الجملة: الجار والمجرور أو الظرف، مثل: «على قدميه» و«على سيارة».","والجملة وشبهها يأخذان حكم النكرة في هذا الباب: «أحكامها في بابنا مقررة».","فإن وقعا بعد معرفةٍ كانا حالًا، وإن وقعا بعد نكرةٍ كانا نعتًا: «جاء أوسٌ على قدميه» حال، و«جاء رجلٌ على قدميه» نعت."],"examples":["جاء أوسٌ على قدميه — شبه جملة بعد معرفة: حال في محل نصب.","جاء رجلٌ على قدميه — شبه جملة بعد نكرة: نعت في محل رفع.","شاهدتُ بشيرًا يضحكُ — جملة فعلية بعد معرفة: حال.","شاهدتُ رجلًا يضحكُ — جملة فعلية بعد نكرة: نعت.","مررتُ ببشيرٍ يلعبُ — حال.","مررتُ بطالبٍ يلعبُ — نعت."],"questions":[{"question":"شبه الجملة هو:","options":["الجار والمجرور أو الظرف","الفعل وفاعله","المبتدأ والخبر","المصدر"],"answer":0,"explanation":"شبه الجملة: الجار والمجرور (على قدميه) والظرف؛ سمي شبهًا لأنه لا فعل فيه."},{"question":"الجملة وشبهها بعد المعرفة يُعربان:","options":["حالًا","نعتًا","مفعولًا به","تمييزًا"],"answer":0,"explanation":"الجمل وأشباه الجمل بعد المعارف أحوال وبعد النكرات نعوت: جاء بشير يضحك (حال)."},{"question":"الجملة وشبهها بعد النكرة يُعربان:","options":["نعتًا","حالًا","حالًا دائمًا","بدلًا"],"answer":0,"explanation":"جاء رجل على قدميه: شبه الجملة نعت لرجل في محل رفع."},{"question":"«على قدميه» في «جاء أوسٌ على قدميه»:","options":["حال في محل نصب","نعت في محل رفع","مفعول فيه","متعلق بالفعل فقط"],"answer":0,"explanation":"أوس معرفة؛ فشبه الجملة بعدها حال في محل نصب، متعلق بمحذوف تقديره حال."},{"question":"«جاء رجلٌ على سيارةٍ» — «على سيارة»:","options":["نعت لرجل في محل رفع","حال منصوبة","مفعول به","تمييز"],"answer":0,"explanation":"رجل نكرة؛ فشبه الجملة بعدها نعت في محل رفع."}]},{"body":["الجملة الواقعة حالًا أو نعتًا نوعان: فعلية واسمية.","الفعلية: «جاء أوسٌ يُسبِّحُ»؛ فجملة يسبح (فعل + فاعل مستتر) حال من أوس في محل نصب.","والاسمية: «جاء أوسٌ لسانُه يسبّحُ»؛ فجملة (لسانه يسبّح) حال أيضًا. وقد تُقرَن بواو الحال: «جاء أوسٌ وهو يسبّحُ».","وبعد النكرة تكون الجملة نعتًا: «جاء رجلٌ يسبّحُ»، و«جاء رجلٌ لسانُه يسبّحُ».","تنبيه: الجملة بعد الاسم الموصول ليست حالًا ولا نعتًا، بل صلة للموصول لا محل لها من الإعراب: «جاء الذي يضحكُ»."],"examples":["جاء أوسٌ يسبّحُ — جملة فعلية حال في محل نصب.","جاء أوسٌ لسانُه يسبّحُ — جملة اسمية حال.","جاء أوسٌ وهو يسبّحُ — واو الحال + جملة اسمية حال.","جاء رجلٌ يسبّحُ — جملة فعلية نعت في محل رفع.","جاء رجلٌ لسانُه يسبّحُ — جملة اسمية نعت.","جاء الذي يضحكُ — يضحك: صلة الموصول لا محل لها."],"questions":[{"question":"في «جاء أوسٌ لسانُه يسبّحُ» جملة «لسانه يسبح»:","options":["جملة اسمية حال في محل نصب","نعت","صلة موصول","مفعول به"],"answer":0,"explanation":"جملة اسمية (مبتدأ + خبر) وقعت بعد معرفة؛ فهي حال في محل نصب."},{"question":"الواو في «جاء أوسٌ وهو يسبّحُ» تسمى:","options":["واو الحال، مبنية لا محل لها","واو المعية","واو العطف","واو القسم"],"answer":0,"explanation":"واو الحال تدخل على الجملة الاسمية الواقعة حالًا: وهو يسبح: حال في محل نصب."},{"question":"«جاء رجلٌ يسبّحُ» — جملة يسبح:","options":["نعت في محل رفع","حال في محل نصب","صلة موصول","خبر"],"answer":0,"explanation":"بعد النكرة (رجل) الجملة الفعلية نعت في محل رفع."},{"question":"الجملة بعد الاسم الموصول:","options":["صلة لا محل لها من الإعراب","حال","نعت","بدل"],"answer":0,"explanation":"يستثنى من القاعدة الجملة بعد الموصول فهي صلة له: جاء الذي يضحك."},{"question":"في «شاهدتُ رجلًا يضحكُ» إعراب جملة يضحك:","options":["نعت في محل نصب تبعًا لرجلًا","حال","صلة","مفعول به ثانٍ"],"answer":0,"explanation":"رجلًا نكرة منصوبة؛ فالجملة الفعلية بعدها نعت في محل نصب تبعًا لها."}]}]},{"id":"wahi-verse-068","title":"مثال: حال الجملة ونعتها","summary":"البيت الثامن والستون: «جاء عامرٌ يسيرُ» حال، و«جاء فارسٌ يختالُ» نعت.","verse":{"number":68,"section":"الحال والنعت","text":"فَـ(جَاءَ عَامِرٌ يَسِيرُ) حَالُ / وَالنَّعْتُ (جَاءَ فَارِسٌ يَخْتَالُ)"},"segments":[{"body":["طبّق الناظم القاعدة في مثالين متقابلين، أولهما: «جاء عامرٌ يسيرُ».","«عامرٌ» اسم علم معرفة، والجملة الفعلية «يسيرُ» (يمشي) جاءت بعده.","والقاعدة: الجملة بعد المعرفة حال؛ فجملة «يسير» في محل نصب حال من عامر.","فالمعنى: جاء عامر حالة كونه يسير (يمشي) زمن مجيئه."],"examples":["جاء عامرٌ يسيرُ — يسير: فعل مضارع مرفوع، فاعله مستتر (هو)، والجملة حال في محل نصب.","جاء بشيرٌ يضحكُ — الجملة بعد معرفة: حال.","عاد خالدٌ يبتسمُ — حال جملة فعلية.","دخل المعلمُ يشرحُ — حال جملة فعلية.","خرج الجيشُ يتقدمُ — حال جملة فعلية.","سافر أخي يبتسمُ — حال جملة فعلية."],"questions":[{"question":"في «جاء عامرٌ يسيرُ» جملة «يسير»:","options":["حال في محل نصب؛ لأنها بعد معرفة","نعت في محل رفع","صلة موصول","خبر"],"answer":0,"explanation":"عامر اسم علم معرفة؛ فالجملة الفعلية بعده حال في محل نصب."},{"question":"فاعل «يسير» في المثال:","options":["ضمير مستتر تقديره هو يعود على عامر","عامر ظاهرًا","لا فاعل له","الراء"],"answer":0,"explanation":"يسير: فعل مضارع مرفوع بالضمة، فاعله ضمير مستتر (هو)، والجملة من الفعل والفاعل حال."},{"question":"معنى «جاء عامرٌ يسيرُ»:","options":["جاء حالة كونه يمشي زمن مجيئه","جاء بعد أن مشى","جاء لكي يمشي","مشى قبل المجيء بزمن"],"answer":0,"explanation":"الحال تبين هيئة صاحبها زمن الفعل: مجيئه مقترنًا بسيره على قدميه."},{"question":"لماذا لم تُعرب الجملة نعتًا هنا؟","options":["لأن صاحبها معرفة لا نكرة","لأنها فعلية","لأنها قصيرة","لأن الفعل ماضٍ"],"answer":0,"explanation":"النعت يوافق موصوفه؛ فلو كان نعتًا لاقتضى نكرة قبله، وعامر معرفة؛ فالجملة حال."},{"question":"«عاد خالدٌ مبتسمًا» و«عاد خالدٌ يبتسمُ» — علاقتهما:","options":["كلتاهما حال: الأولى مفردة والثانية جملة","الأولى نعت والثانية حال","كلتاهما نعت","الأولى حال والثانية نعت"],"answer":0,"explanation":"الحال يكون مفردًا (مبتسمًا) وجملة (يبتسم) بعد المعرفة؛ والجملة في محل نصب."}]},{"body":["المثال المقابل: «جاء فارسٌ يَخْتالُ» أي: يتبختر في مشيته.","«فارسٌ» هنا نكرة (أيّ فارس)، والجملة الفعلية «يختال» وقعت بعدها.","والقاعدة: الجملة بعد النكرة نعت؛ فجملة «يختال» في محل رفع نعت لفارس.","فالمعنى: جاء فارسٌ موصوف بأنه يختال. ولاحظ التقابل: عامر معرفة فحال، وفارس نكرة فنعت."],"examples":["جاء فارسٌ يختالُ — يختال: فعل مضارع مرفوع، فاعله مستتر (هو)، والجملة نعت في محل رفع.","جاء رجلٌ يضحكُ — الجملة بعد نكرة: نعت.","دخل طالبٌ يسألُ — نعت جملة فعلية.","شاهدتُ طائرًا يغرّدُ — نعت في محل نصب تبعًا لطائرًا.","مررتُ برجلٍ يمشي — نعت في محل جر تبعًا لرجلٍ.","قرأتُ قصةً تُمتعُ — نعت جملة فعلية."],"questions":[{"question":"في «جاء فارسٌ يختالُ» جملة «يختال»:","options":["نعت في محل رفع؛ لأنها بعد نكرة","حال في محل نصب","صلة موصول","خبر مبتدأ"],"answer":0,"explanation":"فارس نكرة؛ فالجملة الفعلية بعدها نعت في محل رفع."},{"question":"معنى «يختال»:","options":["يتبختر ويتمايل في مشيته","يسير مسرعًا","يقف ساكنًا","ينام"],"answer":0,"explanation":"اختال يختال: مشى متبخترًا معجبًا بنفسه؛ والجملة نعت لفارس في محل رفع."},{"question":"الفرق بين مثالي البيت:","options":["عامر معرفة فالجملة حال، وفارس نكرة فالجملة نعت","لا فرق","الأولى نعت والثانية حال","كلتاهما حال"],"answer":0,"explanation":"الجمل وأشباه الجمل بعد المعارف أحوال وبعد النكرات نعوت."},{"question":"«مررتُ برجلٍ يسبّحُ» — جملة يسبح في محل:","options":["جر نعتًا لرجلٍ","نصب حالًا","رفع نعتًا","نصب مفعولًا"],"answer":0,"explanation":"رجلٍ نكرة مجرورة؛ فالجملة نعت في محل جر تبعًا لها."},{"question":"فاعل «يختال» في المثال:","options":["ضمير مستتر تقديره هو يعود على فارس","فارس","الواو","لا فاعل"],"answer":0,"explanation":"يختال: فعل مضارع مرفوع بالضمة، فاعله مستتر (هو)، والجملة نعت في محل رفع."}]}]},{"id":"wahi-verse-069","title":"التمييز: مفسّر الإبهام","summary":"البيت التاسع والستون: تعريف التمييز وضابطه، وتمييز الذات بعد الأعداد.","verse":{"number":69,"section":"التمييز","text":"تَمْيِيزُنَا مُفَسِّرُ إِبْهَامَا / مَعْنَاهُ (مِنْ)، كَـ(أَرْبَعِينَ عَامَا)"},"segments":[{"body":["إذا قال صديقك: «عندي عشرون!» سألتَ فورًا: عشرون ماذا؟ فإذا قال: «عشرون قلمًا» زال الإبهام.","التمييز: اسمٌ نكرة منصوب يفسّر إبهام ما قبله على معنى (مِنْ). والمبهم: كل ما يحتمل أكثر من وجه.","فـ«عشرون» مبهمة: عشرون رجالًا؟ أقلامًا؟ كتبًا؟ حتى جاء التمييز فرفع الإبهام: عشرون مِنَ الأقلام.","ومثال البيت: «أربعين عامًا»؛ فالأربعون مبهمة حتى فسّرها «عامًا»: أربعين من الأعوام."],"examples":["عندي عشرون قلمًا — قلمًا: تمييز منصوب؛ فسّر إبهام عشرون.","مضى عشرون رجلًا — رجلًا: تمييز = من الرجال.","أربعين عامًا — مثال البيت: عامًا: تمييز.","عندي أحد عشر كتابًا — كتابًا: تمييز بعد العدد.","قرأتُ ثلاثين آيةً — آيةً: تمييز.","تصدّقَ بمائة جنيهٍ... وتصدّق بمئةٍ درهمًا — درهمًا: تمييز عند عدم الإضافة."],"questions":[{"question":"التمييز هو:","options":["اسم نكرة منصوب يفسّر إبهام ما قبله على معنى (من)","وصف يوافق موصوفه","اسم مرفوع بعد فعل","حرف جر"],"answer":0,"explanation":"التمييز: اسم نكرة منصوب يرفع إبهام ما قبله؛ مثل: عندي عشرون قلمًا — قلمًا: تمييز."},{"question":"المبهم هو:","options":["كل ما يحتمل أكثر من وجه","كل معرفة","كل ضمير","كل فعل"],"answer":0,"explanation":"الإبهام: الاحتمال؛ فعشرون تحتمل رجالًا وأقلامًا وكتبًا حتى يأتي التمييز فيرفع الإبهام."},{"question":"معنى التمييز يقدَّر بحرف:","options":["مِنْ","إلى","على","في"],"answer":0,"explanation":"التمييز على معنى (من): عشرون من الأقلام، أربعين من الأعوام."},{"question":"إعراب «عامًا» في «أربعين عامًا»:","options":["تمييز منصوب وعلامة نصبه الفتحة","مضاف إليه مجرور","مفعول به","حال"],"answer":0,"explanation":"عامًا: اسم نكرة منصوب فسّر إبهام العدد أربعين؛ تمييز."},{"question":"أي جملة تحتاج إلى تمييز؟","options":["عندي خمسون...","جاء زيدٌ","قرأتُ الدرسَ","سافر أخي"],"answer":0,"explanation":"الأعداد المركبة من عشرين إلى تسعين تلزم منصوبة وتحتاج تمييزًا يفسرها: خمسون طالبًا."}]},{"body":["ضابط التمييز سهل: تضع قبل الاسم (مِنْ) أو (مِنْ جهةِ)؛ فإن استقام المعنى فهو تمييز.","فـ«عندي عشرون قلمًا» يصح: عشرون مِنَ الأقلام. و«أنا أجمل منك خُلْقًا» يصح: أجمل مِنْ جهةِ الخُلق.","وللتمييز نوعان؛ أولهما: التمييز المفرد (تمييز الذات): ما كان إبهامه في مفرد، وهو الذي توضع قبله (من).","ومن أشهر مواضعه: الاسم المنصوب بعد العدد: «مضى عشرون رجلًا»، «عشرون حبّةً»، «ثلاثون يومًا»."],"examples":["عشرون رجلًا — الضابط: عشرون مِنَ الرجال .","أنا أجمل منك خُلْقًا — الضابط: مِنْ جهةِ الخُلق .","مضى عشرون رجلًا — تمييز ذات بعد عدد.","عشرون حبّةً — تمييز بعد عدد.","ثلاثون يومًا — تمييز بعد عدد.","أربعون نعجةً — تمييز بعد عدد."],"questions":[{"question":"ضابط التمييز أن تضع قبله:","options":["مِنْ أو مِنْ جهةِ","حالة كونه","الموصوف بأنه","مَعَ"],"answer":0,"explanation":"تضع قبل التمييز (من) نحو: عشرون من الأقلام، أو (من جهة) نحو: أجمل منك من جهة الخلق."},{"question":"النوع الأول من التمييز (المفرد) يسمى:","options":["تمييز الذات","تمييز النسبة","الحال","النعت"],"answer":0,"explanation":"التمييز المفرد يسمى تمييز الذات؛ لأن إبهامه في مفرد (العدد، المقدار)، وتوضع قبله (من)."},{"question":"من مواضع تمييز الذات:","options":["الاسم المنصوب بعد العدد","الاسم بعد الفاعل","الاسم بعد حرف الجر","الخبر"],"answer":0,"explanation":"مثل: مضى عشرون رجلًا، عشرون حبةً؛ فالمنصوب بعد العدد تمييز."},{"question":"«ثلاثون يومًا» — يومًا:","options":["تمييز منصوب بالفتحة","مضاف إليه","نعت","حال"],"answer":0,"explanation":"يومًا: اسم نكرة منصوب فسّر إبهام ثلاثين على معنى من؛ تمييز."},{"question":"الفرق بين «ثلاثة أقلامٍ» و«ثلاثين قلمًا»:","options":["الأولى مضاف إليه مجرور، والثانية تمييز منصوب","كلتاهما تمييز","كلتاهما مضاف إليه","الأولى تمييز"],"answer":0,"explanation":"العدد من 3-10 يضاف إلى جمع مجرور، ومن 11-99 يلزم تمييزًا مفردًا منصوبًا."}]}]},{"id":"wahi-verse-070","title":"تمييز النسبة: من جهة","summary":"البيت السبعون: تمييز النسبة يقدَّر بـ(من جهة)، مثل: طاب المؤمن نفسًا، وأنت أعلى خلقًا.","verse":{"number":70,"section":"التمييز","text":"وَنِسْبَةٌ تَقْدِيرُهَا بِـ(مِنْ جِهَهْ) / كَـ(أَنْتَ أَعْلَىٰ خُلُقًا وَأَبْهَهْ)"},"segments":[{"body":["النوع الثاني: تمييز النسبة (الملفوظ/الملحوظ). ما معنى النسبة هنا؟","انظر: «طاب المؤمنُ نفْسًا». الفعل (طاب) معلوم، والمؤمن معلوم، لكن المبهم: نسبة الطيبة إلى المؤمن؛ من أي جهة هي؟","أمن جهة الخُلق؟ أم العلم؟ أم النَّفْس؟ فجاء «نفْسًا» يرفع الإبهام: طاب من جهة النفس.","فتمييز النسبة يقدَّر بـ(مِنْ جهةِ) كما قال الناظم، وإعرابه: تمييز منصوب بالفتحة."],"examples":["طابَ المؤمنُ نفْسًا — نفسًا: تمييز = من جهة النفس.","زَكَتْ حَنَّانُ خُلْقًا — من جهة الخلق.","اشْتَعَلَ الرأسُ شَيْبًا — من جهة الشيب.","أنا أجمل منك خُلْقًا — من جهة الخلق.","زيدٌ أكرمُ نَفْسًا — من جهة النفس.","هو أصدقُ لَهْجةً — من جهة اللهجة."],"questions":[{"question":"تمييز النسبة إبهامه في:","options":["نسبة الفعل إلى الشيء","مفرد العدد","الحرف","الضمير"],"answer":0,"explanation":"الإبهام في نسبة الفعل إلى الشيء: طاب المؤمن — من أي جهة طاب؟ فالتمييز يجيب: نفسًا = من جهة النفس."},{"question":"تقدير تمييز النسبة:","options":["مِنْ جهةِ","مَعَ","حالة كونه","الموصوف بأنه"],"answer":0,"explanation":"تمييز النسبة توضع قبله (من جهة): طاب المؤمن نفسًا = من جهة النفس، بخلاف تمييز الذات (من)."},{"question":"إعراب «نفسًا» في «طاب المؤمن نفسًا»:","options":["تمييز منصوب بالفتحة","مفعول به","حال","نعت"],"answer":0,"explanation":"نفسًا: اسم نكرة منصوب فسّر إبهام نسبة الطيبة إلى المؤمن؛ تمييز منصوب."},{"question":"«اشتعل الرأس شيبًا» — شيبًا تفيد:","options":["أن الاشتعال من جهة الشيب لا غيره","لون الرأس","مكان الاشتعال","زمن الاشتعال"],"answer":0,"explanation":"شيبًا: تمييز نسبة؛ فسّر أن إبهام الاشتعال من جهة الشيب: اشتعل شيبُ الرأس."},{"question":"أي جملة فيها تمييز نسبة؟","options":["زيدٌ أكرمُ نفسًا","عندي عشرون قلمًا","مضى عشرون رجلًا","ثلاثون يومًا"],"answer":0,"explanation":"زيد أكرم نفسًا: الإبهام في نسبة الكرم إلى زيد، فالتمييز من جهة؛ أما الباقي فتمييز ذات بعد أعداد."}]},{"body":["مثال البيت: «أنتَ أعلى خُلُقًا وأَبْهَهْ» أي: وأبهةً (عند الوقف تُحذف التنوين وتبقى الألف).","المعنى: أنت أعلى من غيرك من جهة الخُلق، وأعلى من جهة الأبهة والهيبة. فـ«خُلْقًا» و«أبهةً» تمييزان منصوبان.","ومن مواضع تمييز النسبة: الاسم المنصوب المحوَّل من الفاعل؛ تقول: «طاب زيدٌ نفسًا»، وأصلها: «طابتْ نفسُ زيدٍ».","فـ«نفسًا» هنا كان أصلها فاعلًا ثم حُوّلت إلى التمييز؛ ولهذا يسمى: المحوَّل من الفاعل."],"examples":["أنت أعلى خُلْقًا وأبهةً — خلقًا وأبهةً: تمييزان منصوبان بعد أعلى.","طاب زيدٌ نفسًا — أصلها: طابت نفسُ زيدٍ؛ نفسًا محوّل من الفاعل.","اشْتَعَلَ الرأسُ شَيْبًا — أصلها: اشتعل شيبُ الرأس.","قَرَّ أبي عَيْنًا — أصلها: قرّت عينُ أبي.","تَصَبَّبَ العاملُ عَرَقًا — أصلها: تصبّب عرقُ العامل.","ضاقَ به صَدْرًا — أصلها: ضاق صدرُه به."],"questions":[{"question":"«أنت أعلى خلقًا» — خلقًا تقديرها:","options":["من جهة الخلق","من الخلق","حالة كونه خلوقًا","مع الخلق"],"answer":0,"explanation":"خلقًا: تمييز نسبة منصوب؛ تقديره: أنت أعلى من جهة الخلق."},{"question":"«وأبْهَهْ» في آخر البيت تقديرها عند الوصل:","options":["وأبهةً","وأبهى","وأبها","وبهاء"],"answer":0,"explanation":"التنوين يحذف وقفًا وتبقى ألفه؛ والمعنى: وأعلى من جهة الأبهة؛ تمييز منصوب."},{"question":"المحوَّل من الفاعل يكون:","options":["تمييزًا منصوبًا","فاعلًا مرفوعًا","مفعولًا به","مبتدأ"],"answer":0,"explanation":"طاب زيد نفسًا: أصلها (طابت نفس زيد)؛ حُوّل الفاعل فصار تمييزًا منصوبًا."},{"question":"حوّلْ «قرّتْ عينُ أبي» إلى صيغة التمييز:","options":["قرَّ أبي عينًا","قرّت عينًا أبي","أبي قرَّ عينٌ","قرَّ عينُ أبي"],"answer":0,"explanation":"بحذف إضافة الاسم ونصبه: قرَّ أبي عينًا — عينًا: تمييز محوّل من الفاعل."},{"question":"«تصبّب العامل عرقًا» — عرقًا:","options":["تمييز منصوب محوّل من فاعل","مفعول به","حال","فاعل"],"answer":0,"explanation":"أصلها: تصبّب عرقُ العامل؛ فعرقًا: تمييز منصوب بالفتحة محوّل من الفاعل."}]}]},{"id":"wahi-verse-071","title":"مواضع انفرد بها التمييز","summary":"البيت الحادي والسبعون: التمييز بعد أفعل ونعم وبئس والمقادير، والفرق بين الحال والتمييز.","verse":{"number":71,"section":"التمييز","text":"وَانْفَرَدَ التَّمْيِيزُ بَعْدَ (أَفْعَلَا) / كَذَا الْمَقَادِيرُ، وَجَا مُحَوَّلَا"},"segments":[{"body":["«انفرد التمييز بعد أفعل»؛ أي: تفرّد التمييز دون سائر المنصوبات بمجيئه بعد اسم التفضيل (أفعل).","مثل: «السيفُ أصدقُ أنباءً من الكتبِ» و«العلمُ أشرفُ نسبًا من المالِ».","فـ«أنباءً» و«نسبًا» تمييزان منصوبان: أصدق من جهة الأنباء، وأشرف من جهة النسبة.","ومثل اسم التفضيل في ذلك فعلا المدح والذم (نِعْمَ وبِئْسَ): «نِعْمَ رجلًا زيدٌ» و«بِئْسَ خُلْقًا العَجَبُ»."],"examples":["السيفُ أصدقُ أنباءً من الكتبِ — أنباءً: تمييز بعد أصدق.","العلمُ أشرفُ نسبًا من المالِ — نسبًا: تمييز بعد أشرف.","نِعْمَ رجلًا زيدٌ — رجلًا: تمييز بعد نعم.","بِئْسَ خُلْقًا العَجَبُ — خلقًا: تمييز بعد بئس.","أنتَ أحسنُ عملًا — عملًا: تمييز بعد أفعل.","هي أجملُ روحًا — روحًا: تمييز بعد أفعل."],"questions":[{"question":"انفرد التمييز بالمجيء بعد:","options":["اسم التفضيل (أفعل) ونعم وبئس","الفاعل","حرف الجر","المبتدأ"],"answer":0,"explanation":"التمييز يأتي بعد اسم التفضيل: العلم أشرف نسبًا، وبعد نعم وبئس: نعم رجلًا زيد."},{"question":"إعراب «أنباءً» في «السيف أصدق أنباءً من الكتب»:","options":["تمييز منصوب بالفتحة","مفعول به","حال","مضاف إليه"],"answer":0,"explanation":"أنباءً: اسم نكرة منصوب بعد اسم التفضيل أصدق؛ فسّر جهة الصدق؛ تمييز."},{"question":"«نِعْمَ رجلًا زيدٌ» — رجلًا:","options":["تمييز منصوب بعد نعم","فاعل","مفعول به","نعت"],"answer":0,"explanation":"رجلًا: تمييز منصوب بعد فعل المدح نعم، وزيد: فاعل نعم."},{"question":"معنى «العلم أشرف نسبًا من المال»:","options":["العلم أشرف من المال من جهة النسبة","العلم أكثر من المال","نسبة العلم للمال","المال أشرف"],"answer":0,"explanation":"نسبًا: تمييز من جهة؛ فالشرف في نسب العلم وذريته لا في عينه."},{"question":"لماذا قيل «انفرد» التمييز بعد أفعل؟","options":["لأنه تفرّد بهذا الموضع دون سائر المنصوبات","لأنه مفرد","لأنه معرفة","لأنه لا ينصب"],"answer":0,"explanation":"لا يأتي بعد اسم التفضيل مفعول ولا حال؛ بل التمييز وحده: أصدق أنباءً."}]},{"body":["وموضع آخر للتمييز: المقادير؛ سواء دلت على وزنٍ أو كيلٍ أو مساحةٍ أو ذرع.","تقول: «تصدّقْ بصاعٍ أرزًا» و«اشتريتُ ذراعًا قماشًا» و«رغبتُ في كِيلٍ عسلًا»؛ فالمنصوب بعد المقدار تمييز.","وتقديرها بـ(مِنْ): صاع من الأرز، ذراع من القماش.","وأخيرًا الفرق المهم بين الحال والتمييز: الحال وصفٌ على معنى (حالة كونه): «جاء أوس ضاحكًا»، والتمييز جامد على معنى (مِنْ): «عشرون رجلًا»."],"examples":["تصدّقْ بصاعٍ أرزًا — أرزًا: تمييز بعد مقدار كيلي.","اشتريتُ ذراعًا قماشًا — قماشًا: تمييز بعد مقدار طولي.","رغبتُ في كيلٍ عسلًا — عسلًا: تمييز.","عندي صاعٌ تمرًا — تمرًا: تمييز.","جاء أوسٌ ضاحكًا — حال (وصف: حالة كونه) لا تمييز.","عشرون رجلًا — تمييز (جامد على معنى من) لا حال."],"questions":[{"question":"المقادير التي يأتي التمييز بعدها تشمل:","options":["الوزن والكيل والمساحة والذرع","الألوان","الأفعال","الضمائر"],"answer":0,"explanation":"المنصوب بعد المقدار تمييز: صاع أرزًا، ذراع قماشًا؛ سواء دل على وزن أو كيل أو مساحة."},{"question":"«اشتريتُ ذراعًا قماشًا» — قماشًا تقديرها:","options":["من القماش","حالة كونه قماشًا","في القماش","على القماش"],"answer":0,"explanation":"قماشًا: تمييز ذات منصوب على معنى (من): ذراع من القماش."},{"question":"الفرق بين الحال والتمييز من حيث اللفظ:","options":["الحال وصف يدل على صفة، والتمييز جامد لا صفة فيه","كلاهما وصف","كلاهما جامد","الحال جامد والتمييز وصف"],"answer":0,"explanation":"الحال يكون بالوصف (ضاحكًا)، والتمييز بالجامد (رجلًا، قماشًا) الذي لا يدل على صفة."},{"question":"الفرق بينهما من حيث المعنى:","options":["الحال على معنى (حالة كونه) والتمييز على معنى (من)","كلاهما على معنى من","كلاهما على معنى حالة كونه","لا فرق"],"answer":0,"explanation":"جاء أوس ضاحكًا = حالة كونه ضاحكًا؛ وعشرون رجلًا = عشرون من الرجال."},{"question":"«جاء القومُ فرحينَ» — فرحين: حال أم تمييز؟","options":["حال؛ لأنه وصف على معنى حالة كونه","تمييز؛ لأنه منصوب","تمييز؛ لأنه نكرة","حال؛ لأنه جامد"],"answer":0,"explanation":"فرحين: وصف نكرة بعد معرفة على معنى حالة كونه؛ حال منصوبة بالياء، وليست تمييزًا لأنها ليست على معنى من."}]}]},{"id":"wahi-verse-072","title":"المستثنى التام المثبت","summary":"البيت الثاني والسبعون: أركان الاستثناء وأدواته، ووجوب نصب المستثنى في التام المثبت.","verse":{"number":72,"section":"المستثنى","text":"إِنْ تَمَّتِ الْأَرْكَانُ فِي الْمُسْتَثْنَىٰ / فَانْصِبْهُ مُثْبَتًا، كَـ(إِلَّا سِنًّا)"},"segments":[{"body":["باب جديد: المستثنى. وهو اسمٌ يقع بعد أداة استثناء؛ مثل: «جاء الضيوف إلا سهلًا».","ولأسلوب الاستثناء ثلاثة أركان: مستثنًى منه (الضيوف)، وأداة (إلا)، ومستثنًى (سهلًا).","وأدوات الاستثناء: (إلَّا) وهي حرف، و(غير وسوى) وهما اسمان، و(عدا وخلا وحاشا) وتكون حرفي جر وأفعالًا ماضية.","والمستثنى منه يكون اسمًا ظاهرًا (جاء الضيوف إلا سهلًا)، وضميرًا بارزًا (جاؤوا إلا سهلًا)، وضميرًا مستترًا (سنسافر إلا سهلًا؛ أي: نحن)."],"examples":["جاء الضيوفُ إلا سهلًا — الضيوف: مستثنى منه ظاهر، وإلا: أداة، وسهلًا: مستثنى.","جاؤوا إلا سهلًا — المستثنى منه: واو الجماعة (ضمير بارز).","سنسافرُ إلا سهلًا — المستثنى منه: ضمير مستتر (نحن).","قرأتُ القرآنَ إلا جزءًا — جزءًا: مستثنى منصوب.","مررتُ بالفصولِ إلا فصلَينِ — فصلين: مستثنى منصوب بالياء.","الطلابُ ناجحونَ إلا المهملينَ — المهملين: مستثنى منصوب بالياء."],"questions":[{"question":"المستثنى هو:","options":["اسم يقع بعد أداة استثناء","اسم قبل إلا","حرف استثناء","الفعل قبل إلا"],"answer":0,"explanation":"المستثنى: اسم يقع بعد أداة الاستثناء: جاء الضيوف إلا سهلًا — سهلًا: مستثنى منصوب."},{"question":"أركان أسلوب الاستثناء الثلاثة:","options":["مستثنى منه، وأداة، ومستثنى","فعل وفاعل ومفعول","مبتدأ وخبر وحرف","نعت وحال وتمييز"],"answer":0,"explanation":"الأركان: المستثنى منه (الضيوف)، الأداة (إلا)، المستثنى (سهلًا)."},{"question":"أدوات الاستثناء:","options":["إلا، غير وسوى، عدا وخلا وحاشا","إن وأن","من وإلى","كان وأخواتها"],"answer":0,"explanation":"إلا حرف، وغير وسوى اسمان، وعدا وخلا وحاشا تكون حرفي جر وأفعالًا ماضية."},{"question":"المستثنى منه يكون:","options":["اسمًا ظاهرًا وضميرًا بارزًا وضميرًا مستترًا","اسمًا ظاهرًا فقط","ضميرًا فقط","حرفًا"],"answer":0,"explanation":"جاء الضيوف إلا سهلًا (ظاهر)، جاؤوا إلا سهلًا (بارز)، سنسافر إلا سهلًا (مستتر: نحن)."},{"question":"في «جاؤوا إلا سهلًا» المستثنى منه:","options":["واو الجماعة","سهلًا","إلا","جاؤوا"],"answer":0,"explanation":"المستثنى منه هنا ضمير بارز هو واو الجماعة في جاؤوا، وسهلًا: مستثنى منصوب."}]},{"body":["الاستثناء التام المثبت: ما تمّت أركانُه الثلاثة ولم يسبق بنفيٍ ولا نهيٍ ولا استفهام.","وحكمه كما قال الناظم: «فانصبه مثبتًا»؛ يجب نصب المستثنى فيه وجوبًا.","فنقول: «سافر الإخوةُ إلا وهبًا»، و«قرأتُ القرآنَ إلا جزءًا»، و«جاء الطلابُ إلا أخاكَ».","ولاحظ علامات النصب المختلفة: الفتحة في المفرد (وهبًا)، والياء في المثنى والجمع (فصلَينِ، المهملين)، والألف في أخوك من الأسماء الخمسة."],"examples":["سافر الإخوةُ إلا وهبًا — وهبًا: مستثنى منصوب بالفتحة وجوبًا.","الطلابُ ناجحونَ إلا المهملينَ — المهملين: مستثنى منصوب بالياء.","قرأتُ القرآنَ إلا جزءًا — جزءًا: مستثنى منصوب بالفتحة.","مررتُ بالفصولِ إلا فصلَينِ — فصلين: مستثنى منصوب بالياء للتثنية.","جاء الطلابُ إلا أخاكَ — أخاك: مستثنى منصوب بالألف لأنه من الأسماء الخمسة.","حضر الضيوفُ إلا واحدًا — واحدًا: مستثنى منصوب."],"questions":[{"question":"الاستثناء التام المثبت هو:","options":["ما تمّت أركانه ولم يسبق بنفي ولا نهي ولا استفهام","ما سبق بنفي","ما حذفت أداته","ما كان بعد سؤال"],"answer":0,"explanation":"التام المثبت: تام الأركان غير منفي؛ وحكمه وجوب نصب المستثنى: سافر الإخوة إلا وهبًا."},{"question":"حكم المستثنى في التام المثبت:","options":["النصب وجوبًا","الرفع وجوبًا","الجر وجوبًا","يجوز الوجهان"],"answer":0,"explanation":"قال الناظم: فانصبه مثبتًا؛ فينصب المستثنى وجوبًا: قرأت القرآن إلا جزءًا."},{"question":"إعراب «المهملينَ» في «الطلاب ناجحون إلا المهملينَ»:","options":["مستثنى منصوب وعلامة نصبه الياء","نعت مرفوع","حال","بدل مرفوع"],"answer":0,"explanation":"المهملين: مستثنى منصوب وجوبًا، وعلامة نصبه الياء لأنه جمع مذكر سالم."},{"question":"لماذا نُصبت «أخاكَ» بالألف في «جاء الطلاب إلا أخاكَ»؟","options":["لأنها من الأسماء الخمسة","لأنها مفرد","لأنها مثنى","لأنها جمع"],"answer":0,"explanation":"أخوك من الأسماء الخمسة؛ تُنصب بالألف: أخاكَ: مستثنى منصوب وجوبًا في التام المثبت."},{"question":"«فصلَينِ» في «مررت بالفصول إلا فصلين» نُصبت بـ:","options":["الياء لأنها مثنى","الفتحة","الكسرة","الألف"],"answer":0,"explanation":"فصلين: مستثنى منصوب بالياء لأنه مثنى، والنصب هنا واجب؛ لأن الاستثناء تام مثبت."}]}]},{"id":"wahi-verse-073","title":"المستثنى بعد النفي: وجهان","summary":"البيت الثالث والسبعون: الاستثناء التام المنفي يجوز فيه النصب على الاستثناء أو البدل من المستثنى منه.","verse":{"number":73,"section":"المستثنى","text":"وَبَعْدَ نَفْيِهِ لَهُ وَجْهَانِ / كَـ(مَا أَتَوْا إِلَّا الْمُوَجَّهَانِ)"},"segments":[{"body":["إذا كان الاستثناء تام الأركان لكنه مسبوق بنفي: «ما سافر الإخوةُ إلا وهبٌ» — فالحكم يتغير!","قال الناظم: «وبعد نفيه له وجهان»: يجوز في المستثنى بعد النفي التام وجهان.","الوجه الأول: النصب على الاستثناء: «ما سافر الإخوةُ إلا وهبًا» — وهبًا: مستثنى منصوب.","والوجه الثاني: البدل من المستثنى منه فيتبعه في إعرابه: «ما سافر الإخوةُ إلا وهبٌ» — وهبٌ: بدل من الإخوة مرفوع."],"examples":["ما سافر الإخوةُ إلا وهبٌ — وهبٌ: بدل من الإخوة مرفوع.","ما سافر الإخوةُ إلا وهبًا — وهبًا: مستثنى منصوب.","لم ينجحِ الطلابُ إلا المجتهدُونَ — بدل مرفوع.","لم ينجحِ الطلابُ إلا المجتهدِينَ — مستثنى منصوب.","ما قرأتُ الكتابَ إلا بابًا — بابًا: بدل من الكتاب منصوب، أو مستثنى منصوب.","ما مررتُ بالفصولِ إلا فصلَينِ — بدل مجرور بالفصول، أو مستثنى منصوب بالياء."],"questions":[{"question":"في الاستثناء التام المنفي يجوز في المستثنى:","options":["وجهان: النصب على الاستثناء أو البدل","النصب وجوبًا فقط","الرفع وجوبًا فقط","الجر"],"answer":0,"explanation":"بعد النفي التام: ما سافر الإخوة إلا وهبٌ (بدل مرفوع) أو وهبًا (مستثنى منصوب)."},{"question":"«ما سافر الإخوةُ إلا وهبٌ» — وهبٌ:","options":["بدل من الإخوة مرفوع","مستثنى منصوب","نعت","حال"],"answer":0,"explanation":"وهبٌ بالرفع: بدل من المستثنى منه (الإخوة) يتبعه في إعرابه المرفوع."},{"question":"«لم ينجح الطلابُ إلا المجتهدينَ» — المجتهدين:","options":["مستثنى منصوب وعلامة نصبه الياء","بدل مرفوع","نعت","فاعل"],"answer":0,"explanation":"المجتهدين بالياء: مستثنى منصوب على الاستثناء؛ ولو قلت المجتهدون لكان بدلًا مرفوعًا."},{"question":"متى يجوز إعراب المستثنى بدلًا من المستثنى منه؟","options":["في الاستثناء التام المنفي","في التام المثبت","في الناقص","أبدًا"],"answer":0,"explanation":"البدل يتبع المستثنى منه في إعرابه، ولا يجوز إلا بعد نفي أو نهي أو استفهام مع تمام الأركان."},{"question":"«ما مررتُ بالفصول إلا فصلَينِ» — يجوز أن يكون فصلين:","options":["بدلًا مجرورًا من الفصول أو مستثنى منصوبًا","بدلًا فقط","مستثنى فقط","نعتًا"],"answer":0,"explanation":"فصلين بالياء تحتمل وجهين: بدل مجرور من (الفصول) — والياء علامة جر المثنى — أو مستثنى منصوب — والياء علامة نصبه."}]},{"body":["مثال البيت: «ما أتَوْا إلا الموجَّهانِ». لاحظ الألف في آخره!","المستثنى منه هنا: واو الجماعة في «أتوا» (مرفوع). فإذا أردنا البدل قلنا: «الموجَّهانِ» بالألف؛ لأنه مثنى مرفوع يتبع الواو.","وإذا أردنا الوجه الثاني (النصب على الاستثناء) قلنا: «الموجَّهَيْنِ» بالياء؛ لأن المثنى يُنصب بالياء.","فالمثنى هنا يكشف الوجهين كشفًا ظاهرًا: ألفٌ للبدل المرفوع، وياءٌ للمستثنى المنصوب."],"examples":["ما أتَوْا إلا الموجَّهانِ — بالألف: بدل مرفوع من واو الجماعة.","ما أتَوْا إلا الموجَّهَيْنِ — بالياء: مستثنى منصوب.","ما حضر المعلمونَ إلا المخلصانِ — بدل مرفوع.","ما حضر المعلمونَ إلا المخلصينِ — مستثنى منصوب.","ما قرأ الطلابُ إلا البارعانِ — بدل مرفوع.","ما نجح الفريقُ إلا المجتهدَيْنِ — مستثنى منصوب."],"questions":[{"question":"«ما أتوا إلا الموجَّهانِ» — الموجَّهانِ إعرابه:","options":["بدل من واو الجماعة مرفوع وعلامة رفعه الألف","مستثنى منصوب","نعت","فاعل"],"answer":0,"explanation":"الموجَّهانِ بالألف: بدل مرفوع من الواو في (أتوا)؛ لأن المثنى يُرفع بالألف."},{"question":"لو قلنا: «ما أتوا إلا الموجَّهَيْنِ» لكان إعرابها:","options":["مستثنى منصوب وعلامة نصبه الياء","بدل مرفوع","نعت مجرور","حال"],"answer":0,"explanation":"بالياء: مستثنى منصوب على الاستثناء؛ لأن المثنى يُنصب ويُجر بالياء."},{"question":"علامة رفع المثنى:","options":["الألف","الياء","الضمة","الواو"],"answer":0,"explanation":"المثنى يُرفع بالألف: الموجَّهانِ، ويُنصب ويُجر بالياء: الموجَّهَيْنِ."},{"question":"المستثنى منه في «ما أتوا إلا الموجَّهانِ»:","options":["واو الجماعة في أتوا","الموجَّهانِ","إلا","ما"],"answer":0,"explanation":"أتوا: فعل ماضٍ والواو ضمير بارز في محل رفع فاعل، وهو المستثنى منه الذي اتبعه البدل."},{"question":"أي صيغة تعرب بدلًا مرفوعًا؟","options":["ما حضر المعلمون إلا المخلصانِ","ما حضر المعلمون إلا المخلصينِ","حضر المعلمون إلا المخلصينِ","حضر المعلمون إلا المخلصانِ"],"answer":0,"explanation":"بعد النفي مع الألف للمثنى: المخلصانِ: بدل مرفوع؛ والمخلصين: مستثنى منصوب."}]}]},{"id":"wahi-verse-074","title":"الاستثناء الناقص: الحصر","summary":"البيت الرابع والسبعون: الاستثناء الناقص يفيد الحصر، ويُعرب المستثنى فيه بإعراب ما قبل إلا.","verse":{"number":74,"section":"المستثنى","text":"وَنَاقِصٌ حَصْرٌ، كَأَنَّ (إِلَّا) / حَذْفٌ، كَـ(مَا أَسِيرُ إِلَّا لَيْلًا)"},"segments":[{"body":["النوع الثالث: الاستثناء الناقص؛ وهو ناقص الأركان لعدم وجود المستثنى منه فيه، ولا يكون إلا منفيًّا.","انظر: «ما سافر وهبٌ» — لم يُذكر مستثنى منه! فمن الذي لم يسافر؟ غير مذكور. والمعنى: لم يُسافر أحدٌ سوى وهب.","وهذا النوع يفيد الحصر كما قال الناظم: «وناقصٌ حصرٌ»؛ أي: قصر الفعل على المستثنى وحده.","وحكمه: «كأن إلا حذفٌ»؛ يُعرب المستثنى بإعراب ما قبل إلا كأنها ليست: «ما سافر وهبٌ» = سافر وهبٌ (فاعل)، و«ما رأيتُ إلا سهلًا» = رأيتُ سهلًا (مفعول به)."],"examples":["ما سافر وهبٌ — وهب: فاعل مرفوع؛ كقولك: سافر وهب.","ما رأيتُ إلا سهلًا — سهلًا: مفعول به منصوب؛ مثل: رأيتُ سهلًا.","ما أخي إلا سهلٌ — سهل: خبر مرفوع؛ مثل: أخي سهل.","ما قرأتُ إلا سورةً — سورةً: مفعول به.","ما حضر إلا الطالبُ — الطالب: فاعل مرفوع.","ما نجح إلا المجتهدُ — المجتهد: فاعل."],"questions":[{"question":"الاستثناء الناقص هو:","options":["ناقص الأركان لعدم وجود المستثنى منه، ولا يكون إلا منفيًّا","تام الأركان مثبت","ما حذفت أداته","ما كان بغير"],"answer":0,"explanation":"الناقص: لا مستثنى منه فيه ولا يكون إلا منفيًّا: ما سافر وهبٌ — وهب: فاعل كأن إلا محذوفة."},{"question":"الاستثناء الناقص يفيد:","options":["الحصر","التعظيم","التقليل","التشبيه"],"answer":0,"explanation":"قال الناظم: وناقص حصر؛ فمعنى (ما سافر وهب): حصر السفر في وهب وحده."},{"question":"حكم إعراب المستثنى في الناقص:","options":["يُعرب بإعراب ما قبل إلا كأنها محذوفة","ينصب وجوبًا","يرفع وجوبًا","يجر وجوبًا"],"answer":0,"explanation":"ما رأيت إلا سهلًا = رأيت سهلًا: مفعول به؛ وما سافر وهب = سافر وهب: فاعل."},{"question":"«ما أخي إلا سهلٌ» — سهلٌ:","options":["خبر مرفوع","مفعول به","فاعل","حال"],"answer":0,"explanation":"كأن إلا محذوفة: أخي سهل — سهل: خبر مرفوع بالضمة."},{"question":"«ما حضر إلا الطالبُ» — الطالبُ:","options":["فاعل مرفوع","مستثنى منصوب","بدل","مفعول به"],"answer":0,"explanation":"حذفنا إلا تقديرًا: حضر الطالب — الطالب: فاعل مرفوع بالضمة؛ والمعنى: لم يحضر سواه."}]},{"body":["مثال البيت: «ما أسيرُ إلا ليلًا». ما إعراب «ليلًا»؟","احذف «إلا» تقديرًا: «ما أسيرُ ليلًا»؛ فتجدها ظرف زمان منصوبًا.","فالمعنى: لا أسير إلا في الليل؛ حُصِر السير في الليل وحده.","ومثله: «ما سافر وهبٌ إلا خائفًا»؛ خائفًا: حال منصوبة، كقولك: سافر وهب خائفًا. فكل ما بعد إلا في الناقص يأخذ حكم ما لو لم تكن إلا موجودة."],"examples":["ما أسيرُ إلا ليلًا — ليلًا: ظرف زمان منصوب؛ التقدير: ما أسير ليلًا.","ما سافر وهبٌ إلا خائفًا — خائفًا: حال؛ مثل: سافر وهب خائفًا.","ما جلستُ إلا صباحًا — صباحًا: ظرف زمان.","ما قرأتُ إلا متأدبًا — متأدبًا: حال منصوبة.","ما كلمتُه إلا قائمًا — قائمًا: حال.","ما شاهدتُه إلا مبتسمًا — مبتسمًا: حال."],"questions":[{"question":"«ما أسير إلا ليلًا» — ليلًا:","options":["ظرف زمان منصوب","مفعول به","تمييز","حال"],"answer":0,"explanation":"كأن إلا محذوفة: ما أسير ليلًا — ليلًا: ظرف زمان منصوب بالفتحة؛ والمعنى: حصر السير في الليل."},{"question":"«ما سافر وهب إلا خائفًا» — خائفًا:","options":["حال منصوبة","مفعول به","تمييز","نعت"],"answer":0,"explanation":"التقدير: سافر وهب خائفًا — خائفًا: حال منصوبة؛ لأن المستثنى يعرب بإعراب ما قبل إلا."},{"question":"المعنى الذي يفيده «ما أسير إلا ليلًا»:","options":["حصر السير في الليل وحده","السير في الليل والنهار","نفي السير مطلقًا","المدح"],"answer":0,"explanation":"الاستثناء الناقص يفيد الحصر: لا سير إلا ليلًا؛ أي: قُصر الفعل على المستثنى."},{"question":"لماذا قال الناظم «كأن إلا حذفٌ»؟","options":["لأن المستثنى يأخذ إعراب موقعه لو حذفت إلا","لأن إلا تحذف لفظًا","لأن إلا زائدة","لأن الناقص لا أداة له"],"answer":0,"explanation":"نعامل الجملة كأن إلا غير موجودة: ما أسير ليلًا (ظرف)؛ فإلا موجودة لفظًا ومحذوفة حكمًا."},{"question":"«ما كلمتُه إلا قائمًا» — قائمًا:","options":["حال منصوبة بالفتحة","مفعول به","ظرف","نعت"],"answer":0,"explanation":"التقدير: كلمته قائمًا — قائمًا: حال منصوبة؛ فالقاعدة: أعرب ما بعد إلا كما لو لم تكن."}]}]},{"id":"wahi-verse-075","title":"الاستثناء بغير وسوى","summary":"البيت الخامس والسبعون: المستثنى بعد غير وسوى يُعرب مضافًا إليه مجرورًا دائمًا.","verse":{"number":75,"section":"المستثنى","text":"وَبَعْدَ (غَيْرِ، وَسِوَىٰ) مُجْرُورُ / كَـ(النَّاسُ غَيْرَ خَالِدٍ تَدُورُ)"},"segments":[{"body":["غير وسوى أداتا استثناء، وهما اسمان لا حرفان، ولذلك لهما حكم خاص.","المستثنى بعدهما يُعرب مضافًا إليه مجرورًا دائمًا كما قال الناظم: «وبعد غير وسوى مجرور».","فنقول: «جاء الطلابُ غيرَ وهبٍ» — وهبٍ: مضاف إليه مجرور بالكسرة، و«غيرَ» مستثنى منصوب وهو مضاف.","وأما «غير» و«سوى» نفسهما فيُعربان بإعراب ما بعد إلا: فبعد التام المثبت: مستثنى منصوب، وبعد المنفي: يجوز النصب أو البدل، وبعد الناقص: بإعراب ما قبلها."],"examples":["جاء الطلابُ غيرَ وهبٍ — وهب: مضاف إليه مجرور؛ وغير: مستثنى منصوب مضاف.","ما سافروا غيرَ وهبٍ — غير: مستثنى منصوب بعد نفي.","ما سافروا غيرُ وهبٍ — غير: بدل من واو الجماعة مرفوع.","ما سارَ غيرُ وهبٍ — غير: فاعل مرفوع (استثناء ناقص).","قرأتُ الكتبَ سوى القصصِ — القصص: مضاف إليه مجرور.","حضر الجميعُ سوى أخيكَ — أخيك: مضاف إليه مجرور."],"questions":[{"question":"حكم المستثنى بعد غير وسوى:","options":["يُعرب مضافًا إليه مجرورًا دائمًا","يُنصب دائمًا","يُرفع دائمًا","يجوز فيه الوجهان"],"answer":0,"explanation":"قال الناظم: وبعد غير وسوى مجرور؛ جاء الطلاب غير وهبٍ — وهب: مضاف إليه مجرور بالكسرة."},{"question":"غير وسوى نوعهما:","options":["اسمان يُعربان بإعراب ما بعد إلا","حرفان","فعلان","حرفا جر"],"answer":0,"explanation":"غير وسوى اسمان؛ لذلك يجرّ ما بعدهما على الإضافة، ويُعربان حسب موقعهما: مستثنى أو بدلًا أو فاعلًا."},{"question":"«جاء الطلاب غيرَ وهبٍ» — غيرَ:","options":["مستثنى منصوب وهو مضاف","حرف جر","نعت","مضاف إليه"],"answer":0,"explanation":"غير: مستثنى منصوب بالفتحة وهو مضاف، ووهب: مضاف إليه مجرور بالكسرة."},{"question":"«ما سار غيرُ وهبٍ» — غيرُ:","options":["فاعل مرفوع","مستثنى منصوب","بدل","مفعول به"],"answer":0,"explanation":"استثناء ناقص: لم يُذكر مستثنى منه؛ فغير: فاعل مرفوع بالضمة وهو مضاف، ووهب: مضاف إليه."},{"question":"«ما سافروا غيرُ وهبٍ» — غيرُ يجوز أن تكون:","options":["بدلًا من واو الجماعة مرفوعًا","فاعلًا","مفعولًا به","حالًا"],"answer":0,"explanation":"بعد النفي وجهان: غيرَ (مستثنى منصوب) أو غيرُ (بدل مرفوع من الواو)."}]},{"body":["مثال البيت: «الناسُ غيرَ خالدٍ تدورُ» أي: تدور الناس وتتقلب في أحوالها إلا خالد.","«غيرَ»: مستثنى منصوب وهو مضاف، و«خالدٍ»: مضاف إليه مجرور بالكسرة — وهذا هو الحكم الثابت بعد غير وسوى.","و«سوى» مثل «غير» تمامًا في الحكم: «حضر الجميع سوى أخيك».","فاحفظ: ما بعد غير وسوى مجرور على الإضافة أبدًا، والاختلاف إنما هو في إعراب غير وسوى نفسيهما حسب نوع الاستثناء."],"examples":["الناسُ غيرَ خالدٍ تدورُ — خالد: مضاف إليه مجرور، وغير: مستثنى منصوب مضاف.","حضر الجميعُ سوى أخيكَ — سوى: مستثنى منصوب مضاف، وأخيك: مضاف إليه.","سافر الأهلُ غيرَ أمي — أمي: مضاف إليه مجرور.","قرأتُ الدرسَ سوى التمرينِ — التمرين: مضاف إليه.","نجح الطلابُ غيرَ المهملِ — المهمل: مضاف إليه مجرور.","ذاكر الجميعُ سوى الكسولِ — الكسول: مضاف إليه."],"questions":[{"question":"«الناس غيرَ خالدٍ تدور» — خالدٍ:","options":["مضاف إليه مجرور وعلامة جره الكسرة","مستثنى منصوب","فاعل","نعت"],"answer":0,"explanation":"المستثنى بعد غير وسوى مجرور على الإضافة دائمًا: خالدٍ: مضاف إليه مجرور."},{"question":"«غيرَ» في مثال البيت إعرابها:","options":["مستثنى منصوب وهو مضاف","حرف جر مبني","مضاف إليه","فاعل"],"answer":0,"explanation":"غير: مستثنى منصوب بالفتحة وهو مضاف، وما بعدها مضاف إليه مجرور."},{"question":"«سوى» حكمها:","options":["مثل غير تمامًا","حرف جر","أقل من غير","لا يستثنى بها"],"answer":0,"explanation":"سوى أداة استثناء اسم مثل غير: حضر الجميع سوى أخيك — أخيك: مضاف إليه مجرور."},{"question":"معنى «الناس غير خالد تدور»:","options":["تدور الناس وتتقلب إلا خالد","يدور خالد مع الناس","الناس لا يدورون","خالد يدور وحده"],"answer":0,"explanation":"المعنى: كل الناس يتقلبون في الأحوال إلا خالد؛ وخالد: مضاف إليه مجرور بعد غير."},{"question":"«قرأت الكتب سوى القصصِ» — القصصِ:","options":["مضاف إليه مجرور","مستثنى منصوب","مفعول به","نعت"],"answer":0,"explanation":"بعد سوى يجر الاسم على الإضافة: القصص: مضاف إليه مجرور بالكسرة، وسوى: مستثنى منصوب مضاف."}]}]},{"id":"wahi-verse-076","title":"الاستثناء بـ«عدا وخلا وحاشا»","summary":"البيت السادس والسبعون: حكم الاسم بعد عدا وخلا وحاشا؛ يجوز جره ونصبه.","verse":{"number":76,"section":"الاستثناء","text":"بَعْدَ (عَدَا، ثُمَّ خَلَا، وَحَاشَا) / جَرٌّ وَنَصْبٌ، كَـ(عَدَا فِرَاشَا)"},"segments":[{"body":["لفظًا لفظًا: «بَعْدَ» أي: بعد استعمال هذه الأدوات الثلاث. «عَدَا» أداة استثناء معناها: غير. «ثُمَّ» حرف عطف للترتيب. «خَلَا» أداة ثانية معناها أيضًا: غير. «وَحَاشَا» أداة ثالثة معناها: غير، وتستعمل كثيرًا للتنزيه نحو: حاشا لله.","في الدرس الماضي تعلمنا الاستثناء بـ«إلا». وهناك ثلاث كلمات أخرى تعمل عملها، وهي: «عَدَا» و«خَلَا» و«حَاشَا»، وكلها بمعنى: غير. فتقول: حضر الطلاب عدا زيدٍ، أي: غير زيد.","وحكم الاسم الذي يقع بعدها: يجوز فيه وجهان: الجر، والنصب. فتقول بالجر: حضر الطلابُ عدا زيدٍ. وبالنصب: حضر الطلابُ عدا زيدًا. وكلاهما صحيح.","ما السر في ذلك؟ لأن هذه الكلمات لها شبهٌ من حروف الجر وشبهٌ من الأفعال؛ فمن أجراها مجرى حرف الجر جرَّ ما بعدها، ومن أجراها مجرى الفعل الماضي نصب ما بعدها على أنه مفعول به."],"examples":["حضر الطلابُ عدا زيدٍ — زيدٍ: مستثنى مجرور.","حضر الطلابُ عدا زيدًا — زيدًا: مستثنى منصوب.","ما قرأتُ الكتابَ خلا بابًا — بابًا: مستثنى منصوب.","ما قرأتُ الكتابَ خلا بابٍ — بابٍ: مستثنى مجرور.","سافر الإخوةُ حاشا أحمدَ — أحمدَ: مستثنى منصوب.","نجح الجميعُ عدا كريمٍ — كريمٍ: مستثنى مجرور."],"questions":[{"question":"الأدوات الثلاث التي ذكرها البيت للاستثناء هي:","options":["عَدَا وخَلَا وحَاشَا","إلا وغير وسوى","ليس ولعل وكأن","من وإلى وعن"],"answer":0,"explanation":"قال الناظم: بعد عدا ثم خلا وحاشا؛ وكلها بمعنى (غير) وتفيد الاستثناء مثل إلا."},{"question":"حكم الاسم الواقع بعد (عدا وخلا وحاشا):","options":["يجوز جره ونصبه","يلزم جره دائمًا","يلزم نصبه دائمًا","يلزم رفعه دائمًا"],"answer":0,"explanation":"يجوز في المستثنى بعدها الجر والنصب: حضر الطلاب عدا زيدٍ / زيدًا."},{"question":"في «سافر الإخوة حاشا أحمدَ» إعراب «أحمدَ»:","options":["مستثنى منصوب وعلامة نصبه الفتحة","مفعول به منصوب","فاعل مرفوع","مضاف إليه مجرور"],"answer":0,"explanation":"أحمدَ مستثنى بحاشا منصوب بالفتحة، ويجوز أيضًا جره: حاشا أحمدَ."},{"question":"معنى (عدا) و(خلا) و(حاشا) جميعًا:","options":["غير","إلا بمعنى لكن","مع","مثل"],"answer":0,"explanation":"الثلاثة معناها (غير): حضر القوم عدا زيد أي غير زيد."},{"question":"لماذا جاز النصب بعد (عدا)؟","options":["لأنها تُشبه الفعل الماضي فينصب ما بعدها مفعولًا به","لأنها حرف نصب مثل إنّ","لأنها أداة جزم","لأنها حرف عطف"],"answer":0,"explanation":"عدا وخلا وحاشا تُجرى مجرى الفعل الماضي فاعله ضمير مستتر تقديره (هو)، فينصب ما بعدها مفعولًا به، ويجوز جرها مجرى حرف الجر."}]},{"body":["لفظًا لفظًا: «جَرٌّ وَنَصْبٌ» أي: الوجهان الجائزان في المستثنى بعدها: أن يُجرَّ أو يُنصب. «كَـ» أي: مثل. «عَدَا فِرَاشَا» مثال الناظم نفسه، والتقدير: ما رأيتُ عدا فراشًا، أو: ما رأيتُ عدا فراشٍ.","فمثال البيت: «عدا فراشا» يحتمل الوجهين: فتجرّ «فراش» بالكسرة على أن «عدا» حرف جر، أو تنصبها بالفتحة على أنها فعل ماضٍ.","وإذا عربتَ بالجر قلت: عدا: حرف جر مبني على السكون لا محل له من الإعراب، وفراشٍ: اسم مجرور وعلامة جره الكسرة.","وإذا عربتَ بالنصب قلت: عدا: فعل ماضٍ مبني على الفتح، فاعله ضمير مستتر تقديره (هو)، وفراشًا: مفعول به منصوب وعلامة نصبه الفتحة.","وهذا البيت آخر أحكام باب الاستثناء؛ فقد علمتَ أن المستثنى بـ(إلا) منصوب، وأن المستثنى بـ(عدا وخلا وحاشا) يجوز فيه الجر والنصب."],"examples":["ما حضر عدا فراشٍ — عدا: حرف جر، فراشٍ: اسم مجرور.","ما حضر عدا فراشًا — عدا: فعل ماضٍ، فراشًا: مفعول به منصوب.","أكلتُ الطعامَ خلا تمرًا — تمرًا: منصوب.","أكلتُ الطعامَ خلا تمرٍ — تمرٍ: مجرور.","قرأ الطلابُ حاشا غائبًا — غائبًا: منصوب.","جاء المصلون عدا متأخرٍ — متأخرٍ: مجرور."],"questions":[{"question":"إعراب (عدا) إذا جررتَ ما بعدها:","options":["حرف جر مبني لا محل له من الإعراب","فعل ماضٍ","اسم منصوب","حرف عطف"],"answer":0,"explanation":"على الجر تكون عدا حرف جر مبني على السكون لا محل له من الإعراب، وما بعدها اسم مجرور."},{"question":"إعراب (عدا) إذا نصبتَ ما بعدها:","options":["فعل ماضٍ فاعله ضمير مستتر تقديره (هو)","حرف جر","حرف نصب","أداة شرط"],"answer":0,"explanation":"على النصب تكون عدا فعلًا ماضيًا مبنيًا على الفتح، فاعله ضمير مستتر تقديره (هو)، وما بعدها مفعول به منصوب."},{"question":"مثال البيت «عدا فراشا» يحتمل:","options":["الجر والنصب معًا","الجر فقط","النصب فقط","الرفع والجر"],"answer":0,"explanation":"فراشًا: مفعول به منصوب، أو فراشٍ: اسم مجرور؛ وكلاهما جائز بعد عدا."},{"question":"في «ما قرأتُ الكتابَ خلا بابٍ» بابٍ:","options":["اسم مجرور بعد خلا التي هي حرف جر","مستثنى منصوب لا محل له","مضاف إليه فقط","فاعل مرفوع"],"answer":0,"explanation":"خلا هنا أُجريت مجرى حرف الجر، فبابٍ اسم مجرور وعلامة جره الكسرة، ويجوز: خلا بابًا."},{"question":"أي جملة صحيحة الوجهين بعد الأداة؟","options":["حضر القوم عدا زيدٍ / زيدًا","حضر القوم إلا زيدٍ","ما حضر إلا زيدٌ بالرفع وجه واحد دائمًا","حضر زيدٌ عدا القومِ"],"answer":0,"explanation":"بعد عدا وخلا وحاشا يجوز الجر والنصب؛ أما إلا فالمستثنى بعدها منصوب في التام المثبت."}]}]},{"id":"wahi-verse-077","title":"المنادى المفرد المعين: «يا مُهَيْمِنُ»","summary":"البيت السابع والسبعون: المنادى المفرد المعين مبني على الضم في محل نصب.","verse":{"number":77,"section":"المنادى","text":"هَذَا الْمُنَادَى الْمُفْرَدُ الْمُعَيَّنُ / أَضْمِمْهُ فِي مَحَلِّ، (يَا مُهَيْمِنُ)"},"segments":[{"body":["لفظًا لفظًا: «هَذَا» اسم إشارة للمفرد أي: هذا النوع الذي سنذكره. «الْمُنَادَى» أي: الاسم الذي تأتي قبله أداة النداء (يا) لطلب من تناديه. «الْمُفْرَدُ» أي: اسم واحد لا إضافة فيه. «الْمُعَيَّنُ» أي: معلوم شخصه، تعرف مَن هو بعينه.","عندما تريد أن تنادي أحدًا تقول: يا محمد! فـ«يا» اسمها أداة نداء، و«محمد» اسمها المنادى.","فإذا كان المنادى اسمًا واحدًا ومعيّنًا (تعرف من هو: علم كمحمد، أو نكرة قصدتَ بها شخصًا معلومًا نحو: يا رجلُ اتقِ الله) فحكمه: يُبنى على الضم.","معنى «يبنى على الضم»: يلزم آخره الضمة، لا تتغير بتغير موقعه في الجملة. وإن كان مثنى بُني على الألف: يا محمدانِ، وإن كان جمع مذكر سالمًا بُني على الواو: يا مسلمونَ."],"examples":["يا محمدُ تفضَّلْ — محمدُ: منادى مبني على الضم في محل نصب.","يا رجلُ اتقِ الله — نكرة مقصودة مبنية على الضم.","يا محمدانِ تعالَيا — مثنى مبني على الألف في محل نصب.","يا مسلمونَ اتحِدوا — جمع مذكر سالم مبني على الواو في محل نصب.","يا مهيمنُ — مثل البيت: علم مفرد مبني على الضم.","يا حاجُّ تفضَّلْ — منادى مفرد معين مبني على الضم."],"questions":[{"question":"المنادى المفرد المعين حكمه:","options":["مبني على الضم في محل نصب","منصوب بالفتحة دائمًا","مرفوع مبتدأ","مجرور بالإضافة"],"answer":0,"explanation":"مثل: يا محمدُ — منادى مبني على الضم في محل نصب."},{"question":"معنى (المعين) في المنادى:","options":["أنك تعرف شخص من تناديه بعينه","أي اسم نكرة","أي اسم مضاف","أي جمع"],"answer":0,"explanation":"المعين: معلوم شخصه، كالعلم (يا محمد) والنكرة المقصودة (يا رجلُ)."},{"question":"في «يا مسلمونَ اتحدوا» إعراب «مسلمونَ»:","options":["منادى مبني على الواو في محل نصب","منادى منصوب بالفتحة","فاعل مرفوع","مبتدأ مرفوع"],"answer":0,"explanation":"المنادى المعين الجمع مذكرًا سالمًا يبنى على الواو في محل نصب."},{"question":"في «يا محمدانِ تعالَيا» إعراب «محمدانِ»:","options":["منادى مبني على الألف في محل نصب","منادى منصوب بالياء","مفعول به","مضاف إليه"],"answer":0,"explanation":"المعين المثنى يبنى على الألف في محل نصب."},{"question":"إعراب أداة النداء (يا):","options":["حرف نداء مبني على السكون لا محل له من الإعراب","حرف جر","فعل أمر","اسم مبني في محل رفع"],"answer":0,"explanation":"(يا) حرف نداء مبني على السكون لا محل له من الإعراب، وما بعده منادى."}]},{"body":["لفظًا لفظًا: «أَضْمِمْهُ» أي: اجعل آخره مضمومًا (عليه ضمة). «فِي مَحَلِّ» أي: في تقدير موضعه الإعرابي. «يَا مُهَيْمِنُ» مثال الناظم: منادَى الله باسم من أسمائه الحسنى (المهيمن)، وهو علم مفرد.","فالناظم يقول: المنادى المفرد المعين اجعل آخره ضمًّا في محلِّ نصب. ومعنى «في محل نصب»: أن موضعه من الجملة موضع المنصوبات، لكنه مبني فلا تظهر عليه حركة النصب (الفتحة)، بل يلزم الضمة.","فلا تقل: يا محمدَ بالفتحة؛ لأن محمدًا علم مفرد معين. إنما الفتحة للنوع الثاني الذي يأتي في البيت التالي.","مثال من شرح المؤلف: «يا مهيمنُ يا محمدُ» — فالمهيمن ومحمد كلاهما منادى مبني على الضم في محل نصب.","والنكرة المقصودة تلحق به: يا طالبُ انتبهْ — إذا قصدتَ طالبًا معلومًا لك؛ فهي مبنية على الضم أيضًا."],"examples":["يا مهيمنُ يا محمدُ — كلاهما مبني على الضم في محل نصب.","يا طالبُ انتبهْ — نكرة مقصودة مبنية على الضم.","يا زيدُ أقبِلْ — علم مفرد مبني على الضم.","يا هندُ اقرئي — علم مفرد مبني على الضم.","يا رجلانِ اتقيا الله — مثنى مبني على الألف.","يا طلابُ هذا اختبارُكم — جمع مقصود مبني على الضم (على الصحيح)."],"questions":[{"question":"معنى قول الناظم «أضممْه في محل»:","options":["ابنِه على الضم وموضعه الإعرابي النصب","انصبْه بالفتحة","ارفعْه بالضمة مبتدأ","اجرُرْه بالكسرة"],"answer":0,"explanation":"المفرد المعين مبني على الضم في محل نصب؛ فالضمة بناء، ومحله من الإعراب النصب."},{"question":"«يا مهيمنُ» في مثال البيت: مهيمنُ:","options":["منادى مبني على الضم في محل نصب","منادى منصوب بالفتحة","مبتدأ مرفوع","فاعل مرفوع"],"answer":0,"explanation":"المهيمن علم مفرد معين، فيبنى على الضم في محل نصب."},{"question":"لماذا لا نقول «يا محمدَ» بالفتحة؟","options":["لأن المنادى المفرد المعين مبني على الضم لا معرب","لأن محمدًا ممنوع من الصرف","لأن الفتحة محرمة في النداء","لأن محمدًا جمع"],"answer":0,"explanation":"العلم المفرد المعين من المنادى مبني على الضم في محل نصب، والفتحة للمضاف والشبيه بالمضاف والنكرة غير المقصودة."},{"question":"النكرة المقصودة مثل «يا رجلُ اتقِ الله» حكمها:","options":["مبنية على الضم كالعلم المفرد","منصوبة بالفتحة","مجرورة بالكسرة","معربة بالرفع"],"answer":0,"explanation":"النكرة المقصودة (قصدتَ بها شخصًا معلومًا) تبنى على الضم في محل نصب."},{"question":"متى يُبنى المنادى على الواو؟","options":["إذا كان جمع مذكر سالمًا معينًا: يا مسلمونَ","إذا كان علمًا مفردًا","إذا كان مضافًا","إذا كان نكرة غير مقصودة"],"answer":0,"explanation":"الجمع المذكر السالم المعين يبنى على الواو في محل نصب: يا مسلمونَ اتحدوا."}]}]},{"id":"wahi-verse-078","title":"المنادى المنصوب: «يا ظَلُومَ نَفْسِهِ»","summary":"البيت الثامن والسبعون: ما عدا المفرد المعين من المنادى يكون منصوبًا معربًا.","verse":{"number":78,"section":"المنادى","text":"وَغَيْرُهُ الْمَنْصُوبُ يَأْتِي مُعْرَبًا / كَـ(يَا ظَلُومَ نَفْسِهِ﴿، يَا مُتْعَبَا)"},"segments":[{"body":["لفظًا لفظًا: «وَغَيْرُهُ» أي: وما عدا المنادى المفرد المعين. «الْمَنْصُوبُ» أي: حكمه النصب. «يَأْتِي مُعْرَبًا» أي: يكون معربًا، تتغير حركته مع موقعه، لا مبنيًا كالنوع الأول.","ما هو «غير المفرد المعين»؟ ثلاثة أنواع: (1) المضاف نحو: يا عبدَ الله. (2) الشبيه بالمضاف: اسم أُكمل بكلمة بعده بغير طريق الإضافة نحو: يا رحيمًا بالعباد. (3) النكرة غير المقصودة: تنادي أي أحد لا شخصًا بعينه نحو: يا طالبًا اجتهدْ.","هذه الثلاثة حكمها: منصوبة معربة. فتقول بالفتحة: يا عبدَ اللهِ، يا غفارَ الذنوبِ، يا مكرمًا للطلابِ، يا طالبًا.","والعلامة تتبع نوع الاسم: فالمثنى بالياء: يا صديقَيْ أخي، وجمع المذكر السالم بالياء: يا مهندسي الشركةِ، والأسماء الخمسة بالألف: يا أخا الدنيا."],"examples":["يا عبدَ اللهِ — مضاف: منادى منصوب بالفتحة.","يا حارسَ المدرسةِ — مضاف منصوب بالفتحة.","يا رحيمًا بالعبادِ — شبيه بالمضاف منصوب.","يا مكرمًا أباهُ — شبيه بالمضاف منصوب.","يا طالبًا اجتهدْ — نكرة غير مقصودة منصوبة.","يا صديقَيْ أخي — مثنى: منادى منصوب بالياء."],"questions":[{"question":"المنادى الذي ينصب معربًا هو:","options":["المضاف والشبيه بالمضاف والنكرة غير المقصودة","العلم المفرد","النكرة المقصودة","كل منادى"],"answer":0,"explanation":"قال الناظم: وغيره (أي غير المفرد المعين) المنصوب يأتي معربًا."},{"question":"في «يا عبدَ اللهِ» إعراب «عبدَ»:","options":["منادى منصوب وعلامة نصبه الفتحة وهو مضاف","منادى مبني على الضم","مفعول به","مبتدأ"],"answer":0,"explanation":"عبدَ: منادى منصوب بالفتحة وهو مضاف، واللهِ: مضاف إليه مجرور."},{"question":"في «يا رحيمًا بالعبادِ» نوع المنادى:","options":["شبيه بالمضاف","علم مفرد","نكرة مقصودة","مضاف حقيقي"],"answer":0,"explanation":"رحيمًا: اسم أُكمل بجار ومجرور (بالعباد) بغير طريق الإضافة؛ فهو شبيه بالمضاف: منادى منصوب بالفتحة."},{"question":"«يا طالبًا اجتهدْ» قالها أستاذ أمام طلابه لا يريد واحدًا بعينه؛ طالبًا:","options":["نكرة غير مقصودة: منادى منصوب بالفتحة","نكرة مقصودة مبنية على الضم","علم مبني على الضم","فاعل مرفوع"],"answer":0,"explanation":"النكرة غير المقصودة منصوبة معربة؛ فلو قصد طالبًا معلومًا قال: يا طالبُ بالضم."},{"question":"علامة نصب المنادى المثنى في «يا صديقَيْ أخي»:","options":["الياء","الفتحة","الألف","الكسرة"],"answer":0,"explanation":"صديقَيْ: منادى منصوب وعلامة نصبه الياء لأنه مثنى، وهو مضاف وأخي مضاف إليه."}]},{"body":["لفظًا لفظًا: «كَـ» أي: مثل. «يَا ظَلُومَ نَفْسِهِ» مثال الناظم الأول: ظلومَ اسم فاعل من ظلم، أُكمل بـ«نفسِه» فصار شبيهًا بالمضاف. «يَا مُتْعَبَا» المثال الثاني: متعبًا نكرة غير مقصودة، نُصب وأُدغمت نون التنوين في واو الجزر (الوقف) فكتبت بالألف.","فمثال البيت الأول «يا ظلومَ نفسِه﴿»: المنادى هنا شبيه بالمضاف؛ لأن (ظلوم) أُكمل بكلمة (نفسِه)؛ فنصبناه بالفتحة: ظلومَ.","والثاني «يا متعبا»: نكرة غير مقصودة (ينادي أي متعب)؛ فنصبها بالفتحة المقدرة مع التنوين: مُتْعَبًا.","فالقاعدة سهلة: انظر إلى المنادى: هل هو اسم واحد معين؟ ابنه على الضم. هل هو مضاف أو شبيه به أو نكرة غير مقصودة؟ انصبه.","ولاحظ: النداء إعرابه كله «محلي» في النوع الأول؛ أي: مبني في محل نصب، أما هنا فالنصب ظاهر بالفتحة ونحوها."],"examples":["يا ظلومَ نفسِهِ — شبيه بالمضاف: منصوب بالفتحة.","يا متعبًا — نكرة غير مقصودة: منصوبة بالفتحة.","يا غفارَ الذنوبِ — مضاف: منصوب بالفتحة.","يا حكيمًا رأيُه — شبيه بالمضاف: منصوب.","يا عاملًا احفظْ حقَّك — نكرة غير مقصودة منصوبة.","يا أخا الدنيا — من الأسماء الخمسة: منصوب بالألف."],"questions":[{"question":"«ظلومَ» في «يا ظلومَ نفسِه﴿»:","options":["منادى منصوب بالفتحة لأنه شبيه بالمضاف","منادى مبني على الضم","مفعول به","مضاف إليه مجرور"],"answer":0,"explanation":"ظلومَ أُكملت بـ(نفسه) فصارت شبيهة بالمضاف: منادى منصوب وعلامة نصبه الفتحة، ونفسِ: مضاف إليه مجرور."},{"question":"«متعبًا» في مثال البيت «يا متعبا» نوعه:","options":["نكرة غير مقصودة منصوبة","علم معين مبني","نكرة مقصودة مبنية","مضاف"],"answer":0,"explanation":"متعبًا: منادى منصوب بالفتحة؛ لأنه نكرة غير مقصودة (ينادي أي متعب)."},{"question":"الضابط العام للمنادى:","options":["المفرد المعين مبني على الضم، وغيره منصوب معرب","الكل مبني","الكل منصوب بالفتحة","الكل مجرور"],"answer":0,"explanation":"هذا خلاصة البيتين: هذا المنادى المفرد المعين أضممْه في محل، وغيره المنصوب يأتي معربًا."},{"question":"في «يا مهندسي الشركةِ» إعراب «مهندسي»:","options":["منادى منصوب بالياء لأنه جمع مذكر سالم مضاف","منادى مبني على الواو","مفعول به","فاعل"],"answer":0,"explanation":"مهندسي: منادى منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم، وهو مضاف، والشركةِ: مضاف إليه مجرور."},{"question":"أي منادى يُبنى (لا يُنصب)؟","options":["يا محمدُ — علم مفرد معين","يا عبدَ الله","يا رحيمًا بالعباد","يا طالبًا (لغير معين)"],"answer":0,"explanation":"العلم المفرد المعين وحده (مع النكرة المقصودة) هو الذي يبنى على الضم في محل نصب."}]}]},{"id":"wahi-verse-079","title":"جر الأسماء بحروف الجر: تمهيد","summary":"البيت التاسع والسبعون: ألحق جر الأسماء بحروف الجر المعروفة المحصورة.","verse":{"number":79,"section":"جر الأسماء","text":"أَلْحِقْ جَرًّا بِحُرُوفِ الْجَرِّ / مَعْرُوفَةٌ مَّذْكُورَةٌ بِالْحَصْرِ"},"segments":[{"body":["لفظًا لفظًا: «أَلْحِقْ» أي: ضُمَّ وأتبِع. «جَرًّا» أي: جرَّ الأسماء. «بِحُرُوفِ الْجَرِّ» أي: بواسطة الحروف التي تجرّ الاسم بعدها. «مَعْرُوفَةٌ» أي: مشهورة عند النحويين. «مَّذْكُورَةٌ بِالْحَصْرِ» أي: معدودة محصورة لا تزاد ولا تنقص.","ننتقل الآن إلى باب جديد: (جر الأسماء). الجر معناه: أن يلي آخرَ الاسم كسرةٌ، نحو: مَرَرْتُ بِزَيْدٍ — فزيدٍ تحته كسرة، نقول: اسم مجرور.","ما الذي يجرّ الاسم؟ أشهر شيء: حروف الجر. وحرف الجر كلمة صغيرة تأتي قبل الاسم فتكسر آخره وتغيّر المعنى: بِ، مِنْ، إِلَى... نحو: ذهبتُ إلى المدرسةِ.","يقول الناظم: ألحقْ في كلامك جرَّ الأسماء بحروف الجر، وهي حروف معروفة مذكورة بالحصر؛ أي: عددها معلوم محدود، ستعرفها كلها في البيت التالي، فلا يدخل فيها حرف آخر."],"examples":["ذَهَبْتُ إِلَى الْمَدْرَسَةِ — المدرسةِ: اسم مجرور بـ(إلى).","مَرَرْتُ بِرَجُلٍ كَرِيمٍ — برجلٍ: الباء حرف جر، رجلٍ مجرور.","الْكِتَابُ عَلَى الْمَكْتَبِ — على المكتبِ: جار ومجرور.","خَرَجْتُ مِنَ الْبَيْتِ — من: حرف جر، البيتِ: مجرور.","سَافَرْتُ فِي سَبِيلِ الْعِلْمِ — في: حرف جر.","هَذَا لَكَ — اللام حرف جر، والكاف ضمير مجرور."],"questions":[{"question":"الجر في اللغة النحوية هو:","options":["كسرة تلي آخر الاسم بعامل","ضمة تلي آخر الاسم","فتحة تلي آخر الاسم","سكون يلي آخر الاسم"],"answer":0,"explanation":"الجر: كسرة تلحق آخر الاسم لعامل، نحو: مررتُ بزيدٍ — زيدٍ: اسم مجرور وعلامة جره الكسرة."},{"question":"معنى «مذكورة بالحصر» في البيت:","options":["حروف الجر محصورة العدد لا تزاد","مذكورة في القرآن فقط","محصورة في ثلاثة أحرف","غير معلومة العدد"],"answer":0,"explanation":"حروف الجر محصورة معروفة العدد، يعدّها الناظم في البيت التالي، فلا يدخل فيها سواها."},{"question":"حرف الجر يعمل في الاسم الذي بعده:","options":["يجرّه؛ فيجعل آخره مكسورًا","يرفعه","ينصبه","لا يعمل فيه شيئًا"],"answer":0,"explanation":"حرف الجر يجر الاسم بعده: إلى المدرسةِ — المدرسةِ: اسم مجرور وعلامة جره الكسرة."},{"question":"قول الناظم «ألحقْ جرًّا» معناه:","options":["استعمل جر الأسماء في كلامك بحروف الجر","أخرِج الجر من الكلام","اجمع الجر والرفع","احذف حروف الجر"],"answer":0,"explanation":"ألحق: ضم وأتبع؛ أي: اجعل الجر لاحقًا للأسماء بحروف الجر المعروفة."},{"question":"الجار والمجرور في الجملة:","options":["يتعلقان بفعل أو اسم قبلهما ويفيدان معنى","لا محل لهما أبدًا من كل وجه","يكونان مبتدأ دائمًا","يكونان خبرًا دائمًا"],"answer":0,"explanation":"شبه الجملة من الجار والمجرور متعلقة بفعل أو معنى قبلها: ذهبتُ إلى المدرسةِ."}]},{"body":["لفظًا لفظًا — تثبيت: «بِحُرُوفِ الْجَرِّ مَعْرُوفَةٌ» وصفٌ لحروف الجر: معروفة مشهورة. «مَّذْكُورَةٌ بِالْحَصْرِ» وصف ثانٍ: معدودة محصورة. والميم الزائدة بعد اللام في (مَّذكورة) لتوضيح اللفظ في النظم.","لماذا شبّه الناظم الجر بشيء يُلحَق؟ لأن الجر ليس في الاسم أصلًا؛ الاسم مرفوع في ذاته، فإذا دخل عليه حرف الجر أُلحق به الجر من خارج.","واعلم أن للجر ثلاثة أسباب كبرى ستمر عليك: (1) حرف الجر قبل الاسم. (2) الإضافة: الاسم بعد المضاف مجرور دائمًا. (3) التبعية: التابع يتبع مجرورًا. وهذا البيت يمهد للأول، ثم يذكرها الناظم كلها في الخلاصة (البيت التاسع والثمانين).","فاحفظ الآن: كل اسم بعد حرف جر = مجرور. وعلامته: الكسرة في المفرد وجمع التكسير وجمع المؤنث، والياء في المثنى وجمع المذكر السالم والأسماء الخمسة."],"examples":["جَلَسْتُ تَحْتَ الشَّجَرَةِ — تحت: ظرف مبني... الشجرةِ: مضاف إليه مجرور.","سِرْتُ مَعَ صَدِيقَيْ — صديقَيْ: مجرور بالياء لأنه مثنى.","الْمُعَلِّمُونَ فِي الْفُصُولِ — الفصولِ: مجرور بالكسرة (جمع تكسير).","مَرَرْتُ بِالْمُعَلِّمِينَ — المعلمينَ: مجرور بالياء (جمع مذكر).","سَأَلْتُ عَنِ الْمُعَلِّمَاتِ — المعلماتِ: مجرور بالكسرة (جمع مؤنث).","هَذَا الْكِتَابُ لِأَبِيكَ — أبيكَ: مجرور بالياء (من الأسماء الخمسة)."],"questions":[{"question":"علامة جر المثنى:","options":["الياء","الكسرة","الفتحة","الضمة"],"answer":0,"explanation":"المثنى يجر بالياء: مررتُ برجلينِ / سرتُ مع صديقَيْ."},{"question":"علامة جر جمع المذكر السالم:","options":["الياء","الكسرة","الألف","الواو"],"answer":0,"explanation":"جمع المذكر السالم يجر بالياء: مررتُ بالمعلمينَ."},{"question":"علامة جر جمع المؤنث السالم وجمع التكسير:","options":["الكسرة","الياء","الفتحة","الألف"],"answer":0,"explanation":"الجمعان يجران بالكسرة: عن المعلماتِ، في الفصولِ."},{"question":"أسباب الجر الثلاثة الكبرى هي:","options":["حرف الجر والإضافة والتبعية","الرفع والنصب والجزم","المبتدأ والخبر والفاعل","النداء والاستثناء والترخيم"],"answer":0,"explanation":"يجر الاسم بحرف جر قبله، أو بوقوعه مضافًا إليه، أو بتبعيته لمجرور؛ وستفصل في الخلاصة."},{"question":"في «هذا الكتابُ لأبيكَ» إعراب «أبيكَ»:","options":["اسم مجرور باللام وعلامة جره الياء لأنه من الأسماء الخمسة، والكاف مضاف إليه","مفعول به منصوب","فاعل مرفوع","مبتدأ مرفوع"],"answer":0,"explanation":"أبيكَ: مجرور بالياء لأنه من الأسماء الخمسة، والكاف ضمير متصل مبني في محل جر مضاف إليه."}]}]},{"id":"wahi-verse-080","title":"حروف الجر الأحد عشر","summary":"البيت الثمانون: حصر حروف الجر: لام ومن وفي وعن وباء وإلى وكاف وربّ ومذ وحتى وعلى.","verse":{"number":80,"section":"جر الأسماء","text":"لَامٌ، وَمِنْ، وَفِي، وَعَنْ، بَا، وَإِلَىٰ / كَافٌ، وَرُبَّ، مُذْ، وَحَتَّىٰ، وَعَلَىٰ"},"segments":[{"body":["لفظًا لفظًا: هذا البيت قائمة؛ فاحفظها اسمًا اسمًا: «لَامٌ» حرف اللام (لِ). «وَمِنْ» حرف (مِنْ). «وَفِي» حرف (فِي). «وَعَنْ» حرف (عَنْ). «بَا» حرف الباء (بِ). «وَإِلَىٰ» حرف (إِلَى).","والشطر الثاني يكمل القائمة: «كَافٌ» حرف الكاف (كَ) للتشبيه. «وَرُبَّ» حرف (رُبَّ) للتقليل والتكثير. «مُذْ» حرف (مُذْ) لابتداء الزمن. «وَحَتَّىٰ» حرف (حَتَّى) للغاية. «وَعَلَىٰ» حرف (عَلَى) للاستعلاء.","فالمجموع: أحد عشر حرف جر: اللام، من، في، عن، الباء، إلى، الكاف، ربّ، مذ، حتى، على.","ولكل حرف معنى يضيفه: من للابتداء، إلى للانتهاء، عن للمجاوزة، على للاستعلاء، في للظرفية، الباء للإلصاق، اللام للاختصاص، الكاف للتشبيه، ربّ للتقليل أو التكثير، مذ ومنذ لابتداء الزمان، حتى لانتهاء الغاية."],"examples":["سَافَرْتُ مِنْ مِصْرَ إِلَى الشَّامِ — من: ابتداء، إلى: انتهاء.","عَبَرْتُ عَنِ النَّهْرِ — عن: للمجاوزة.","الْكِتَابُ عَلَى الطَّاوِلَةِ — على: للاستعلاء.","النَّخْلُ فِي الْبُسْتَانِ — في: للظرفية.","مَثَلُكَ كَمَثَلِ أَخِيكَ — الكاف: للتشبيه.","رُبَّ مُجْتَهِدٍ نَاجِحٌ — ربّ: للتكثير هنا."],"questions":[{"question":"عدد حروف الجر التي حصرها الناظم:","options":["أحد عشر حرفًا","تسعة أحرف","سبعة أحرف","خمسة عشر حرفًا"],"answer":0,"explanation":"اللام ومن وفي وعن والباء وإلى والكاف وربّ ومذ وحتى وعلى: أحد عشر حرفًا."},{"question":"حرف الجر الدال على التشبيه:","options":["الكاف: مثلك كمثل أخيك","الباء","حتى","عن"],"answer":0,"explanation":"الكاف حرف جر للتشبيه: مثلك كمثل أخيك — أخيك: اسم مجرور بالكاف."},{"question":"حرف الجر الدال على انتهاء الغاية:","options":["حتى","من","في","اللام"],"answer":0,"explanation":"حتى لانتهاء الغاية: سرتُ حتى المسجدِ — المسجدِ: اسم مجرور بحتى."},{"question":"معنى (عن) في «عبرتُ عن النهرِ»:","options":["المجاوزة","الاستعلاء","الظرفية","الابتداء"],"answer":0,"explanation":"عن للمجاوزة: أي جاوزتُ النهر؛ والنهرِ: اسم مجرور وعلامة جره الكسرة."},{"question":"(رُبَّ) تفيد:","options":["التقليل أو التكثير بحسب السياق","القسم فقط","الاستثناء","الشرط"],"answer":0,"explanation":"ربّ حرف جر للتقليل أو التكثير: ربَّ مجتهدٍ ناجحٌ — مجتهدٍ: اسم مجرور بربّ."}]},{"body":["لفظًا لفظًا — تثبيت القائمة كاملة: لامٌ (لِ)، ومِنْ، وفِي، وعَنْ، با (بِ)، وإلى، كافٌ (كَ)، وربَّ، ومُذْ، وحتى، وعلى. رتّبها في ذهنك هكذا وردّدها حتى تحفظها.","ومن الحروف ما يجيء على وجهين: «مذ» أصلها «منذ» وتحذف منها النون كثيرًا، وكلتاهما حرف جر لابتداء الزمان: مذ يومُ الجمعةِ / منذ يومِ الجمعةِ.","وتنبيه مهم: ليست كل (اللام) ولا كل (حتى) حرف جر في كل موضع! اللام قد تكون للابتداء (لام الابتداء) نحو: لَزيدٌ قائم، وحتى قد تكون حرف عطف نحو: مات الكلُّ حتى الأميرُ. فالعبرة بالمعنى: إن جرّت اسمًا فهي حرف جر.","فإذا أردت أن تعرف حرف الجر: انظر هل بعده اسم مجرور؟ وهل له معنى من المعاني السابقة؟ فإن اجتمعا فهو حرف جر."],"examples":["مُذْ يَوْمُ الْجُمُعَةِ — مذ: لابتداء الزمن، يومُ: مضاف إليه... (مذ يومَ أيضًا).","مُنْذُ عَامٍ — منذ: حرف جر لابتداء الزمن.","سِرْتُ حَتَّى الْمَسْجِدِ — حتى: حرف جر للغاية.","مَاتَ النَّاسُ حَتَّى الأُمَرَاءُ — حتى هنا: حرف عطف لا جر!","لَزَيْدٌ قَائِمٌ — اللام هنا: لام الابتداء لا حرف جر.","كَتَبْتُ بِالْقَلَمِ — الباء: للاستعانة/الإلصاق، القلمِ: مجرور."],"questions":[{"question":"(مذ) و(منذ) تستعملان لـ:","options":["ابتداء الزمان","التشبيه","الاستعلاء","الغاية"],"answer":0,"explanation":"مذ ومنذ حرفا جر لابتداء الزمان: مذ يوم الجمعة، منذ عامٍ — وما بعدهما مجرور."},{"question":"في «مات الناسُ حتى الأمراءِ» حتى:","options":["حرف عطف وليست حرف جر","حرف جر للغاية","حرف نصب","أداة استثناء"],"answer":0,"explanation":"لأنها عطفت الأمراء على الناس ولم تجره بل أتبعته مرفوعًا؛ فحتى هنا عاطفة."},{"question":"في «لزيدٌ قائمٌ» اللام:","options":["لام الابتداء وليست حرف جر","حرف جر للاختصاص","حرف عطف","أداة شرط"],"answer":0,"explanation":"اللام هنا للابتداء دخلت على المبتدأ فلزمته الضمة؛ فليست كل لام حرف جر."},{"question":"الباء في «كتبتُ بالقلمِ» تفيد:","options":["الاستعانة والإلصاق","الظرفية","الغاية","التشبيه"],"answer":0,"explanation":"الباء للإلصاق والاستعانة: كتبتُ بالقلم — القلمِ: اسم مجرور بالباء وعلامة جره الكسرة."},{"question":"أي تركيب صحيح الجر؟","options":["النخلُ في البستانِ","النخلُ في البستانُ","النخلُ في البستانَ","النخلُ في البستانْ بالسكون"],"answer":0,"explanation":"بعد حرف الجر (في) يكون الاسم مجرورًا بالكسرة: البستانِ."}]}]},{"id":"wahi-verse-081","title":"الجر بالإضافة: بمعنى اللام ومن وفي","summary":"البيت الحادي والثمانون: الإضافة التي بمعنى اللام أو من أو في تجر المضاف إليه.","verse":{"number":81,"section":"جر الأسماء","text":"أَوْ بِالْإِضَافَةِ الَّتِي بِمَعْنَىٰ / اللَّامِ، ثُمَّ (مِنْ) وَ(فِي)، كَـ(كُنَّا"},"segments":[{"body":["لفظًا لفظًا: «أَوْ بِالْإِضَافَةِ» أي: أو يكون الجر بواسطة الإضافة. «الَّتِي بِمَعْنَىٰ اللَّامِ» أي: الإضافة التي معناها معنى حرف الجر (اللام) أي: الاختصاص والملك. «ثُمَّ مِنْ وَفِي» أي: أو بمعنى (من) أو بمعنى (في). «كَكُنَّا» بدء مثال يكمل في البيت التالي.","الإضافة: أن تضم اسمين؛ الأول يسمى (مضاف) والثاني (مضاف إليه)، والمضاف إليه يكون مجرورًا دائمًا. نحو: كتابُ الطالبِ — الطالبِ: مضاف إليه مجرور.","لكن للإضافة معاني؛ أحيانًا تكون بمعنى حرف جر خفي. منها الإضافة بمعنى اللام للاختصاص: «سيارةُ ظافرٍ» = سيارةٌ لِظافرٍ (ملك له).","ومنها بمعنى (من): «بابُ خشبٍ» = بابٌ مِنْ خشبٍ. وبمعنى (في): «صلاةُ الليلِ» = صلاةٌ فِي الليلِ. فالمضاف إليه مجرور في الكل؛ لكن المعنى المقصود يختلف."],"examples":["سَيَّارَةُ ظَافِرٍ — بمعنى اللام: سيارة لظافر؛ ظافرٍ: مضاف إليه مجرور.","بَابُ خَشَبٍ — بمعنى من: باب من خشب؛ خشبٍ: مضاف إليه مجرور.","صَلَاةُ اللَّيْلِ — بمعنى في: صلاة في الليل؛ الليلِ: مضاف إليه مجرور.","خَاتَمُ ذَهَبٍ — بمعنى من: خاتم من ذهب.","قِرَاءَةُ الصَّبَاحِ — بمعنى في: قراءة في الصباح.","قَلَمُ أَحْمَدَ — بمعنى اللام: قلم لأحمد."],"questions":[{"question":"المضاف إليه حكمه دائمًا:","options":["مجرور","منصوب","مرفوع","مجزوم"],"answer":0,"explanation":"المضاف إليه مجرور دائمًا: كتابُ الطالبِ — الطالبِ: مضاف إليه مجرور وعلامة جره الكسرة."},{"question":"الإضافة بمعنى اللام مثالها:","options":["سيارةُ ظافرٍ = سيارة لظافر","بابُ خشبٍ","صلاةُ الليلِ","نومُ الظهرِ"],"answer":0,"explanation":"سيارة ظافر: الإضافة فيها بمعنى اللام للاختصاص والملك، وظافرٍ مضاف إليه مجرور."},{"question":"الإضافة بمعنى (من) مثالها:","options":["بابُ خشبٍ = باب من خشب","قلمُ أحمدَ","صلاةُ الليلِ","سيارةُ ظافرٍ"],"answer":0,"explanation":"بابُ خشبٍ: أي باب مصنوع من خشب؛ خشبٍ: مضاف إليه مجرور."},{"question":"الإضافة بمعنى (في) مثالها:","options":["صلاةُ الليلِ = صلاة في الليل","بابُ خشبٍ","سيارةُ ظافرٍ","خاتمُ ذهبٍ"],"answer":0,"explanation":"صلاةُ الليلِ: أي الصلاة في وقت الليل؛ الليلِ: مضاف إليه مجرور."},{"question":"في «خاتمُ ذهبٍ» إعراب «ذهبٍ»:","options":["مضاف إليه مجرور وعلامة جره الكسرة","مفعول به","نعت مرفوع","حرف جر"],"answer":0,"explanation":"ذهبٍ: مضاف إليه مجرور بالكسرة، والإضافة بمعنى (من): خاتم من ذهب."}]},{"body":["لفظًا لفظًا: «كَـ(كُنَّا)» — المثال يبدأ هنا ويكمل في أول البيت التالي: «كُنَّا بِبَيْتِ طِينٍ، فِي شِتَا تِشْرِينِ». فاحفظ أن البيتين متصلان في مثال واحد.","فالمثال الكامل: كُنَّا بِبَيْتِ طِينٍ فِي شِتَا تِشْرِينَ. ومعناه: كنا في بيتٍ من طين، في شتاءِ شهر تشرين.","فتأمل: «بيتِ طينٍ» إضافة بمعنى (من): بيت من طين. و«شتا تشرين» إضافة بمعنى (في): شتاء في تشرين. فجمع الناظم المعنيين في مثال واحد لطيف.","وعرفتَ بذلك أن الجر يأتي للاسم من طريقين حتى الآن: بحرف جر صريح قبله (البيت السابق)، أو بوقوعه مضافًا إليه بعد اسم آخر (هذا البيت)."],"examples":["كُنَّا بِبَيْتِ طِينٍ — طينٍ: مضاف إليه مجرور، والإضافة بمعنى من.","فِي شِتَا تِشْرِينَ — تشرينَ: مضاف إليه مجرور، والإضافة بمعنى في.","لِبَاسُ صُوفٍ — بمعنى من: لباس من صوف.","حِصَادُ الصَّيْفِ — بمعنى في: حصاد في الصيف.","دَرْسُ النَّحْوِ — بمعنى اللام/الاختصاص: درس للنحو.","قِيَامُ اللَّيْلِ — بمعنى في: قيام في الليل."],"questions":[{"question":"مثال البيتين «كنا ببيت طين في شتا تشرين» فيه إضافتان بمعنى:","options":["من ثم في","في ثم من","اللام ثم اللام","عن ثم على"],"answer":0,"explanation":"بيت طين = بيت من طين، وشتا تشرين = شتاء في تشرين؛ وكل مضاف إليه مجرور."},{"question":"إعراب «طينٍ» في «ببيتِ طينٍ»:","options":["مضاف إليه مجرور وعلامة جره الكسرة","مفعول به منصوب","نعت مجرور بالفتحة","فاعل مرفوع"],"answer":0,"explanation":"طينٍ: مضاف إليه مجرور وعلامة جره الكسرة، والإضافة بمعنى (من)."},{"question":"إعراب «تشرينَ» في «شتا تشرينَ»:","options":["مضاف إليه مجرور وعلامة جره الفتحة لأنه ممنوع من الصرف","مفعول فيه ظرف","مبتدأ مرفوع","منادى منصوب"],"answer":0,"explanation":"تشرين علم أعجمي ممنوع من الصرف يجر بالفتحة: مضاف إليه مجرور وعلامة جره الفتحة."},{"question":"طريقا الجر اللذان مرّا عليك حتى الآن:","options":["حرف الجر الصريح، والإضافة","النداء والاستثناء","الرفع والنصب","العطف والتوكيد"],"answer":0,"explanation":"الجر يكون بحرف جر قبل الاسم، أو بوقوع الاسم مضافًا إليه؛ والثالث (التبعية) يأتي في التوابع."},{"question":"الإضافة التي بمعنى اللام تفيد:","options":["الاختصاص والملك","الوقت","المادة المصنوع منها الشيء","المجاوزة"],"answer":0,"explanation":"سيارة ظافر = سيارة لظافر: اختصاص وملك؛ واللام أصل المعنى."}]}]},{"id":"wahi-verse-082","title":"حذف نون المثنى والجمع والتنوين عند الإضافة","summary":"البيت الثاني والثمانون: تكملة مثال الإضافة، وحذف نون المثنى والجمع والتنوين من المضاف.","verse":{"number":82,"section":"جر الأسماء","text":"بِبَيْتِ طِينٍ، فِي شِتَا تِشْرِينِ / وَاحْذِفْ لَهَا النُّونَ مَعَ التَّنْوِينِ"},"segments":[{"body":["لفظًا لفظًا: هذا الشطر يكمل مثال البيت السابق: «كُنَّا بِبَيْتِ طِينٍ، فِي شِتَا تِشْرِينِ». «بِبَيْتِ» الباء حرف جر وبيتِ اسم مجرور. «طِينٍ» مضاف إليه مجرور: بيت من طين. «فِي شِتَا تِشْرِينِ» شتا = شتاءَ (حذفت همزته في النظم): في شتاء تشرين؛ تشرينَ مضاف إليه مجرور.","فتأمل جمال المثال: جمع الناظم في جملة واحدة إضافةً بمعنى (من) — بيت طين — وإضافةً بمعنى (في) — شتا تشرين.","ثم انتقل الناظم إلى حكم مهم في المضاف (الاسم الأول): «وَاحْذِفْ لَهَا النُّونَ». أي: إذا أضفتَ المثنى أو جمع المذكر السالم فاحذف نونهما.","فالمثنى أصله «مسلمانِ» وجمع المذكر «مسلمونَ»؛ فإذا أضفتهما حذفتَ النون: «مسلما البيتِ»، «مسلمو البيتِ». والياء والواو هما علامة إعرابهما؛ أما النون فعلامة إتمام المثنى والجمع، تسقط عند الإضافة."],"examples":["مُسْلِمَا الْقَرْيَةِ — أصلها مسلمانِ؛ حذفت النون للإضافة.","مُسْلِمُو الْمَدِينَةِ — أصلها مسلمونَ؛ حذفت النون للإضافة.","مُعَلِّمَا الْمَدْرَسَةِ حَاضِرَانِ — معلما: مثنى مضاف محذوف النون.","طَالِبُو الْعِلْمِ مَحْمُودُونَ — طالبو: جمع مذكر مضاف محذوف النون.","جَاءَ وَلَدَا عَمِّي — ولدا: مثنى مضاف، عمّي: مضاف إليه مجرور بالياء.","رَأَيْتُ مُهَنْدِسِي الشَّرِكَةِ — مهندسي: جمع مضاف محذوف النون مجرور بالياء."],"questions":[{"question":"ماذا يُحذف من المثنى وجمع المذكر السالم عند الإضافة؟","options":["النون","الياء أو الواو","الألف","التاء"],"answer":0,"explanation":"تحذف نون المثنى ونون جمع المذكر السالم عند الإضافة: مسلمانِ + بيت = مسلما البيتِ."},{"question":"«مسلما القريةِ» أصلها قبل الإضافة:","options":["مسلمانِ","مسلمينَ","مسلمًا","مسلمونَ"],"answer":0,"explanation":"الأصل: مسلمانِ؛ فلما أضيف حذفت نونه فصار: مسلما القريةِ — مسلما: مبتدأ مرفوع بالألف وهو مضاف."},{"question":"في «معلمو المدرسةِ مجتهدونَ» إعراب «معلمو»:","options":["مبتدأ مرفوع بالواو لأنه جمع مذكر سالم وهو مضاف، حذفت نونه للإضافة","مبتدأ مرفوع بالضمة","فاعل منصوب","مضاف إليه مجرور"],"answer":0,"explanation":"معلمو: مبتدأ مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم وهو مضاف حذفت نونه."},{"question":"«شتا تشرينِ» في مثال البيت إضافتها بمعنى:","options":["في — شتاء في تشرين","من","اللام","عن"],"answer":0,"explanation":"شتا تشرين = شتاء في شهر تشرين؛ تشرين: مضاف إليه مجرور."},{"question":"لماذا تحذف نون المثنى والجمع عند الإضافة؟","options":["لأن النون علامة إتمام المثنى والجمع وتسقط للإضافة","لأنها حرف جر","للتخفيف فقط بلا سبب","لأنها أصلية في الفعل"],"answer":0,"explanation":"نون المثنى والجمع المذكر عوض عن التنوين، فتسقط عند الإضافة كما يسقط التنوين."}]},{"body":["لفظًا لفظًا: «مَعَ التَّنْوِينِ» أي: واحذف للإضافة النون (في المثنى والجمع) مع حذف التنوين (في المفرد وجمع التكسير وجمع المؤنث). والتنوين: نون ساكنة زائدة في آخر الاسم تُنطق ولا تُكتب حرفًا، بل تكون بضمتين أو فتحتين أو كسرتين: مُسْلِمٌ.","فالمفرد المضاف يحذف تنوينه: «كتابٌ» تصير «كتابُ الطالبِ» — لا نون.","ومرادف الإضافة هنا يشمل ما يعمل عملها: فالاسم الذي لا يُضاف لا يُنصب نونه... بل القاعدة: كل اسم أُضيف أو وقع بعد حرف جر أو نحو ذلك يسقط تنوينه عند الإضافة خاصة.","واعلم أن حذف التنوين علامة على اتصال الاسم بما بعده؛ فلا تقع بين المضاف والمضاف إليه فواصل: لا تقول: كتابُ الجديدِ الطالبِ، بل: الكتابُ الجديدُ أو كتابُ الطالبِ الجديدِ.","فالقاعدة في كلمة: المضاف ممنوع من ثلاثة: من (ال)، ومن النون، ومن التنوين. تقول: بيتُ الرجلِ، لا البيتُ الرجلِ، ولا بيتًا الرجلِ."],"examples":["كِتَابُ الطَّالِبِ — كتاب: مضاف مرفوع محذوف التنوين، الطالبِ: مضاف إليه مجرور.","بَابُ الْبَيْتِ مَفْتُوحٌ — باب: مضاف محذوف التنوين.","غُرْفَةُ النَّوْمِ واسعةٌ — غرفة: مضاف.","قِرَاءَةُ الْقُرْآنِ — قراءة: مضاف محذوف التنوين.","صَلَاةُ الْفَجْرِ — صلاة: مضاف.","مِفْتَاحُ السَّيَّارَةِ ضَاعَ — مفتاح: مضاف محذوف التنوين."],"questions":[{"question":"التنوين هو:","options":["نون ساكنة زائدة تلحق آخر الاسم النكرة لفظًا","ضمتان على الفعل","كسرة للجر","ألف للتثنية"],"answer":0,"explanation":"التنوين نون ساكنة زائدة في آخر الاسم: مسلمٌ؛ ويحذف عند الإضافة: مسلمُ القريةِ."},{"question":"المضاف يمتنع من:","options":["ال ونون المثنى والجمع والتنوين","الحركات الثلاث","الهمزة","الشدة"],"answer":0,"explanation":"المضاف لا يقبل (ال) ولا النون ولا التنوين: تقول بيتُ الرجلِ لا بيتًا ولا البيتُ."},{"question":"أي صيغة صحيحة؟","options":["كتابُ الطالبِ","كتابٌ الطالبِ","الكتابُ الطالبِ (بمعنى كتاب الطالب)","كتابًا الطالبِ"],"answer":0,"explanation":"المضاف يجرد من ال والتنوين: كتابُ الطالبِ — الطالبِ: مضاف إليه مجرور."},{"question":"في «رأيتُ مهندسي الشركةِ» إعراب «مهندسي»:","options":["مفعول به منصوب بالياء لأنه جمع مذكر سالم وهو مضاف محذوف النون","مفعول به منصوب بالفتحة","فاعل مرفوع بالواو","مضاف إليه مجرور"],"answer":0,"explanation":"مهندسي: مفعول به منصوب وعلامة نصبه الياء، وهو مضاف حذفت نونه للإضافة، والشركةِ: مضاف إليه مجرور."},{"question":"«واحذفْ لها النونَ مع التنوينِ» الضمير في (لها) يعود على:","options":["الإضافة","النون","المدرسة","اللغة"],"answer":0,"explanation":"لها: للإضافة؛ أي: احذف لأجل الإضافة نون المثنى والجمع، واحذف معها التنوين من المفرد."}]}]},{"id":"wahi-verse-083","title":"التوابع الأربعة: النعت والتوكيد والعطف والبدل","summary":"البيت الثالث والثمانون: التوابع أربعة: نعت وتوكيد وعطف وبدل، والنعت سبق شرحه.","verse":{"number":83,"section":"التوابع","text":"نَعْتٌ وَتَوْكِيدٌ وَعَطْفٌ وَبَدَلْ / تَوَابِعُ الْإِعْرَابِ، وَالنَّعْتُ رَحَلْ"},"segments":[{"body":["لفظًا لفظًا: «نَعْتٌ» وصف يتبع اسمًا قبله. «وَتَوْكِيدٌ» تقوية وتأكيد للاسم قبله. «وَعَطْفٌ» ربط اسم باسم بحرف عطف. «وَبَدَلْ» اسم يقوم مقام الذي قبله في الحكم.","ما معنى (التوابع)؟ التابع: اسم يأتي بعد اسم آخر ويتبعه في إعرابه: إن رُفع الأول رُفع، وإن نُصب نُصب، وإن جُرّ جُرّ. فهو تابع له لا مستقل.","والتوابع أربعة: النعت، والتوكيد، والعطف، والبدل. احفظها بهذا الترتيب.","«وَالنَّعْتُ رَحَلْ» أي: النعت رحل وراح؛ أي: سبق شرحه فيما مضى (مع درس الحال)، فلن يعيده الناظم هنا. فالمتبقي من هذه الباب: التوكيد والعطف والبدل.","مثال سريع على التبعية: جاء الطالبُ المجتهدُ — المجتهدُ: نعت مرفوع تبع الطالبُ. ورأيتُ الطالبَ المجتهدَ — نعت منصوب تبعه."],"examples":["جَاءَ الطَّالِبُ الْمُجْتَهِدُ — المجتهدُ: نعت مرفوع يتبع الطالبُ.","رَأَيْتُ الطَّالِبَ الْمُجْتَهِدَ — المجتهدَ: نعت منصوب يتبعه.","جَاءَ زَيْدٌ نَفْسُهُ — نفسُه: توكيد مرفوع يتبع زيدٌ.","قَرَأْتُ الْكِتَابَ نَفْسَهُ — نفسَه: توكيد منصوب يتبعه.","حَضَرَ أَحْمَدُ وَخَالِدٌ — خالدٌ: معطوف مرفوع يتبع أحمدُ.","أَكَلْتُ التُّفَّاحَةَ نِصْفَهَا — نصفَها: بدل منصوب يتبعها."],"questions":[{"question":"التوابع الأربعة هي:","options":["النعت والتوكيد والعطف والبدل","الفاعل والمفعول والمبتدأ والخبر","الحال والتمييز والاستثناء والنداء","الجر والنصب والرفع والجزم"],"answer":0,"explanation":"قال الناظم: نعت وتوكيد وعطف وبدل توابع الإعراب."},{"question":"معنى كون التابع (تابعًا):","options":["يتبع ما قبله في رفعه ونصبه وجره","يأتي بعده في السطر فقط","يكون دائمًا منصوبًا","يكون دائمًا مرفوعًا"],"answer":0,"explanation":"التابع يحذو حذو متبوعه: جاء الطالبُ المجتهدُ، رأيت الطالبَ المجتهدَ."},{"question":"لماذا لم يشرح الناظم النعت هنا؟","options":["لأنه سبق شرحه مع الحال فيما مضى","لأنه ليس من التوابع","لأنه نسيه","لأنه لا يتبع"],"answer":0,"explanation":"قال: والنعت رَحَل؛ أي سبق بيانه في موضعه، فبقي التوكيد والعطف والبدل."},{"question":"في «حضر أحمدُ وخالدٌ» خالدٌ:","options":["معطوف مرفوع بالضمة يتبع أحمد","نعت مرفوع","بدل مرفوع","توكيد مرفوع"],"answer":0,"explanation":"خالدٌ: معطوف على أحمد مرفوع بالضمة؛ والعطف من التوابع."},{"question":"في «أكلتُ التفاحةَ نصفَها» نصفَها:","options":["بدل منصوب بالفتحة يتبع التفاحة","نعت منصوب","مفعول به ثان","حال"],"answer":0,"explanation":"نصفَها: بدل بعض من كل منصوب بالفتحة، متبوعه (التفاحةَ) منصوب فيتبعه."}]},{"body":["لفظًا لفظًا — تثبيت: «تَوَابِعُ الْإِعْرَابِ» أي: هذه الأربعة هي التي تتبع الإعراب؛ فإعرابها ليس من نفسها بل من متبوعها. «وَالنَّعْتُ رَحَلْ» رَحَل: ذهب وسار؛ كناية عن أنه مضى شرحه.","والفائدة الكبرى من هذا الباب: الجر بالتبعية. فإذا وقع التابع بعد اسم مجرور جُرَّ مثله: مررتُ بالطالبِ المجتهدِ — المجتهدِ: نعت مجرور.","وهذا هو الوجه الثالث من أوجه الجر التي سيجمعها الناظم في الخلاصة: الجر بالحرف، والجر بالإضافة، والجر بالتبعية.","فدرّب نفسك: كل اسم بعد اسم: اسأل هل هو نعت (وصف)؟ أم توكيد (تأكيد)؟ أم معطوف (بعد حرف عطف)؟ أم بدل (يقوم مقامه)؟ ثم أتبعْه إعراب متبوعه."],"examples":["مَرَرْتُ بِالطَّالِبِ الْمُجْتَهِدِ — المجتهدِ: نعت مجرور يتبع مجرورًا.","سَلَّمْتُ عَلَى زَيْدٍ نَفْسِهِ — نفسِهِ: توكيد مجرور بالتبعية.","مَرَرْتُ بِأَحْمَدَ وَخَالِدٍ — خالدٍ: معطوف مجرور.","قَرَأْتُ لِلطَّالِبِ الْمُجْتَهِدِ — المجتهدِ: نعت مجرور.","أَعْجَبَنِي الْخَطِيبُ فَصَاحَتُهُ — فصاحتُه: بدل اشتمال مرفوع.","هَذَا الْكِتَابُ نَفْسُهُ مُفِيدٌ — نفسُه: توكيد مرفوع."],"questions":[{"question":"في «مررتُ بالطالبِ المجتهدِ» المجتهدِ:","options":["نعت مجرور بالكسرة تبعًا للطالبِ","نعت مرفوع","حال منصوبة","مضاف إليه"],"answer":0,"explanation":"المجتهدِ: نعت مجرور وعلامة جره الكسرة؛ لأن متبوعه (الطالبِ) مجرور فيتبعه."},{"question":"الوجه الثالث لجر الأسماء (بعد الحرف والإضافة) هو:","options":["التبعية لمجرور","النداء","الاستثناء","الافتعال"],"answer":0,"explanation":"التابع الواقع بعد مجرور يجر تبعًا له: مررتُ بزيدٍ نفسِهِ — نفسِهِ: توكيد مجرور."},{"question":"التوكيد معناه:","options":["تأكيد الاسم قبله وتقويته ودفع ما قد يسبق من وهن","وصف الاسم","ربط اسمين","استثناء جزء"],"answer":0,"explanation":"التوكيد: تقوية للمتبوع وتأكيد له نحو: جاء زيدٌ نفسُه."},{"question":"في «سلمتُ على زيدٍ نفسِهِ» نفسِهِ:","options":["توكيد مجرور بالكسرة تبعًا لزيدٍ","توكيد مرفوع","نعت مجرور بالفتحة","مفعول به"],"answer":0,"explanation":"نفسِهِ: توكيد مجرور وعلامة جره الكسرة تبعًا لمتبوعه المجرور (زيدٍ)."},{"question":"أي الأسماء الآتية ليس من التوابع؟","options":["الفاعل","النعت","التوكيد","البدل"],"answer":0,"explanation":"التوابع أربعة فقط: النعت والتوكيد والعطف والبدل؛ والفاعل مرفوع مستقل لا تابع."}]}]},{"id":"wahi-verse-084","title":"حروف العطف: «جاء زيد وفتىً»","summary":"البيت الرابع والثمانون: العطف يأتي بحروف تسعة، والناظم يؤثر سبعة منها.","verse":{"number":84,"section":"التوابع","text":"وَالْعَطْفُ يَأْتِي بِحُرُوفٍ تِسْعَةْ / كَـ(جَاءَ زَيْدٌ وَفَتًى)، بَلِ السَّبْعَةْ"},"segments":[{"body":["لفظًا لفظًا: «وَالْعَطْفُ» أي: ربط اسم باسم بحرف من حروف العطف فيشاركه في الحكم. «يَأْتِي بِحُرُوفٍ تِسْعَةْ» أي: حروفه تسعة في المشهور. «كَجَاءَ زَيْدٌ وَفَتًى» مثال: جاء زيدٌ وفتىً — فتىً معطوف على زيد.","العطف: أن تقول: جاء زيدٌ وعمرو؛ فـ(عمرو) اسمه (معطوف)، و(زيد) (معطوف عليه)، و(الواو) (حرف عطف). والمعطوف يتبع المعطوف عليه في الإعراب: رفعًا ونصبًا وجرًّا.","وحروف العطف تسعة عند جمهور النحويين: الواو، والفاء، وثمّ، وأو، وأم، وحتى، وبل، ولكنْ، ولا.","ثم قال الناظم: «بَلِ السَّبْعَةْ» أي: بل الأصح عندي أنها سبعة؛ فأخرج (أم) لأنها للاستفهام المعادل، وأخرج (حتى) لأنها تصلح لغير العطف وتشترك... فالمعتمد سبعة: الواو والفاء وثم وأو وبل ولكن ولا."],"examples":["جَاءَ زَيْدٌ وَفَتًى — فتىً: معطوف على زيد مرفوع مثله... (وفي المثال ورد بالنصب للجزْر: وفتىً معطوف على زيدٌ مرفوع محلًّا).","قَرَأْتُ الْكِتَابَ ثُمَّ الْقُرْآنَ — القرآنَ: معطوف منصوب.","مَرَرْتُ بِزَيْدٍ أَوْ عَمْرٍو — عمرٍو: معطوف مجرور.","لَا تَقْرَبِ الشَّرَّ وَلَا الْخُبْثَ — لا: حرف عطف (للنهي).","أَكْرَمْتُ الْفَقِيرَ بَلِ الْمِسْكِينَ — بل: حرف عطف للإضراب.","جَاءَ الْقَوْمُ فَالْجَيْشُ — الفاء: للترتيب والتعقيب."],"questions":[{"question":"العطف هو:","options":["ربط اسم باسم بحرف عطف فيتبعه في الإعراب والحكم","وصف الاسم","تأكيد الاسم","جر الاسم بالإضافة"],"answer":0,"explanation":"جاء زيدٌ وعمرو: عمرو معطوف على زيد مرفوع مثله، والواو حرف عطف."},{"question":"حروف العطف التسعة في المشهور:","options":["الواو والفاء وثم وأو وأم وحتى وبل ولكن ولا","من وإلى وعن وعلى وفي والباء والكاف واللام ورب","إن وأن وكأن ولكن وليت ولعل وإذ وإذا ولو","ثلاثة فقط"],"answer":0,"explanation":"عدّها الشارح تسعة، ثم أثبت الناظم سبعة بإخراج (أم) و(حتى)."},{"question":"قول الناظم «بل السبعة» معناه:","options":["الراجح عنده أن حروف العطف سبعة","أنها سبعة عشر","أن السبعة خطأ","أنه زادها سبعة"],"answer":0,"explanation":"إضراب عن التسعة إلى السبعة: أخرج أم وحتى، فبقيت: الواو والفاء وثم وأو وبل ولكن ولا."},{"question":"في «قرأتُ الكتابَ ثم القرآنَ» إعراب «القرآنَ»:","options":["معطوف على الكتابَ منصوب بالفتحة","مفعول به مستقل","نعت منصوب","بدل مرفوع"],"answer":0,"explanation":"القرآنَ: معطوف على الكتابَ منصوب وعلامة نصبه الفتحة؛ والتابع يتبع متبوعه."},{"question":"الفاء في «جاء القوم فالجيشُ» تفيد:","options":["الترتيب مع التعقيب","التعليل فقط","الاستئناف","الجزم"],"answer":0,"explanation":"الفاء للترتيب والتعقيب: الجيش جاء بعد القوم مباشرة؛ والجيشُ: معطوف مرفوع."}]},{"body":["لفظًا لفظًا — المثال: «جَاءَ زَيْدٌ وَفَتًى» جاء: فعل ماضٍ، زيدٌ: فاعل مرفوع، الواو: حرف عطف، فتىً: معطوف. ونُصب «فتىً» هنا لضرورة الوزن (جَزْر الألف خاتمةً)، ومحله الرفع تبعًا لزيد.","فائدة: حروف العطف لها معانٍ: الواو للمطلق (الجمع بلا ترتيب): جاء زيد وعمرو. الفاء للترتيب مع التعقيب: دخل الطبيب فالمريض. ثمّ للترتيب مع التراخي: وصل الأول ثم الثاني (بعد مدة). أو لأحد الشيئين: اجلسْ مع أستاذٍ أو مُعيدٍ.","وبل للإضراب (العدول عن الأول إلى الثاني): ما جاء خالدٌ بل زيدٌ. ولكنْ للاستدراك: جاء القوم لكنْ قائدُهم تأخر. ولا لنفي الثاني بعد نفي الأول: لا عالمَ ولا متعلمَ (في مثل هذا التركيب).","واعلم أن المعطوف يشارك المعطوف عليه في الحكم: فإن كان الأول فاعلًا فالثاني كذلك، وإن كان الأول مفعولًا فالثاني كذلك. وهذا سر تسميته تابعًا."],"examples":["جَاءَ زَيْدٌ وَعَمْرٌو — الواو: جمع بلا ترتيب.","دَخَلَ الطَّبِيبُ فَالْمَرِيضُ — الفاء: ترتيب وتعقيب.","وَصَلَ الْأَوَّلُ ثُمَّ الثَّانِي — ثم: ترتيب وتراخٍ.","سَافَرْ أَبُوكَ أَوْ أَخُوكَ — أو: لأحد الشيئين.","مَا حَضَرَ خَالِدٌ بَلْ زَيْدٌ — بل: إضراب.","لَا ضَرَبَ وَلَا شَتَمَ — لا: عطف النفي."],"questions":[{"question":"الواو في «جاء زيد وعمرو» تفيد:","options":["الجمع والمشاركة بلا ترتيب معين","الترتيب والتعقيب","الترتيب والتراخي","الإضراب"],"answer":0,"explanation":"الواو مطلقة للجمع؛ لا تدل على ترتيب: جاء زيد وعمرو — عمرو: معطوف مرفوع."},{"question":"(ثم) تفيد:","options":["الترتيب مع التراخي (بعد مدة)","التعقيب الفوري","الإضراب","التخيير"],"answer":0,"explanation":"ثم: للترتيب مع التراخي؛ بخلاف الفاء فهي للترتيب مع التعقيب الفوري."},{"question":"(بل) في «ما حضر خالد بل زيد» تفيد:","options":["الإضراب: العدول عن الأول وإثبات الثاني","الترتيب","التعليل","الشرط"],"answer":0,"explanation":"بل للإضراب: أثبت المجيء لزيد بعد نفيه عن خالد؛ زيدٌ: معطوف مرفوع... (فاعل بعد إضراب)."},{"question":"لماذا أخرج الناظم (أم) و(حتى) من حروف العطف؟","options":["لأن أم للاستفهام وحتى يغلب عليها الجر بالغاية","لأنهما ليسا حرفين","لأنهما من حروف الجر دائمًا","لأنهما من أدوات النصب"],"answer":0,"explanation":"أم استفهام معادل، وحتى للغاية غالبًا؛ فالأصح عنده حصر العطف في سبعة."},{"question":"المعطوف يشارك المعطوف عليه في:","options":["الحكم الإعرابي: رفعًا ونصبًا وجرًّا","العدد فقط","النوع فقط","الجنس فقط"],"answer":0,"explanation":"المعطوف تابع؛ فيرفع بما رفع به متبوعه وينصب بما نصب به: رأيت زيدًا وعمرًا."}]}]},{"id":"wahi-verse-085","title":"التوكيد نوعان: لفظي ومعنوي","summary":"البيت الخامس والثمانون: التوكيد نوعان؛ اللفظي بتكرار اللفظ، والمعنوي بألفاظ مخصوصة.","verse":{"number":85,"section":"التوابع","text":"تَوْكِيدُنَا نَوْعَانِ: فَاللَّفْظِيُّ / مُكَرَّرٌ، وَالثَّانِي مَعْنَوِيُّ"},"segments":[{"body":["لفظًا لفظًا: «تَوْكِيدُنَا» أي: توكيدنا نحن — أي التوكيد في كلامنا. «نَوْعَانِ» أي: قسمان اثنان. «فَاللَّفْظِيُّ» الفاء للتفصيل: فأما الأول فهو اللفظي، أي: المتعلق باللفظ نفسه. «مُكَرَّرٌ» أي: معناه أن اللفظ يُكرَّر. «وَالثَّانِي مَعْنَوِيُّ» والنوع الثاني هو المعنوي، أي: المتعلق بالمعنى لا بتكرار اللفظ.","التوكيد: اسم يأتي بعد اسم ليقوّيه ويؤكده ويدفع عنه احتمال السهو أو الشك. فإذا قلت: جاء زيدٌ نفسُه؛ أكدتَ أن زيدًا نفسه هو الذي جاء لا غيره.","النوع الأول: التوكيد اللفظي: أن تكرر اللفظ نفسه بعينه: «جاء زيدٌ زيدٌ»، «قرأتُ الدرسَ الدرسَ»، «سمعتُ القولَ القولَ». فالكلمة الثانية توكيد للأولى وتتبعها في الإعراب.","وهذا أقل التوكيدين استعمالًا في كلامنا اليوم، لكنه كثير في كلام العرب قديمًا؛ ومنه في القرآن: ﴿كَلَّا سَوْفَ تَعْلَمُونَ، ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ﴾ — تكرار للتأكيد والتهويل."],"examples":["جَاءَ زَيْدٌ زَيْدٌ — الثانية: توكيد لفظي مرفوع.","قَرَأْتُ الدَّرْسَ الدَّرْسَ — الثانية: توكيد لفظي منصوب.","مَرَرْتُ بِرَجُلٍ رَجُلٍ — توكيد لفظي مجرور.","سَمِعْتُ الْقَوْلَ الْقَوْلَ — توكيد لفظي منصوب.","حَقًّا حَقًّا أَقُولُ — توكيد لفظي.","صَبْرًا صَبْرًا يَا نَفْسُ — توكيد لفظي."],"questions":[{"question":"التوكيد نوعاه:","options":["اللفظي والمعنوي","الرفع والنصب","الظاهر والمضمر","المفرد والجمع"],"answer":0,"explanation":"قال الناظم: توكيدنا نوعان: فاللفظي مكرر، والثاني معنوي."},{"question":"التوكيد اللفظي هو:","options":["تكرار اللفظ الأول بعينه","استعمال نفس وعين","تكرار الحرف الأول","استعمال كل وأجمع"],"answer":0,"explanation":"اللفظي: كرر اللفظ نفسه: جاء زيد زيد؛ فالثاني توكيد لفظي للأول ويتبعه."},{"question":"في «قرأتُ الدرسَ الدرسَ» إعراب «الدرسَ» الثانية:","options":["توكيد لفظي منصوب وعلامة نصبه الفتحة","مفعول به","نعت منصوب","بدل مرفوع"],"answer":0,"explanation":"الدرسَ الثانية: توكيد لفظي منصوب بالفتحة؛ لأن متبوعها منصوب."},{"question":"فائدة التوكيد عمومًا:","options":["تأكيد المتبوع ودفع احتمال السهو والشك","الزخرفة فقط","الإطالة","الإيجاز"],"answer":0,"explanation":"التوكيد يقوّي الخبر: جاء زيد نفسه — تأكيد أنه هو بعينه جاء."},{"question":"مثال قرآني على التوكيد اللفظي:","options":["﴿كلا سوف تعلمون، ثم كلا سوف تعلمون﴾","﴿قل هو الله أحد﴾","﴿الحمد لله﴾","﴿إنا أعطيناك الكوثر﴾"],"answer":0,"explanation":"تكرار ﴿سوف تعلمون﴾ توكيد لفظي للتهويل والتأكيد."}]},{"body":["لفظًا لفظًا: «وَالثَّانِي مَعْنَوِيُّ» — النوع الثاني يسمى المعنوي؛ لأنه لا يكرر اللفظ، بل يأتي بلفظ آخر يدل على تأكيد المعنى.","فبدل أن تقول: جاء زيد زيد، تقول: جاء زيد نفسُه، أو عينُه. فـ(نفس) و(عين) ألفاظ التوكيد المعنوي للمفرد.","وللجمع ألفاظ أخرى: كلٌّ، وجميعٌ، وأجمعُ وأجمعونَ وأجمعينَ، وكِلْتَا وكِلَا للمثنى. تقول: أكرمْتُ الطلابَ كلَّهُمْ، جاء الجيشُ أجمعُ.","وشرط مهم: أكثر هذه الألفاظ لا تتوكد إلا بضمير يعود على المؤكَّد (المتبوع): نفسُه، عينُه، كلُّهم، أجمعونَ. فالضمير فيها راجع إلى الأول.","وإعراب التوكيد المعنوي مثل اللفظي: تابع لمتبوعه في رفعه ونصبه وجره: جاء زيدٌ نفسُه (مرفوع)، رأيتُ زيدًا نفسَه (منصوب)، مررتُ بزيدٍ نفسِهِ (مجرور)."],"examples":["جَاءَ زَيْدٌ نَفْسُهُ — نفسُه: توكيد معنوي مرفوع.","رَأَيْتُ زَيْدًا عَيْنَهُ — عينَه: توكيد معنوي منصوب.","أَكْرَمْتُ الطُّلَّابَ كُلَّهُمْ — كلَّهم: توكيد منصوب.","جَاءَ الْجَيْشُ أَجْمَعُ — أجمعُ: توكيد مرفوع.","حَضَرَ التُّجَّارُ جَمِيعًا — جميعًا: توكيد منصوب... (أو حال).","كِلْتَا الْيَدَيْنِ نَظِيفَتَانِ — كلتا للمثنى المؤنث."],"questions":[{"question":"ألفاظ التوكيد المعنوي للمفرد:","options":["نفس وعين","كل وجميع","أجمع وأجمعون","كلا وكلتا"],"answer":0,"explanation":"للمفرد: نفس وعين: جاء زيد نفسُه، رأيت زيدًا عينَه."},{"question":"ألفاظ التوكيد المعنوي للجمع:","options":["كل وجميع وأجمع وأجمعون وأجمعين","نفس وعين","كلا وكلتا فقط","لا شيء للجمع"],"answer":0,"explanation":"للجمع: كل وجميع وأجمع وتوابعه: أكرمت الطلاب كلَّهم / جاء الجيش أجمعُ."},{"question":"في «رأيتُ زيدًا نفسَه» إعراب «نفسَه»:","options":["توكيد معنوي منصوب بالفتحة","مفعول به","نعت منصوب","مضاف إليه"],"answer":0,"explanation":"نفسَه: توكيد معنوي منصوب بالفتحة يتبع زيدًا، والهاء ضمير مضاف إليه."},{"question":"شرط (نفس وعين وكل وأجمع) في التوكيد:","options":["أن تُضاف إلى ضمير يعود على المؤكَّد","أن تكون مفردة من الضمير","أن تسبق المؤكد","أن تكون معرفة بال"],"answer":0,"explanation":"تتوكد مضافة لضمير المتبوع: نفسُه، عينُه، كلُّهم، أجمعونَ."},{"question":"(كلا وكلتا) تستعملان لـ:","options":["المثنى","المفرد","الجمع","النكرة فقط"],"answer":0,"explanation":"كلا للمذكر المثنى وكلتا للمؤنث المثنى: كتب الطالبان كلاهما، نجحت الطالبتان كلتاهما."}]}]},{"id":"wahi-verse-086","title":"أمثلة التوكيد: «نفسه» و«أجمعين»","summary":"البيت السادس والثمانون: مثالان على التوكيد المعنوي: جاء زيد نفسه، وأكرم الطلاب أجمعين.","verse":{"number":86,"section":"التوابع","text":"كَـ(جَاءَ زَيْدٌ نَفْسُهُ يَقِينًا) / وَ(أَكْرَمَ الطُّلَّابَ أَجْمَعِينَا)"},"segments":[{"body":["لفظًا لفظًا: «كَجَاءَ» مثل: جاء (فعل ماضٍ). «زَيْدٌ» فاعل مرفوع. «نَفْسُهُ» توكيد معنوي مرفوع يتبع زيدٌ، والهاء ضمير يعود على زيد. «يَقِينًا» أي: مجيئه ثابت متيقَّن لا شك فيه؛ مفعول مطلق أو حال مؤكدة.","فالمثال الأول: «جاء زيدٌ نفسُه يقينًا». المعنى: جاء زيد بنفسه مجيئًا ثابتًا متيقنًا. فانظر كيف وظّف الناظم التوكيد: (نفسه) تؤكد أن زيدًا بذاته جاء، و(يقينًا) تؤكد ثبوت المجيء.","إعرابه: جاء: فعل ماضٍ مبني على الفتح. زيدٌ: فاعل مرفوع بالضمة. نفسُه: توكيد معنوي مرفوع بالضمة، وهو مضاف، والهاء ضمير متصل مبني في محل جر مضاف إليه. يقينًا: مفعول مطلق منصوب بالفتحة (أو حال).","فلاحظ القاعدة الذهبية: التوكيد تابع؛ فرُفع لأن متبوعه (زيدٌ) مرفوع."],"examples":["جَاءَ زَيْدٌ نَفْسُهُ يَقِينًا — نفسُه: توكيد معنوي مرفوع.","حَضَرَ الْمُدِيرُ نَفْسُهُ — نفسُه: توكيد مرفوع.","قَرَأْتُ الْكِتَابَ نَفْسَهُ — نفسَه: توكيد منصوب.","سَلَّمْتُ عَلَى الشَّيْخِ نَفْسِهِ — نفسِهِ: توكيد مجرور.","صَدَقَ الْعَبْدُ عَيْنُهُ — عينُه: توكيد معنوي مرفوع.","فَازَ الْمُجْتَهِدُ نَفْسُهُ — نفسُه: توكيد مرفوع."],"questions":[{"question":"في «جاء زيدٌ نفسُه» إعراب «نفسُه»:","options":["توكيد معنوي مرفوع بالضمة، مضاف، والهاء مضاف إليه","نعت مرفوع","مفعول به","فاعل ثان"],"answer":0,"explanation":"نفسُه: توكيد معنوي مرفوع بالضمة يتبع زيدٌ، والهاء ضمير متصل مبني في محل جر مضاف إليه."},{"question":"«يقينًا» في المثال تفيد:","options":["تأكيد ثبوت المجيء وأنه لا شك فيه","الشك","الوقت","المكان"],"answer":0,"explanation":"يقينًا: مفعول مطلق منصوب (أو حال) يؤكد ثبوت الفعل: جاء مجيئًا متيقنًا."},{"question":"لماذا رُفعت «نفسُه»؟","options":["لأنها تابعة لمتبوع مرفوع (زيدٌ)","لأنها فاعل","لأنها مبتدأ","لأن التوكيد يرفع دائمًا ولو بعد منصوب"],"answer":0,"explanation":"التوكيد تابع يتبع متبوعه: زيدٌ مرفوع فنفسُه مرفوعة."},{"question":"في «رأيتُ زيدًا نفسَه» نفسَه:","options":["توكيد معنوي منصوب بالفتحة","توكيد مرفوع","نعت","حال"],"answer":0,"explanation":"نفسَه: توكيد منصوب بالفتحة؛ لأن متبوعها (زيدًا) منصوب."},{"question":"الضمير في (نفسه):","options":["ضمير متصل مبني في محل جر مضاف إليه يعود على المؤكد","فاعل","مبتدأ","لا محل له"],"answer":0,"explanation":"الهاء في نفسُه: ضمير متصل مبني في محل جر مضاف إليه، يعود على زيد."}]},{"body":["لفظًا لفظًا: «وَأَكْرَمَ» أي: ومثل: أكرم (فعل ماضٍ معناه: أحسن إليه وكرّمه). «الطُّلَّابَ» مفعول به منصوب (جمع تكسير من طالب). «أَجْمَعِينَا» توكيد معنوي للجمع منصوب بالياء، ونوّن في النظم للوزن.","فالمثال الثاني: «أكرمَ الطلابَ أجمعينَ». المعنى: أكرم الطلاب كلَّهم من غير استثناء. و(أجمعين) لفظ جمعي يؤكد شمول الإكرام للجميع.","إعرابه: أكرمَ: فعل ماضٍ مبني على الفتح، والفاعل ضمير مستتر تقديره (هو). الطلابَ: مفعول به منصوب بالفتحة. أجمعينَ: توكيد معنوي منصوب وعلامة نصبه الياء (لأنه ملحق بجمع المذكر السالم).","وقد ورد في شرح المؤلف: «أكرم الطلاب كلهم أجمعين» — جمع توكيدين: (كلهم) ثم (أجمعين) تأكيدًا فوق تأكيد؛ فيجوز اجتماع أكثر من توكيد.","فقارن بين المثالين: الأول توكيد للمفرد بـ(نفسه)، والثاني توكيد للجمع بـ(أجمعين). وهكذا تختم باب التوكيد."],"examples":["أَكْرَمَ الطُّلَّابَ أَجْمَعِينَ — أجمعينَ: توكيد منصوب بالياء.","أَكْرَمَ الطُّلَّابَ كُلَّهُمْ أَجْمَعِينَ — توكيدان متتابعان.","حَضَرَ الْجُنْدُ أَجْمَعُونَ — أجمعونَ: توكيد مرفوع بالواو.","رَأَيْتُ الْفَرِيقَ كُلَّهُ — كلَّه: توكيد منصوب.","نَجَحَ الطَّالِبَانِ كِلَاهُمَا — كلاهما: توكيد للمثنى مرفوع.","سَافَرَ الْجَمْعُ جَمِيعًا — جميعًا: توكيد منصوب."],"questions":[{"question":"في «أكرمَ الطلابَ أجمعينَ» إعراب «أجمعينَ»:","options":["توكيد معنوي منصوب وعلامة نصبه الياء","مفعول به منصوب بالفتحة","نعت مرفوع","فاعل"],"answer":0,"explanation":"أجمعينَ: توكيد معنوي منصوب بالياء (ملحق بجمع المذكر) يتبع الطلابَ."},{"question":"إعراب «الطلابَ» في المثال:","options":["مفعول به منصوب وعلامة نصبه الفتحة","فاعل مرفوع","مبتدأ","توكيد"],"answer":0,"explanation":"الطلابَ: مفعول به منصوب بالفتحة؛ والفاعل ضمير مستتر تقديره (هو)."},{"question":"«أكرم الطلاب كلهم أجمعين» فيها:","options":["توكيدان معنويان متتابعان للجمع","خطأ إعرابي","توكيد لفظي","عطف"],"answer":0,"explanation":"يجوز اجتماع توكيدين: كلَّهم توكيد أول منصوب، وأجمعين توكيد ثان منصوب تأكيدًا."},{"question":"أجمع وأجمعون وأجمعين تتبع:","options":["جميعَ طرق إعراب الملحق بجمع المذكر: واو وياء","المفرد فقط","المثنى فقط","جمع المؤنث فقط"],"answer":0,"explanation":"أجمع يرفع بالواو: جاء الجيش أجمعونَ، وينصب ويجر بالياء: أكرم الطلاب أجمعينَ."},{"question":"متى تستعمل (أجمعين) بدل (نفسه)؟","options":["عند توكيد الجمع","عند توكيد المفرد","عند توكيد الفعل","في النداء"],"answer":0,"explanation":"نفس وعين للمفرد، وأجمع وأجمعون وأجمعين وكل وجميع للجمع."}]}]},{"id":"wahi-verse-087","title":"البدل: تعريفه وأنواعه","summary":"البيت السابع والثمانون: البدل هو التابع المقصود بالحكم، وأنواعه: كل وبعض واشتمال وغلط.","verse":{"number":87,"section":"التوابع","text":"وَالتَّابِعُ الْمَقْصُودُ بِالْحُكْمِ بَدَلْ / أَنْوَاعُهُ: كُلٌّ وَبَعْضٌ وَاشْتِمَالْ"},"segments":[{"body":["لفظًا لفظًا: «وَالتَّابِعُ» أي: الاسم التابع من التوابع. «الْمَقْصُودُ بِالْحُكْمِ» أي: الذي نريده حقيقة بالحكم ونقصده بالكلام. «بَدَلْ» أي: هو المسمى بدلًا. «أَنْوَاعُهُ» أي: أقسامه. «كُلٌّ» أي: بدل الكل من الكل. «وَبَعْضٌ» وبدل البعض من الكل. «وَاشْتِمَالْ» وبدل الاشتمال. (والرابع: الغلط، في البيت التالي).","ما البدل؟ اسم يذكر بعد اسم، والحكم في الحقيقة عليه هو لا على الأول. فإذا قلت: «جاء الصديقُ أبو بكرٍ» — من الذي جاء حقيقة؟ أبو بكر؛ فهو المقصود بالحكم، و(الصديق) كأنه ممهد وطريق إليه. فأبو بكر: بدل.","فالبدل عكس النعت تقريبًا: في النعت الأول هو المقصود والثاني وصف له، أما في البدل فالثاني هو المقصود بالحكم.","وأنواع البدل أربعة: (1) بدل كل من كل: الثاني عين الأول: جاء الصديقُ أبو بكرٍ. (2) بدل بعض من كل: الثاني جزء الأول: أكلتُ التفاحةَ نصفَها. (3) بدل الاشتمال: الثاني فيه اشتمال على الأول بضمير أو لحوق معنى: أعجبني الخطيبُ فصاحتُه. (4) بدل الغلط: تذكر الصواب بعد الغلط."],"examples":["جَاءَ الصَّدِيقُ أَبُو بَكْرٍ — أبو بكر: بدل كل من كل مرفوع.","أَكَلْتُ التُّفَّاحَةَ نِصْفَهَا — نصفَها: بدل بعض من كل منصوب.","أَعْجَبَنِي الْخَطِيبُ فَصَاحَتُهُ — فصاحتُه: بدل اشتمال مرفوع.","قَرَأْتُ الْقَلَمَ الْكِتَابَ — الكتابَ: بدل غلط من (القلم) منصوب.","سَافَرَ أَخُوكَ مُحَمَّدٌ — محمدٌ: بدل كل مرفوع.","شَرِبْتُ اللَّبَنَ ثُلُثَهُ — ثلثَه: بدل بعض من كل منصوب."],"questions":[{"question":"البدل هو:","options":["التابع المقصود بالحكم حقيقة","التابع الوصفي","المعطوف بحرف","المستثنى بإلا"],"answer":0,"explanation":"قال الناظم: والتابع المقصود بالحكم بدل؛ فالحكم يقع عليه هو، والأول طريق إليه."},{"question":"أنواع البدل الأربعة:","options":["كل من كل، وبعض من كل، واشتمال، وغلط","لفظي ومعنوي","ظاهر ومضمر","مفرد وجمع"],"answer":0,"explanation":"أنواعه: كل وبعض واشتمال وغلط؛ ذكر الناظم ثلاثة في البيت وأتم الرابع في البيت التالي."},{"question":"في «جاء الصديقُ أبو بكرٍ» إعراب «أبو بكرٍ»:","options":["بدل كل من كل مرفوع بالضمة","نعت مرفوع","معطوف","توكيد"],"answer":0,"explanation":"أبو بكرٍ: بدل من الصديق مرفوع بالضمة؛ وهو المقصود بالمجيء حقيقة."},{"question":"في «أكلتُ التفاحةَ نصفَها» نوع البدل:","options":["بدل بعض من كل","بدل كل من كل","بدل اشتمال","بدل غلط"],"answer":0,"explanation":"نصفَها: بدل بعض من كل منصوب بالفتحة؛ فالنصف جزء التفاحة، والهاء ضمير يعود عليها."},{"question":"الفرق بين البدل والنعت:","options":["في البدل الثاني هو المقصود بالحكم، وفي النعت الأول هو المقصود والثاني وصفه","لا فرق","النعت يتبع والبدل لا يتبع","البدل للجمع فقط"],"answer":0,"explanation":"النعت وصف يتبع موصوفًا مقصودًا؛ والبدل اسم مقصود بالحكم يتبع ممهدًا."}]},{"body":["لفظًا لفظًا — تدقيق: «أَنْوَاعُهُ: كُلٌّ وَبَعْضٌ وَاشْتِمَالْ» — والبيت انتهى بحرف الجزء (بدل) فأتم الرابع (وغلط) في أول البيت التالي. فالأنواع أربعة لا ثلاثة.","بدل الاشتمال: أن يشتمل المبدل منه على البدل بوجه من الوجوه: بضمير يعود عليه نحو: أعجبني الخطيبُ فصاحتُه (الهاء تعود على الخطيب)، أو بلحوق معنى نحو: ضاع الزندُ فتفطَّرَ الكفُّ (الكف جزء من صاحب الزند... بل منه).","بدل الغلط: أن تغلط أو تنسى فتذكر الصواب بعده: «قرأتُ القلمَ الكتابَ» — قلت القلم خطأ ثم صححت بالكتاب؛ فالكتاب بدل غلط من القلم، منصوب مثله.","ومن بدل الكل ما يسمى (المطابق): أن يطابق الثاني الأول عينًا: الصديقُ أبو بكرٍ — عينه بلا زيادة. ومنه أعلام الشيء الواحد المتتابعة: جاء محمدٌ أحمدُ (اسمان لشخص واحد).","والقاعدة الجامعة: البدل يتبع مبدله منه في الإعراب دائمًا: مرفوعًا فمرفوع، ومنصوبًا فمنصوب، ومجرورًا فمجرور."],"examples":["أَعْجَبَنِي الْخَطِيبُ فَصَاحَتُهُ — فصاحتُه: بدل اشتمال مرفوع، والهاء تعود على الخطيب.","قَرَأْتُ الْقَلَمَ الْكِتَابَ — الكتابَ: بدل غلط منصوب.","جَاءَ مُحَمَّدٌ أَحْمَدُ — أحمدُ: بدل كل (علم متتابع) مرفوع.","ضَاعَ الزَّنْدُ فَتَفَطَّرَ الْكَفُّ — الكفُّ: بدل اشتمال مرفوع.","رَأَيْتُ هَذَا الرَّجُلَ — الرجلَ: بدل من اسم الإشارة منصوب.","مَرَرْتُ بِالْعَالِمِ الشَّيْخِ — الشيخِ: بدل مجرور."],"questions":[{"question":"بدل الاشتمال هو:","options":["أن يشتمل المبدل منه على البدل بضمير أو لحوق معنى","أن يكون البدل عين الأول","أن يكون البدل جزء الأول","أن يصحح غلطًا"],"answer":0,"explanation":"أعجبني الخطيب فصاحتُه: فصاحتُه بدل اشتمال مرفوع؛ لأن الخطيب يشتمل على فصاحته والضمير يعود عليه."},{"question":"بدل الغلط مثاله:","options":["قرأتُ القلمَ الكتابَ","جاء الصديق أبو بكر","أكلت التفاحة نصفها","أعجبني الخطيب فصاحته"],"answer":0,"explanation":"قرأت القلم الكتاب: غلطتَ فقلت القلم ثم أردت الصواب فقلت الكتاب؛ فالكتاب بدل غلط منصوب."},{"question":"في «رأيتُ هذا الرجلَ» إعراب «الرجلَ»:","options":["بدل من اسم الإشارة منصوب بالفتحة","نعت منصوب","مفعول به أول","توكيد"],"answer":0,"explanation":"الرجلَ: بدل من اسم الإشارة (هذا) منصوب بالفتحة؛ وهو من بدل الكل."},{"question":"البدل يتبع مبدله منه في:","options":["الإعراب: رفعًا ونصبًا وجرًّا","العدد فقط","النوع فقط","الشكل فقط"],"answer":0,"explanation":"البدل تابع: سافر أخوك محمدٌ (مرفوع)، رأيت أخاك محمدًا (منصوب)، مررت بأخيك محمدٍ (مجرور)."},{"question":"«أعلام الشيء الواحد المتتابعة» مثالها:","options":["جاء محمدٌ أحمدُ — اسمان لشخص واحد","أكلت التفاحة نصفها","قرأت القلم الكتاب","جاء زيد وعمرو"],"answer":0,"explanation":"محمد وأحمد علمان لشخص واحد؛ فالثاني بدل مطابق مرفوع من بدل الكل من الكل."}]}]},{"id":"wahi-verse-088","title":"بدل الغلط وأمثلة البدل: «أسمع أخي أسامة»","summary":"البيت الثامن والثمانون: إتمام أنواع البدل بالغلط، ومثال يجمع بدل الكل وبدل الاشتمال.","verse":{"number":88,"section":"التوابع","text":"وَغَلَطٌ، كَـ(أَسْمَعْ أَخِي أُسَامَهْ / مُحَمَّدًا كَلَامَهُ وَسَلَامَهْ)"},"segments":[{"body":["لفظًا لفظًا: «وَغَلَطٌ» أي: والنوع الرابع من البدل: بدل الغلط. «كَأَسْمَعْ» مثل: أسمعَ (بفتح العين في الوصل: أسمعَ) أي: جعل يسمع. «أَخِي» فاعل: أخي. «أُسَامَهْ» بدل من أخي (أسامةُ بضمة في الوصل، والسكون للوقف في النظم).","فالمثال الأول: «أسمعَ أخي أسامةُ...». (أسمع) فعل ماضٍ رباعي معناه: جعله يسمع. (أخي): فاعل مرفوع بالياء لأنه من الأسماء الخمسة مضاف إلى ياء المتكلم. (أسامةُ): بدل كل من كل (بدل مطابق) من (أخي)؛ لأن أسامة هو عين الأخ.","وهذا يصدق عليه ضابط من شرح المؤلف: من بدل الكل (أعلام الشيء الواحد المتتابعة)؛ فالأخ وأسامة شخص واحد، ذكر أولًا بوصفه (أخي) ثم بعلمه (أسامة).","وإعرابه: أسامةُ: بدل من (أخي) مرفوع، وعلامة رفعه الضمة. ولماذا رُفع؟ لأن متبوعه (أخي) مرفوع؛ والبدل تابع."],"examples":["أَسْمَعَ أَخِي أُسَامَةُ — أسامةُ: بدل كل من (أخي) مرفوع.","جَاءَ أَخُوكَ عَلِيٌّ — عليٌّ: بدل مطابق مرفوع.","رَأَيْتُ أَخَاكَ عَلِيًّا — عليًّا: بدل منصوب.","مَرَرْتُ بِأَخِيكَ عَلِيٍّ — عليٍّ: بدل مجرور.","قَرَأْتُ الْقَلَمَ الْكِتَابَ — الكتابَ: بدل غلط منصوب.","شَاهَدْتُ الصَّدِيقَ أَبَا بَكْرٍ — أبا بكرٍ: بدل كل منصوب."],"questions":[{"question":"النوع الرابع من أنواع البدل هو:","options":["بدل الغلط","بدل الاشتمال","بدل البعض","بدل الكل"],"answer":0,"explanation":"أتم الناظم الأنواع الأربعة بقوله: وغلط؛ مثل: قرأت القلم الكتاب — الكتاب بدل غلط."},{"question":"في «أسمع أخي أسامةُ» إعراب «أسامةُ»:","options":["بدل كل من كل (مطابق) مرفوع بالضمة","نعت مرفوع","فاعل","مفعول به"],"answer":0,"explanation":"أسامةُ: بدل من (أخي) مرفوع بالضمة؛ وهو المقصود بالحكم حقيقة."},{"question":"إعراب «أخي» في المثال:","options":["فاعل مرفوع وعلامة رفعه الياء لأنه من الأسماء الخمسة مضاف لياء المتكلم","مبتدأ مرفوع بالضمة","مفعول به","بدل مرفوع بالضمة"],"answer":0,"explanation":"أخي: فاعل مرفوع بالياء (اسم من الأسماء الخمسة مضاف)، والياء ضمير متصل مبني في محل جر مضاف إليه."},{"question":"معنى الفعل «أسمعَ» هنا:","options":["جعل غيره يسمع (أفعل السماع)","سمع بنفسه فقط","أطاع","قال"],"answer":0,"explanation":"أسمعَ: ألحق غيره بالسماع؛ فالمعنى: جعل أخي أسامةُ محمدًا يسمع كلامه وسلامه."},{"question":"بدل الغلط يكون عندما:","options":["تغلط أو تنسى فتذكر الصواب بعد الغلط","تذكر جزء الشيء","تذكر عين الشيء","تصف الشيء"],"answer":0,"explanation":"قرأت القلم الكتاب: ذكرت الصواب (الكتاب) بعد الغلط (القلم)؛ فالكتاب بدل غلط منصوب تبعًا لمتبوعه."}]},{"body":["لفظًا لفظًا: «مُحَمَّدًا» مفعول به منصوب (الذي أُسمع). «كَلَامَهُ» بدل اشتمال من محمدًا. «وَسَلَامَهْ» معطوف على كلامه (وسلامه بالفتحة في الوصل).","فالشطر الثاني: «محمدًا كلامَه وسلامَه». محمدًا: مفعول به لـ(أسمع). كلامَه: بدل اشتمال من (محمدًا) منصوب؛ لأن محمدًا يشتمل على كلامه، والهاء ضمير يعود عليه. وسلامَه: معطوف على كلامه منصوب مثله.","فانظر كيف جمع الناظم في جملة واحدة: بدل كل (أسامة من أخي)، وبدل اشتمال (كلامه من محمدًا)، وعطفًا (وسلامه). مراجعة ذكية لباب التوابع كله.","وبدل الاشتمال ضابطه: أن يكون البدل داخلًا في المبدل منه أو لاحقًا به لحوقًا قويًا، مع ضمير يربطه به غالبًا: كلامُه، سلامُه، فصاحتُه — كلها ترجع بضمير إلى الأول.","وبذلك انتهى باب التوابع: النعت (مضى)، والتوكيد، والعطف، والبدل. وبعده تأتي الخلاصة الجامعة لإعراب الاسم كله."],"examples":["أَسْمَعَ أَخِي أُسَامَةُ مُحَمَّدًا كَلَامَهُ — كلامَه: بدل اشتمال منصوب.","وَسَلَامَهُ — معطوف على كلامه منصوب.","أَعْجَبَنِي الْخَطِيبُ فَصَاحَتُهُ وَطَلَاقَتُهُ — بدل اشتمال ومعطوف عليه.","سَمِعْتُ الْمُؤَذِّنَ صَوْتَهُ — صوتَه: بدل اشتمال منصوب.","أَكْرَمْتُ الْعَالِمَ عِلْمَهُ — علمَه: بدل اشتمال منصوب.","قَرَأْتُ الشَّاعِرَ شِعْرَهُ وَنَثْرَهُ — شعرَه: بدل اشتمال، ونثره: معطوف."],"questions":[{"question":"في «محمدًا كلامَه» إعراب «كلامَه»:","options":["بدل اشتمال من (محمدًا) منصوب بالفتحة","نعت منصوب","مفعول به ثان","مضاف إليه"],"answer":0,"explanation":"كلامَه: بدل اشتمال منصوب بالفتحة؛ لأن محمدًا يشتمل على كلامه، والهاء ضمير يعود عليه في محل جر."},{"question":"«وسلامه» في المثال:","options":["معطوف على (كلامه) منصوب مثله","بدل غلط","نعت","توكيد"],"answer":0,"explanation":"وسلامَه: الواو حرف عطف، وسلامَه معطوف على كلامَه منصوب وعلامة نصبه الفتحة."},{"question":"ضابط بدل الاشتمال:","options":["اشتمال المبدل منه على البدل مع ضمير يعود عليه غالبًا","مطابقة البدل للأول","جزئية البدل من الكل","التصحيح بعد الغلط"],"answer":0,"explanation":"كأعجبني الخطيب فصاحتُه: الفصاحة محتتواة في الخطيب، والهاء تعود عليه."},{"question":"جمع مثال البيت بين:","options":["بدل كل وبدل اشتمال وعطف","النعت والحال","الاستثناء والنداء","التوكيد اللفظي والمعنوي"],"answer":0,"explanation":"أسامة: بدل كل، وكلامه: بدل اشتمال، وسلامه: معطوف — ثلاثة توابع في مثال واحد."},{"question":"لماذا نُصب «كلامه» ولم يرفع؟","options":["لأن متبوعه (محمدًا) منصوب فاتبعه","لأن البدل ينصب دائمًا","لأنه مفعول به","لأنه جاء بعد فعل"],"answer":0,"explanation":"البدل تابع لمتبوعه: محمدًا منصوب (مفعول به) فكلامَه منصوب بالفتحة."}]}]},{"id":"wahi-verse-089","title":"خلاصة جر الأسماء: ثلاثة مواضع","summary":"البيت التاسع والثمانون: باب خلاصة إعراب الاسم؛ جر الأسماء في ثلاثة مواضع: بالحرف والمضاف ثم التابع.","verse":{"number":89,"section":"خلاصة إعراب الاسم","text":"جَرُّ الْأَسَامِي جَاءَ فِي مَوَاضِعْ / بِالْحَرْفِ وَالْمُضَافِ ثُمَّ التَّابِعْ"},"segments":[{"body":["لفظًا لفظًا: «جَرُّ الْأَسَامِي» أي: جر الأسماء (الأسامي جمع اسم). «جَاءَ فِي مَوَاضِعْ» أي: جاء في مواضع وأماكن (مواضعَ بفتح العين في الوصل، والسكون للوقف). «بِالْحَرْفِ» أي: الموضع الأول: بحرف الجر. «وَالْمُضَافِ» الثاني: بالمضاف (أي بالإضافة). «ثُمَّ التَّابِعْ» والثالث: بالتابع (التبعية).","نبدأ بابًا جامعًا لطيفًا: (خلاصة إعراب الاسم). فيه يجمع الناظم كل ما تعلمناه عن إعراب الاسم: جرًّا ورفعًا ونصبًا، في أبيات معدودة.","أول الخلاصة: الجر. الاسم لا يُجر إلا في ثلاثة مواضع، قد مررت بها كلها: (1) بعد حرف جر: مررتُ بزيدٍ. (2) مضافًا إليه: كتابُ زيدٍ. (3) تابعًا لمجرور: مررتُ بزيدٍ الكريمِ.","فاحفظ هذه القاعدة الجامعة: إذا رأيت اسمًا مجرورًا فاسأل: ما الذي جرّه؟ فالجواب واحد من ثلاثة: حرف قبله، أو إضافة، أو تبعية. لا رابع لها."],"examples":["مَرَرْتُ بِزَيْدٍ — زيدٍ: مجرور بحرف الجر (الباء).","كِتَابُ زَيْدٍ — زيدٍ: مجرور بالإضافة (مضاف إليه).","مَرَرْتُ بِزَيْدٍ الْكَرِيمِ — الكريمِ: نعت مجرور بالتبعية.","سَلَّمْتُ عَلَى زَيْدٍ نَفْسِهِ — نفسِهِ: توكيد مجرور بالتبعية.","بَابُ الْبَيْتِ — البيتِ: مضاف إليه مجرور.","جَلَسْتُ فِي مَقْعَدٍ وَثِيرٍ — وثيرٍ: نعت مجرور تبعًا لمقعدٍ."],"questions":[{"question":"مواضع جر الأسماء ثلاثة:","options":["بحرف الجر، وبالمضاف (الإضافة)، ثم بالتابع","المبتدأ والخبر والفاعل","النصب والرفع والجزم","النداء والاستثناء والحال"],"answer":0,"explanation":"قال الناظم: جر الأسامي جاء في مواضع: بالحرف والمضاف ثم التابع."},{"question":"في «كتابُ الطالبِ» جُرّ «الطالبِ» بـ:","options":["الإضافة: مضاف إليه","حرف الجر","التبعية","النداء"],"answer":0,"explanation":"الطالبِ: مضاف إليه مجرور بالكسرة؛ والإضافة الموضع الثاني لجر الأسماء."},{"question":"في «مررتُ بالطالبِ المجتهدِ» المجتهدِ جرّ بـ:","options":["التبعية: نعت تابع لمجرور","الإضافة","حرف الجر","العطف"],"answer":0,"explanation":"المجتهدِ: نعت مجرور بالتبعية لمتبوعه المجرور (الطالبِ)."},{"question":"في «سلمتُ على زيدٍ نفسِهِ» نفسِهِ جرّت بـ:","options":["التبعية: توكيد تابع لمجرور","الإضافة","حرف جر مباشر","النداء"],"answer":0,"explanation":"نفسِهِ: توكيد مجرور بالكسرة تبعًا لزيدٍ المجرور بحرف الجر (على)."},{"question":"أي اسم مجرور يخرج عن المواضع الثلاثة؟","options":["لا شيء؛ كل مجرور سببه واحد من الثلاثة","المجرور بالنداء","المجرور بالاستثناء","المجرور بالحال"],"answer":0,"explanation":"الجر محصور في: حرف جر، أو إضافة، أو تبعية؛ فإن وجدت مجرورًا فابحث عن واحد منها."}]},{"body":["لفظًا لفظًا — تثبيت: «بِالْحَرْفِ» الباء هنا للسببية: أي: بسبب الحرف. «وَالْمُضَافِ» أي: وبسبب المضاف إليه (وقوع الاسم مضافًا إليه). «ثُمَّ التَّابِعْ» ثم للترتيب المهمل: وبسبب التبعية.","ولنراجع حروف الجر التي حفظناها: لام ومن وفي وعن وباء وإلى وكاف ورب ومذ وحتى وعلى — أحد عشر حرفًا؛ كل اسم بعد واحد منها مجرور.","والإضافة: كل اسم ثانٍ بعد اسم مضاف فهو مجرور: غرفةُ نومٍ، مفتاحُ بابٍ، قراءةُ صباحٍ.","والتبعية: كل نعت أو توكيد أو معطوف أو بدل بعد اسم مجرور فهو مجرور: مررتُ برجلٍ كريمٍ، بزيدٍ نفسِهِ، بخالدٍ وعمرو، بالصديقِ أبي بكرٍ.","فهذه الخلاصة مفتاح إعراب أي اسم مجرور تقابله في كتاب أو حديث أو قرآن: مررتُ بالذي خزع... فكل مجرور تجد له سببًا من الثلاثة."],"examples":["بِسْمِ اللَّهِ — اسمِ: مجرور بالباء، اللهِ: مضاف إليه مجرور (إضافة بعد حرف).","مَرَرْتُ بِالصَّدِيقِ أَبِي بَكْرٍ — أبي: بدل مجرور بالتبعية.","سَافَرْتُ فِي شَهْرِ رَمَضَانَ — رمضانَ: مضاف إليه مجرور بالفتحة (ممنوع من الصرف).","كِتَابُ الطَّالِبِ الْجَدِيدِ — الجديدِ: نعت مجرور للطالبِ بالتبعية... (أو للكتاب بحسب المعنى).","هَذَا لِلْمُجْتَهِدِينَ الْمُتَفَوِّقِينَ — المتفوقينَ: نعت مجرور بالياء.","قَرَأْتُ فِي كِتَابِ النَّحْوِ دَرْسًا — النحوِ: مضاف إليه مجرور."],"questions":[{"question":"حروف الجر التي حفظناها عددها وأسماؤها:","options":["أحد عشر: لام ومن وفي وعن وباء وإلى وكاف ورب ومذ وحتى وعلى","خمسة فقط","عشرون","ثلاثة"],"answer":0,"explanation":"الأحد عشر محصورة: لام، من، في، عن، با، إلى، كاف، رب، مذ، حتى، على."},{"question":"في «بسم الله» سبب جر «اللهِ»:","options":["الإضافة (مضاف إليه بعد اسمِ المجرور بالباء)","حرف الجر مباشرة","التبعية","النداء"],"answer":0,"explanation":"اسمِ: مجرور بالباء، واللهِ: مضاف إليه مجرور؛ فالجر الأول بالحرف والثاني بالإضافة."},{"question":"«مررتُ بالصديقِ أبي بكرٍ» أبي:","options":["بدل مجرور بالياء تبعًا للصديقِ","نعت مرفوع","فاعل","مضاف إليه بالكسرة"],"answer":0,"explanation":"أبي: بدل من الصديق مجرور بالتبعية، علامة جره الياء لأنه من الأسماء الخمسة مضاف."},{"question":"متى يجر المنعوت (النعت)؟","options":["إذا كان متبوعه مجرورًا","دائمًا","أبدًا","إذا كان مفردًا"],"answer":0,"explanation":"النعت تابع: مررت بالطالب المجتهدِ — المجتهدِ: نعت مجرور؛ ورأيت الطالبَ المجتهدَ: منصوب."},{"question":"الخلاصة الجامعة لجر الاسم:","options":["اسأل عن الحرف أو الإضافة أو التبعية","كل اسم بعد فعل مجرور","كل اسم نكرة مجرور","كل اسم معرفة مجرور"],"answer":0,"explanation":"لا يجر الاسم إلا بأحد ثلاثة: حرف جر قبله، أو وقوعه مضافًا إليه، أو تبعيته لمجرور."}]}]},{"id":"wahi-verse-090","title":"خلاصة رفع الأسماء: سبعة منازل (1)","summary":"البيت التسعون: رفع الأسماء في سبعة منازل؛ أولها: المبتدأ والخبر والفاعل.","verse":{"number":90,"section":"خلاصة إعراب الاسم","text":"وَرَفْعُهَا فِي سَبْعَةِ الْمَنَازِلِ / فِي مُبْتَدَأ أَوْ خَبَرٍ أَوْ فَاعِلِ"},"segments":[{"body":["لفظًا لفظًا: «وَرَفْعُهَا» أي: ورفع الأسماء (الضمير للأسامي). «فِي سَبْعَةِ الْمَنَازِلِ» أي: في سبعة مواضع (المنازل جمع منزل بمعنى: موضع ومحل). «فِي مُبْتَدَأ» المنزل الأول: المبتدأ. «أَوْ خَبَرٍ» الثاني: الخبر. «أَوْ فَاعِلِ» الثالث: الفاعل.","بعد الجر يجيء الرفع. الرفع معناه: ضمة تلي آخر الاسم لعامل، وهو حال الاسم الأصلية. وله سبعة مواضع يعدها الناظم في هذا البيت والذي بعده.","الأول: المبتدأ: الاسم المرفوع الذي نبدأ به الجملة الاسمية: «العلمُ نورٌ» — العلمُ: مبتدأ مرفوع.","الثاني: الخبر: الذي يتمم معنى المبتدأ ويخبر عنه: «نورٌ» في المثال السابق: خبر مرفوع.","الثالث: الفاعل: الذي قام بالفعل: «كتبَ الطالبُ الدرسَ» — الطالبُ: فاعل مرفوع."],"examples":["الْعِلْمُ نُورٌ — العلمُ: مبتدأ مرفوع، نورٌ: خبر مرفوع.","كَتَبَ الطَّالِبُ الدَّرْسَ — الطالبُ: فاعل مرفوع.","الصِّدْقُ نَجَاةٌ — الصدقُ: مبتدأ، نجاةٌ: خبر.","فَازَ الْمُجْتَهِدُ — المجتهدُ: فاعل مرفوع.","الْبَيْتُ كَبِيرٌ — البيتُ: مبتدأ، كبيرٌ: خبر.","قَرَأَ أَخِي الْكِتَابَ — أخي: فاعل مرفوع بالياء (أسماء خمسة)."],"questions":[{"question":"مواضع رفع الأسماء عددها:","options":["سبعة منازل","ثلاثة","خمسة","تسعة"],"answer":0,"explanation":"قال الناظم: ورفعها في سبعة المنازل؛ أولها المبتدأ ثم الخبر ثم الفاعل."},{"question":"المبتدأ هو:","options":["اسم مرفوع نبدأ به الجملة الاسمية","اسم منصوب بعد فعل","اسم مجرور بعد حرف","اسم بعد إن"],"answer":0,"explanation":"العلمُ نور: العلمُ مبتدأ مرفوع بالضمة، ونورٌ خبره مرفوع."},{"question":"الخبر هو:","options":["الاسم المرفوع الذي يتمم معنى المبتدأ ويخبر عنه","أول الجملة الفعلية","المفعول به","الحال"],"answer":0,"explanation":"نورٌ في (العلم نور): خبر المبتدأ مرفوع بالضمة."},{"question":"الفاعل هو:","options":["الاسم المرفوع الدال على من قام بالفعل","من وقع عليه الفعل","الاسم بعد حرف الجر","الاسم المنادي"],"answer":0,"explanation":"كتب الطالبُ الدرسَ: الطالبُ فاعل مرفوع بالضمة، والدرسَ مفعول به منصوب."},{"question":"في «فاز المجتهدُ» إعراب «المجتهدُ»:","options":["فاعل مرفوع وعلامة رفعه الضمة","مبتدأ مرفوع","خبر مرفوع","مفعول به"],"answer":0,"explanation":"المجتهدُ: فاعل مرفوع بالضمة؛ لأنه من قام بفعل الفوز."}]},{"body":["لفظًا لفظًا — تثبيت الثلاثة الأولى: «في مبتدأ أو خبر أو فاعل» — لاحظ أن الناظم قال (أو) لا (و)؛ لأن الاسم الواحد يكون في منزل واحد منها في الجملة الواحدة.","فالرفع علامته: الضمة في المفرد وجمع التكسير وجمع المؤنث السالم، والواو في جمع المذكر السالم، والألف في المثنى. راجع: المسلمونَ جاءوا (واو)، المسلمانِ جاءا (ألف)، المسلماتُ جئنَ (ضمة).","واعلم أن الفاعل لا يكون إلا بعد فعل مبني للمعلوم، ويتقدمه الفعل غالبًا: نجحَ الطالبُ. أما المبتدأ فيتصدر الجملة الاسمية: الطالبُ ناجحٌ.","وبقي من المنازل السبعة أربعة يذكرها البيت التالي: نائب الفاعل، واسم كان، وخبر إن، والتابع لمرفوع. فتأهب لإكمال العد.","فالقاعدة الآن: إذا رأيت اسمًا مرفوعًا فاسأل: أهو مبتدأ؟ خبر؟ فاعل؟ فإن لم يكن واحدًا منها فهو من الأربعة الباقية."],"examples":["الْمُسْلِمُونَ مُتَعَاوِنُونَ — المسلمونَ: مبتدأ مرفوع بالواو.","الطَّالِبَانِ مُجْتَهِدَانِ — الطالبانِ: مبتدأ مرفوع بالألف.","حَضَرَ الْمُعَلِّمُونَ — المعلمونَ: فاعل مرفوع بالواو.","الْمُسْلِمَاتُ صَالِحَاتٌ — المسلماتُ: مبتدأ مرفوع بالضمة.","نَجَحَ الْمُجْتَهِدَانِ — المجتهدانِ: فاعل مرفوع بالألف.","الدُّنْيَا دَارُ عَمَلٍ — الدنيا: مبتدأ، دارٌ: خبر مرفوع."],"questions":[{"question":"علامة رفع جمع المذكر السالم:","options":["الواو","الضمة","الألف","الياء"],"answer":0,"explanation":"المسلمونَ متعاونون: المسلمونَ مبتدأ مرفوع بالواو؛ وحضر المعلمونَ: فاعل مرفوع بالواو."},{"question":"علامة رفع المثنى:","options":["الألف","الواو","الضمة","الياء"],"answer":0,"explanation":"نجح المجتهدانِ: المجتهدانِ فاعل مرفوع بالألف لأنه مثنى."},{"question":"الفرق بين المبتدأ والفاعل:","options":["المبتدأ يتصدر الجملة الاسمية، والفاعل يتبع فعلًا مبنيًا للمعلوم","لا فرق","الفاعل أول الجملة دائمًا","المبتدأ بعد فعل دائمًا"],"answer":0,"explanation":"العلمُ نور (مبتدأ)، كتب الطالبُ (فاعل بعد فعل)."},{"question":"المنازل الأربعة الباقية للرفع (تأتي في البيت التالي):","options":["نائب الفاعل واسم كان وخبر إن والتابع","المفعول به والحال والتمييز والمستثنى","المضاف إليه واسم الإشارة والنعت والعطف","اسم لا والمنادى والمفعول المطلق والمفعول لأجله"],"answer":0,"explanation":"أتمها الناظم في البيت 91: أو نائبٍ أو اسمِ كانَ أو خبرِ إنَّ وتابعٍ."},{"question":"في «الدنيا دارُ عملٍ» إعراب «دارٌ»:","options":["خبر المبتدأ مرفوع وعلامة رفعه الضمة وهو مضاف","مبتدأ ثان","فاعل","نعت"],"answer":0,"explanation":"دارٌ: خبر مرفوع بالضمة وهو مضاف، وعملٍ: مضاف إليه مجرور."}]}]},{"id":"wahi-verse-091","title":"خلاصة إعراب الاسم: منازل الرفع السبع","summary":"البيت الحادي والتسعون: جمع منازل رفع الاسم السبع، وأن مواضع نصب الأسماء كثيرة كالغمر.","verse":{"number":91,"section":"خلاصة إعراب الاسم","text":"أَوْ نَائِبٍ أَوِ اسْمِ (كَانَ) أَوْ خَبَرْ / (إِنَّ)، وَتَابِعٍ، وَنَصْبُهُمْ غَمَرْ"},"segments":[{"body":["لفظًا لفظًا: «أَوْ» حرف عطف يُكمل عَدَّ ما بدأه الناظم في البيتين السابقين. «نَائِبٌ» أي: نائب الفاعل، وهو الاسم المرفوع الذي يأتي بعد الفعل المبني للمجهول. «اسْمِ (كَانَ)» أي: الاسم المرفوع الذي يقع بعد كان وأخواتها. «أَوْ خَبَرْ (إِنَّ)» أي: الخبر المرفوع الذي يقع بعد إنّ وأخواتها. «وَتَابِعٌ» أي: كل نعت أو عطف أو توكيد أو بدل يتبع مرفوعًا قبله. «وَنَصْبُهُمْ» أي: نصب الأسماء. «غَمَرْ» أي: كثير واسع، من الغَمْر وهو الماء الكثير الذي يغمر.","جمع الناظم في هذا البيت مع البيتين قبله منازلَ رفع الاسم كلها، وهي سبعة: المبتدأ، والخبر، والفاعل، ونائب الفاعل، واسم كان وأخواتها، وخبر إن وأخواتها، والتابع للمرفوع. فكل اسم مرفوع في العربية لا يخرج عن واحد من هؤلاء السبعة.","لماذا سماها منازل؟ لأن الإعراب كالبيت تسكنه الكلمة؛ فالمرفوع لا يسكن إلا في واحد من هذه البيوت السبعة، فإذا وجدت اسمًا مرفوعًا فاسأل نفسك: في أي منزل هو؟","ثم قال عن مواضع نصب الأسماء إنها «غمر» أي كثيرة جدًا واسعة، لا يحصرها بيت ولا بيتان؛ فقد ذكر في المنظومة كلها أكثر من اثني عشر موضعًا للنصب."],"examples":["نَزَلَ القرآنُ من الله — القرآنُ: فاعل مرفوع.","قُرئَ القرآنُ — القرآنُ: نائب فاعل مرفوع.","القرآنُ نورٌ — القرآنُ: مبتدأ مرفوع، ونورٌ: خبر مرفوع.","صارَ القرآنُ نورًا — القرآنُ: اسم صار مرفوع.","إنَّ القرآنَ نورٌ — نورٌ: خبر إنّ مرفوع.","أفضلُ الأمةِ الصديقُ الأكبرُ — الأكبرُ: نعت للصديق، تابع مرفوع."],"questions":[{"question":"عدد منازل رفع الاسم التي جمعتها المنظومة:","options":["سبعة منازل","خمسة منازل","عشرة منازل","ثلاثة منازل"],"answer":0,"explanation":"المنازل السبع: المبتدأ، والخبر، والفاعل، ونائب الفاعل، واسم كان، وخبر إن، والتابع للمرفوع."},{"question":"معنى قوله «وَنَصْبُهُمْ غَمَرْ»:","options":["مواضع نصب الأسماء كثيرة واسعة كالماء الغمر","نصب الأسماء خطأ محرَّم","مواضع النصب ثلاثة فقط","النصب أشرف من الرفع"],"answer":0,"explanation":"الغمر الماء الكثير؛ شبه الناظم كثرة مواضع النصب بالبحر الواسع، فقد مرّ معنا أكثر من اثني عشر موضعًا."},{"question":"الاسم الواقع بعد كان وأخواتها يكون دائمًا:","options":["مرفوعًا ويسمى اسم كان","منصوبًا ويسمى خبر كان","مجرورًا بالإضافة","مجزومًا"],"answer":0,"explanation":"كان وأخواتها ترفع المبتدأ ويسمى اسمها، وتنصب الخبر؛ مثل: صار القرآنُ نورًا."},{"question":"خبر إنّ وأخواتها يكون دائمًا:","options":["مرفوعًا","منصوبًا","مجرورًا","مبنيًا على السكون"],"answer":0,"explanation":"إنّ وأخواتها تنصب المبتدأ (اسم إن) وترفع الخبر؛ مثل: إن القرآنَ نورٌ. نور: خبر إن مرفوع."},{"question":"في «قُرئَ القرآنُ» إعراب «القرآنُ»:","options":["نائب فاعل مرفوع وعلامة رفعه الضمة","فاعل مرفوع","مفعول به منصوب","مبتدأ مرفوع"],"answer":0,"explanation":"الفعل (قُرئ) مبني للمجهول، فالاسم المرفوع بعده نائب فاعل، وهو رابع منازل الرفع."}]},{"body":["لفظًا لفظًا: «وَنَصْبُهُمْ» الضمير «هُم» يعود على الأسماء؛ أي: نصب الأسماء. «غَمَرْ» خبر مبتدأ محذوف تقديره: هو غمر، أي كثير واسع.","ما هي مواضع النصب الكثيرة التي مرّت بنا في المنظومة؟ أهمها: المفعولات الخمسة (المفعول به، والمفعول فيه، والمفعول له، والمفعول معه، والمفعول المطلق)، وخبر كان وأخواتها، واسم إن وأخواتها، والحال، والتمييز، والمستثنى في أكثر أحواله، والمنادى، والتابع للمنصوب.","تأمل: كل واحد من هذه المواضع أخذ من المنظومة أبوابًا كاملة؛ فلهذا صدق الناظم حين وصف نصب الأسماء بأنه غمر لا ساحل له.","وأما مواضع جر الاسم فثلاثة فقط: اسم مسبوق بحرف جر، واسم مضاف إليه، وتابع لمجرور. فالرفع سبعة، والنصب غمر، والجر ثلاثة؛ هذه خلاصة إعراب الاسم كلها."],"examples":["أكرمْ والديكَ — والديكَ: مفعول به منصوب.","انتظرتُكَ اليومَ أمامَ المسجدِ — اليومَ: مفعول فيه (ظرف) منصوب.","كان القرآنُ نورًا — نورًا: خبر كان منصوب.","قرأتُ القرآنَ خاشعًا — خاشعًا: حال منصوبة.","اشتريتُ عشرين كتابًا — كتابًا: تمييز منصوب.","قرأتُ القرآنَ إلا جزءًا — جزءًا: مستثنى منصوب."],"questions":[{"question":"من مواضع نصب الاسم:","options":["الحال والتمييز والمستثنى","المبتدأ والخبر","الفاعل ونائبه","المضاف إليه"],"answer":0,"explanation":"مرّ بنا في المنظومة أكثر من اثني عشر موضعًا للنصب؛ منها: المفعولات الخمسة، وخبر كان، واسم إن، والحال، والتمييز، والمستثنى، والمنادى، والتابع للمنصوب."},{"question":"مواضع جر الاسم عددها:","options":["ثلاثة: بحرف الجر، والإضافة، والتابع للمجرور","سبعة","خمسة","غمر لا يحصى"],"answer":0,"explanation":"الاسم يُجر بثلاثة أشياء فقط: حرف جر سابق، أو إضافة، أو تبعية لمجرور."},{"question":"في «قرأتُ القرآنَ خاشعًا» إعراب «خاشعًا»:","options":["حال منصوبة وعلامة نصبها الفتحة","نعت مرفوع","مفعول به ثانٍ","تمييز منصوب"],"answer":0,"explanation":"خاشعًا بيان لهيئة القارئ وقت القراءة، فهي حال منصوبة بالفتحة."},{"question":"المفعولات الخمسة هي:","options":["به، وفيه، وله، ومعه، والمطلق","به، والحال، والتمييز، والنداء، والاستثناء","كان وإن وظن وأخواتها","الرفع والنصب والجر والجزم والوقف"],"answer":0,"explanation":"المفعول به نحو: أكرم والديك؛ والمفعول فيه: انتظرتك اليوم؛ والمفعول له: ارحم المساكين رجاءَ رحمة الله؛ والمفعول معه: سرتُ والحديقة؛ والمطلق: تلا الإمام تلاوةً خاشعة."},{"question":"في «يا محمدُ» يكون «محمدُ»:","options":["منادى مبنيًا على الضم في محل نصب","مبتدأ مرفوعًا","فاعلًا مرفوعًا","مضافًا إليه"],"answer":0,"explanation":"المنادى المفرد العلم يُبنى على الضم في محل نصب، والنداء أحد مواضع النصب عند الناظم."}]}]},{"id":"wahi-verse-092","title":"إعراب المضارع: النواصب الأربع","summary":"البيت الثاني والتسعون: أن ولن وكي وإذن؛ أربع أدوات تنصب الفعل المضارع بنفسها.","verse":{"number":92,"section":"إعراب الفعل المضارع","text":"(إِذَنْ وَأَنْ وَلَنْ وَكَيْ) نَوَاصِبُ / كَـ(لَنْ تَزُورَهُمْ، إِذَنْ يُعَاتِبُوا)"},"segments":[{"body":["لفظًا لفظًا: «إِذَنْ» حرف جواب بكسر الهمزة وسكون الذال. «وَأَنْ» حرف مصدري بفتح الهمزة وتخفيف النون. «وَلَنْ» حرف نفي للمستقبل. «وَكَيْ» حرف تعليل أي بيان السبب. «نَوَاصِبُ» جمع ناصب؛ والناصب: ما يجعل آخر الفعل المضارع مفتوحًا بعد أن كان مضمومًا.","بعد أن انتهينا من إعراب الاسم نبدأ إعراب الفعل المضارع. والقاعدة الأولى: الفعل المضارع يكون مرفوعًا دائمًا، إلا إذا دخل عليه ناصب فينصب، أو جازم فيجزم. فالرفع هو الأصل، والنصب والجزم عارضان.","أول النواصب أربع أدوات قوية تنصب المضارع بنفسها، لا تحتاج إلى معين: أن، ولن، وكي، وإذن.","أن: حرف مصدري يفيد التعليل غالبًا نحو: يجب أن نتعاونَ. لن: تنفي الفعل في المستقبل نحو: لن أُهمِلَ. كي: تبين السبب والغرض نحو: اجتهد كي تنجحَ. إذن: تجيء جوابًا لكلام سابق وتفيد الترتيب والتسبب نحو: قال: سأجتهد، فقيل له: إذن تنجحَ."],"examples":["يجب أن نتساعدَ — نتساعدَ: مضارع منصوب بأن وعلامته الفتحة.","يحب أن يتعلمَ — يتعلمَ: منصوب بأن.","لن تسافروا — تسافروا: منصوب بلن وعلامته حذف النون.","سافروا كي تستفيدوا — تستفيدوا: منصوب بكي وعلامته حذف النون.","تعلمتُ كي أُعَلِّمَ وأفيدَ — أُعَلِّمَ: منصوب بكي.","إذن تنجحَ (جوابًا لمن قال: سوف أجتهد) — تنجحَ: منصوب بإذن."],"questions":[{"question":"النواصب الأربع التي تنصب المضارع بنفسها:","options":["أن ولن وكي وإذن","لم ولما ولا ولام الأمر","إن وأن ولعل وليت","من وعن وعلى وفي"],"answer":0,"explanation":"قال الناظم: إذن وأن ولن وكي نواصب. وهي تنصب المضارع بنفسها دون أن مضمرة."},{"question":"في «لن أُهمِلَ» إعراب «أُهمِلَ»:","options":["فعل مضارع منصوب بلن وعلامة نصبه الفتحة","فعل مضارع مجزوم بالسكون","فعل ماض مبني على الفتح","فعل مضارع مرفوع"],"answer":0,"explanation":"لن حرف نفي ونصب مبني على السكون، وأُهملَ فعل مضارع منصوب بلن بالفتحة، وفاعله مستتر تقديره أنا."},{"question":"«كي» حرف:","options":["تعليل ينصب المضارع","عطف","استدراك","شرط جازم"],"answer":0,"explanation":"كي تفيد بيان السبب: تعلمتُ كي أُعَلِّمَ؛ أي: لأجل التعليم. وهي من النواصب الأربع."},{"question":"«إذن» الناصبة تكون:","options":["جوابًا لكلام سابق، ولا يحسن الابتداء بها","في أول كل جملة","حرف جر","أداة استفهام"],"answer":0,"explanation":"إذن حرف جواب ونصب؛ تقع جوابًا لطلب أو خبر سابق: قال: يجب أن نتحد، فقيل: إذن ننتصرَ."},{"question":"في «لن تسافروا» علامة نصب «تسافروا»:","options":["حذف النون لأنه من الأفعال الخمسة","الفتحة الظاهرة","الكسرة","السكون"],"answer":0,"explanation":"تسافروا من الأفعال الخمسة؛ ينصب ويجزم بحذف النون، وواو الجماعة فاعل مبني على السكون في محل رفع."}]},{"body":["لفظًا لفظًا في مثال البيت: «لَنْ تَزُورَهُمْ» تزور: فعل مضارع منصوب بلن بالفتحة، والهاء والميم: مفعول به. «إِذَنْ يُعَاتِبُوا» يعاتبوا: منصوب بإذن وعلامة نصبه حذف النون، وواو الجماعة فاعل.","تنبيه مهم: لا تخلط بين أن الناصبة وأختيها! «أَنْ» بفتح الهمزة وتخفيف النون: حرف مصدري ناصب. «إِنْ» بكسر الهمزة: حرف شرط جازم سيأتي. «أَنَّ وإِنَّ» بتشديد النون: حرفان ناسخان ينصبان المبتدأ ويرفعان الخبر، وقد مضيا في باب إن وأخواتها.","لماذا سميت أن حرفًا مصدريًا؟ لأنها مع الفعل بعدها تؤول بمصدر: يجب أن تتعلمَ، أي: يجب التعلمُ. فكأن الحرف يصنع من الفعل مصدرًا.","وإذن لا تأتي إلا جوابًا: إن قال لك أحد: سوف أجتهد، قلت له: إذن تنجحَ. فهي تربط جوابك بكلامه، وتجعل النجاح ثمرة للاجتهاد."],"examples":["أنْ تتعلمَ: أن حرف مصدري ناصب — تتعلمَ: منصوب بالفتحة.","إنْ تجتهدْ تنجحْ: إن حرف شرط جازم (سيأتي في الجوازم).","إنَّ القرآنَ نورٌ: إنَّ ناسخة تنصب المبتدأ وترفع الخبر.","إذن ننتصرَ (جوابًا لمن قال: يجب أن نتحد) — ننتصرَ: منصوب بإذن.","لن أبرحَ — أبرحَ: منصوب بلن، والفاعل مستتر تقديره أنا.","كي تقرأَ: كي حرف تعليل ونصب — تقرأَ: منصوب بالفتحة."],"questions":[{"question":"مثال البيت «لَنْ تَزُورَهُمْ، إِذَنْ يُعَاتِبُوا» يجمع بين ناصبين هما:","options":["لن وإذن","أن وكي","لم ولما","حتى ولام الأمر"],"answer":0,"explanation":"المثال الأول لنصب المضارع بلن بالفتحة، والثاني لنصبه بإذن بحذف النون: يعاتبوا."},{"question":"«أن» المصدرية تفيد مع الفعل بعدها تأويلًا بـ:","options":["مصدر","اسم فاعل","اسم مفعول","جمع"],"answer":0,"explanation":"أن والمضارع بعدها في تأويل مصدر: يحب أن يتعلم أي يحب التعلم؛ ولهذا سميت الحرف المصدري."},{"question":"الفرق بين «أنْ» و«إنَّ»:","options":["أنْ تنصب المضارع، وإنَّ تنصب المبتدأ وترفع خبره","لا فرق بينهما","أنْ للجزم وإنَّ للنصب","أنْ للماضي وإنَّ للمضارع"],"answer":0,"explanation":"أنْ المخففة حرف مصدري ناصب للمضارع، وأنَّ وإنَّ المشددتان ناسختان للجملة الاسمية دخلتا في باب إن وأخواتها."},{"question":"في «إذن يُعَاتِبُوا» علامة النصب:","options":["حذف النون لأنه من الأفعال الخمسة","الفتحة","السكون","حذف حرف العلة"],"answer":0,"explanation":"يعاتبوا فعل مضارع منصوب بإذن وعلامة نصبه حذف النون، وواو الجماعة فاعل في محل رفع مبني على السكون."},{"question":"«إذن ننتصرَ» لا تصح ابتداءً؛ لأن إذن:","options":["حرف جواب يحتاج إلى كلام سابق يجيب عنه","حرف جر لا يدخل على الأفعال","حرف عطف","اسم شرط"],"answer":0,"explanation":"إذن حرف جواب ونصب مبني على السكون لا محل له من الإعراب؛ فلا بد قبلها من كلام تجيب عنه."}]}]},{"id":"wahi-verse-093","title":"نواصب أخرى: اللامان وأو وحتى والواو والفاء","summary":"البيت الثالث والتسعون: ستة نواصب أخرى تنصب المضارع بأن مضمرة: اللامان وأو وحتى والواو والفاء.","verse":{"number":93,"section":"إعراب الفعل المضارع","text":"وَبَعْدَ لَامَيْنِ وَ(أَوْ) وَ(حَتَّىٰ) / وَالْوَاوِ وَالْفَاءِ لَهُ نَصَبْتَا"},"segments":[{"body":["لفظًا لفظًا: «وَبَعْدَ» أي: وبعد الأدوات الأربع المتقدمة تأتي نواصب أخرى. «لَامَيْنِ» مثنى لام: لامان اثنتان، وهما لام التعليل ولام الجحود. «وَ(أَوْ)» حرف العطف المعروف، لكنه هنا بمعنى خاص. «وَ(حَتَّىٰ)» حرف التعليل والغاية. «وَالْوَاوِ وَالْفَاءِ» معطوفان على لامين: أي وبعد الواو والفاء أيضًا. «لَهُ» أي: للمضارع. «نَصَبْتَا» ماضٍ مثنى: نصبت الواو والفاء.","اللام الأولى: لام التعليل، وتفيد بيان السبب مثل كي: جئتُ لأتعلمَ، وسافروا لتستفيدوا. واللام الثانية: لام الجحود، وتقع بعد (ما كان) و(لم يكن): ما كان قيسٌ ليسافرَ، لم يكن أخوك ليتأخرَ.","و«حتى» حرف تعليل وغاية: جثوتُ حتى أتعلمَ، وصُمْ حتى تغيبَ الشمس. وأما «أو» فتنصب المضارع إذا كانت بمعنى (إلى أن): سأجتهد أو أنجحَ، أو بمعنى (إلا أن): سأفتح الباب أو ينكسرَ.","هذه الأدوات الستة كلها تنصب المضارع، لكن ليس بنفسها، بل بـ«أن» مضمرة محذوفة بعدها؛ ولهذا فرّق الناظم بينها وبين الأربع الأولى."],"examples":["جئتُ لأتعلمَ — لام التعليل، وأتعلمَ: منصوب بأن مضمرة بعد اللام.","ما كان أخوك ليتأخرَ — لام الجحود، وليتأخرَ: منصوب بأن مضمرة.","صُمْ حتى تغيبَ الشمس — تغيبَ: منصوب بحتى.","سأجتهد أو أنجحَ — أو بمعنى (إلى أن)، وأنجحَ: منصوب.","سأفتح الباب أو ينكسرَ — أو بمعنى (إلا أن)، وينكسرَ: منصوب.","سأعيد الشرح أو تفهموا — أو بمعنى (إلى أن)، وتفهموا: منصوب بحذف النون."],"questions":[{"question":"«اللامين» في البيت هما:","options":["لام التعليل ولام الجحود","لام الأمر ولام الابتداء","لام الجر ولام التوكيد","لام التعجب ولام الاستفتاح"],"answer":0,"explanation":"لام التعليل نحو: جئت لأتعلم؛ ولام الجحود تقع بعد ما كان ولم يكن: ما كان قيسٌ ليسافر."},{"question":"لام الجحود تقع بعد:","options":["ما كان ولم يكن","كل فعل ماض","حروف الجر","أدوات الشرط"],"answer":0,"explanation":"لام الجحود لا تقع إلا بعد (ما كان) و(لم يكن): لم يكن أخوك ليتأخر."},{"question":"«أو» تنصب المضارع إذا كانت بمعنى:","options":["إلى أن أو إلا أن","العطف على الجمل","التخيير بين الأشياء","الشك"],"answer":0,"explanation":"الأشهر في (أو) كونها حرف عطف، لكنها تنصب المضارع إذا جاءت بمعنى (إلى أن): سأجتهد أو أنجحَ، أو (إلا أن): سأفتح الباب أو ينكسرَ."},{"question":"في «صم حتى تغيبَ الشمس» إعراب «تغيبَ»:","options":["فعل مضارع منصوب بأن مضمرة بعد حتى وعلامة نصبه الفتحة","مضارع مرفوع بالضمة","مضارع مجزوم","ماض مبني على الفتح"],"answer":0,"explanation":"حتى حرف تعليل وغاية مبني على السكون، وتغيبَ منصوب بالفتحة لأن مضمرة بعد حتى، والفاعل الشمس."},{"question":"الأدوات الستة في هذا البيت تنصب المضارع:","options":["بأن مضمرة محذوفة بعدها","بنفسها دون واسطة","بالكسرة","لا تنصب أصلًا"],"answer":0,"explanation":"الأربع الأولى (أن ولن وكي وإذن) تنصب بنفسها، والستة الباقية تنصب بأن مضمرة محذوفة؛ ولذا يصح أن يقال: نواصب المضارع أربع فقط."}]},{"body":["لفظًا لفظًا: «وَالْوَاوِ» أي: واو المعية، وهي واو بمعنى (مع). «وَالْفَاءِ» أي: فاء السببية، وتفيد الترتيب مع التعليل. «لَهُ» أي: للفعل المضارع. «نَصَبْتَا» أي: كل واحدة منهما نصبته.","متى تنصب الواو والفاء؟ إذا وقعتا بعد نفي أو طلب. فتقول: اجتهدْ فتنجحَ، واجتهدْ وتنجحَ؛ ولا تتركِ الصلاةَ وترجوَ راحةَ البال.","ما الطلب؟ كل ما دل على مطلوب، وهو ثمانية أشياء: الأمر، والنهي، والاستفهام، والدعاء، والتمني، والترجي، والعرض، والتحضيض. فإذا جاءت الفاء أو الواو بعد واحد منها نصبتا المضارع.","قارن: «اجتهدتَ فنجحتَ» بالفاء العاطفة على الماضي لا عمل لها، و«اجتهدْ فتنجحَ» بالفاء السببية بعد الطلب ناصبة. والفرق ظاهر في آخر الفعل: نجحتَ بالفتح لأنه ماض، وتنجحَ بالفتح لأنه منصوب."],"examples":["اجتهدْ فتنجحَ — فاء السببية بعد الأمر، وتنجحَ: منصوب.","اجتهدْ وتنجحَ — واو المعية بعد الأمر، وتنجحَ: منصوب.","لا تتركِ الصلاةَ وترجوَ راحةَ البال — واو المعية بعد النهي، وترجوَ: منصوب.","ليتني غني فأتصدقَ — فاء السببية بعد التمني، وفأتصدقَ: منصوب.","ليتني غني وأتصدقَ — واو المعية بعد التمني.","لا تُكْثِرِ النومَ وتأتيَ مثلَه — واو المعية بعد النهي، وتأتيَ: منصوب بحذف حرف العلة."],"questions":[{"question":"تنصب الواو والفاء المضارع إذا وقعتا بعد:","options":["نفي أو طلب","مبتدأ","حرف جر","فعل ماض فقط"],"answer":0,"explanation":"واو المعية وفاء السببية تنصبان المضارع بعد نفي أو طلب: اجتهد فتنجحَ، لم تجتهدْ تنجحَ."},{"question":"الطلب الذي بعده تنصب الفاء والواو أنواعه:","options":["ثمانية: منها الأمر والنهي والدعاء والتمني","ثلاثة فقط","نوعان","عشرة"],"answer":0,"explanation":"الطلب ثمانية أشياء: الأمر والنهي والاستفهام والدعاء والتمني والترجي والعرض والتحضيض."},{"question":"في «لا تتركِ الصلاةَ وترجوَ راحةَ البال» إعراب «ترجوَ»:","options":["فعل مضارع منصوب بواو المعية وعلامة نصبه الفتحة","معطوف مرفوع","مجزوم بلا الناهية","ماض"],"answer":0,"explanation":"لا الناهية اقتصر جزمها على (تترك)، والواو واو معية ناصبة لـ(ترجو)؛ فتتركْ مجزوم وترجوَ منصوب."},{"question":"مجموع نواصب المضارع التي ذكرها الناظم في البيتين:","options":["عشرة","أربعة","ستة","خمسة"],"answer":0,"explanation":"أربعة تنصب بنفسها: أن ولن وكي وإذن، وستة بأن مضمرة: اللامان وأو وحتى والواو والفاء؛ المجموع عشرة."},{"question":"معنى «نَصَبْتَا» في آخر البيت:","options":["نصبت الواو والفاء (فعل ماض مثنى)","نصبتُ أنا","نصبتَ أنت","اسم مفعول"],"answer":0,"explanation":"نصبتا فعل ماض مبني على الفتح، والألف فاعل تثنية يعود على الواو والفاء."}]}]},{"id":"wahi-verse-094","title":"الجوازم الأربع: لام الأمر ولا ولم ولما","summary":"البيت الرابع والتسعون: أربع أدوات تجزم الفعل المضارع وحده دائمًا: اللام ولا ولم ولما.","verse":{"number":94,"section":"إعراب الفعل المضارع","text":"وَأَرْبَعٌ تَعْمَلُ دَوْمًا جَزْمًا / اللَّامُ، ثُمَّ (لَا وَلَمْ وَلَمَّا)"},"segments":[{"body":["لفظًا لفظًا: «وَأَرْبَعٌ» أي: أربع أدوات. «تَعْمَلُ» أي: تعمل عملها في الفعل. «دَوْمًا» مفعول مطلق أو حال بمعنى: دائمًا. «جَزْمًا» أي: تجزم المضارع. «اللَّامُ» أي: لام الأمر. «ثُمَّ» حرف عطف للترتيب. «لَا» الناهية. «وَلَمْ» حرف نفي. «وَلَمَّا» حرف نفي أيضًا لكن بمعنى خاص.","ما الجزم؟ أن يصير آخر الفعل المضارع ساكنًا بعد أن كان متحركًا: من «يذهبُ» إلى «يذهبْ». وهذه الأربعة تجزم فعلًا واحدًا هو الفعل الذي يليها مباشرة، وتعمل دائمًا لا تتخلف.","«لم» حرف نفي يقلب زمن الفعل إلى الماضي: لم يذهبْ أي: ما ذهب. و«لمّا» تنفي أمرًا متوقع الحدوث لم يحدث بعد: جاء الوفد إلى الكلية ولمّا يدخلوا القاعةَ بعد.","فالفرق بينهما: لم للنفي المطلق في الزمن الماضي، ولمّا لنفي ما كان منتظرًا وقوعه إلى الآن. وكلتاهما تجزم المضارع."],"examples":["لم يذهبْ — يذهبْ: مضارع مجزوم بلم وعلامة جزمه السكون.","لم يذهبوا — يذهبوا: مجزوم بلم وعلامة جزمه حذف النون.","لم يكن النحوُ صعبًا — يكنْ: مجزوم بلم.","لمّا أذهبْ بعدُ — أذهبْ: مجزوم بلمّا.","جاء الوفدُ ولمّا يدخلوا القاعةَ — يدخلوا: مجزوم بلمّا وعلامته حذف النون.","لم يلذَّ بشربه — يلذَّ: مجزوم بلم، والفاعل مستتر تقديره هو."],"questions":[{"question":"الأدوات الأربع التي تجزم فعلًا واحدًا دائمًا:","options":["لام الأمر ولا الناهية ولم ولمّا","أن ولن وكي وإذن","إن ومن وما ومتى","حتى وأو والواو والفاء"],"answer":0,"explanation":"قال الناظم: وأربع تعمل دومًا جزمًا: اللام، ثم لا ولم ولمّا."},{"question":"الفرق بين «لم» و«لمّا»:","options":["لم تنفِ الماضي، ولمّا تنفي المتوقع حدوثه","لم للأمر ولمّا للنهي","لم للحاضر ولمّا للمستقبل","لا فرق بينهما"],"answer":0,"explanation":"لم تنفي وقلبها الزمن إلى الماضي: لم يذهب أي ما ذهب؛ ولمّا تنفي الأمر المتوقع: جاء الوفد ولمّا يدخلوا."},{"question":"في «لم يذهبوا» علامة الجزم:","options":["حذف النون لأنه من الأفعال الخمسة","السكون","حذف حرف العلة","الفتحة"],"answer":0,"explanation":"يذهبوا من الأفعال الخمسة؛ تجزم بحذف النون، وواو الجماعة فاعل مبني على السكون في محل رفع."},{"question":"الجزم في اللغة معناه:","options":["القطع؛ فكأن الجازم قطع حركة آخر الفعل","الوصل","الرفع","التشديد"],"answer":0,"explanation":"سمي جزمًا لأن آخر الفعل يُقطع عنه ما كان فيه من حركة أو حرف: يذهبُ يصير يذهبْ."},{"question":"«لمّا يدخلوا» في مثل: جاء الوفد إلى الكلية ولمّا يدخلوا القاعة، تفيد:","options":["أن الدخول كان متوقعًا ولم يحدث بعد","أن الدخول مستحيل","أن الدخول حدث أمس","الأمر بالدخول"],"answer":0,"explanation":"لمّا حرف نفي للأمر المتوقع حدوثه؛ أي: كان منتظرًا أن يدخلوا فلم يدخلوا بعد."}]},{"body":["لفظًا لفظًا: «اللَّامُ» أي لام الأمر، وهي لام مكسورة تأتي للطلب: لتفتحْ بيتك. و«لَا» الناهية، وهي التي تنهى عن الفعل: لا تتأخرْ عن الصلاة. وهما يجزمان كما تجزم لم ولمّا.","لا الناهية: يطلب بها المتكلم الكف عن الفعل: لا تتأخرْ عن الصلاة، ولا تركضْ في المسجد، ولا تقطعوا أرحامكم. ولا تخف: هذه لا تختلف عن لا النافية في الشكل، لكن الناهية يتبعها مجزوم، والنافية يتبعها مرفوع: لا يفعلُ الخيرَ مهملٌ.","لام الأمر: لتفتحْ بيتك، ولتُكرمْ ضيوفك، ولتسمعْ مني قبل أن تحكم. وتفيد الطلب والإرشاد برفق.","علامات الجزم ثلاث: السكون في الفعل الصحيح الآخر: لم يذهبْ. وحذف النون في الأفعال الخمسة: لم يذهبوا. وحذف حرف العلة في المعتل الآخر: لم يدعُ، لم يخشَ."],"examples":["لا تتأخرْ عن الصلاة — تتأخرْ: مجزوم بلا الناهية وعلامته السكون.","لا تركضْ في المسجد — تركضْ: مجزوم بلا الناهية.","لا تقطعوا أرحامكم — تقطعوا: مجزوم وعلامته حذف النون.","لتفتحْ بيتك — تفتحْ: مجزوم بلام الأمر وعلامته السكون.","لتُكرمْ ضيوفك — تُكرمْ: مجزوم بلام الأمر.","لم يدعُ — يدعُ: مجزوم وعلامته حذف حرف العلة (الواو)."],"questions":[{"question":"في «لا تتأخرْ عن الصلاة» إعراب «تتأخرْ»:","options":["فعل مضارع مجزوم بلا الناهية وعلامة جزمه السكون","منصوب بلا","مرفوع بالضمة","ماض مبني على الفتح"],"answer":0,"explanation":"لا الناهية حرف نهي وجزم مبني على السكون لا محل له من الإعراب، وتتأخرْ مجزوم بالسكون."},{"question":"لام الأمر مثالها:","options":["لتُكرمْ ضيوفك","لا تُكرمْ ضيوفك","لم يكرمْ ضيوفه","إن تكرمْ ضيوفك"],"answer":0,"explanation":"لام الأمر لام مكسورة للطلب تجزم المضارع: لتفتحْ بيتك ولتسمعْ مني قبل أن تحكم."},{"question":"علامات جزم المضارع ثلاث هي:","options":["السكون وحذف النون وحذف حرف العلة","الفتحة والكسرة والضمة","السكون فقط","حذف النون فقط"],"answer":0,"explanation":"السكون للصحيح الآخر: لم يذهبْ؛ وحذف النون للأفعال الخمسة: لم يذهبوا؛ وحذف حرف العلة للمعتل: لم يدعُ."},{"question":"«لَا» في «لا تقطعوا أرحامكم» تسمى:","options":["لا الناهية الجازمة","لا النافية للجنس","لا العاطفة","لا الزائدة"],"answer":0,"explanation":"هي لا الناهية: حرف نهي وجزم؛ وتقطعوا مجزوم بحذف النون، وواو الجماعة فاعل."},{"question":"مجموع جوازم المضارع التي تجزم فعلًا واحدًا:","options":["أربعة: اللام ولا ولم ولمّا","خمسة","عشرة","اثنا عشر"],"answer":0,"explanation":"هذه الأربعة تجزم فعلًا واحدًا دائمًا، وسيأتي النوع الثاني: جوازم الشرط التي تجزم فعلين."}]}]},{"id":"wahi-verse-095","title":"جوازم الشرط: قوية تجزم فعلين","summary":"البيت الخامس والتسعون: أدوات الشرط الجازمة تجزم فعل الشرط وجوابه معًا، مثل: من يكبرْ ينبهْ.","verse":{"number":95,"section":"إعراب الفعل المضارع","text":"جَوَازِمُ الشَّرْطِ قَوِيَّةٌ، فَهِي / تَجْزِمْ فِعْلَيْنِ، كَ(مَنْ يَكْبَرْ يَنْبَهِ)"},"segments":[{"body":["لفظًا لفظًا: «جَوَازِمُ» جمع جازم، وهو ما يجزم الفعل. «الشَّرْطِ» مضاف إليه؛ والشرط: أن يتوقف حصول شيء على حصول شيء آخر. «قَوِيَّةٌ» خبر مبتدأ محذوف: هي قوية. «فَهِي» الفاء استئنافية، والهاء مبتدأ. «تَجْزِمْ» خبره. «فِعْلَيْنِ» مثنى فعل: فعلين اثنين. «كَ» الكاف للتشبيه: مثل. «مَنْ يَكْبَرْ يَنْبَهِ» أي: من يكبرْ في السن والعقل يَنْبَهْ أي يصير نبيهًا فطنًا.","لماذا قال الناظم عن جوازم الشرط إنها قوية؟ لأن الجوازم الأربعة السابقة كانت تجزم فعلًا واحدًا فقط، أما أدوات الشرط فتجزم فعلين معًا: فعل الشرط وجواب الشرط. فهي أقوى عملًا من أختها.","ما فعل الشرط وما جواب الشرط؟ تأمل: «من يجتهدْ ينجحْ». «يجتهد» فعل يتوقف عليه النجاح؛ فهو فعل الشرط. و«ينجح» هو الثمرة والجواب؛ فهو جواب الشرط. وكلاهما مجزوم.","ومثال الناظم من الحياة: «مَنْ يَكْبَرْ يَنْبَهِ»؛ أي كل من كبر صار نبيهًا فطنًا. فكبرَه شرط، ونبوغه ونباهته جواب، وكلا الفعلين مجزوم."],"examples":["مَنْ يَجْتَهِدْ يَنْجَحْ — يجتهد: فعل الشرط مجزوم بالسكون، وينجح: جواب الشرط مجزوم بالسكون.","مَنْ يَكْبَرْ يَنْبَهِ — مثال البيت: كلا الفعلين مجزوم بالسكون.","مَنْ يَعْمَلْ خيرًا يُجْزَ به — يعمل: فعل الشرط مجزوم، ويُجزَ: جواب الشرط مجزوم.","إنْ تأتِ أُكرمْكَ — تأتِ: مجزوم بحذف حرف العلة، وأُكرمْكَ: مجزوم بالسكون.","مَنْ يَدْعُ يَسْمَعْهُ الله — يدعُ: مجزوم بحذف حرف العلة، ويسمعْه: مجزوم بالسكون.","إنْ تؤمنوا وتتقوا يؤتِكم — تؤمنوا: مجزوم بحذف النون، ويؤتِكم: مجزوم بحذف حرف العلة."],"questions":[{"question":"لماذا وصف الناظم جوازم الشرط بأنها «قوية»؟","options":["لأنها تجزم فعلين معًا لا فعلًا واحدًا","لأنها أصعب في الحفظ","لأنها أكثر عددًا من الحروف","لأنها تنصب أيضًا"],"answer":0,"explanation":"لم ولمّا ولا واللام تجزم فعلًا واحدًا، وأدوات الشرط تجزم فعل الشرط وجوابه؛ فعملها أقوى."},{"question":"في «من يكبرْ ينبهْ» فعل الشرط هو:","options":["يكبرْ","ينبهْ","من","كلاهما معًا"],"answer":0,"explanation":"فعل الشرط هو الذي يتوقف عليه الجواب: يكبرْ؛ وجواب الشرط: ينبهْ؛ وكلاهما مضارع مجزوم بالسكون."},{"question":"معنى «يَنْبَهِ» في مثال البيت:","options":["يصير نبيهًا فطنًا","ينام","يكبر","يعمل"],"answer":0,"explanation":"يَنْبَهْ من النباهة وهي الفطنة وقوة العقل: من يكبرْ في السن والتجربة يَنْبَهْ."},{"question":"في «من يدعُ يسمعْه الله» علامة جزم «يدعُ»:","options":["حذف حرف العلة لأنه معتل الآخر","السكون","حذف النون","الفتحة"],"answer":0,"explanation":"يدعُ معتل الآخر بالواو؛ يجزم بحذف حرف العلة فيصير يدعْ، ويسمعْه جواب الشرط مجزوم بالسكون."},{"question":"جواب الشرط يكون دائمًا:","options":["مجزومًا","منصوبًا","مرفوعًا","مبنيًا على الفتح"],"answer":0,"explanation":"جوازم الشرط تجزم فعلين: فعل الشرط وجواب الشرط؛ فالجواب مجزوم كما أن فعل الشرط مجزوم."}]},{"body":["لفظًا لفظًا في الإعراب: في «مَنْ يَكْبَرْ يَنْبَهِ»: (مَنْ) اسم شرط جازم مبني على السكون في محل رفع مبتدأ. (يَكْبَرْ) فعل مضارع مجزوم بالسكون لأنه فعل الشرط، وفاعله مستتر تقديره هو. (يَنْبَهِ) فعل مضارع مجزوم بالسكون لأنه جواب الشرط، وفاعله مستتر تقديره هو. والجملة الاسمية من أداة الشرط وفعلها في محل رفع خبر المبتدأ، وجملة الجواب لا محل لها من الإعراب.","انتبه لموضع دقيق: علامة الجزم تتغير بحسب آخر الفعل: صحيح الآخر يجزم بالسكون: من يعملْ يُجزَ. معتل الآخر يجزم بحذف حرف العلة: إن تأتِ أُكرمْكَ، من يدعُ يسمعْه الله. ومن الأفعال الخمسة يجزم بحذف النون: إن تؤمنوا وتتقوا يؤتِكم أجرًا.","وقد يقترن جواب الشرط بالفاء إذا كان الجواب جملة اسمية أو فيها معنى التعليل، نحو: إن تجتهدْ فأنت ناجح. أما إذا كان الجواب مضارعًا صريحًا فيجزم مباشرة بلا فاء.","هذا الباب من أجمل أبواب العربية؛ لأنه يعلمك منطق اللغة: كل شرط له جواب، وكل عمل له ثمرة؛ ولهذا جاءت القواعد كلها في صورة شرط وجواب."],"examples":["من يجتهدْ ينجحْ — يجتهد: مجزوم بالسكون؛ لأنه صحيح الآخر.","إن تأتِ أُكرمْكَ — تأتِ: مجزوم بحذف حرف العلة (الياء).","من يدعُ يسمعْه الله — يدعُ: مجزوم بحذف حرف العلة (الواو).","إن تؤمنوا وتتقوا يؤتِكم أجرًا — تؤمنوا وتتقوا: مجزومان بحذف النون.","من يزرعْ يحصدْ — كلا الفعلين مجزوم بالسكون.","إن تجتهدْ فأنت ناجح — الجواب جملة اسمية مقترنة بالفاء."],"questions":[{"question":"في «إن تأتِ أُكرمْكَ» علامة جزم «تأتِ»:","options":["حذف حرف العلة","السكون","حذف النون","الضمة"],"answer":0,"explanation":"تأتِ معتل الآخر بالياء؛ فعل الشرط مجزوم وعلامة جزمه حذف حرف العلة، وأُكرمْكَ جواب الشرط مجزوم بالسكون."},{"question":"«مَنْ» في «من يجتهدْ ينجحْ» تعرب:","options":["اسم شرط جازم مبني على السكون في محل رفع مبتدأ","حرف نفي","حرف جر","فاعل"],"answer":0,"explanation":"من اسم من أسماء الشرط الجازمة مبني على السكون في محل رفع مبتدأ، وجملة الشرط في محل رفع خبره."},{"question":"متى يقترن جواب الشرط بالفاء؟","options":["إذا كان الجواب جملة اسمية أو شبهها","دائمًا","أبدًا","إذا كان الفعل ماضيًا فقط"],"answer":0,"explanation":"إن تجتهد فأنت ناجح: الجواب جملة اسمية فاقترن بالفاء؛ أما المضارع الصريح فيجزم مباشرة: من يزرع يحصد."},{"question":"في «إن تؤمنوا وتتقوا» علامة جزم الفعلين:","options":["حذف النون لأنهما من الأفعال الخمسة","السكون","حذف حرف العلة","الفتحة"],"answer":0,"explanation":"تؤمنوا وتتقوا من الأفعال الخمسة؛ تجزمان بحذف النون، وواو الجماعة فاعل مبني على السكون في محل رفع."},{"question":"جملة جواب الشرط محلها من الإعراب:","options":["لا محل لها من الإعراب","في محل رفع خبر","في محل نصب مفعول","في محل جر"],"answer":0,"explanation":"جملتا فعل الشرط وجواب الشرط لا محل لهما من الإعراب؛ والجملة الاسمية من الأداة وفعل الشرط في محل رفع خبر المبتدأ."}]}]},{"id":"wahi-verse-096","title":"أدوات الشرط الجازمة التسع","summary":"البيت السادس والتسعون: عدّ أدوات الشرط الجازمة: إن وما وأي ومتى وإذما وأين وأنّى وحيثما ومهما.","verse":{"number":96,"section":"إعراب الفعل المضارع","text":"وَ(إِنْ، وَمَا، أَيُّ، مَتَىٰ، وَإِذْمَا / وَأَيْنَ، أَنَّىٰ، حَيْثُمَا، وَمَهْمَا)"},"segments":[{"body":["لفظًا لفظًا: «وَإِنْ» بكسر الهمزة وسكون النون: حرف الشرط الأشهر. «وَمَا» اسم شرط لغير العاقل. «وَأَيُّ» اسم شرط يتغير معناه بحسب ما يضاف إليه. «وَمَتَىٰ» اسم شرط للزمان. «وَإِذْمَا» حرف شرط مثل إن. «وَأَيْنَ» و«أَنَّىٰ» و«حَيْثُمَا» ثلاثة أسماء للمكان. «وَمَهْمَا» مركبة من مهما: مهما كان الأمر.","عدّ الناظم في هذا البيت تسع أدوات للشرط الجازم، وقد تقدمت عاشرتها (مَنْ) في مثال البيت الماضي: من يكبرْ ينبهْ. فالعدد عشرة في المنظومة، وزاد الشرح عليها (أيّان) للزمان و(كيفما) للحال فصارت اثنتي عشرة أداة.","نكتة لطيفة: أدوات الشرط الجازمة كلها أسماء إلا اثنتين: (إنْ) و(إذما)؛ فهما حرفان، ولهذا يعربان إعراب الحروف: حرف شرط وجزم مبني على السكون لا محل له من الإعراب.","وكل أداة لها ميدانها: من للعاقل: من يجتهدْ ينجحْ. وما ومهما لغير العاقل: ما تعملْ يُكتبْ. ومتى وإذما وأيان للزمان. وأين وأنّى وحيثما للمكان. وأيّ على حسب إضافتها."],"examples":["إنْ تجتهدْ تنجحْ — إنْ: حرف شرط جازم مبني على السكون لا محل له من الإعراب.","مَنْ يجتهدْ ينجحْ — مَنْ: اسم شرط للعاقل.","ما تعملْ يُكتبْ — ما: اسم شرط لغير العاقل.","مهما تعملْ يُكتبْ — مهما: اسم شرط لغير العاقل.","متى تسافرْ أسافرْ معك — متى: اسم شرط للزمان.","إذما تعملْ تُوفَّقْ — إذما: حرف شرط جازم."],"questions":[{"question":"أداتا الشرط الحرفان (وليستا اسمين) هما:","options":["إن وإذما","من وما","أين وأنّى","متى وأيّ"],"answer":0,"explanation":"أدوات الشرط الجازمة كلها أسماء سوى (إن) و(إذما) فهما حرفان؛ يعربان: حرف شرط وجزم مبني على السكون لا محل له من الإعراب."},{"question":"«مَنْ» و«ما» تختصان بـ:","options":["مَنْ للعاقل، وما لغير العاقل","من للمكان، وما للزمان","كلتاهما للعاقل","كلتاهما للزمان"],"answer":0,"explanation":"من يجتهد ينجح: من للعاقل؛ وما تعمل يُكتب: ما لغير العاقل، وكذلك مهما."},{"question":"عدد أدوات الشرط الجازمة في المنظومة مع زيادة الشرح:","options":["اثنتا عشرة أداة","تسع فقط","خمس","عشرون"],"answer":0,"explanation":"النظم ذكر تسعًا في هذا البيت و(من) في مثال سابقه فتمّت عشرًا، والشرح زاد أيّان وكيفما فصارت اثنتي عشرة."},{"question":"«متى» اسم شرط يفيد:","options":["الزمان","المكان","العاقل","الحال"],"answer":0,"explanation":"متى للزمان: متى تسافر أسافر معك؛ ومثله أيان."},{"question":"في «ما تعملْ يُكتبْ» إعراب «ما»:","options":["اسم شرط جازم مبني على السكون في محل رفع مبتدأ","حرف نفي","حرف جر","ضمير"],"answer":0,"explanation":"ما اسم شرط جازم لغير العاقل مبني على السكون في محل رفع مبتدأ، وجملة الشرط في محل رفع خبره."}]},{"body":["لفظًا لفظًا: «وَأَيْنَ، أَنَّىٰ، حَيْثُمَا» ثلاث كلمات كلها للمكان: أين تسكنْ أسكنْ بجوارك، وحيثما تكنْ أزرْك. «وَمَهْمَا» أي: مهما كان الشيء: مهما تعملْ يُكتبْ لك أو عليك.","و«أيّ» أعجب هذه الأدوات؛ لأنها تتنقل بين المعاني بحسب ما يضاف إليه بعدها: أيُّ طالبٍ يجتهدْ ينجحْ (مبتدأ للعاقل)، أيَّ كتابٍ تقرأْ أقرأْ (مفعول به)، أيَّ يومٍ تزرْ أزرْ (ظرف زمان). فانظر إلى المضاف إليه تعرف المعنى.","وزاد الشرح على أدوات النظم: (أيّان) للزمان نحو: أيان تعملْ تُوفَّقْ، و(كيفما) للحال نحو: كيفما تركبْ أركبْ؛ أي: على أي حال كنتَ كنتُ معك.","لاحظ البناء المشترك: كل هذه الأدوات مبنية لا تعرب بتغير أواخرها؛ لأنها من الأسماء المبنية. والعمل واحد: تجزم الفعل بعدها والفعل الجواب."],"examples":["أين تسكنْ أسكنْ بجوارك — أين: اسم شرط للمكان في محل نصب ظرف مكان.","حيثما تكنْ أزرْك — حيثما: اسم شرط للمكان.","أيُّ طالبٍ يجتهدْ ينجحْ — أي: اسم شرط في محل رفع مبتدأ.","أيَّ كتابٍ تقرأْ أقرأْ — أي: اسم شرط في محل نصب مفعول به مقدم.","أيان تعملْ تُوفَّقْ — أيان: اسم شرط للزمان (زيادة الشرح).","كيفما تركبْ أركبْ — كيفما: اسم شرط للحال (زيادة الشرح)."],"questions":[{"question":"الأدوات الثلاث التي تفيد المكان في البيت:","options":["أين وأنّى وحيثما","إن وإذما ومتى","من وما ومهما","أي وأيان وكيفما"],"answer":0,"explanation":"أين وأنّى وحيثما كلها أسماء شرط للمكان: أين تسكن أسكن بجوارك."},{"question":"معنى «أيّ» يتحدد بـ:","options":["ما يضاف إليه بعدها","أول الجملة دائمًا","الفاعل فقط","القافية"],"answer":0,"explanation":"أي تكون مبتدأ أو مفعولًا أو ظرفًا بحسب المضاف إليه: أي طالب، أي كتاب، أي يوم."},{"question":"في «كيفما تركبْ أركبْ» تفيد «كيفما»:","options":["الحال","الزمان","المكان","العاقل"],"answer":0,"explanation":"كيفما اسم شرط للحال زاده الشرح على أدوات النظم؛ أي: على أي حال ركبتَ ركبتُ."},{"question":"«مهما» في «مهما تعملْ يُكتبْ»:","options":["اسم شرط جازم لغير العاقل","حرف عطف","حرف نفي","ظرف زمان"],"answer":0,"explanation":"مهما كما: اسم شرط جازم لغير العاقل مبني في محل رفع مبتدأ، وجملتا الشرط والجواب مجزومتان."},{"question":"أدوات الشرط الجازمة من حيث البناء والإعراب:","options":["كلها مبنية","كلها معربة","المعرب منها أكثر","بعضها أفعال"],"answer":0,"explanation":"أدوات الشرط كلها مبنية: الأسماء منها كمن وما وأي، والحرفان إن وإذما؛ والمبني لا يتغير آخره."}]}]},{"id":"wahi-verse-097","title":"رفع الفعل المضارع الخالي","summary":"البيت السابع والتسعون: الفعل المضارع يُرفع إذا خلَا من ناصب وجازم، مثل: ننتهي، ويقبل العلي.","verse":{"number":97,"section":"إعراب الفعل المضارع","text":"وَيُرْفَعُ الْمُضَارِعُ الْخَلِيُّ / كَ(نَنْتَهِي، وَيَقْبَلُ الْعَلِيُّ)"},"segments":[{"body":["لفظًا لفظًا: «وَيُرْفَعُ» فعل مضارع مبني للمجهول. «الْمُضَارِعُ» نائب فاعل مرفوع. «الْخَلِيُّ» نعت للمضارع، من خلا يخلو أي: الذي خلَا وانفرد، والمراد: الذي خلَا من ناصب وجازم. «كَ» حرف تشبيه: مثل. «نَنْتَهِي» مضارع لضمير نحن. «وَيَقْبَلُ الْعَلِيُّ» يقبل: مضارع، والعلي: فاعله، وهو من أسماء الله الحسنى.","هذا البيت يجمع القاعدة الكبرى في إعراب المضارع: الفعل المضارع يُنصب في عشرة مواضع (بالنواصب العشرة)، ويُجزم في خمسة مواضع (بالجوازم الخمسة)، ويُرفع فيما سوى ذلك. فالرفع هو الأصل الذي يرجع إليه المضارع كلما خلا من عامل.","تدريب عملي: انظر إلى أي فعل مضارع واسأل: هل قبله ناصب؟ هل قبله جازم؟ فإن كان الجواب: لا، فهو مرفوع. «يعمل الموظف بجد»: لا ناصب ولا جازم، فيعمل مرفوع.","ومثالا البيت: «نَنْتَهِي» مرفوع وعلامة رفعه الضمة، والفاعل ضمير مستتر تقديره نحن. و«يَقْبَلُ الْعَلِيُّ» مرفوع بالضمة، والعلي فاعل مرفوع. ولطيفة البيت: الناظم جعل المثال دعاءً: ننتهي من النظم، ويقبل العلي منا العمل."],"examples":["يعمل الموظف بجد — يعمل: مضارع مرفوع وعلامة رفعه الضمة.","الموظفون يعملون بجد — يعملون: مرفوع وعلامة رفعه ثبوت النون.","كان الموظف يعمل بجد — يعمل: مرفوع؛ لأنه خلا من ناصب وجازم.","رأيت الموظف يعمل بجد — يعمل: مرفوع بالضمة.","ننتهي — ننتهي: مضارع مرفوع، والفاعل مستتر تقديره نحن.","يقبل العلي — يقبل: مرفوع بالضمة، والعلي: فاعل."],"questions":[{"question":"معنى «الخلي» في البيت:","options":["الذي خلا من ناصب وجازم","الذي خلقه الله","القديم","الذي في أول الجملة"],"answer":0,"explanation":"الخلي من خلا يخلو؛ والمراد: المضارع الذي تجرد من النواصب والجوازم فيبقى على أصله: الرفع."},{"question":"القاعدة الجامعة لإعراب المضارع:","options":["ينصب في عشرة مواضع، ويجزم في خمسة، ويرفع فيما سوى ذلك","يرفع دائمًا ولا يتغير","ينصب أكثر مما يرفع","يجزم في عشرة مواضع"],"answer":0,"explanation":"ينصب بالنواصب العشرة، ويجزم بالجوازم الخمسة، والرفع هو الأصل فيما عداها: يعمل الموظف بجد."},{"question":"في «ننتهي» الفاعل:","options":["ضمير مستتر تقديره نحن","ضمير مستتر تقديره هو","واو الجماعة","اسم ظاهر"],"answer":0,"explanation":"ننتهي مضارع مرفوع بالضمة، ونون الوقاية لا؛ بل نا الدالة على الفاعلين: فاعل مستتر تقديره نحن."},{"question":"علامتا رفع الفعل المضارع:","options":["الضمة وثبوت النون","الفتحة وحذف النون","السكون وحذف حرف العلة","الكسرة والفتحة"],"answer":0,"explanation":"يرفع بالضمة: يعمل، وبثبوت النون في الأفعال الخمسة: يعملون. والنون تحذف في النصب والجزم."},{"question":"«يقبل العلي» في البيت:","options":["مثال على المضارع المرفوع، وفاعله (العلي) من أسماء الله","جملة اسمية","مثال على الجزم","نداء"],"answer":0,"explanation":"يقبل: مضارع مرفوع بالضمة، والعلي: فاعل مرفوع؛ وجعل الناظم المثال دعاء بقبول العمل."}]},{"body":["لفظًا لفظًا: «نَنْتَهِي» بمعنى: نُنهي العمل ونصل إلى آخره؛ إشارة من الناظم إلى أن المنظومة قاربت على التمام. «وَيَقْبَلُ الْعَلِيُّ» دعاء: يتقبل الله العلي هذا الجهد.","متى تكون النون علامة رفع؟ في الأفعال الخمسة: يفعلان، وتفعلان، ويفعلون، وتفعلون، وتفعلِ (المخاطبة). تقول: الموظفون يعملون بجد؛ فثبوت النون دليل الرفع. وإذا دخل ناصب أو جازم حذفت: لن يعملوا، لم يعملوا.","قارن الثلاثة: يذهبون (مرفوع بثبوت النون)، لن يذهبوا (منصوب بحذف النون)، لم يذهبوا (مجزوم بحذف النون). فالنون أول ضحايا العوامل!","وهكذا ختم الناظم باب المضارع: عرفت نواصبه العشرة، وجوازمه الخمسة، وأن ما بقي فهو مرفوع. فإذا أعربت أي مضارع فامشِ على هذه الخريطة: ابحث عن ناصب، فعن جازم، فإن لم تجد فاحكم بالرفع."],"examples":["يذهبون — مرفوع بثبوت النون، وواو الجماعة فاعل.","لن يذهبوا — منصوب بحذف النون.","لم يذهبوا — مجزوم بحذف النون.","تكتبين الدرس — مضارع مرفوع بثبوت النون (المخاطبة).","يجتهدان الطالبان — مرفوع بثبوت النون، وألف الاثنين فاعل.","المؤمن يحب الخير — يحب: مرفوع بالضمة؛ خلَا من ناصب وجازم."],"questions":[{"question":"الأفعال الخمسة تُرفع بـ:","options":["ثبوت النون","الضمة الظاهرة","الفتحة","السكون"],"answer":0,"explanation":"الأفعال الخمسة: يفعلان وتفعلان ويفعلون وتفعلون وتفعلِ ترفع بثبوت النون، وتنصب وتجزم بحذفها."},{"question":"«لن يذهبوا» علامة إعراب «يذهبوا»:","options":["منصوب بحذف النون","مرفوع بثبوت النون","مجزوم بالسكون","مرفوع بالضمة"],"answer":0,"explanation":"لن ناصبة، والأفعال الخمسة تنصب بحذف النون؛ وواو الجماعة فاعل مبني على السكون في محل رفع."},{"question":"الخطوات الصحيحة لإعراب أي فعل مضارع:","options":["ابحث عن ناصب، فعن جازم، فإن لم يوجد فهو مرفوع","احكم بالرفع دائمًا","ابحث عن حرف جر","ابدأ بالجزم ثم النصب"],"answer":0,"explanation":"خريطة الناظم: المضارع أصله الرفع؛ فلا ينصب إلا بناصب من العشرة، ولا يجزم إلا بجازم من الخمسة."},{"question":"في «تكتبين الدرسَ» علامة رفع «تكتبين»:","options":["ثبوت النون لأنها من الأفعال الخمسة","الضمة","الفتحة","حذف النون"],"answer":0,"explanation":"تكتبين مضارع مرفوع بثبوت النون لأنه من الأفعال الخمسة (المخاطبة)، والياء فاعل."},{"question":"لماذا اختار الناظم «ننتهي ويقبل العلي» مثالين؟","options":["ليجمع بين المثال والدعاء بقبول العمل عند نهاية النظم","لأنهما فعلان معتلان","لأنهما من الأفعال الخمسة","لا سبب"],"answer":0,"explanation":"المنظومة شارفت على التمام، فجعل المثال الأول خبرًا بانتهائها، والثاني دعاء بقبولها؛ وكلاهما مضارع مرفوع."}]}]},{"id":"wahi-verse-098","title":"الخاتمة: تمام المنظومة وسر اسمها","summary":"البيت الثامن والتسعون: تمت المنظومة بحمد الله، وبعضها جاء للناظم في المنام؛ فلذلك سميت «وحي المنام».","verse":{"number":98,"section":"الخاتمة","text":"تَمَّتْ بِحَمْدِ رَبِّنَا السَّلَامِ / وَبَعْضُهَا قَدْ جَاءَ فِي الْمَنَامِ"},"segments":[{"body":["لفظًا لفظًا: «تَمَّتْ» فعل ماض مبني على الفتح معناه: اكتملت وانتهت، والفاعل مستتر تقديره هي يعود على المنظومة. «بِحَمْدِ» الباء حرف جر للسببية، وحمد: اسم مجرور. «رَبِّنَا» مضاف إليه، ونا ضمير المتكلمين. «السَّلَامِ» اسم من أسماء الله الحسنى، بدل من (ربنا) مجرور.","أول ما يقوله الناظم عند الفراغ: الحمد لله. وهكذا أدب أهل العلم: يبدؤون بالحمد ويختمون بالحمد، لأن التوفيق كله من الله؛ فالناظم لم ينسب إتمام الكتاب إلى ذكائه، بل إلى حمد ربه.","وما معنى اسم الله «السلام»؟ هو المُسَلَّم من كل نقص وعيب، والذي يُسَلِّم خلقه، ومنه سلامة المؤمنين يوم القيامة. فالناظم يحمد الله بهذا الاسم الجامع.","لاحظ الأدب: البدء بالحمد في أول المنظومة، والختم بالحمد في آخرها؛ فصار العمل كله بين حمدتين، وهذا أبرك ما يكون عليه عمل."],"examples":["تمت: فعل ماض، والفاعل مستتر تقديره هي (المنظومة).","بحمد: الباء حرف جر، وحمد اسم مجرور به.","ربنا: مضاف إليه مجرور، ونا ضمير متصل في محل جر.","السلام: بدل من (ربنا) مجرور، وهو من أسماء الله الحسنى.","الحمد في أول الكتاب وآخره: أدب أهل العلم.","التوفيق للإتمام من الله وحده: لذلك قدم الحمد."],"questions":[{"question":"«تمت» يعود فاعلها على:","options":["المنظومة","الليلة","الرؤيا","القصيدة القديمة"],"answer":0,"explanation":"تمت: فعل ماض مبني على الفتح، والفاعل مستتر تقديره هي، يعود على المنظومة التي نحن بصددها."},{"question":"«السلام» في البيت:","options":["اسم من أسماء الله الحسنى بدل من (ربنا)","تحية الإسلام","اسم الكتاب","نعت للمنام"],"answer":0,"explanation":"السلام: الله المُسَلَّم من العيوب والنقائص؛ وهو هنا بدل من (ربنا) مجرور مثله."},{"question":"علّة ذكر الحمد عند تمام الكتاب:","options":["التوفيق للإتمام من الله، فيُحمَد عليه","مجرد عادة بلا معنى","لزيادة عدد الأبيات","لأنه بيت سهل النظم"],"answer":0,"explanation":"أدب أهل العلم: نسبة النعمة لربها؛ فالإتمام توفيق من الله يستحق الحمد."},{"question":"إعراب «رَبِّنَا»:","options":["مضاف إليه مجرور وعلامة جره الكسرة، ونا ضمير في محل جر","فاعل مرفوع","مبتدأ","مفعول به"],"answer":0,"explanation":"رب: مضاف إليه مجرور بالكسرة، ونا ضمير متصل مبني في محل جر بالإضافة."},{"question":"بدأ الناظم كتابه بالحمد وختمه به؛ وهذا يدل على:","options":["أدب نسبة الفضل لله في أول العمل وآخره","تكرار بلا فائدة","نسيان","طول الكلام"],"answer":0,"explanation":"صار العمل كله محفوفًا بالحمد من أوله إلى آخره؛ وهو سنة المتقنين من أهل العلم."}]},{"body":["لفظًا لفظًا: «وَبَعْضُهَا» الواو استئنافية، وبعض: مبتدأ، والهاء ضمير يعود على المنظومة: بعض أبياتها. «قَدْ» حرف تحقيق. «جَاءَ» فعل ماض. «فِي الْمَنَامِ» المنام: النوم وما يُرى فيه، جار ومجرور متعلقان بجاء.","هنا سر التسمية! لماذا سميت هذه المنظومة «وحي المنام»؟ لأن بعض أبياتها جاء للناظم الشيخ سليمان العيوني في منامه؛ فرأى في نومه بعض هذا النظم، فلما استيقظ حفظه وأتمه، وسمى كتابه: وحي المنام.","والوحي في اللغة: الإعلام الخفي؛ والمنام: الرؤيا. فالاسم يعني: نظم أُلهم صاحبه بعضَه في نومه. وهذه كرامة من الله لصاحبه، وعلامة على صدق سريرته.","فائدة: أمانة الناظم؛ فقد أخبرنا بحقيقة ما جرى له، ولم يدع ما ليس له، ونسب الفضل كله لله. وهذا درس في الصدق قبل النحو."],"examples":["وبعضها: بعض مبتدأ مرفوع، والهاء مضاف إليه.","قد: حرف تحقيق يدخل على الماضي فيفيد التحقيق.","جاء: فعل ماض، وفاعله مستتر تقديره هو (البعض).","في المنام: جار ومجرور متعلقان بجاء.","وحي المنام: وحي أي إلهام خفي، والمنام الرؤيا.","سبب التسمية: بعض الأبيات جاء في الرؤيا فسميت المنظومة به."],"questions":[{"question":"سميت المنظومة «وحي المنام» لأن:","options":["بعض أبياتها جاء للناظم في منامه","كلها وحي منزل","كتبت ليلًا","اسم اختاره الناشر"],"answer":0,"explanation":"قال الناظم: وبعضها قد جاء في المنام؛ فرأى بعض النظم في رؤياه فسمى الكتاب: وحي المنام."},{"question":"معنى «وحي» في اسم المنظومة:","options":["إعلام خفي وإلهام","كلام جهر","كتاب مطبوع","حرف ناسخ"],"answer":0,"explanation":"الوحي لغة: الإعلام في خفاء؛ والمراد هنا الإلهام الذي يقع للنائم في رؤياه."},{"question":"«قد» في «قد جاء» تفيد:","options":["التحقيق","التقليل","التمني","النهي"],"answer":0,"explanation":"قد إذا دخلت على الفعل الماضي أفادت التحقيق: قد جاء أي: جاء حقًا."},{"question":"إعراب «بعضها»:","options":["مبتدأ مرفوع والهاء ضمير متصل في محل جر بالإضافة","مفعول به","فاعل","حال"],"answer":0,"explanation":"بعض: مبتدأ مرفوع بالضمة، والهاء ضمير مبني في محل جر مضاف إليه، وخبر المبتدأ جملة (جاء)."},{"question":"الفائدة الأدبية من إخبار الناظم بقصة المنام:","options":["الصدق والأمانة ونسبة الفضل لله","التفاخر","الغموض","ملء الصفحة"],"answer":0,"explanation":"أخبر بما جرى له بصدق، ولم يدّعِ أكثر منه، وجعل الفضل لله؛ فهو درس أدب قبل أن يكون درس نحو."}]}]},{"id":"wahi-verse-099","title":"دعاء الناظم: قرة العيون","summary":"البيت التاسع والتسعون: يدعو الناظم ربه أن يزين المنظومة ويجعلها قرة عين، وأن يبارك في أبياتها المئة.","verse":{"number":99,"section":"الخاتمة","text":"يَا رَبِّ زِنْهَا قُرَّةَ الْعُيُونِ / وَبَارِكْ مِئَةَ الْعُيُونِ"},"segments":[{"body":["لفظًا لفظًا: «يَا» حرف نداء. «رَبِّ» منادى مضاف إلى ياء المتكلم؛ أي: يا ربي. «زِنْهَا» فعل أمر من زانَ يَزِين، أي: زيِّنها وجمِّلها، والهاء ضمير يعود على المنظومة. «قُرَّةَ الْعُيُونِ» مفعول به ثان أو حال: أي اجعلها قرةَ عين؛ وقرة العين: ما تقرّ به العين فلا تميل إلى غيره، أي: أعظم الفرح والسرور.","ماذا يطلب الناظم من ربه؟ يطلب أن يزين منظومته في أعين الناس، فتصير محبوبة لهم، تقر بها عيونهم كلما قرؤوها، ولا يملّون منها.","ودعاؤه «زنها قرة العيون» أدب بديع: فالكتاب مهما أتقنه صاحبه لا ينفع حتى يجعل الله له القبول؛ فالقبول من الله، والتزيين الحقيقي هو ما يضعه الله في القلوب.","تأمل اختياره: لم يقل: زنها للناس، بل: قرة العيون؛ لأن الكتاب الذي تقر به عين صاحبه هو الذي يُقرأ ويُحفظ ويُدرَّس، فلا يبقى حبرًا على ورق."],"examples":["يا رب: يا حرف نداء، ورب منادى مضاف لياء المتكلم.","زنها: فعل أمر مبني، والهاء مفعول به يعود على المنظومة.","زان يزين: بابه مثل قال يقول؛ والأمر منه: زِن.","قرة العيون: ما تفرح به العين وتسكن إليه.","قر الله عينك بالعلم: دعاء طيب لطالب العلم.","القبول والتزيين الحقيقي للأعمال من الله وحده."],"questions":[{"question":"«زِنْهَا» معناها:","options":["زيِّنها وجمِّلها","زِنْها ميزانًا","اسأل عنها","انشرها"],"answer":0,"explanation":"زنها من زانَ يَزِين؛ فعل أمر مبني على السكون، والهاء مفعول به يعود على المنظومة."},{"question":"معنى «قرة العيون»:","options":["أعظم الفرح الذي تسكن به العين ولا تميل عنه","دمع العين","مرض العيون","كثرة النظر"],"answer":0,"explanation":"قرة العين: ما تقر به العين أي يسرها ويثبتها؛ فدعا أن تكون منظومته محبوبة مقروءة."},{"question":"إعراب «رب» في «يا ربِّ»:","options":["منادى مضاف منون مقصود، مبني على الضم في محل نصب","مبتدأ مرفوع","فاعل","مفعول به منصوب بالفتحة"],"answer":0,"explanation":"المنادى المضاف منون مقصود: مبني على الضم في محل نصب، وياء المتكلم مضاف إليه في محل جر."},{"question":"الفائدة المقصودة من الدعاء بتزيين المنظومة:","options":["أن يجعل الله لها القبول فيعم نفعها","زيادة بيع الكتاب","الشهرة","حفظ الألفاظ فقط"],"answer":0,"explanation":"الكتاب لا ينفع بمجرد إتقانه؛ بل بالقبول الذي يجعله الله في القلوب، فدعا ربه لأجله."},{"question":"فعل الأمر «زِن» أصله:","options":["زانَ يَزِين (فعل أجوف)","وزنَ يَزِن","زيَّنَ يُزَيِّن","زنَّ يَزُن"],"answer":0,"explanation":"زان يزين فعل أجوف عينه ياء؛ وأمره: زِن، كقال قُلْ، وباع بِعْ."}]},{"body":["لفظًا لفظًا: «وَبَارِكْ» فعل أمر من بَارَكَ يُبَارِك، أي: أعطِ البركة وضاعِف الخير. «مِئَةَ» مفعول به: المئة بيت من أبيات المنظومة. «الْعُيُونِ» مضاف إليه؛ جمع عَين، والمراد عيون من يقرؤها من الطلاب والمعلمين.","فالمعنى: يا رب بارك في هذه الأبيات المئة، واجعلها نافعة مباركة لكل عين تقرؤها وقلب يحفظها.","والبركة: زيادة الخير ونماؤه؛ فالشيء المبارك قد يكون قليلًا في عين الناس ويكثر نفعه. فدعا الناظم أن تكون مئته القليلة مباركة النفع عظيمة الأثر.","ولاحظ ترتيب الدعوات: حمد الله أولًا، ثم دعا بتزيين المنظومة، ثم دعا بالبركة فيها، ثم سيختم بالصلاة على الرسول. وهذا ترتيب أهل الأدب: الحمد، فالدعاء، فالصلاة على النبي صلى الله عليه وسلم."],"examples":["وبارك: فعل أمر من بارك يبارك، معناه: أعطِ البركة.","مئةَ: مفعول به منصوب، والمراد الأبيات المئة.","العيون: جمع عين، مضاف إليه مجرور.","البركة: زيادة الخير ونماؤه ودوام نفعه.","بارك الله لك في علمك: دعاء حسن لطالب العلم.","عدد أبيات المنظومة مئة بيت مرقمة في الكتاب من ١ إلى ١٠٠."],"questions":[{"question":"المراد بـ«مئة» في البيت:","options":["أبيات المنظومة المئة","مئة صفحة","مئة قارئ","مئة سنة"],"answer":0,"explanation":"المنظومة مئة بيت مرقمة؛ فدعا الناظم ربه أن يبارك فيها وفي نفعها."},{"question":"«وبارك» نوعه:","options":["فعل أمر","فعل ماض","فعل مضارع منصوب","اسم فاعل"],"answer":0,"explanation":"بارك: فعل أمر من بَارَكَ يُبَارِك مبني على السكون، والفاعل مستتر تقديره أنت (الله)."},{"question":"معنى البركة التي دعا بها:","options":["زيادة الخير ونماء النفع","كثرة المال فقط","طول العمر فقط","الشهرة"],"answer":0,"explanation":"البركة ثبوت الخير ونماؤه؛ فدعا أن ينمو نفع الأبيات فيمن يقرؤها ويحفظها."},{"question":"«العيون» في البيت:","options":["مضاف إليه مجرور وعلامة جره الكسرة","فاعل مرفوع","مبتدأ","منادى"],"answer":0,"explanation":"العيون: مضاف إليه مجرور بالكسرة، وهو جمع عين؛ والمراد عيون قراء المنظومة."},{"question":"ترتيب أدب الخاتمة عند الناظم:","options":["الحمد، ثم الدعاء للمنظومة، ثم الصلاة على الرسول","الصلاة على الرسول فقط","الدعاء ثم الحمد فقط","لا ترتيب"],"answer":0,"explanation":"بدأ الخاتمة بحمد الله، ثم دعا بالتزيين والبركة، ثم ختم بالصلاة على النبي صلى الله عليه وسلم؛ وهو ترتيب أهل الأدب."}]}]},{"id":"wahi-verse-100","title":"الختام بالصلاة على الرسول","summary":"البيت المئة والأخير: يختم الناظم منظومته بأفضل الصلاة والسلام على الرسول أفضل الأنام.","verse":{"number":100,"section":"الخاتمة","text":"وَأَفْضَلُ الصَّلَاةِ وَالسَّلَامِ / عَلَى الرَّسُولِ أَفْضَلِ الْأَنَامِ"},"segments":[{"body":["لفظًا لفظًا: «وَأَفْضَلُ» اسم تفضيل من فَضُلَ، أي: أكرم وأعلى الصلوات. «الصَّلَاةِ» الدعاء بالرحمة والثناء. «وَالسَّلَامِ» الدعاء بالسلامة من كل آفة، والتحية. «عَلَى الرَّسُولِ» نبينا محمد صلى الله عليه وسلم. «أَفْضَلِ الْأَنَامِ» الأنام: الخلق والناس؛ أي: أفضل الخلق أجمعين.","إعراب البيت: «أفضل» مبتدأ مرفوع وعلامة رفعه الضمة، وهو مضاف. «الصلاة» مضاف إليه مجرور. «والسلام» معطوف على الصلاة مجرور. «على الرسول» جار ومجرور: الخبر مقدم. «أفضل» نعت للرسول مجرور. «الأنام» مضاف إليه مجرور.","هذا هو البيت المئة، خاتمة المنظومة؛ وما أحسن أن يُختم الكتاب بالصلاة على سيد الخلق؛ فقد جرت عادة أهل العلم أن يختم مؤلف كتابَه بالصلاة على النبي صلى الله عليه وسلم، ابتغاء البركة في الكتاب وفي قارئه.","وفي البيت مبالغة لطيفة: كما أن الرسول أفضل الأنام، جعل له أفضل الصلاة والسلام؛ فالأفضل للأفضل."],"examples":["أفضلُ: مبتدأ مرفوع بالضمة، وهو مضاف.","الصلاةِ: مضاف إليه مجرور بالكسرة.","والسلامِ: الواو حرف عطف، والسلام معطوف مجرور.","على الرسولِ: جار ومجرور في محل رفع خبر مقدم.","أفضلِ: نعت للرسول مجرور بالكسرة.","الأنامِ: مضاف إليه مجرور، والأنام: الخلق."],"questions":[{"question":"معنى «الأنام»:","options":["الخلق والناس","النوم","الأنعام","الملائكة فقط"],"answer":0,"explanation":"الأنام: الخلق؛ فأفضل الأنام أي أفضل الخلق، وهو النبي صلى الله عليه وسلم."},{"question":"«أفضل» في أول البيت نوعه وإعرابه:","options":["اسم تفضيل، مبتدأ مرفوع وهو مضاف","فعل ماض","حرف جر","نعت مجرور"],"answer":0,"explanation":"أفضل: اسم تفضيل من فضل، مبتدأ مرفوع بالضمة، مضاف إلى الصلاة."},{"question":"«على الرسول» في البيت:","options":["خبر مقدم لأفضل، جار ومجرور","مفعول به","حال","فاعل"],"answer":0,"explanation":"أفضل الصلاة والسلام على الرسول: المبتدأ (أفضل) وخبره (على الرسول) مقدم عليه."},{"question":"«أفضل الأنام» إضافة «أفضل» الثانية إلى «الأنام» إعرابها:","options":["أفضل: نعت للرسول مجرور، والأنام: مضاف إليه","أفضل: مبتدأ ثان","الأنام: فاعل","أفضل: حال"],"answer":0,"explanation":"الرسول موصوف بأنه أفضل الأنام؛ فالأولى مضاف للصلاة، والثانية نعت مضاف للأنام."},{"question":"من أدب أهل العلم في ختم كتبهم:","options":["الصلاة على النبي صلى الله عليه وسلم ابتغاء البركة","الثناء على أنفسهم","ذكر أسعار الكتب","أسماء أولادهم"],"answer":0,"explanation":"جرى أهل العلم على ختم المؤلفات بالصلاة على النبي صلى الله عليه وسلم طلبًا للبركة في الكتاب وقارئه."}]},{"body":["لفظًا لفظًا: «وَأَفْضَلُ الصَّلَاةِ» أي: أعلى درجات الدعاء بالرحمة. «وَالسَّلَامِ» أي: وأكمل التحية والدعاء بالسلامة. فالصلاة من الله رحمة، ومن العبد دعاء وتعظيم.","لماذا أفضل الصلاة؟ لأن المُصَلَّى عليه أفضل الأنام؛ فتناسب الدرجتان: أفضل دعاء لأفضل خلق. وفيه تنبيه لنا: إذا صليت على النبي فأخلص وأكمل الصيغة؛ فهو أهل لأفضلها.","وبهذا البيت تمت منظومة «وحي المنام» مئة بيت، من التوحيد وأقسام الكلمة إلى الخاتمة. فمن أتقنها فقد بنى أساس النحو كله على بصيرة.","وأنت أيها الطالب: قد بلغت خاتمة النظم، فاحمد الله على التمام كما حمد الناظم، وادعُ بالقبول، وصلِّ على النبي صلى الله عليه وسلم، ثم انتقل إلى دروس شرح الكتاب لتثبيت ما حفظت."],"examples":["اللهم صل وسلم على نبينا محمد: أفضل الصلاة والسلام.","الصلاة من الله: رحمة؛ ومن العبد: دعاء وتعظيم.","أفضل للأفضل: مناسبة بين شرف الدعاء وشرف المدعو له.","خاتمة الكتب بالصلاة على النبي: سنة أهل العلم.","المنظومة تمت مئة بيت من التوحيد إلى الخاتمة.","بعد النظم تأتي دروس الشرح لتثبيت المعاني وفقهها."],"questions":[{"question":"مناسبة قوله «أفضل الصلاة... على... أفضل الأنام»:","options":["أفضل الدعاء لأفضل الخلق: تناسب بين الدرجتين","لا مناسبة","مجرد قافية","تكرار لفظي فقط"],"answer":0,"explanation":"جعل أفضل الصلاة لأفضل الخلق؛ فالأفضل يستحق الأفضل، وهذه بلاغة لطيفة في الختام."},{"question":"الصلاة على النبي من العبد معناها:","options":["دعاء وتعظيم للنبي صلى الله عليه وسلم","ركوع وسجود له","مجرد تحية عابرة","ذكر اسمه فقط"],"answer":0,"explanation":"صلاة العبد على النبي: دعاء له بالرحمة والثناء الجميل وتعظيمه صلى الله عليه وسلم."},{"question":"المراد بـ«السلام» في البيت:","options":["الدعاء بالسلامة والتحية الكاملة","اسم الله السلام","الانصراف","السكون"],"answer":0,"explanation":"السلام هنا: التحية والدعاء بالسلامة؛ فالصلاة رحمة وثناء، والسلام تحية وسلامة."},{"question":"عدد أبيات منظومة «وحي المنام» كما رقمها الكتاب:","options":["مئة بيت","تسعة وتسعون","مئة وواحد","خمسون"],"answer":0,"explanation":"رقم الكتاب الأبيات من ١ إلى ١٠٠، وهذا البيت هو المئة خاتمة النظم."},{"question":"بعد إتمام النظم ينتقل الطالب إلى:","options":["دروس شرح الكتاب لتثبيت المعاني وفقهها","ترك العلم","مادة أخرى بلا مراجعة","نسيان ما حفظ"],"answer":0,"explanation":"النظم جمع القواعد في ألفاظ، والشرح يفكها ويفقهها؛ فبعد التمام تأتي دروس شرح المؤلف لترسيخ الفهم."}]}]}]};
